C *********************************************************************
C
C   ISSUE A (JANUARY 89) (WRITTEN BY E. TAJAN , M. SAINT-JEAN)
C     -CREATION FOR AMERICAN AIR LINES TEST
C
C   ISSUE B (MAY 92)
C     -UPDATING FOLLOWING:REVISED SCAP/6 OF 21 APRIL REF-EP09
C                               SCAP/7 OF 20 JUNE
C     -NEW INITIALIZATION OF COMMON OBSLIM
C     -UPDATING OF COMMON OBSLIM
C     -UPDATING FOLLOWING: DOC.GEN/3011  JANUARY 1990
C     -ADDING OPEN OF PERFO. DATA FILE
C     -ADAPTATION FOR ATR AIRCRAFT
C     -DELETE ZP=ZG IN SUBROUTINE FICHE
C
C ISSUE C (AUG. 92)
C   ABOUT INPUT DATA:
C     -ADDING POSSIBILITY TO USE POPT(12),POPT(13),POPT(19),POPT(20)
C     -INITIALISATION OF CERTIF,CONF(27),CONF(28),CONF(29) (REF SCAP/13)
C     -INITIALISATION OF SPIA,SPIB,SPIC,SPOUTA (REF SCAP/14)
C     -ADDING OPTION ERFLAG = 'F' (INPUT WARNING) (REF SCAP/13)
C     -ADDING FLAG 10 + 11 IN POPT(14)  (REF SCAP/10)
C     -  "     "   2 + 3 IN CONF(1)  (REF SCAP/13)
C     -  "     "   5 IN CONF(5)  (REF SCAP/13)
C     -UPDATING DEFINITION OF CONF(5)=4
C     -NEW DEFINITION OF CONF(5)=6
C   ABOUT OUTPUT DATA:
C       -DEFINITION OF RWYSEG(4) (REF SCAP/14)
C
C ISSUE D (AUG. 94)
C     - NEW PRESENTATION OF SOURCE CODE
C     - INITIALISATION OF RWYSEG(13),CLIMIT(25),CLIMIT(26)
C     - CONNECTION OF COMMON SPIA (FOLLOWING SCAP 3RD EDITION 1994) WITH
C       A NEW ADRESS FOR V1 LIMITED BY BRAKE ENERGY
C     - INITIALISATION OF CLIMIT(8),CLIMIT(9) IF V1MIN=V1MAX
C     - UPDATING OF THE DIMENSION OF TABLES : CLIMIT , RWYSEG
C     - ADDING OPTIONS 3 TO 7 IN RWYD(8)
C     - ADDING SAVE : ACERT,ICERT
C
C ISSUE E (DEC. 95)
C     - TO USE LSPTOW ISSUE K1 (TAKING ACCOUNT OF POST AMENDEMENT 42
C       CONDITIONS ON WET AND CONTAMINATED RWY )
C     - CORRECTION OF INITIALISATION OF SPIA(1) AND SPIA(3)
C     - CORRECTION OF INITIALISATION OF 'ERFLAG' WHEN LIMITATION VMCA
C       IS ENCOUNTERED
C
C ISSUE F (JAN. 97)
C     - TO USE LSPTOW ISSUE K2
C     - INITIALISATION OF ERFLAG AND ERRMSG(1) BY BLANK CHARACTERS
C     - INITIALISATION OF CONF(30) : FLAPS DEFAULT / LOCKED
C     - INITIALISATION OF CONF(31) : SLAPS DEFAULT / LOCKED
C
C ISSUE F (AUG.97)
C     - TO USE LSPTOW ISSUE K3
C
C ISSUE G (DEC. 98)
C     - TO USE LSPTOW ISSUE L
C     - UPDATING OF SCAP ARRAYS RELATIVE TO SCAP DEFINITION (PROVISORY
C       EDITION 1998)
C     - CHANGING OF THE ERROR TREATMENTS TO FILL THE ERRMSG SCAP ARRAY WITH
C       THE TLC COMMON ERROR MESSAGES
C     - CHANGING OF THE PERFOMRANCES DATA FILE ASELECTION TO USE THE ACMDBI
C       VARIABLE FOR THE PERFORMANCES DATA FILE
C     - ADDING WIDTH RUNWAY INPUT (RWYD(11))
C
C ISSUE G1 (MAY. 2001)
C     - TO USE LSPTOW ISSUE M
C     - ADDING SPOILERS INOPERATIVE SCAP INPUT CONF(6)=2.
C     - ADDING LANDING GEAR EXTENDED SCAP INPUT CONF(9)=1.
C     - ADDING ACW GENERATOR INOPERATIVE SCAP INPUT CONF(12)=1.
C     - ADDING ONE BRAKE INOPERATIVE SCAP INPUT CONF(20)=1.
C
C ISSUE G2 (SEP. 2002)
C     - ADDING AIR CONDITIONNING ON SCAP INPUT CONF(4)=1.
C     - REMOVING OBSOLETE 50% FULL REVERSE SCAP INPUT CONF(8)=4.
C     - REMOVING OBSOLETE WITHOUT NOSE GEAR BRAKE BRAKING SCAP INPUT CONF(20)=2.
C     - ADDING SCAP OUTPUT RWYSEG(1), RWYSEG(2), RWYSEG(10), RWYSEG(12),
C       RWYSEG(25) & RWYSEG(29)
C
C ISSUE G4 (OCT. 2009)
C     - ADDING DEVIATION FROM ISA INPUT UNIT(1)=2. OR 3.
C     - DUPLICATE CLIMIT(14) THROUGH CLIMIT(18) IN CLIMIT(8) THROUGH CLIMIT(12)
C       WHEN CLIMIT(7)=CLIMIT(13)
C
C ISSUE G5 (2012)
C     - ALLOW USAGE OF NEW PERFORMANCE DATA FILE VERSION
C     - ADDING USE OF CONF(56) FOR BOOST OPTION SELECTION
C
C ISSUE G6 (NOV. 2013)
C     - ALLOW USAGE OF SINGLE PERFORMANCE DATA FILE WITH MULTIPLE
C       ALTITUDE AND BOOST APPROACH AND LANDING MODULUS
C
C ISSUE G7 (MAY. 2014)
C     - ALLOW USE OF SUPER BOOST ENGINE POWER CONF(56)=3.
C
C***********************************************************************
      SUBROUTINE APRO(
     &TS,
     &TCASA,
     &TCASB
     &)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
