      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
      REAL TRAJ(32)
      REAL TRAJV(10)
      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      REAL GAMXWP
      INTEGER IK1T
      INTEGER IK2T
      INTEGER IKVF
      INTEGER IKV1
      INTEGER IKV2
      REAL AERO(40)
      REAL COEF(40)
      REAL COEFP(40)
      REAL CVIT(80)
      REAL DTCA(21)
      REAL DTCD(21)
      REAL GAP(21)
      REAL GLD(21)
      REAL RAER(8)
      REAL RTFP(8)
      REAL RGLD(8)
      REAL TCGC(20)
      REAL TK1T(20)
      REAL TK2T(20)
      REAL TKV1(20)
      REAL TKVA(40)
      REAL TKVF(20)
      REAL TKVL(40)
      REAL TVQ(8)
      REAL VMU(20)
      REAL V2CP(20)
      REAL GLDA(21)
      REAL VMPE(30)
      REAL XTWD(40)
      COMMON /VAR1/IK1T,IK2T,IKVF,IKV1,IKV2
      COMMON /VAR2/COEF,DTCA,DTCD,AERO,CVIT,GAP,GLD,VMU,COEFP,TK2T,TKVF,
     +TKVA,TKVL,TVQ,TCGC,RGLD,RAER,RTFP,TKV1,TK1T,V2CP,VMPE,
     +XTWD,GAMXWP,GLDA
      INTEGER IHSDMI
      REAL PRON(29)
      REAL RASS(28)
      REAL RPKG(29)
      REAL RPKGI(29)
      REAL RVMAX(28)
      REAL RVMIN(28)
      REAL RV2(28)
      REAL TAA(17)
      REAL ZPQNH(5)
      REAL RVMCA(MAXTTA)
      REAL RVMCG(MAXTTA)
      REAL TASS(MAXTTA,MAXVQ)
      REAL TPKG(MAXTTA,MAXVQ)
      REAL TTAI(MAXTTA)
      REAL TV2(MAXTTA,MAXVQ)
      REAL TVMAX(MAXTTA,MAXVQ)
      REAL TVMIN(MAXTTA,MAXVQ)
      REAL TVPKG(MAXTTA-1,MAXVQ)
      INTEGER IHSD1(MAXTTA-1,MAXVQ)
      INTEGER IHSD2(MAXTTA-1,MAXVQ)
      INTEGER ITMAX(MAXTTA,MAXVQ)
      INTEGER JJ1(MAXTTA,MAXVQ)
      INTEGER JJ2(MAXTTA,MAXVQ)
      INTEGER IT1(29)
      INTEGER IT2(29)
      INTEGER LJ1(29)
      INTEGER LJ2(29)
      INTEGER LV2(5)
      INTEGER LVMAX(5)
      INTEGER LVMIN(5)
      COMMON /RESLB1/LJ1,LJ2,LVMIN,LVMAX,LV2,IT1,IT2,JJ1,
     +JJ2,ITMAX,IHSD1,IHSD2,IHSDMI
      COMMON /RESLB2/PRON,TTAI,RPKG,RPKGI,RVMAX,RVMIN,RV2,RASS,
     +TAA,TPKG,TV2,TVMIN,TVMAX,TASS,TVPKG,ZPQNH,RVMCA,RVMCG
      REAL A1
      REAL A2
      REAL A79
      REAL A9
      REAL PMINF
      REAL PSTL
      REAL PSTL1
      REAL PSTL2
      REAL PSTRUC
      REAL PU
      REAL TU
      REAL UH
      REAL UL
      REAL UP
      REAL EPSI
      REAL C3
      REAL HU
      INTEGER COD
      INTEGER DRYCHK
      INTEGER DRYCHL
      INTEGER IATA
      INTEGER IDLL
      INTEGER IMP
      INTEGER ITERMA
      INTEGER K1
      INTEGER K2
      INTEGER KEMAX
      INTEGER KISU
      INTEGER KPPM
      INTEGER KS
      INTEGER KS4
      INTEGER KSB
      INTEGER KSP
      INTEGER KST
      INTEGER KSU
      INTEGER KTAB1
      INTEGER KTAB2
      INTEGER KTAB3
      INTEGER KTABL
      INTEGER KV1MN
      INTEGER L1610
      INTEGER LA42
      INTEGER MICRO
      INTEGER MODE
      INTEGER OUTMOD
      INTEGER NCONT
      INTEGER KTR
      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      INTEGER DBRMOD
      INTEGER IBRACT
      INTEGER IBRAL1
      INTEGER IBRAL2
      INTEGER KAP1
      INTEGER KAP2
      INTEGER KLD1
      INTEGER KLD2
      INTEGER NAP1
      INTEGER NAP2
      INTEGER NEFFA
      INTEGER NEFFL
      INTEGER NEFFT
      INTEGER NIGC
      INTEGER NLD1
      INTEGER NLD2
      INTEGER IBOOSL
      INTEGER IBOOST
      INTEGER IRTO
      INTEGER IALT
      INTEGER IZRTO
      INTEGER RWSHFT
      REAL TBAMU
      REAL LBAMU1
      REAL LBAMU2
      INTEGER IGC(30)
      INTEGER IZCODA(5)
      INTEGER IZCODL(5)
      INTEGER IZCODT(7)
      COMMON /INP1/NIGC,IZCODT,NAP1,KAP1,NAP2,KAP2,IZCODA,NLD1,KLD1,
     +NLD2,KLD2,IZCODL,NEFFT,NEFFA,NEFFL,IGC,IBOOSL,IBOOST,IRTO,
     +IALT,IZRTO,IBRACT,IBRAL1,IBRAL2,RWSHFT,DBRMOD
      COMMON /INP2/TBAMU,LBAMU1,LBAMU2
      REAL AL1G
      REAL AL1GMN
      REAL AP1G
      REAL AP1GMN
      REAL AP1K
      REAL AP2G
      REAL AP2GMN
      REAL AP2K
      REAL CLD1
      REAL CLD2
      REAL FLAPA
      REAL FLAPL
      REAL FV1VR
      REAL QLD
      REAL SLATA
      REAL SLATL
      REAL TLDA
      REAL TLDP
      REAL STAPMN
      REAL STAPMX
      REAL STEEP1
      REAL STEEP2
      REAL CLDW1
      REAL CLDW2
      REAL EB1L
      REAL EB2L
      INTEGER KODIF
      INTEGER NGAP1
      INTEGER NGAP2
      INTEGER NGLD1
      INTEGER NGLD2
      INTEGER NTAL
      INTEGER LAT1
      INTEGER LAT2
      REAL BEAT(24)
      REAL BINFL(24)
      REAL BMASL(24)
      REAL BPISL(24)
      REAL BVENL(24)
      REAL GAP1(24)
      REAL GAP2(24)
      REAL EMASL(24)
      REAL EVENL(24)
      REAL EEAT(24)
      REAL EINFL(24)
      REAL EPISL(24)
      REAL GLD1(24)
      REAL GLD2(24)
      REAL TALD1(MAXTAL,MAXVQ)
      REAL TRLD1(MAXTAL,MAXVQ)
      REAL TACG1(MAXTAL,MAXVQ)
      REAL TLCG1(MAXTAL,MAXVQ)
      REAL TLEB1(MAXTAL,MAXVQ)
      REAL TIWLD1(MAXTAL,MAXVQ)
      REAL TIWAC1(MAXTAL,MAXVQ)
      REAL TIWLC1(MAXTAL,MAXVQ)
      REAL TIWEB1(MAXTAL,MAXVQ)
      REAL TALD2(MAXTAL,MAXVQ)
      REAL TRLD2(MAXTAL,MAXVQ)
      REAL TACG2(MAXTAL,MAXVQ)
      REAL TLCG2(MAXTAL,MAXVQ)
      REAL TLEB2(MAXTAL,MAXVQ)
      REAL TIWLD2(MAXTAL,MAXVQ)
      REAL TIWAC2(MAXTAL,MAXVQ)
      REAL TIWLC2(MAXTAL,MAXVQ)
      REAL TIWEB2(MAXTAL,MAXVQ)
      REAL TOWLD1(MAXTAL,MAXVQ)
      REAL TOWAC1(MAXTAL,MAXVQ)
      REAL TOWLC1(MAXTAL,MAXVQ)
      REAL TOWEB1(MAXTAL,MAXVQ)
      REAL TOWLD2(MAXTAL,MAXVQ)
      REAL TOWAC2(MAXTAL,MAXVQ)
      REAL TOWLC2(MAXTAL,MAXVQ)
      REAL TOWEB2(MAXTAL,MAXVQ)
      INTEGER CLJ1(MAXTAL,MAXVQ)
      INTEGER CLJ2(MAXTAL,MAXVQ)
      INTEGER DJ1(MAXTAL,MAXVQ)
      INTEGER DJ2(MAXTAL,MAXVQ)
      INTEGER LTITR(5)
      INTEGER LTITRL(5)
      COMMON /LDG1/LTITR,LTITRL,KODIF,CLJ1,CLJ2,DJ1,DJ2,NGAP1,NGAP2,
     +NGLD1,NGLD2,NTAL,LAT1,LAT2
      COMMON /LDG2/TLDA,BMASL,BVENL,BINFL,BPISL,BEAT,TLDP,QLD,FV1VR,
     +AP1G,AP2G,AP1K,AP2K,CLD1,CLD2,GAP1,GAP2,GLD1,GLD2,
     +AP1GMN,AP2GMN,AL1GMN,AL1G,SLATA,FLAPA,SLATL,FLAPL,
     +STAPMN,STAPMX,STEEP1,STEEP2,TALD1,TRLD1,TACG1,TLCG1,TIWLD1,
     +TIWAC1,TIWLC1,TALD2,TRLD2,TACG2,TLCG2,TIWLD2,TIWAC2,TIWLC2,
     +TOWLD1,TOWAC1,TOWLC1,TOWLD2,TOWAC2,TOWLC2,CLDW1,CLDW2,
     +EMASL,EVENL,EINFL,EPISL,EEAT,EB1L,EB2L,TLEB1,TLEB2,TIWEB1,
     +TIWEB2,TOWEB1,TOWEB2
      REAL AKV1
      REAL AKV2
      REAL AP1KV
      REAL AP2KV
      REAL DV2CP
      REAL DVMCA
      REAL DVMCPE
      REAL DVMCG
      REAL FTOKV
      REAL RK2T
      REAL RKV1
      REAL RKVF
      REAL RKVLD1
      REAL RKVLD2
      REAL VMCA
      REAL VMCG
      REAL VS
      INTEGER KMCA
      INTEGER KMCAG
      INTEGER KMCG
      INTEGER KMU
      REAL VDELBR(2)
      REAL VMAP(20)
      REAL VMC1(20)
      REAL VMGP(20)
      COMMON /VIT1/KMCA,KMCG,KMU,KMCAG
      COMMON /VIT2/VMCA,VMCG,RK2T,RKVF,AKV1,AKV2,RKVLD1,RKVLD2,
     +FTOKV,AP1KV,AP2KV,VMC1,VMGP,VMAP,DVMCG,DVMCA,RKV1,
     +DV2CP,DVMCPE,VS,VDELBR
      INTEGER NPMAX
      REAL DIVER(20)
      REAL VNUM(20000)
      INTEGER NTAB(4200)
      COMMON /TABLE1/NTAB,NPMAX
      COMMON /TABLE2/VNUM,DIVER
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      REAL TCASA,TCASB,TS
      REAL DTCAS
      REAL DTCAS1
      REAL PAP1
      REAL PAP2
      REAL R
      REAL RS
      REAL ZPA
      INTEGER J
      REAL Z(12)
      REAL FINT
      EXTERNAL FINT
      EXTERNAL INFLU,JNT
      ZPA = ZP + AERO(20)
      TCASA = FINT(ZPA,DTCA(1),DTCA(14),1)
      TCASA = TCASA - .2
      TCASB = TS + DTCA(20) + .2
      DTCAS = FINT(ZPA,DTCA(1),DTCA(8),1)
      DTCAS1 = (DTCA(20)-DTCAS)*.25
      TAA(5) = DTCAS
      TAA(4) = TAA(5) + DTCAS1
      TAA(3) = TAA(4) + DTCAS1
      TAA(2) = TAA(3) + DTCAS1
      TAA(1) = DTCA(20)
      K1 = 1
      K2 = 1
      DO 10 J = 1,5
      IF (NAP1.NE.0) THEN
      CALL JNT(2601,TAA(J),ZPA,Z(1))
      R = Z(1)
      IF (AP1K.NE.0.) THEN
      IF (AP1K.GT.AP1KV) AP1KV = AP1K
      END IF
      IF (NTAB(2604).NE.0) CALL JNT(524,R,AP1KV,Z(1))
      R = Z(1)*COEF(31) + COEF(32)
      CALL INFLU(2601,R,IZCODA(1),RS)
      PAP1 = RS
      IF (AP1G.NE.0.) THEN
      IF (AP1G.LT.2.1.AND.J.EQ.1) THEN
      WRITE (NT6,FMT=10000)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10001)
      END IF
      KF = 1
      END IF
      K2 = 9
      CALL JNT(2602,PAP1,GAP1(1),GAP1(13))
      GAP1(11) = 2.
      GAP1(12) = 1.
      K2 = 1
      PAP1 = FINT(AP1G,GAP1(1),GAP1(13),2)
      END IF
      TAA(J+5) = PAP1
      END IF
      IF (NAP2.NE.0) THEN
      CALL JNT(2801,TAA(J),ZPA,Z(1))
      R = Z(1)
      IF (AP2K.NE.0.) THEN
      IF (AP2K.GT.AP2KV) AP2KV = AP2K
      END IF
      IF (NTAB(2804).NE.0) CALL JNT(564,R,AP2KV,Z(1))
      R = Z(1)*COEF(33) + COEF(34)
      CALL INFLU(2801,R,IZCODA(1),RS)
      PAP2 = RS
      IF (AP2G.NE.0.) THEN
      IF (AP2G.LT.2.1.AND.J.EQ.1) THEN
      WRITE (NT6,FMT=10000)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10000)
      END IF
      KF = 1
      END IF
      K2 = 9
      CALL JNT(2802,PAP2,GAP2(1),GAP2(13))
      GAP2(11) = 2.
      GAP2(12) = 1.
      K2 = 1
      PAP2 = FINT(AP2G,GAP2(1),GAP2(13),2)
      END IF
      TAA(J+11) = PAP2
      END IF
      TAA(J) = TAA(J) + TS
   10 CONTINUE
      TAA(11) = 99999999.
      TAA(17) = 99999999.
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ****  APPROACH ***** TAA,TCASA,TCASB '
      WRITE (NT6,FMT=*) TAA,TCASA,TCASB
      WRITE (NT6,FMT='(A)') ' AP1G,AP1K,AP1KV '
      WRITE (NT6,FMT=*) AP1G,AP1K,AP1KV
      WRITE (NT6,FMT='(A)') ' AP2G,AP2K,AP2KV '
      WRITE (NT6,FMT=*) AP2G,AP2K,AP2KV
      END IF
      RETURN
10000 FORMAT (1X,/,1X,
     +'INPUT ERROR *** APPROAH GRAD. GAP1 OR GAP2 LOWER THAN 2.1%'
     +)
10001 FORMAT ('APPROAH GRAD. GAP1 OR GAP2 LOWER THAN 2.1%')
      END
      REAL FUNCTION AR(
     &X
     &)
      REAL X
      REAL Y
      INTRINSIC AINT
      IF (X.GT.0.) THEN
      Y = X + 0.5
      ELSE IF (X.LT.0.) THEN
      Y = X - 0.5
      ELSE
      Y = X
      END IF
      Y = AINT(Y)
      AR = Y
      RETURN
      END
