      CHARACTER*12 FUNCTION CHGEXT(
     &FILENM,
     &EXT
     &)
      CHARACTER*3 EXT
      CHARACTER*12 FILENM
      INTEGER I
      CHGEXT = FILENM
      DO 10 I=12,1,-1
      IF (CHGEXT(I:I).EQ.'.') THEN
      CHGEXT(I+1:I+3) = EXT
      RETURN
      END IF
   10 CONTINUE
      DO 20 I=8,1,-1
      IF (CHGEXT(I:I).NE.' ') THEN
      CHGEXT(I+1:I+1) = '.'
      CHGEXT(I+2:I+4) = EXT
      RETURN
      END IF
   20 CONTINUE
      END
      SUBROUTINE CLOSFL(
     &NT
     &)
      INTEGER NT
      CHARACTER*1 ATXT
      LOGICAL OPN
      INQUIRE (UNIT=NT,OPENED=OPN)
      IF (OPN) THEN
      REWIND NT
      READ (NT,FMT='(A1)',ERR=10,END=10) ATXT
      CLOSE (NT)
      END IF
      RETURN
   10 CONTINUE
      CLOSE (NT,STATUS='DELETE')
      RETURN
      END
      SUBROUTINE CONCFL(
     &STR1,
     &STR2,
     &STRTOT
     &)
      CHARACTER*(*) STR1,STR2,STRTOT
      INTEGER INDX
      INTEGER I
      INTEGER N
      INTEGER GCAPST
      EXTERNAL GCAPST
      INTRINSIC INDEX
      INDX = GCAPST(CHAR(92),STR1)
      IF (INDX.GT.1) THEN
      STRTOT = STR1(1:INDX)//STR2
      ELSE
      STRTOT = STR2
      END IF
      END
      SUBROUTINE DECAL1(
     &A
     &)
      CHARACTER*80 A
      INTEGER I
      INTEGER J
      INTEGER K
      INTEGER KD
      INTEGER L
      CHARACTER*5 Z5
      DO 20 L = 1,5
      KD = 13* (L-1) + 9
      J = 0
      Z5 = ' '
      DO 10 K = 1,5
      I = KD + K
      IF (A(I:I).NE.' ') THEN
      J = J + 1
      Z5(J:J) = A(I:I)
      END IF
   10 CONTINUE
      A(KD+1:KD+5) = Z5
   20 CONTINUE
      RETURN
      END
      SUBROUTINE ECRIT(
     &ZON1,
     &NT
     &)
      INTEGER NT
      CHARACTER*80 ZON1
      INTEGER I
      CHARACTER ZON2(80)
      READ (ZON1,FMT='(80A1)') ZON2
      DO 10 I = 1,80
      IF (ZON2(I).EQ.'*') ZON2(I) = ' '
   10 CONTINUE
      WRITE (NT,FMT='(80A1)') ZON2
      RETURN
      END
      SUBROUTINE EFFECT(
     &IP,
     &MESS,
     &IOK
     &)
      INTEGER IP,IOK
      CHARACTER*34 MESS
      IOK = 0
      IF (IP.EQ.9) THEN
      MESS = 'AUTOFEATHER INOP.                 '
      ELSE IF (IP.EQ.11) THEN
      MESS = 'ECU OFF                           '
      ELSE IF (IP.EQ.12) THEN
      MESS = 'ONE SCU INOP.                     '
      ELSE IF (IP.EQ.13) THEN
      MESS = 'ANTI-SKID OFF                     '
      ELSE IF (IP.EQ.14) THEN
      MESS = 'LOW PRESSURE TYRE                 '
      ELSE IF (IP.EQ.17) THEN
      MESS = 'ONE TORQUE IND. INOP.             '
      ELSE IF (IP.EQ.18) THEN
      MESS = 'ECU ON - ATPCS OFF                '
      ELSE IF (IP.EQ.19) THEN
      MESS = 'EMERGENCY BRAKING                 '
      ELSE IF (IP.EQ.22) THEN
      MESS = 'VREF + 10 KT                      '
      ELSE IF (IP.EQ.23) THEN
      MESS = 'VREF + 5 KT                       '
      ELSE IF (IP.EQ.24) THEN
      MESS = 'EEC OFF                           '
      ELSE IF (IP.EQ.25) THEN
      MESS = 'AFU OFF                           '
      ELSE IF (IP.EQ.26) THEN
      MESS = 'ATPCS OFF                         '
      ELSE IF (IP.EQ.27) THEN
      MESS = 'FLAPS RETRACTED                   '
      ELSE IF (IP.EQ.28) THEN
      MESS = 'FLUIDS II/IV USE METHOD 1         '
      ELSE IF (IP.EQ.29) THEN
      MESS = 'FLUIDS II/IV USE METHOD 2         '
      ELSE IF (IP.EQ.33) THEN
      MESS = 'ONE ACW GEN INOP.                 '
      ELSE IF (IP.EQ.34) THEN
      MESS = 'ONE BRAKE INOP.                   '
      ELSE IF (IP.EQ.35) THEN
      MESS = 'FLIGHT LANDING GEAR DOWN          '
      ELSE IF (IP.EQ.36) THEN
      MESS = 'SPOILERS SYSTEM INOP.             '
c-    ELSE IF (IP.EQ.37) THEN
c-    MESS = 'TWO ENGINES AT RTO POWER          '
cc    PRTO = 'TWO ENGINES AT RTO POWER'
cc    IOK = 2
      ELSE IF (IP.EQ.42) THEN
      MESS = 'REDUCED FLAPS 15                  '
      ELSE IF (IP.EQ.44) THEN
      MESS = 'REDUCED FLAPS 25                  '
      ELSE
      IOK = 1
      END IF
      END
