      REAL ZMALL2
      REAL WMILL2
      REAL WMALL2
      REAL SMILL2
      REAL SMALL2
      REAL V2SMIL
      REAL V2SMAL
      REAL V1RMIL
      REAL V1RMAL
      REAL PMILBT
      REAL PMALBT
      REAL PMILL1
      REAL PMALL1
      REAL PMILL2
      REAL PMALL2
      REAL ALIM(20)
      REAL ZLIM(40)
      COMMON /LIMIT1/IXTRPL
      COMMON /LIMIT2/ZLIM,PMIN,PINI,PMAX,V2VSMI,V2VSMA,V1VRMI,V1VRI,
     +V1VRMA,ZMIN,ZMAX,DTMIN,DTMAX1,DTMAX2,ALIM,SSGMIN,
     +TMILBT,TMALBT,ZMILBT,ZMALBT,WMILBT,WMALBT,SMILBT,SMALBT,
     +TMILL1,TMALL1,ZMILL1,ZMALL1,WMILL1,WMALL1,SMILL1,SMALL1,
     +TMILL2,TMALL2,ZMILL2,ZMALL2,WMILL2,WMALL2,SMILL2,SMALL2,
     +V2SMIL,V2SMAL,V1RMIL,V1RMAL,PMILBT,PMALBT,PMILL1,PMALL1,
     +PMILL2,PMALL2
      CHARACTER*10 RBOOST
      CHARACTER*12 PWDQ
      CHARACTER*12 PWDQ1
      CHARACTER*12 PWDQ2
      CHARACTER*14 PBRACT
      CHARACTER*14 PBRAL1
      CHARACTER*14 PBRAL2
      CHARACTER*15 PDELBR
      CHARACTER*16 PV1VR
      CHARACTER*15 PV2VS
      CHARACTER*15 PBOOST
      CHARACTER*15 PBOOSL
      CHARACTER*16 PVQ
      CHARACTER*20 PDQNH
      CHARACTER*20 PGRAD
      CHARACTER*21 PACA
      CHARACTER*21 PACL
      CHARACTER*21 PAIA
      CHARACTER*21 PAIL
      CHARACTER*21 PANEA
      CHARACTER*21 PANEL
      CHARACTER*21 PREVL
      CHARACTER*24 PRTO
      CHARACTER*34 P1535
      CHARACTER*34 PAC
      CHARACTER*34 PAI
      CHARACTER*34 PREV
      CHARACTER*34 PRWYS
      CHARACTER*34 PANE(4)
      COMMON /OUTA/PV2VS,PV1VR,PVQ,PRWYS,PAC,PAI,PANE,P1535,PREV,PWDQ,
     +PWDQ1,PWDQ2,PGRAD,PDQNH,PACA,PACL,PAIA,PAIL,PANEA,PANEL,
     +PREVL,PBOOST,PBOOSL,PRTO,RBOOST,PDELBR,PBRACT,PBRAL1,PBRAL2
      REAL DQNH(2)
      REAL DQVMCA(2)
      REAL DQVMCG(2)
      REAL DTOW(5,2)
      REAL DV1MAX(5,2)
      REAL DV1MIN(5,2)
      REAL DV1MOY(5,2)
      REAL DV2(5,2)
      REAL DVR(5,2)
      COMMON /EFFET/DQNH,DTOW,DV1MIN,DV1MAX,DV1MOY,DVR,DV2,DQVMCA,DQVMCG
      INTEGER MC
      REAL A
      REAL DIFLE1
      REAL DIFLE2
      REAL PFR
      REAL RF
      REAL V2VMU
      REAL V2VSU
      REAL V1MBB
      INTEGER I
      INTEGER IDCAS
      INTEGER IDCASL
      INTEGER IDEG
      INTEGER J
      INTEGER NL
      INTEGER NL4
      CHARACTER*4 ICAL
      CHARACTER*4 IWIN
      REAL VF(19)
      REAL XLPQ(3)
      REAL XZF(3)
      REAL Z(12)
      REAL ZOUTQ(60)
      REAL FINT,FINTV
      EXTERNAL FINT,FINTV
      EXTERNAL JNT,PIST
      INTRINSIC ABS,INT,MOD
      SAVE NL,NL4
      IF (MC.EQ.3) THEN
      GO TO 50
      ELSE IF (MC.EQ.0) THEN
      GO TO 30
      ELSE IF (MC.EQ.2) THEN
      IDCAS = 0
      IDCASL = 0
      RETURN
      ELSE IF (MC.EQ.7) THEN
      IF (DRYCHL.NE.0) THEN
      IDCASL = IDCASL + 1
      WRITE (NTBL(INTB)) ZOUL1,ZOUL2
      WRITE (NTBL(INTB)) IDCASL
      WRITE (NTBL(INTB)) NPIST,QFU,ZGP,ICFA1,ICFL1,ICFA2,ICFL2,TLDP,
     +PP,IP,IT,IL,IH,IWQ,NDATE,VQ0
      WRITE (NTBL(INTB)) IAC,ITO,IAP,IZCODA,IZCODL,NEFFA,NEFFL,KOM8,
     +KOM11,KOM12,KOM15,KOM16,AZA,AZB,AZL,LZON1,LZON2,LZON3,LZON4,
     +CFL1,CFL2,CGPL,IETA,LTITRL,TEXAP1,TEXAP2,CAR1,CAR2,CAR3,
     +CAR5,CAR7
      WRITE (NTBL(INTB)) DRYCHL,CHECK1,CHECK2,KATT,KAT2,KISU,NTA,
     +VQL,NVQL,LAT1,LAT2
      END IF
      RETURN
      ELSE IF (MC.EQ.8) THEN
      IF (DRYCHL.NE.0) THEN
      WRITE (NTBL(INTB)) ZOUL1,ZOUL2
      END IF
      RETURN
      ELSE IF (MC.EQ.9) THEN
      IF (DRYCHK.NE.0) THEN
      WRITE (NTB(INTB)) DIVER,IOBFTO,ZPQNH
      END IF
      RETURN
      ELSE IF (MC.EQ.10) THEN
      IF (DRYCHK.NE.0) THEN
      WRITE (NTB(INTB)) TCAS,PSTRUC,PRON,NPROND,IPRON,PVMC,IMCA
      END IF
      RETURN
      ELSE IF (MC.EQ.11) THEN
      IF (DRYCHK.NE.0) THEN
      DO 5 J=1,NVQT
      DO 3 I=IPRON(J),NPROND
      ZOUT(1)  = ITMAX(I,J)
      ZOUT(3)  = TPKG(I,J)
      ZOUT(4)  = JJ1(I,J)
      ZOUT(5)  = JJ2(I,J)
      ZOUT(45) = TVMIN(I,J)
      ZOUT(46) = TVMAX(I,J)
      ZOUT(48) = TV2(I,J)
      WRITE (NTB(INTB)) ZOUT
    3 CONTINUE
    5 CONTINUE
      END IF
      RETURN
      ELSE IF (MC.EQ.12) THEN
      WRITE (NTB(INTB)) ZOUTE
      RETURN
      ELSE IF (MC.EQ.5.OR.MC.EQ.6) THEN
      NL = NL + 1
      NL4 = NL4 + 1
      IF (KSB.EQ.1) THEN
      WRITE (NT7) ZOUT
      END IF
      IF (DRYCHK.NE.0) WRITE (NTB(INTB)) ZOUT,IHSDMI,ZP,IVMCA(7),
     +IVMCG(7),V1MBB
      RETURN
      ELSE IF (MC.EQ.13) THEN
      ZOUTQ(47) = FINTV(VRP,CVIT(1))
      IF (ABS(V1MAXP-V1MINP).GT.EPSI) THEN
      IF ((KSP.EQ.1).OR.(KSP.EQ.2)) THEN
      V1VRMB = 0.5*(V1VRP+VOPTP)
      V1MBAL = V1VRMB * ZOUTQ(47)
      END IF
      IF (KSP.EQ.3) THEN
      ZOUTQ(9) = V1VRP
      XLPQ(1) = XLP(1)
      XLPQ(2) = XLP(2)
      XLPQ(3) = V1VRP
      CALL PIST(5,XLPQ(1),XLE(1),RF)
      ZOUTQ(12) = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLPQ(1),XLE(1),RF)
      ZOUTQ(13) = (RF*COEF(3)+COEF(4)+ATOD)/UL
      XLPQ(3) = VOPTP
      ZOUTQ(14) = VOPTP
      CALL PIST(5,XLPQ(1),XLE(1),RF)
      ZOUTQ(17) = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLPQ(1),XLE(1),RF)
      ZOUTQ(18) = (RF*COEF(3)+COEF(4)+ATOD)/UL
      DIFLE1 = ZOUTQ(12) - ZOUTQ(13)
      DIFLE2 = ZOUTQ(17) - ZOUTQ(18)
      IF (DIFLE1*DIFLE2.GT.0) THEN
      IF (ABS(DIFLE1).LT.ABS(DIFLE2)) THEN
      V1VRMB = ZOUTQ(9)
      ELSE
      V1VRMB = ZOUTQ(14)
      END IF
      V1MBAL = V1VRMB * ZOUTQ(47)
      ELSE
      IF (ABS(DIFLE1).LT.ABS(DIFLE2)) THEN
      V1VRMB = ZOUTQ(9)
   11 CONTINUE
      XLPQ(3) = V1VRMB + EPSI
      CALL PIST(5,XLPQ(1),XLE(1),RF)
      ASDMBA = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLPQ(1),XLE(1),RF)
      TODMBA = (RF*COEF(3)+COEF(4)+ATOD)/UL
      DIFLE2 = ASDMBA - TODMBA
      IF (DIFLE1*DIFLE2.LT.0) GO TO 12
      V1VRMB = XLPQ(3)
      DIFLE1 = DIFLE2
      GO TO 11
   12 CONTINUE
      IF (ABS(DIFLE1).LT.ABS(DIFLE2)) THEN
      V1MBAL = V1VRMB * ZOUTQ(47)
      ELSE
      V1VRMB = XLPQ(3)
      V1MBAL = V1VRMB * ZOUTQ(47)
      END IF
      ELSE
      V1VRMB = ZOUTQ(14)
   15 CONTINUE
      XLPQ(3) = V1VRMB - EPSI
      CALL PIST(5,XLPQ(1),XLE(1),RF)
      ASDMBA = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLPQ(1),XLE(1),RF)
      TODMBA = (RF*COEF(3)+COEF(4)+ATOD)/UL
      DIFLE1 = ASDMBA - TODMBA
      IF (DIFLE1*DIFLE2.LT.0) GO TO 16
      V1VRMB = XLPQ(3)
      DIFLE2 = DIFLE1
      GO TO 15
   16 CONTINUE
      IF (ABS(DIFLE2).LT.ABS(DIFLE1)) THEN
      V1MBAL = V1VRMB * ZOUTQ(47)
      ELSE
      V1VRMB = XLPQ(3)
      V1MBAL = V1VRMB * ZOUTQ(47)
      END IF
      END IF
      END IF
      END IF
      ELSE
      V1MBAL = FINTV(V1MAXP,CVIT(1))
      END IF
      RETURN
      END IF
      ZOUT(2) = VQP
      ZOUT(3) = XLP(1)*UP
      ZOUT(6) = XLP(2)
      ZOUT(7) = V2P
      ZOUT(8) = VRP
      ZOUT(47) = FINTV(VRP,CVIT(1))
      V2VSU = FINTV(XLP(1),VMU)
      V2VMU = V2VSU*VS
      ZOUTS(4) = V2VMU + DV2CP
      IF (CVIT(21).EQ.0.) THEN
      K2 = 1
      K1 = 1
      CALL JNT(2205,XLP(1),V2P,Z(1))
      ZOUT(48) = Z(1)
      CALL JNT(2205,XLP(1),V2VMU,Z(1))
      ZOUTS(5) = Z(1)
      ELSE
      ZOUT(48) = FINTV(V2P,CVIT(21))
      ZOUTS(5) = FINTV(V2VMU,CVIT(21))
      END IF
      A = ZOUT(43)
      ZOUT(44) = FINTV(A,CVIT(1))
      A = ZOUT(51)*1.05
      ZOUT(52) = FINTV(A,CVIT(1))
      A = ZOUT(51)*1.1
      IF (CVIT(21).EQ.0.) THEN
      CALL JNT(2205,XLP(1),V2P,Z(1))
      ZOUT(53) = Z(1)
      ELSE
      ZOUT(53) = FINTV(A,CVIT(21))
      END IF
      IF (ABS(V1MAXP-V1MINP).GT.EPSI) THEN
      ZOUT(9) = V1VRP
      ZOUT(10) = V1MINP
      ZOUT(45) = FINTV(V1MINP,CVIT(1))
      XLP(3) = V1VRP
      CALL PIST(2,XLP(1),XLE(1),RF)
      ZOUT(11) = (RF*COEF(5)+COEF(6)+ATOD)/UL
      CALL PIST(5,XLP(1),XLE(1),RF)
      ZOUT(12) = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      ZOUT(13) = (RF*COEF(3)+COEF(4)+ATOD)/UL
      IF (KSP.EQ.1) THEN
      V1VRMB = 0.5*(V1VRP+VOPTP)
      V1MBAL = V1VRMB * ZOUT(47)
      XLP(3) = V1VRMB
      CALL PIST(2,XLP(1),XLE(1),RF)
      TORMBA = (RF*COEF(5)+COEF(6)+ATOD)/UL
      CALL PIST(5,XLP(1),XLE(1),RF)
      ASDMBA = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      TODMBA = (RF*COEF(3)+COEF(4)+ATOD)/UL
      END IF
      END IF
      XLP(3) = VOPTP
      ZOUT(14) = VOPTP
      ZOUT(15) = V1MAXP
      ZOUT(46) = FINTV(V1MAXP,CVIT(1))
      CALL PIST(2,XLP(1),XLE(1),RF)
      ZOUT(16) = (RF*COEF(5)+COEF(6)+ATOD)/UL
      CALL PIST(5,XLP(1),XLE(1),RF)
      ZOUT(17) = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      ZOUT(18) = (RF*COEF(3)+COEF(4)+ATOD)/UL
      ZOUT(19) = V1VRLP
      ZOUT(20) = PMAXLP*UP
      ZOUTS(2) = PMAXP2*UP
      ZOUTS(3) = V1VRP2
      CALL PIST(6,XLP(1),XVE(1),RF)
      RF = RF*COEF(19) + COEF(20)
      ZOUT(21) = RF
      IF (E(25).EQ.1.) THEN
      CALL PIST(3,XLP(1),XLE(1),RF)
      ZOUT(56) = (RF*COEF(15)+COEF(16)+ATOD)/UL
      CALL PIST(4,XLP(1),XLE(1),RF)
      ZOUT(57) = (RF*COEF(17)+COEF(18)+ATOD)/UL
      END IF
      IF (TZREF(6).NE.A9) THEN
      IDEG = XMAS(11) + EPSI
      VF(10) = A9
      XZF(2) = XLP(2)
      XZF(3) = XLP(3)
      DO 20 I = 9,1,-1
      XZF(1) = XMAS(I)
      CALL PIST(6,XZF(1),XVE(1),RF)
      VF(10-I) = RF*COEF(19) + COEF(20)
      VF(20-I) = XMAS(I)
   20 CONTINUE
      IF (ABS(V1MAXP-V1MINP).GT.EPSI) THEN
      IF ((ZOUT(4).EQ.6.).OR.(ZOUT(5).EQ.6.)) THEN
      ZOUTS(1) = ZOUT(3)
      ELSE
      PFR = FINT(V1MINP,VF(1),VF(11),IDEG)
      ZOUTS(1) = PFR*UP
      END IF
      END IF
      IF ((ZOUT(4).EQ.6.).OR.(ZOUT(5).EQ.6.)) THEN
      ZOUT(60) = ZOUT(3)
      ELSE
      PFR = FINT(V1MAXP,VF(1),VF(11),IDEG)
      ZOUT(60) = PFR*UP
      END IF
      END IF
      IF ((ABS(V1MAXP-V1MINP).GT.EPSI).AND.(KSP.EQ.3)) THEN
      DIFLE1 = ZOUT(12) - ZOUT(13)
      DIFLE2 = ZOUT(17) - ZOUT(18)
      IF (DIFLE1*DIFLE2.GT.0) THEN
      IF (ABS(DIFLE1).LT.ABS(DIFLE2)) THEN
      V1VRMB = ZOUT(9)
      ELSE
      V1VRMB = ZOUT(14)
      END IF
      XLP(3) = V1VRMB
      CALL PIST(5,XLP(1),XLE(1),RF)
      ASDMBA = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      TODMBA = (RF*COEF(3)+COEF(4)+ATOD)/UL
      CALL PIST(2,XLP(1),XLE(1),RF)
      TORMBA = (RF*COEF(5)+COEF(6)+ATOD)/UL
      V1MBAL = V1VRMB * ZOUT(47)
      ELSE
      IF (ABS(DIFLE1).LT.ABS(DIFLE2)) THEN
      V1VRMB = ZOUT(9)
   21 CONTINUE
      XLP(3) = V1VRMB + EPSI
      CALL PIST(5,XLP(1),XLE(1),RF)
      ASDMBA = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      TODMBA = (RF*COEF(3)+COEF(4)+ATOD)/UL
      DIFLE2 = ASDMBA - TODMBA
      IF (DIFLE1*DIFLE2.LT.0) GO TO 22
      V1VRMB = XLP(3)
      DIFLE1 = DIFLE2
      GO TO 21
   22 CONTINUE
      IF (ABS(DIFLE1).LT.ABS(DIFLE2)) THEN
      XLP(3) = V1VRMB
      CALL PIST(5,XLP(1),XLE(1),RF)
      ASDMBA = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      TODMBA = (RF*COEF(3)+COEF(4)+ATOD)/UL
      CALL PIST(2,XLP(1),XLE(1),RF)
      TORMBA = (RF*COEF(5)+COEF(6)+ATOD)/UL
      V1MBAL = V1VRMB * ZOUT(47)
      ELSE
      V1VRMB = XLP(3)
      V1MBAL = V1VRMB * ZOUT(47)
      CALL PIST(2,XLP(1),XLE(1),RF)
      TORMBA = (RF*COEF(5)+COEF(6)+ATOD)/UL
      END IF
      ELSE
      V1VRMB = ZOUT(14)
   25 CONTINUE
      XLP(3) = V1VRMB - EPSI
      CALL PIST(5,XLP(1),XLE(1),RF)
      ASDMBA = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      TODMBA = (RF*COEF(3)+COEF(4)+ATOD)/UL
      DIFLE1 = ASDMBA - TODMBA
      IF (DIFLE1*DIFLE2.LT.0) GO TO 26
      V1VRMB = XLP(3)
      DIFLE2 = DIFLE1
      GO TO 25
   26 CONTINUE
      IF (ABS(DIFLE2).LT.ABS(DIFLE1)) THEN
      XLP(3) = V1VRMB
      CALL PIST(5,XLP(1),XLE(1),RF)
      ASDMBA = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      TODMBA = (RF*COEF(3)+COEF(4)+ATOD)/UL
      CALL PIST(2,XLP(1),XLE(1),RF)
      TORMBA = (RF*COEF(5)+COEF(6)+ATOD)/UL
      V1MBAL = V1VRMB * ZOUT(47)
      ELSE
      V1VRMB = XLP(3)
      V1MBAL = V1VRMB * ZOUT(47)
      CALL PIST(2,XLP(1),XLE(1),RF)
      TORMBA = (RF*COEF(5)+COEF(6)+ATOD)/UL
      END IF
      END IF
      END IF
      END IF
      IF (ABS(V1MAXP-V1MINP).GT.EPSI) THEN
      V1MBB = V1MBAL
      ELSE
      V1MBB = ZOUT(46)
      END IF
      IF (MC.EQ.1) GO TO 40
   30 CONTINUE
      IF (KSP.EQ.2) GO TO 50
      IF (AV.EQ.'ATRA') CFTO(1:3) = '  F'
      NL = 0
      IF (DRYCHK.EQ.1) THEN
      IF (MICRO.EQ.0) CALL TAB3(NT3D,NL)
      ELSE
      CALL TAB3(NT3,NL)
      END IF
      IF (KS4.EQ.0) GO TO 50
      NL4 = 0
      IF (DRYCHK.EQ.1) THEN
      IF (MICRO.EQ.0) CALL TAB4(NT4D,NL4)
      ELSE
      CALL TAB4(NT4,NL4)
      END IF
      GO TO 50
   40 CONTINUE
      IF (KSP.NE.2) THEN
      NL = NL + 1
      IF (DRYCHK.EQ.1) THEN
      IF (MICRO.EQ.0) CALL TAB3(NT3D,NL)
      ELSE
      CALL TAB3(NT3,NL)
      END IF
      IF (KS4.NE.0) THEN
      NL4 = NL4 + 1
      IF (DRYCHK.EQ.1) THEN
      IF (MICRO.EQ.0) CALL TAB4(NT4D,NL4)
      ELSE
      CALL TAB4(NT4,NL4)
      END IF
      IF (KS.GT.0) THEN
      WRITE (NT6,FMT='(/,A)') ' ENGOUT***  ZOUT '
      WRITE (NT6,FMT=10300) (ZOUT(I),I,I=1,60)
      END IF
      END IF
      END IF
   50 CONTINUE
      IF (MC.EQ.3) THEN
      IF (KSB.EQ.1) WRITE (NT7) ZOUT
      IF (DRYCHK.NE.0) THEN
      IDCAS = IDCAS + 1
      WRITE (NTB(INTB)) ZOUT,A9
      WRITE (NTB(INTB)) IDCAS
      END IF
      IF (CODCAL.EQ.1) THEN
      IWIN = ICTA(2)
      ELSE
      IWIN = ICTA(1)
      END IF
      ICAL = ICTA(3)
      IF (V2VS.NE.0) THEN
      ICAL = ICTA(4)
      ELSE
      ICAL = ICTA(3)
      END IF
      IF (KSB.EQ.1) THEN
      WRITE (NT7) NPIST,QFU,ICFTO,ZGP,TORP,ASDP,TODP,PP,IP,IT,IL,
     +IWQ,NDATE,KOM6,IWIN,ICAL,VQ0,IH
      WRITE (NT7) IAC,ITO,IZCODP,KOMP,KOM1,KOM2
      END IF
      IF (DRYCHK.NE.0) THEN
      WRITE (NTB(INTB)) NPIST,QFU,ICFTO,ZGP,TORP,ASDP,TODP,PP,IP,IT,
     +IL,IH,IWQ,IQ,NDATE,KOM6,IWIN,ICAL,VQ0,TOR,ASD,TOD,DP,HP,
     +NOBST,KOBS
      WRITE (NTB(INTB)) IAC,ITO,IAP,IZCODP,IZCODT,NEFFT,KOMP,KOM1,
     +KOM2,KOM7,KOM8,KOM13,KOM14,IETA,CFTO,CGPT,LTITR,PSTRUC,CAR1,
     +CAR2,CAR3,CAR5,CAR6
      WRITE (NTB(INTB)) DRYCHK,KTR,KST,KISU,KMU,KTAB1,NCT1,NCT4,NTA,
     +VQT,NVQT,NTPU,FV1VR,V2VS,AERO(12),ZLIM(16),ZLIM(17),NGRAD1,
     +NGRAD2,DQNH
      WRITE (NTB(INTB)) PV2VS,PV1VR,PVQ,PGRAD,PAC,PAI,PANE,PWDQ1,
     +PWDQ2,PREV,P1535,PRWYS,CFA1,CFA2,PWDQ,ZWID,ZWID2,PDQNH
      END IF
      RETURN
      END IF
      IF (MC.NE.0) THEN
      IF (KSB.EQ.1) WRITE (NT7) ZOUT
      IF (DRYCHK.NE.0) WRITE (NTB(INTB)) ZOUT,IHSDMI,ZP,IVMCA(7),
     +IVMCG(7),V1MBB
      END IF
      RETURN
10300 FORMAT (4 (1X,F13.3,' (',I2,') '))
      END
      REAL FUNCTION FINDIV(
     &A,
     &X,
     &Y,
     &NPOIN,
     &IDG
     &)
      REAL A
      INTEGER IDG,NPOIN
      REAL X(*),Y(*)
      INTEGER I
      REAL X1(20)
      REAL Y1(20)
      REAL FINT,FINTID
      EXTERNAL FINT,FINTID
      IF ((X(NPOIN).EQ.0.).OR.(Y(NPOIN).EQ.0.)) THEN
      FINDIV = A
      ELSE
      DO 10 I=1,NPOIN-3
      X1(I) = X(NPOIN-2-I)
      Y1(I) = Y(NPOIN-2-I)
   10 CONTINUE
      X1(NPOIN-2) = X(NPOIN-2)
      Y1(NPOIN-2) = Y(NPOIN-2)
      IF (IDG.EQ.0) THEN
      X1(NPOIN-1) = X(NPOIN-1)
      X1(NPOIN) = X(NPOIN)
      Y1(NPOIN-1) = Y(NPOIN-1)
      Y1(NPOIN) = Y(NPOIN)
      FINDIV = FINTID(A,X1,Y1,NPOIN)
      ELSE
      FINDIV = FINT(A,X1(1),Y1(1),IDG)
      END IF
      END IF
      RETURN
      END
      REAL FUNCTION FINT(
     &A,
     &X,
     &Y,
     &K
     &)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      REAL AK1
      REAL AK2
      REAL ASD
      REAL PP
      REAL TA
      REAL TISA
      REAL TOD
      REAL TOR
      REAL VC1
      REAL VENT
      REAL V2VS
      REAL WIDTH
      REAL ZP
      INTEGER IOBFTO
      INTEGER KF
      INTEGER NOBST
      INTEGER KOBS
      INTEGER KCGA
      INTEGER KCGL
      INTEGER KCGT
      REAL D(MAXOBS)
      REAL DGA(11)
      REAL DIST(10)
      REAL DP(MAXOBS)
      REAL H(MAXOBS)
      REAL HP(MAXOBS)
      REAL PEN1SI(24)
      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
      REAL TRAJ(32)
      REAL TRAJV(10)
      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      REAL A
      INTEGER K
      REAL X(100),Y(100)
      INTEGER I
      INTEGER J
      INTEGER KN
      INTEGER L
      INTEGER M
      INTEGER N
      REAL Z(3)
      IF (A.GE.99999999.) GO TO 200
      IF (X(2).LE.X(1)) GO TO 210
      N = K
      IF (N.EQ.1) GO TO 30
      IF (A.LT.X(1)) N = 1
      IF (N.EQ.1) GO TO 30
      DO 10 KN = 2,100
      IF (X(KN).EQ.99999999.) GO TO 20
   10 CONTINUE
   20 CONTINUE
      IF (A.GT.X(KN-1)) N = 1
   30 CONTINUE
      I = 1
      IF (A-X(1)) 70,60,40
   40 CONTINUE
      DO 50 I = 2,100
      IF (X(I).LE.X(I-1)) GO TO 210
      IF (A-X(I)) 70,60,50
   50 CONTINUE
      IF (K6.EQ.1) WRITE (NT6,FMT=10020)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10021)
      END IF
      GO TO 220
   60 CONTINUE
      FINT = Y(I)
      RETURN
   70 CONTINUE
      IF (I- (N+2)/2) 80,80,90
   80 CONTINUE
      I = 1
      GO TO 120
   90 CONTINUE
      I = I - (N+2)/2
      DO 100 J = 1,N
      L = I + J
      IF (X(L)-99999999.) 100,110,190
  100 CONTINUE
      GO TO 120
  110 CONTINUE
      I = I + J - N - 1
  120 CONTINUE
      M = N
      DO 130 J = 1,M
      L = I + J
      Z(J) = (A-X(I))* (Y(L)-Y(I))/ (X(L)-X(I)) + Y(I)
  130 CONTINUE
  140 CONTINUE
      IF (M-1) 180,180,150
  150 CONTINUE
      M = M - 1
      I = I + 1
      DO 160 J = 1,M
      L = I + J
      Z(J+1) = (A-X(I))* (Z(J+1)-Z(1))/ (X(L)-X(I)) + Z(1)
  160 CONTINUE
      DO 170 J = 1,M
      Z(J) = Z(J+1)
  170 CONTINUE
      GO TO 140
  180 CONTINUE
      FINT = Z(1)
      RETURN
  190 CONTINUE
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) TA,VENT
      IF (K6.EQ.1) WRITE (NT6,FMT=10020)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10021)
      END IF
      GO TO 220
  200 CONTINUE
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) TA,VENT
      IF (K6.EQ.1) WRITE (NT6,FMT=10000)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10001)
      END IF
      GO TO 220
  210 CONTINUE
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) TA,VENT
      IF (K6.EQ.1) WRITE (NT6,FMT=10010)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10011)
      END IF
  220 CONTINUE
      KF = 1
      FINT = 99999999.
      IF (K6.EQ.1) WRITE (NT6,FMT=10030) A,(X(I),I=1,20)
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) Y
      RETURN
10000 FORMAT (/,/,10X,'ARG. GRATER THAN 99999999.')
10001 FORMAT ('ARG. GREATER THAN 99999999.')
10010 FORMAT (/,/,10X,'NOT INCREASING ABSCISSAS')
10011 FORMAT ('NOT INCREASING ABSCISSAS')
10020 FORMAT (/,/,10X,'ABSCISSAS NOT ENDED BY 99999999.')
10021 FORMAT ('ABSCISSAS NOT ENDED BY 99999999.')
10030 FORMAT (2X,'ARG = ',F14.1,/,2X,'ABSC.= ',4 (7 (2X,F14.5),/))
10040 FORMAT (2X,'ORD.= ',3 (7 (2X,F14.5),/),6 (2X,F14.5))
10050 FORMAT (10X,'TEMPERATURE=',F6.2,10X,'VENT=',F7.2)
      END
      REAL FUNCTION FINTID(
     &A,
     &X,
     &Y,
     &NPOIN
     &)
      REAL A
      INTEGER NPOIN
      REAL X(*),Y(*)
      REAL Z
      INTEGER IDG
      REAL FINT
      EXTERNAL FINT
      IF (X(NPOIN).NE.0.) GO TO 10
      FINTID = A
      RETURN
   10 CONTINUE
      IDG = X(NPOIN-1) + .001
      IF (IDG.GT.3) IDG = 3
      Z = FINT(A,X(1),Y(1),IDG)
      FINTID = Z
      RETURN
      END
      REAL FUNCTION FINTV(
     &ABS,
     &CURV
     &)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      REAL AK1
      REAL AK2
      REAL ASD
      REAL PP
      REAL TA
      REAL TISA
      REAL TOD
      REAL TOR
      REAL VC1
      REAL VENT
      REAL V2VS
      REAL WIDTH
      REAL ZP
      INTEGER IOBFTO
      INTEGER KF
      INTEGER NOBST
      INTEGER KOBS
      INTEGER KCGA
      INTEGER KCGL
      INTEGER KCGT
      REAL D(MAXOBS)
      REAL DGA(11)
      REAL DIST(10)
      REAL DP(MAXOBS)
      REAL H(MAXOBS)
      REAL HP(MAXOBS)
      REAL PEN1SI(24)
      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
      REAL TRAJ(32)
      REAL TRAJV(10)
      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      REAL ABS
      REAL CURV(*)
      INTEGER IDG
      INTEGER L
      INTEGER N1
      INTEGER N2
      INTEGER N3
      INTEGER NPMIN
      INTEGER NX
      REAL FINT
      EXTERNAL FINT
      IF (CURV(1).EQ.0.) GO TO 20
      NX = CURV(3)
      IDG = CURV(2)
      N1 = 4
      N2 = N1 + NX + 1
      N3 = N1 + 2*NX
      NPMIN = IDG + 1
      IF (NX.GE.NPMIN) GO TO 10
      IF (K6.EQ.1) WRITE (NT6,FMT=10000)
      IF (K6.EQ.1) WRITE (NT6,FMT=10010) (CURV(L),L=1,N3)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10020)
      END IF
      KF = 1
   10 CONTINUE
      FINTV = FINT(ABS,CURV(N1),CURV(N2),IDG)
      RETURN
   20 CONTINUE
      FINTV = ABS
      RETURN
10000 FORMAT (/,/,
     +' ** NUMBER OF ABSC. NOT ENOUGH DETECTED BY *FINTV* - SEE CURVE BE
     +LOW :',/)
10010 FORMAT (7 (2X,F14.5))
10020 FORMAT ('NUMBER OF ABSCISSA TO LOW FOR INTERPOLATION')
      END
      INTEGER FUNCTION GCAPST (
     &CARACT,
     &STRING
     &)
      CHARACTER CARACT
      CHARACTER*(*) STRING
      INTEGER LENGTH
      INTEGER I
      INTEGER POSCAR
      LOGICAL FOUND
      LOGICAL CONTIN
      POSCAR = 0
      LENGTH = len(STRING)
      I     = LENGTH
      FOUND = .FALSE.
      CONTIN = .TRUE.
   10 CONTINUE
      IF (STRING(I:I).EQ.CARACT) then
      FOUND = .TRUE.
      POSCAR = I
      ELSE IF (I.GT.1) then
      I = I-1
      ELSE IF (I.EQ.1) then
      CONTIN = .FALSE.
      END IF
      IF ((CONTIN).and.(.not.FOUND).and.(I.GE.1)) GO TO 10
      GCAPST = POSCAR
      RETURN
      END
