      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      INTEGER NPMAX
      REAL DIVER(20)
      REAL VNUM(20000)
      INTEGER NTAB(4200)
      COMMON /TABLE1/NTAB,NPMAX
      COMMON /TABLE2/VNUM,DIVER
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      REAL RES,VX
      INTEGER N
      INTEGER IZCOD(7)
      REAL VAL
      REAL Y
      INTEGER IC
      INTEGER KC
      INTEGER KLC
      INTEGER L
      INTEGER N1
      REAL Z(12)
      EXTERNAL JNT
      VAL = VX
      KA = 0
      N1 = 5
      K1 = 1
      K2 = 1
      DO 10 KC = 30,32
      KLC = N + KC - 1
      IF (NTAB(KLC).EQ.0) GO TO 10
      CALL JNT(KLC,VAL,Y,Z(1))
      VAL = Z(1)
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)') ' ***INFLU FIXE*** KLC VAL '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) KLC,VAL
   10 CONTINUE
      IF (N.LE.481) N1 = 7
      DO 20 L = 1,N1
      IF (IZCOD(L).NE.0) KA = 1
   20 CONTINUE
      IF (KA.EQ.0) GO TO 40
      DO 30 IC = 1,N1
      KC = IZCOD(IC)
      IF (KC.EQ.0) GO TO 30
      KLC = N + KC - 1
      IF (NTAB(KLC).EQ.0) GO TO 30
      CALL JNT(KLC,VAL,Y,Z(1))
      VAL = Z(1)
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' ***INFLU DEMANDE*** KLC VAL '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) KLC,VAL
   30 CONTINUE
   40 CONTINUE
      RES = VAL
      RETURN
      END
