      CALL TRANSA(IDON(1),CTIF(IAD),NMOT)
      END IF
      ELSE IF (NOM.EQ.'KOCA') THEN
      IF (NP1.GT.40) THEN
      GO TO 580
      ELSE
      CALL TRANSA(IDON(1),KOCA(IAD),NMOT)
      END IF
      ELSE IF (NOM.EQ.'CAR1') THEN
      IF (NP1.GT.3) THEN
      GO TO 580
      ELSE
      CALL TRANSA(IDON(1),CAR1(IAD),NMOT)
      END IF
      ELSE IF (NOM.EQ.'CAR2') THEN
      IF (NP1.GT.5) THEN
      GO TO 580
      ELSE
      CALL TRANSA(IDON(1),CAR2(IAD),NMOT)
      END IF
      ELSE IF (NOM.EQ.'CAR3') THEN
      IF (NP1.GT.2) THEN
      GO TO 580
      ELSE
      CALL TRANSA(IDON(1),CAR3(IAD),NMOT)
      END IF
      ELSE IF (NOM.EQ.'CAR4') THEN
      IF (NP1.GT.5) THEN
      GO TO 580
      ELSE
      CALL TRANSA(IDON(1),CAR4(IAD),NMOT)
      END IF
      ELSE IF (NOM.EQ.'CAR5') THEN
      IF (NP1.GT.40) THEN
      GO TO 580
      ELSE
      CALL TRANSA(IDON(1),CAR5(IAD),NMOT)
      END IF
      ELSE IF (NOM.EQ.'CAR6') THEN
      IF (NP1.GT.20) THEN
      GO TO 580
      ELSE
      CALL TRANSA(IDON(1),CAR6(IAD),NMOT)
      END IF
      ELSE IF (NOM.EQ.'CAR7') THEN
      IF (NP1.GT.20) THEN
      GO TO 580
      ELSE
      CALL TRANSA(IDON(1),CAR7(IAD),NMOT)
      END IF
      ELSE
      IF (NT.EQ.NT5) THEN
      GO TO 610
      END IF
      END IF
      IF (K.EQ.1) WRITE (NT6,FMT=10000) NOM,IAD,NMOT,
     +(IDON(L),L=1,NMOT)
      GO TO 400
  580 CONTINUE
      IF (K6.EQ.1) WRITE (NT6,FMT=10090) NOM
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10100) NOM
      END IF
      KF = 1
      RETURN
  590 CONTINUE
      IF (K6.EQ.1) THEN
      WRITE (NT6,FMT=10070)
      WRITE (NT6,FMT=10020) NOM,IAD,NMOT, (DONE(L),L=1,NMOT)
      END IF
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10110)
      END IF
      KF = 1
      RETURN
  600 CONTINUE
      IF (K6.EQ.1) THEN
      WRITE (NT6,FMT=10080)
      WRITE (NT6,FMT=10000) NOM,IAD,NMOT, (IDON(L),L=1,NMOT)
      END IF
      KF = 1
      RETURN
  610 CONTINUE
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) NOM
      KF = 1
      RETURN
  630 CONTINUE
      IF (KERR.NE.0) THEN
      CALL RIDERR(KERR,NT,NT6,IMP)
      KF = 1
      RETURN
      END IF
10000 FORMAT (1X,A4,I4,I2,7 (A4,' ',A4,' '))
10010 FORMAT (A4,I4,I2,7 (A4,1X,A4,1X))
10020 FORMAT (1X,A4,I4,I2,7E16.9)
10030 FORMAT (A4,I4,I2,7E10.6)
10040 FORMAT (/,'       LIST OF TABLES MODIFIED BY THE USER',/,
     +'       ***********************************')
10050 FORMAT ('     *** INPUT ERROR : YOU CAN NOT MODIFY THE TABLE : ',
     +A4)
10070 FORMAT (
     +'     *** INPUT ERROR : -NMOT-  GRATER THAN 7  *** SEE LINE BELOW'
     +)
10080 FORMAT (
     +'     *** INPUT ERROR : -NMOT-  GRATER THAN 14 *** SEE LINE BELOW'
     +)
10090 FORMAT ('     *** INPUT ERROR : TOO MANY VALUES IN TABLE : ',A4)
10100 FORMAT ('TOO MANY VALUES IN TABLE : ',A4)
10110 FORMAT (
     +'TOO MUCH DATA TO STORE IN THE LINES OF THE AIRCRAFT DATA FILE')
      END
      SUBROUTINE INITA(
     &Z,
     &NP,
     &VAL
     &)
      INTEGER NP
      CHARACTER*4 VAL
      CHARACTER*4 Z(*)
      INTEGER I
      DO 10 I = 1,NP
      Z(I) = VAL
   10 CONTINUE
      RETURN
      END
