      CHARACTER*12 CHGEXT
      EXTERNAL CHGEXT
      EXTERNAL INITA,RIDERR,SETMSG
      DATA NT5F,NT6F/'ROOT1.ADF   ','RESUGEN.OUT '/
      DATA NT20F/'LSPPATH.PTH '/
      KER = 0
      IF (IATA.EQ.0) THEN
      NT1 = 1
      NT2 = 2
      NT3 = 3
      NT4 = 4
      KS4 = 1
      NT5 = 5
      NT6 = 6
      NT7 = 7
      NT8 = 8
      NT9 = 9
      NT10 = 10
      NT11 = 11
      NT20 = 20
      NT1D = 31
      NT2D = 32
      NT3D = 33
      NT4D = 34
      NT8D = 38
      DO 10 I=1,10
      NTB(I) = 59+I
      NTBL(I) = 69+I
   10 CONTINUE
      K6 = 1
      END IF
      IF (IPAS.EQ.0) THEN
      IF (MICRO.EQ.1) THEN
      IF (IDLL.EQ.0) THEN
C      WRITE (*,FMT='(A1)') SDP
C      WRITE (*,FMT=10060) ISU
C      WRITE (*,FMT='(1X,//,A)') ' PROGRAM  EXECUTING'
      END IF
      END IF
      CALL INITA(ITO1,5,NBLAN)
      CALL INITA(IAP1,5,NBLAN)
      CALL INITA(IAC1,5,NBLAN)
      END IF
      RETURN
  650 CONTINUE
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)') ' STOP *** EMPTY INPUT FILE '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'EMPTY INPUT FILE'
      END IF
      IF ((MICRO.EQ.1).AND.(IDLL.EQ.0).AND.(.NOT.IPAD)) WRITE (*,
     +FMT='(A)') ' STOP *** EMPTY INPUT FILE '
      KER = 1
      RETURN
  660 CONTINUE
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A,A12)')
     +' STOP *** READING ERROR IN ',NT20F
      KER = 1
      RETURN
  670 CONTINUE
      KF = 1
      IF (KERR.NE.0) THEN
      CALL RIDERR(KERR,NT5,NT6,IMP)
      END IF
      KER = 1
      RETURN
