     +'* *',/,14X,
     +'*   L O W  S P E E D  P E R F O R M A N C E   * *',/,14X,
     +'*',45X,'* *',/,14X,'*',20X,'T L C',20X,'* *',/,14X,'*',
     +45X,'* *',/,14X,
     +'*   TAKE OFF AND LANDING CHARTS COMPUTATION   * *',/,14X,
     +'*         PROGRAM  ISSUE : ',A11,8X,'* *',/,14X,
     +'*',45X,'* *',/,14X,47 ('*'))
      END
      SUBROUTINE PIST(
     &M,
     &XL,
     &XLV,
     &RF
     &)
      REAL A1
      REAL A2
      REAL A79
      REAL A9
      REAL PMINF
      REAL PSTL
      REAL PSTL1
      REAL PSTL2
      REAL PSTRUC
      REAL PU
      REAL TU
      REAL UH
      REAL UL
      REAL UP
      REAL EPSI
      REAL C3
      REAL HU
      INTEGER COD
      INTEGER DRYCHK
      INTEGER DRYCHL
      INTEGER IATA
      INTEGER IDLL
      INTEGER IMP
      INTEGER ITERMA
      INTEGER K1
      INTEGER K2
      INTEGER KEMAX
      INTEGER KISU
      INTEGER KPPM
      INTEGER KS
      INTEGER KS4
      INTEGER KSB
      INTEGER KSP
      INTEGER KST
      INTEGER KSU
      INTEGER KTAB1
      INTEGER KTAB2
      INTEGER KTAB3
      INTEGER KTABL
      INTEGER KV1MN
      INTEGER L1610
      INTEGER LA42
      INTEGER MICRO
      INTEGER MODE
      INTEGER OUTMOD
      INTEGER NCONT
      INTEGER KTR
      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      LOGICAL DRYLD1
      LOGICAL DRYLD2
      LOGICAL DRYTYP
      REAL BE30(96)
      REAL BE31(96)
      REAL BE32(96)
      REAL BINT(96)
      REAL BMAS(96)
      REAL BPIS(96)
      REAL BV2(96)
      REAL BVEN(96)
      REAL TZREF(21)
      REAL XPPM(12)
      REAL XVE(12)
      REAL XLE(12)
      REAL XLEL(12)
      REAL XMAL(12)
      REAL XMAS(12)
      REAL XBEL(12)
      COMMON /PISTE1/DRYTYP,DRYLD1,DRYLD2
      COMMON /PISTE2/XLE,XVE,XMAS,BINT,BPIS,BVEN,BV2,BMAS,BE30,BE31,
     +BE32,TZREF,XPPM,XMAL,XLEL,XBEL
      INTEGER NPMAX
      REAL DIVER(20)
      REAL VNUM(20000)
      INTEGER NTAB(4200)
      COMMON /TABLE1/NTAB,NPMAX
      COMMON /TABLE2/VNUM,DIVER
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      INTEGER DBRMOD
      INTEGER IBRACT
      INTEGER IBRAL1
      INTEGER IBRAL2
      INTEGER KAP1
      INTEGER KAP2
      INTEGER KLD1
      INTEGER KLD2
      INTEGER NAP1
      INTEGER NAP2
      INTEGER NEFFA
      INTEGER NEFFL
      INTEGER NEFFT
      INTEGER NIGC
      INTEGER NLD1
      INTEGER NLD2
      INTEGER IBOOSL
      INTEGER IBOOST
      INTEGER IRTO
      INTEGER IALT
      INTEGER IZRTO
      INTEGER RWSHFT
      REAL TBAMU
      REAL LBAMU1
      REAL LBAMU2
      INTEGER IGC(30)
      INTEGER IZCODA(5)
      INTEGER IZCODL(5)
      INTEGER IZCODT(7)
      COMMON /INP1/NIGC,IZCODT,NAP1,KAP1,NAP2,KAP2,IZCODA,NLD1,KLD1,
     +NLD2,KLD2,IZCODL,NEFFT,NEFFA,NEFFL,IGC,IBOOSL,IBOOST,IRTO,
     +IALT,IZRTO,IBRACT,IBRAL1,IBRAL2,RWSHFT,DBRMOD
      COMMON /INP2/TBAMU,LBAMU1,LBAMU2
      REAL RF
      INTEGER M
      REAL XL(3),XLV(12)
      REAL R1
      REAL R2
      REAL R3
      REAL R30
      REAL R31
      REAL R32
      REAL R4
      REAL R5
      REAL R6
      REAL R7
      INTEGER ID
      INTEGER IDG
      INTEGER IK
      INTEGER IR0
      INTEGER IRL
      INTEGER L
      INTEGER LMU
      REAL XL1(3)
      REAL Z(12)
      REAL FINT
      EXTERNAL FINT
      EXTERNAL JNT,TRANSR
      IF (KS.EQ.1) CALL TRANSR(XL(1),XL1(1),3)
      IR0 = M
      L = (IR0-1)*200 + 3
      LMU = (IR0-1)*200 + 60
      IRL = (IR0-1)*12 + 1
      ID = IRL + 10
      IK = IRL + 11
      R1 = TZREF(IR0)
      IF (BMAS(IK).NE.0) THEN
      IDG = BMAS(ID) + EPSI
      R2 = FINT(XL(1),XMAS(1),BMAS(IRL),IDG)
      ELSE
      R2 = R1
      END IF
      IF (NTAB(L).NE.0) THEN
      K1 = 1
      K2 = 1
      CALL JNT(L,R2,XL(3),Z(1))
      R3 = Z(1)
      ELSE
      R3 = R2
      END IF
      IF (BV2(IK).NE.0) THEN
      IDG = BV2(ID) + EPSI
      R4 = FINT(R3,XLV(1),BV2(IRL),IDG)
      ELSE
      R4 = R3
      END IF
      R4MU = R4
      IF (LJALAC.AND.(M.EQ.5)) THEN
      IF ((TBAMU.NE.0.).AND.(NTAB(LMU).NE.0)) THEN
      K1 = 9
      K2 = 1
      CALL JNT(LMU,R4,TBAMU,Z)
      R4MU = Z(1)
      END IF
      END IF
      IF (BE30(IK).NE.0) THEN
      IDG = BE30(ID) + EPSI
      R30 = FINT(R4MU,XLV(1),BE30(IRL),IDG)
      ELSE
      R30 = R4MU
      END IF
      IF (BE31(IK).NE.0) THEN
      IDG = BE31(ID) + EPSI
      R31 = FINT(R30,XLV(1),BE31(IRL),IDG)
      ELSE
      R31 = R30
      END IF
      IF (BE32(IK).NE.0) THEN
      IDG = BE32(ID) + EPSI
      R32 = FINT(R31,XLV(1),BE32(IRL),IDG)
      ELSE
      R32 = R31
      END IF
      IF (BVEN(IK).NE.0) THEN
      IDG = BVEN(ID) + EPSI
      R5 = FINT(R32,XLV(1),BVEN(IRL),IDG)
      ELSE
      R5 = R32
      END IF
      IF (BPIS(IK).NE.0) THEN
      IDG = BPIS(ID) + EPSI
      R6 = FINT(R5,XLV(1),BPIS(IRL),IDG)
      ELSE
      R6 = R5
      END IF
      IF (BINT(IK).NE.0) THEN
      IDG = BINT(ID) + EPSI
      R7 = FINT(R6,XLV(1),BINT(IRL),IDG)
      ELSE
      R7 = R6
      END IF
      RF = R7
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
