      INTEGER IDRYL
      INTEGER IDRYT
      INTEGER IER
      INTEGER IJ
      INTEGER IKF
      INTEGER IL1
      INTEGER IL2
      INTEGER IPASR
      INTEGER IPOS
      INTEGER IPOSG
      INTEGER IPOSL
      INTEGER IPOST
      INTEGER K
      INTEGER KER
      INTEGER KERR
      INTEGER KPA27
      INTEGER KPA42
      INTEGER KPA44
      INTEGER KLD1MS
      INTEGER KLD11
      INTEGER KLD2MS
      INTEGER KLD21
      INTEGER KPL27
      INTEGER KPL42
      INTEGER KPL44
      INTEGER KPT27
      INTEGER L
      INTEGER LOCLV1
      INTEGER LOCIV1
      INTEGER L1
      INTEGER L161
      INTEGER L162
      INTEGER L2
      INTEGER L3
      INTEGER L4
      INTEGER L8
      INTEGER L8S
      INTEGER M
      INTEGER M1
      INTEGER M2
      INTEGER M3
      INTEGER M4
      INTEGER M5
      INTEGER M6
      INTEGER M7
      INTEGER MN
      INTEGER NDCOMT
      INTEGER NIGCMS
      INTEGER NIGR
      INTEGER NTC
      INTEGER NTD
      INTEGER NTE
      INTEGER NX
      INTEGER NY
      INTEGER ILNFL0
      INTEGER ILIFL0
      INTEGER ILNFL1
      INTEGER ILIFL1
      INTEGER ILNFL2
      INTEGER ILIFL2
      INTEGER ILNFLB
      INTEGER ILIFLB
      INTEGER IANFL0
      INTEGER IAIFL0
      INTEGER IANFL1
      INTEGER IAIFL1
      INTEGER IANFL2
      INTEGER IAIFL2
      INTEGER IANFLB
      INTEGER IAIFLB
      INTEGER PNTIND
      CHARACTER ALD1
      CHARACTER ALD2
      CHARACTER*2 EFFECT
      CHARACTER*2 STAPE
      CHARACTER*4 CER
      CHARACTER*4 MODIF
      CHARACTER*4 NODI
      CHARACTER*8 CFT1
      CHARACTER*255 MSG
      CHARACTER*255 F_TAPE
      LOGICAL CHECKT
      LOGICAL OPN
      INTEGER DRYRWY(10)
      INTEGER NALFA
      INTEGER GCAPST
      LOGICAL NEUTRV
      EXTERNAL NALFA,NEUTRV,GCAPST
      EXTERNAL INITA,INITR,INIVNU,READMO,RIDERR,SETMSG,TRANRI,TRANSA,
     +TRANSR
      INTRINSIC INT,AMIN1,AMAX1
      SAVE IPOST,IPOSL,KLD11,KLD21,NIGR,CER,L161,L8S
      DATA NIGR/0/
      DATA KLD11/0/,KLD21/0/
      DATA L161/0/
      DATA L8S/0/
      DATA CER/'    '/
      DATA NODI/'MODI'/
    5 CONTINUE
      NBRAE = 0
      NTC = NT11
      M1 = 0
      M2 = 0
      M4 = 0
      M5 = 0
      M6 = 0
      M7 = 0
      KER = 0
      ICYA = 0
      ICYL = 0
      ICYT = 0
      LACONX = .FALSE.
      IK1T = 0
      IK2T = 0
      IKVF = 0
      IKV1 = 0
      IKV2 = 0
      NIGCMS = 0
      KLD1MS = 0
      KLD2MS = 0
      IF (IATA.EQ.0) THEN
      IF (LDELBN) THEN
      LDELBR = .TRUE.
      END IF
      LDELBN = .FALSE.
      IF (LDELBD) THEN
      LDELBR = .TRUE.
      END IF
      LDELBD = .FALSE.
      END IF
      IXTRPL = 0
      IF (IATA.EQ.0) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT=10070) SDP
      READ (NT5,FMT=10000,END=480,IOSTAT=KERR,ERR=470) IAC,ITO,IAP,
     +IXTRPL,MODE,KMO,KTPA,KSB,KTR,KS4,KSU,KSP,KST,NDATE
      IF (LDELB2) THEN
      IAP(3)(3:3)='D'
      END IF
      END IF
   10 CONTINUE
      DO 20 I = 1,5
      IF (IAC(I).NE.IAC1(I)) M1 = 1
      IF (ITO(I).NE.ITO1(I)) M1 = 1
      IF (ITO(I).NE.ITO1(I)) M2 = 1
      IF (IAP(I).NE.IAP1(I)) M2 = 1
   20 CONTINUE
      CALL TRANSA(IAC(1),IAC1(1),5)
      CALL TRANSA(ITO(1),ITO1(1),5)
      CALL TRANSA(IAP(1),IAP1(1),5)
      IF (M1.EQ.1) THEN
      CALL READMO(NTC,NTD,IAC,ITO,KER,IPOSG)
      IPOST = IPOSG
      IF (K6.EQ.1) THEN
      IF (KER.EQ.0) THEN
      WRITE (NT6,FMT=10050) IAC,ITO
      ELSE IF (KER.EQ.1) THEN
      WRITE (NT6,FMT=10040) IAC,ITO
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10041) IAC,ITO
      END IF
      ELSE IF (KER.EQ.2) THEN
      WRITE (NT6,FMT=10060) IAC,ITO
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10061) IAC,ITO
      END IF
      END IF
      END IF
      IF (KER.NE.0) GO TO 480
      END IF
      IF (M2.EQ.1) THEN
      CALL READMO(NTC,NTE,IAC,IAP,KER,IPOSG)
      IPOSL = IPOSG
      IF (K6.EQ.1) THEN
      IF (KER.EQ.0) THEN
      WRITE (NT6,FMT=10050) IAC,IAP
      ELSE IF (KER.EQ.1) THEN
      WRITE (NT6,FMT=10040) IAC,IAP
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10041) IAC,IAP
      END IF
      ELSE IF (KER.EQ.2) THEN
      WRITE (NT6,FMT=10060) IAC,IAP
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10061) IAC,IAP
      END IF
      END IF
      END IF
      IF (KER.NE.0) GO TO 480
      END IF
      IF (IATA.EQ.0) THEN
      CALL INITI(IZCODA,5,0)
      CALL INITI(IZCODL,5,0)
      IF ((MODE.EQ.0).OR.(MODE.EQ.1)) THEN
      READ (NT5,FMT=10010,IOSTAT=KERR,ERR=470) NIGC,IZCODT,NAP1,
     +KAP1,NAP2,KAP2,IZCODA,NLD1,ALD1,NLD2,ALD2,IZCODL,
     +EFFECT,OUTMOD,DBRMOD,KTABL,IDRYT,IDRYL,KTAB3,KTAB2,KTAB1,
     +KISU,CCERT,MODIF
      IF (CCERT.EQ.'JAL') THEN
      LJALAC = .TRUE.
      RWSHFT = JASHFT
      END IF
      NIGC = NIGC+RWSHFT
      NIGCMS = NIGC
      IF (IXTRPL.EQ.1) THEN
      IF (LJALAC) THEN
      IF ((NIGC.EQ.59).OR.(NIGC.EQ.61).OR.(NIGC.EQ.64).AND.
     +(DRYCHK.NE.1)) THEN
      RWNXTT = .TRUE.
      ELSE
      RWNXTT = .FALSE.
      END IF
      RWNXTL = .FALSE.
      ELSE
      RWNXTT = .TRUE.
      RWNXTL = .TRUE.
      END IF
      ELSE
      RWNXTT = .FALSE.
      RWNXTL = .FALSE.
      END IF
      IF (KSU.EQ.2) THEN
      IDRYL = 0
      END IF
      IF ((LJALAC).AND.(KSU.NE.0)) THEN
      IDRYT = 0
      IDRYL = 0
      END IF
      IF (LJALAC) THEN
      DO 490 L = 1,7
      IF ((IZCODT(L).EQ.15).OR.(IZCODT(L).EQ.16)) THEN
      IZCODT(L) = 0
      IF ( IZCODT(L).EQ.15 ) THEN
      WRITE (NT6,FMT=10250)
      WRITE (NT6,FMT=10251)
		ELSE
      WRITE (NT6,FMT=10240)
      WRITE (NT6,FMT=10241)
		END IF
      END IF
  490 CONTINUE
      DO 500 L = 1,5
      IF ((IZCODL(L).EQ.15).OR.(IZCODL(L).EQ.16)) THEN
      IZCODL(L) = 0
      IF ( IZCODL(L).EQ.15 ) THEN
      WRITE (NT6,FMT=10270)
      WRITE (NT6,FMT=10271)
		ELSE
      WRITE (NT6,FMT=10260)
      WRITE (NT6,FMT=10261)
		END IF
      END IF
  500 CONTINUE
      IF (NIGC.GT.(JASHFT+1)) THEN
      DO 510 L = 1,7
      IF (IZCODT(L).EQ.10) THEN
      IZCODT(L) = 0
      IF (NIGC.EQ.(JASHFT+2)) THEN
      WRITE (NT6,FMT=10280)
      WRITE (NT6,FMT=10283)
		  ELSE IF (NIGC.EQ.(JASHFT+2)) THEN
      WRITE (NT6,FMT=10280)
      WRITE (NT6,FMT=10282)
		  ELSE
      WRITE (NT6,FMT=10280)
      WRITE (NT6,FMT=10281)
		  END IF
      END IF
  510 CONTINUE
      END IF
      END IF
      IF (.NOT.LDELBR) THEN
      IF ((DBRMOD.EQ.1).OR.(DBRMOD.EQ.2)) THEN
      WRITE (NT6,FMT=10290) DBRMOD
      WRITE (NT6,FMT=10291)
      WRITE (NT6,FMT=10292)
      DBRMOD = 0
      END IF
      END IF
	
      IF (LDELBR.AND.(DBRMOD.EQ.1)) THEN
      LDELBR=.FALSE.
      LDELBN=.TRUE.
      ELSE
      LDELBN=.FALSE.
      END IF
	
      IF (LDELBR.AND.(DBRMOD.EQ.2)) THEN
      LDELBR=.FALSE.
      LDELBD=.TRUE.
      IAP(3)(3:3)='D'
      IF (IAP(3).NE.IAP1(3)) M2 = 1
      CALL TRANSA(IAP(1),IAP1(1),5)
      ELSE
      LDELBD=.FALSE.
      END IF
      IF (EFFECT.EQ.'E1') THEN
      IF ((KAP1.EQ.2).OR.(KAP2.EQ.2)) THEN
      IF (LJALAC) THEN
      READ (NT5,FMT=10205,IOSTAT=KERR,ERR=470)
     +(DQNH(I),I=1,2),STEEP1,STEEP2,IBRACT,TBAMU,
     +IBRAL1,LBAMU1,IBRAL2,LBAMU2
      ELSE
      READ (NT5,FMT=10201,IOSTAT=KERR,ERR=470)
     +(DQNH(I),I=1,2),STEEP1,STEEP2
      END IF
      ELSE
      IF (LJALAC) THEN
      READ (NT5,FMT=10204,IOSTAT=KERR,ERR=470)
     +(DQNH(I),I=1,2),IBRACT,TBAMU,
     +IBRAL1,LBAMU1,IBRAL2,LBAMU2
      ELSE
      READ (NT5,FMT=10200,IOSTAT=KERR,ERR=470)
     +(DQNH(I),I=1,2)
      END IF
      END IF
      ELSE IF ((KAP1.EQ.2).OR.(KAP2.EQ.2)) THEN
      IF (LJALAC) THEN
      READ (NT5,FMT=10206,IOSTAT=KERR,ERR=470) STEEP1,STEEP2,
     +IBRACT,TBAMU,IBRAL1,LBAMU1,IBRAL2,LBAMU2
      ELSE
      READ (NT5,FMT=10202,IOSTAT=KERR,ERR=470) STEEP1,STEEP2
      END IF
      ELSE IF (LJALAC) THEN
      READ (NT5,FMT=10203,IOSTAT=KERR,ERR=470)
     +IBRACT,TBAMU,IBRAL1,LBAMU1,IBRAL2,LBAMU2
      END IF
      IF (KAP1.EQ.2) THEN
      KAP1 = 0
      END IF
      IF (KAP2.EQ.2) THEN
      KAP2 = 0
      END IF
      IF ((DQNH(1).EQ.0.).AND.(DQNH(2).EQ.0.)) THEN
      MODE = 0
      IF (KTAB1.GT.1) THEN
      KTAB1 = 1
      END IF
      END IF
      IF (KTAB1.EQ.0) THEN
      MODE = 0
      END IF
      IF (CER.NE.CCERT) M5 = 1
      KLD1 = NALFA(ALD1,IER)
      IF (IER.EQ.1) THEN
      KF = 1
      WRITE (NT6,FMT=10090) ALD1
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10091) ALD1
      END IF
      END IF
      KLD1 = KLD1+RWSHFT
      KLD1MS = KLD1
      KLD2 = NALFA(ALD2,IER)
      IF (IER.EQ.1) THEN
      KF = 1
      WRITE (NT6,FMT=10090) ALD2
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10091) ALD2
      END IF
      END IF
      KLD2 = KLD2+RWSHFT
      KLD2MS = KLD2
      IF (LJALAC) THEN
      IF (LDELBR.AND.(KLD1.NE.(1+JASHFT)).AND.(KLD1.NE.(2+JASHFT))
     +.AND.(KLD1.NE.(3+JASHFT)).AND.(KLD2.NE.(1+JASHFT)).AND.
     +(KLD2.NE.(2+JASHFT)).AND.(KLD2.NE.(3+JASHFT))) THEN
      LDELBR = .FALSE.
      END IF
      ELSE
      IF (LDELBR.AND.
     +(KLD1.NE.1).AND.(KLD1.NE.2).AND.(KLD1.NE.9).AND.
     +(KLD2.NE.1).AND.(KLD2.NE.2).AND.(KLD2.NE.9)) THEN
      LDELBR = .FALSE.
      END IF
      END IF
      IF (LDELBD.AND.(KSU.EQ.0).AND.
     +(KLD1.NE.1).AND.(KLD1.NE.2).AND.(KLD1.NE.9).AND.
     +(KLD2.NE.1).AND.(KLD2.NE.2).AND.(KLD2.NE.9)) THEN
      KF = 1
      WRITE (NT6,FMT=10300)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10301)
      END IF
      END IF
      IF (LDELBD.AND.(KSU.NE.0).AND.
     +(KLD1.NE.1).AND.(KLD1.NE.2).AND.(KLD1.NE.9)) THEN
      KF = 1
      WRITE (NT6,FMT=10300)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10301)
      END IF
      END IF
      IF (LDELB2.AND.(KSU.NE.0).AND.
     +(KLD1.NE.1).AND.(KLD1.NE.2).AND.(KLD1.NE.9)) THEN
      KF = 1
      WRITE (NT6,FMT=10300)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10301)
      END IF
      END IF
      IF ((LDELB2).OR.(LDELBD)) THEN
      IF (LJALAC) THEN
      IF ((NLD1.NE.0).AND.(KLD1.NE.(1+JASHFT)).AND.
     +(KLD1.NE.(2+JASHFT)).AND.(KLD1.NE.(3+JASHFT))) THEN
      NLD1 = 0
      END IF
      IF ((NLD2.NE.0).AND.(KLD2.NE.(1+JASHFT)).AND.
     +(KLD2.NE.(2+JASHFT)).AND.(KLD2.NE.(3+JASHFT))) THEN
      NLD2 = 0
      END IF
      ELSE
      IF ((NLD1.NE.0).AND.
     +(KLD1.NE.1).AND.(KLD1.NE.2).AND.(KLD1.NE.9)) THEN
      NLD1 = 0
      END IF
      IF ((NLD2.NE.0).AND.
     +(KLD2.NE.1).AND.(KLD2.NE.2).AND.(KLD2.NE.9)) THEN
      NLD2 = 0
      END IF
      END IF
      END IF
      IF (KTAB1.LT.0.OR.KTAB1.GT.3) THEN
      KF = 1
      WRITE (NT6,FMT=10180)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10181)
      END IF
      END IF
      IF (KTAB2.LT.0.OR.KTAB2.GT.2) THEN
      KF = 1
      WRITE (NT6,FMT=10170)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10171)
      END IF
      KF = 1
      END IF
      IF ((KTAB1.GT.1).AND.(KTAB2.EQ.0)) THEN
      KF = 1
      WRITE (NT6,FMT=10210)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10211)
      END IF
      END IF
      IF ((KTAB1.GT.1).AND.(MODE.EQ.0)) THEN
      KF = 1
      WRITE (NT6,FMT=10220)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10221)
      END IF
      END IF
      IF ((IDRYT.EQ.1).AND.(KSP.EQ.0)) KSP = 2
      IF (LDELB2) THEN
      KSP = 0
      END IF
      CALL INITR(TKV1,20,A9)
      READ (NTC,FMT=10190,REC=IPOST,IOSTAT=KERR,ERR=470) NDCOMT
      IPOS = IPOST + NDCOMT - 1
      CALL INICOM(NTC,0,IPOS)
      IF (((IDRYT.EQ.1).OR.(IDRYL.EQ.1)).AND.
     +((M2.EQ.1).OR.(M5.EQ.1))) THEN
      IF (CCERT.NE.NBLAN) THEN
      DO 31 I = 1,8
      IF (CCERT.EQ.CTIF((I-1)*14 + 1)) AERO(14) = RAER(I)
   31 CONTINUE
      END IF
      END IF
      DO 32 I=1,10
      DRYRWY(I) = INT(TKV1(2*I-1))
   32 CONTINUE
      IF (NIGC.EQ.(RWSHFT+1)) THEN
      DRYTYP = .TRUE.
      ELSE
      DRYTYP = .FALSE.
      DO 33 I=1,10
      IF (NIGC.EQ.DRYRWY(I)) DRYTYP = .TRUE.
   33 CONTINUE
      END IF
      IF (IDRYT.EQ.1) THEN
      IF (LJALAC) THEN
      IF ((NIGC.EQ.(JASHFT+2)).OR.(NIGC.EQ.(JASHFT+3))) THEN
      CHECKT = .TRUE.
      ELSE
      CHECKT = .FALSE.
      END IF
      ELSE
      CHECKT = .TRUE.
      IF (NIGC.EQ.1) THEN
      CHECKT = .FALSE.
      ELSE
      DO 34 I=1,10
      IF (NIGC.EQ.DRYRWY(I)) THEN
      CHECKT = .FALSE.
      GO TO 35
      END IF
   34 CONTINUE
      END IF
      END IF
   35 CONTINUE
      IF ((DRYCHK.LT.2).AND.CHECKT) THEN
      DRYCHK = 1
      NIGC = 1+RWSHFT
      DRYTYP = .TRUE.
      KSB = 0
      CALL ENGOUT(2)
      INQUIRE (NTB(1),OPENED=OPN)
      WRITE(STAPE,'(I2)') NTB(1)
      PNTIND = GCAPST('.',NT1CT)
      F_TAPE=NT1CT(1:PNTIND)//STAPE
      IF (.NOT.OPN)  OPEN (NTB(1),FORM='UNFORMATTED',
     +FILE=F_TAPE,ACCESS='SEQUENTIAL')
      INQUIRE (NT1D,OPENED=OPN)
      IF (.NOT.OPN) THEN
      IF (MICRO.EQ.0) THEN
      OPEN (NT1D,FORM='FORMATTED',STATUS='UNKNOWN',
     +ACCESS='SEQUENTIAL')
      ELSE IF (MICRO.EQ.1) THEN
      IF (IDLL.EQ.0) THEN
      IF (.NOT.IPAD) THEN
      OPEN (NT1D,FILE=NT1DF,FORM='FORMATTED',
     +STATUS='UNKNOWN',ACCESS='SEQUENTIAL')
      ELSE
      OPEN (NT1D,FILE=NT1DCT,FORM='FORMATTED',
     +STATUS='UNKNOWN',ACCESS='SEQUENTIAL')
      END IF
      ELSE IF (IDLL.EQ.1) THEN
      OPEN (NT1D,FILE=NT1DCT,FORM='FORMATTED',
     +STATUS='UNKNOWN',ACCESS='SEQUENTIAL')
      END IF
      END IF
      END IF
      IF (MICRO.EQ.0) THEN
      INQUIRE (NT3D,OPENED=OPN)
      IF (.NOT.OPN) THEN
      IF (MICRO.EQ.0) THEN
      OPEN (NT3D,FORM='FORMATTED',STATUS='UNKNOWN',
     +ACCESS='SEQUENTIAL')
      ELSE IF (MICRO.EQ.1) THEN
      OPEN (NT3D,FILE=NT3DF,FORM='FORMATTED',
     +STATUS='UNKNOWN',ACCESS='SEQUENTIAL')
      END IF
      END IF
      INQUIRE (NT4D,OPENED=OPN)
      IF (.NOT.OPN) THEN
      IF (MICRO.EQ.0) THEN
      OPEN (NT4D,FORM='FORMATTED',STATUS='UNKNOWN',
     +ACCESS='SEQUENTIAL')
      ELSE IF (MICRO.EQ.1) THEN
      OPEN (NT4D,FILE=NT4DF,FORM='FORMATTED',
     +STATUS='UNKNOWN',ACCESS='SEQUENTIAL')
      END IF
      END IF
      END IF
      END IF
      END IF
      IF (LJALAC) THEN
      IF ((KLD1.EQ.(0+JASHFT)).OR.(KLD1.EQ.(1+JASHFT))) THEN
      DRYLD1 = .TRUE.
      ELSE
      DRYLD1 = .FALSE.
      END IF
      ELSE
      IF ((KLD1.EQ.0).OR.(KLD1.EQ.1).OR.(KLD1.EQ.2)) THEN
      DRYLD1 = .TRUE.
      ELSE
      DRYLD1 = .FALSE.
      DO 36 I=1,10
      	IF (KLD1.EQ.DRYRWY(I)) THEN
      	  DRYLD1 = .TRUE.
      	  GO TO 37
      	END IF
   36 CONTINUE
      END IF
      END IF
   37 CONTINUE
      IF (LJALAC) THEN
      IF ((KLD2.EQ.(0+JASHFT)).OR.(KLD2.EQ.(1+JASHFT))) THEN
      DRYLD2 = .TRUE.
      ELSE
      DRYLD2 = .FALSE.
      END IF
      ELSE
      IF ((KLD2.EQ.0).OR.(KLD2.EQ.1).OR.(KLD2.EQ.2)) THEN
      DRYLD2 = .TRUE.
      ELSE
      DRYLD2 = .FALSE.
      DO 38 I=1,10
      	IF (KLD2.EQ.DRYRWY(I)) THEN
      	  DRYLD2 = .TRUE.
      	  GO TO 39
      	END IF
   38 CONTINUE
      END IF
      END IF
   39 CONTINUE
      IF (IDRYL.EQ.1) THEN
      CHECK1 = .TRUE.
      IF (DRYLD1) THEN
      CHECK1 = .FALSE.
      END IF
      CHECK2 = .TRUE.
      IF (DRYLD2) THEN
      CHECK2 = .FALSE.
      END IF
      IF ((LDELB2).OR.(LDELBD)) THEN
      CHECK1 = .FALSE.
      CHECK2 = .FALSE.
      END IF
      IF ((DRYCHL.LT.2).AND.(CHECK1.OR.CHECK2)) THEN
      DRYCHL = 1
      CALL ENGOUT(2)
      IF (CHECK1) THEN
      DRYLD1 = .TRUE.
      IF (LJALAC) THEN
      KLD1 = 1+JASHFT
      ELSE
      KLD1 = 2
      END IF
      END IF
      IF (CHECK2) THEN
      DRYLD2 = .TRUE.
      IF (LJALAC) THEN
      KLD2 = 1+JASHFT
      ELSE
      KLD2 = 2
      END IF
      END IF
      INQUIRE (NTBL(1),OPENED=OPN)
      WRITE(STAPE,'(I2)') NTBL(1)
      PNTIND = GCAPST('.',NT1CT)
      F_TAPE=NT1CT(1:PNTIND)//STAPE
      IF (.NOT.OPN)  OPEN (NTBL(1),FORM='UNFORMATTED',
     +FILE=F_TAPE,ACCESS='SEQUENTIAL')
      INQUIRE (NT2D,OPENED=OPN)
      IF (.NOT.OPN) THEN
      IF (MICRO.EQ.0) THEN
      OPEN (NT2D,FORM='FORMATTED',STATUS='UNKNOWN',
     +ACCESS='SEQUENTIAL')
      ELSE IF (MICRO.EQ.1) THEN
      IF (IDLL.EQ.0) THEN
      IF (.NOT.IPAD) THEN
      OPEN (NT2D,FILE=NT2DF,FORM='FORMATTED',
     +STATUS='UNKNOWN',ACCESS='SEQUENTIAL')
      ELSE
      OPEN (NT2D,FILE=NT2DCT,FORM='FORMATTED',
     +STATUS='UNKNOWN',ACCESS='SEQUENTIAL')
      END IF
      ELSE IF (IDLL.EQ.1) THEN
      OPEN (NT2D,FILE=NT2DCT,FORM='FORMATTED',
     +STATUS='UNKNOWN',ACCESS='SEQUENTIAL')
      END IF
      END IF
      END IF
      END IF
      END IF
      	  IF ((M2.EQ.1).AND.(LDELBD)) THEN
      	    CALL READMO(NTC,NTE,IAC,IAP,KER,IPOSG)
      	    IPOSL = IPOSG
      	    IF (K6.EQ.1) THEN
      	      IF (KER.EQ.0) THEN
