      	  	  NBERR = NBERR + 1
      	  	  WRITE (ERRM(NBERR),FMT=10061) IAC,IAP
      	  	END IF
      	      END IF
      	    END IF
      	    IF (KER.NE.0) GO TO 480
      	  END IF
      ELSE
      READ (NT5,FMT=10020,IOSTAT=KERR,ERR=470) NIGC,IZCODT,
