      END IF
      L8 = 0
      DO 100 L = 1,7
      IF (IZCODT(L).EQ.8) L8 = 8
  100 CONTINUE
      IF (L8S.NE.L8) THEN
      M7 = 1
      L8S = L8
      END IF
      IF (CER.NE.CCERT) M5 = 1
      CER = CCERT
      IF (M1.EQ.0.AND.M2.EQ.0.AND.M4.EQ.0.AND.M5.EQ.0.AND.M6.EQ.0.AND.
