      CALL TRANSR(PENT1S(1),PENT2S(1),24)
      CALL TRANSR(PEN1SI(1),PEN2SI(1),24)
      ELSE IF (SSGMIN.EQ.3.) THEN
      CALL TRANSR(PENT3S(1),PENT2S(1),24)
      CALL TRANSR(PEN3SI(1),PEN2SI(1),24)
      END IF
      IF (NTAB(1802).NE.0) THEN
