     +' *** BAD RANGE FOR 2ND SEG. GRAD. IN PERFO. DATA FILE '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'BAD RANGE FOR 2ND SEG. GRAD. IN PERFO. DATA FILE '
