      END IF
      DO 210 I = 1,9
      VAL = VNUM(IAD+NX+2+I)
      PENT2S(I) = VAL
      PEN2SI(20-I) = VAL
  210 CONTINUE
      END IF
      END IF
      IF ((IBRACT.NE.0).OR.(TBAMU.NE.0.)) THEN
