     +(KOM4((4*(NIGCMS-RWSHFT-1)+I)),I=1,4),
     +' RUNWAY STATUS AT TAKE-OFF'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A,4(A4),A)')
     +'MU EFFECT NOT ALLOWED FOR ',
     +(KOM4((4*(NIGCMS-RWSHFT-1)+I)),I=1,4),
     +' RUNWAY STATUS AT TAKE-OFF'
      END IF
      END IF
      END IF
      IF ((IBRAL1.NE.0).OR.(LBAMU1.NE.0.)) THEN
      IF (((NTAB(3460).EQ.0).AND.(DRYCHL.NE.1))
     +.OR.(KLD1MS.LT.16+JASHFT)) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A,4(A4),A)')
     +' *** MU EFFECT NOT ALLOWED FOR ',
     +(KOM4L((4*(KLD1MS-RWSHFT-1)+I)),I=1,4),
     +' RUNWAY STATUS AT LANDING'
