     +(KOM4L((4*(KLD1MS-RWSHFT-1)+I)),I=1,4),
     +' RUNWAY STATUS AT LANDING'
      END IF
      END IF
      END IF
      IF ((IBRAL2.NE.0).OR.(LBAMU2.NE.0.)) THEN
      IF (((NTAB(3660).EQ.0).AND.(DRYCHL.NE.1))
