      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A,4(A4),A)')
     +' *** MU EFFECT NOT ALLOWED FOR ',
     +(KOM4L((4*(KLD2MS-RWSHFT-1)+I)),I=1,4),
     +' RUNWAY STATUS AT LANDING'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A,4(A4),A)')
     +'MU EFFECT NOT ALLOWED FOR ',
     +(KOM4L((4*(KLD2MS-RWSHFT-1)+I)),I=1,4),
     +' RUNWAY STATUS AT LANDING'
      END IF
      END IF
      END IF
      IF (KF.EQ.1) RETURN
  220 CONTINUE
      CGPT = '     '
      CGPL = '     '
      KCGT = 0.
      KCGA = 0.
      KCGL = 0.
      WRITE (CGPT,FMT='(A4,A1)') BAST(1),BAST(2)
      WRITE (CGPL,FMT='(A4,A1)') BASL(1),BASL(2)
      IF (CGPT.NE.'     ') THEN
      DO 240 L = 1,7
      L2 = IZCODT(L)
