      IF (L.EQ.1) GO TO 250
      DO 230 M = L,2,-1
      IZCODT(M) = IZCODT(M-1)
  230 CONTINUE
      IZCODT(1) = L2
      END IF
  240 CONTINUE
  250 CONTINUE
      IF ((MODE.EQ.0).OR.(MODE.EQ.1)) THEN
      DO 270 L = 1,5
      L2 = IZCODA(L)
