      IF (L.EQ.1) GO TO 280
      DO 260 M = L,2,-1
      IZCODA(M) = IZCODA(M-1)
  260 CONTINUE
      IZCODA(1) = L2
      END IF
  270 CONTINUE
  280 CONTINUE
      DO 300 L = 1,5
      L2 = IZCODL(L)
      IF (L2.EQ.13) THEN
      K = L
      KCGL = 1
      WRITE (CGPL,FMT='(A4,A1)') BASL(3),BASL(4)
