      KOM3(34) = 'OUT '
      KOM3(35) = 'REVE'
      KOM3(36) = 'RSE '
      END IF
      END IF
      END IF
  350 CONTINUE
      IF (L.EQ.7.AND.IPASR.EQ.0) THEN
      IF (NIGC.NE.(RWSHFT+1)) THEN
      IF (BCDT(1).EQ.1..OR.BCDT(1).GE.A79) THEN
      IREV = 0
      END IF
      IF (BCDT(1).EQ.0..OR.IAC(1).EQ.'A320') THEN
      DO 360 I = 1,7
      IF (IZCODT(I).EQ.0.OR.I.EQ.7) THEN
      IZCODT(I) = 15
      L2 = 15
      IZCODP(I) = 0
      NEFFT = NEFFT - 1
