      KF = 1
      END IF
      END IF
      END IF
      END IF
      IF (L2.EQ.0) GO TO 390
      L3 = (L2-7)*4 + 1
      L4 = (L-1)*4 + 1
      CALL TRANSA(KOM3(L3),KOMP(L4),4)
      IF (L2.EQ.13.AND.KCGT.EQ.1) GO TO 390
      IF (IREV.NE.2) CALL TRANSA(KOM3(L3),KOM7(1),4)
      NEFFT = NEFFT + 1
      IF ((NIGC.NE.(RWSHFT+1))) THEN
      IF (.NOT.((NIGC.EQ.(2+RWSHFT)).OR.(NIGC.EQ.7).OR.
     +(NIGC.EQ.8).OR.(NIGC.EQ.9).OR.
     +(NIGC.EQ.(3+RWSHFT)).OR.(NIGC.EQ.(16+RWSHFT)))) THEN
      IF (AV.EQ.'A3BA'.AND.L2.EQ.16) THEN
