      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10111) L2
      END IF
      KF = 1
      END IF
      ELSE IF (AV.EQ.'ATRA'.AND.L2.EQ.10) THEN
      IF (NTAB(10).EQ.0.OR.NTAB(210).EQ.0) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10110) L2
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10111) L2
      END IF
      END IF
      END IF
      END IF
      END IF
      DO 380 K = 1,20,2
      IL2 = INT(TK2T(K))
      IF (IL2.EQ.L2) THEN
      IF (RK2T.NE.A9.AND.RK2T.NE.TK2T(K+1)) THEN
