     +' *** KV2 CONFLICT DUE TO DEFINITION OF INPUT TABLE : IZCODT '
      IF ((L2.NE.8).AND.(IK2T.NE.8)) THEN
      WRITE (NT6,FMT='(A,4A4,A,4A4,A)') 'COMPUTATION WITH ',
     +(KOM3((IL2-7)*4+I),I=1,4),' AND ',
     +(KOM3((IK2T-7)*4+I),I=1,4),' NOT ALLOWED'
      END IF
      END IF
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'KV2 CONFLICT DUE TO DEFINITION OF INPUT TABLE : IZCODT'
      IF ((L2.NE.8).AND.(IK2T.NE.8)) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A,4A4,A,4A4,A)')
     +'COMPUTATION WITH ',(KOM3((IL2-7)*4+I),I=1,4),
     +' AND ',(KOM3((IK2T-7)*4+I),I=1,4),' NOT ALLOWED'
      END IF
      END IF
      END IF
      RK2T = TK2T(K+1)
      IK2T = IL2
      IF (RK2T.LT.ZLIM(4).OR.RK2T.GT.ZLIM(5)) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** V2/VS OUT OF POSSIBLE RANGE - SEE DEFINITION OF TABLE : TK2T
     + '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'V2/VS OUT OF POSSIBLE RANGE - SEE DEFINITION OF TABLE : TK2T'
      END IF
