      END IF
      IF (ICYL.EQ.1) THEN
c-C   For every landing effect
c-    DO 442 I=1,5
c-C   If the current effect is flaps retracted
c-    IF (IZCODL(I).EQ.27) THEN
c-C   Output an error message to the trace file
c-    IF (K6.EQ.1) THEN
c-    WRITE (NT6,FMT='(A,4A4,A,4A4,A)')
c-    +              'LDG : COMPUTATION WITH ',
c-    +              (KOM3((IZCODL(I)-7)*4+K),K=1,4),' AND ',
c-    +              (KOM3(4+K),K=1,4),' NOT ALLOWED'
c-    END IF
c-C   Raise the error flag
c-    KF = 1
c-C   Output an error message to the internal error log
c-    IF (NBERR.LT.MERR) THEN
c-    NBERR = NBERR + 1
c-    WRITE (ERRM(NBERR),FMT='(A,4A4,A,4A4,A)')
c-    +              'LDG : COMPUTATION WITH ',
c-    +              (KOM3((IZCODL(I)-7)*4+K),K=1,4),
c-    +              ' AND ',(KOM3(4+K),K=1,4),' NOT ALLOWED'
c-    END IF
c-C   End if
c-    END IF
c-C   End for
c-  442       CONTINUE
      IF (KPL27.EQ.1) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,FMT='(A,4A4,A,4A4,A)')
     +'LDG : COMPUTATION WITH ',
     +(KOM3((IZCODL(ILNFL0)-7)*4+K),K=1,4),' AND ',
     +(KOM3(4+K),K=1,4),' NOT ALLOWED'
      END IF
      KF = 1
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A,4A4,A,4A4,A)')
     +'LDG : COMPUTATION WITH ',
     +(KOM3((IZCODL(ILNFL0)-7)*4+K),K=1,4),
     +' AND ',(KOM3(4+K),K=1,4),' NOT ALLOWED'
      END IF
      END IF
      END IF
      END IF
      IF (KCGT.NE.KCGA.AND. (NAP1.NE.0.OR.NAP2.NE.0)) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** CG POSITION HAS TO BE THE SAME FOR TAKE OFF AND APPROACH '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'CG POSITION HAS TO BE THE SAME FOR TAKE OFF AND APPROACH'
      END IF
      KF = 1
      END IF
      END IF
      CALL INITR(GAP1,24,A9)
      CALL INITR(GAP2,24,A9)
      CALL INITR(GLD1,24,A9)
      CALL INITR(GLD2,24,A9)
      IF (ALIM(10).NE.0..AND.ALIM(10).NE.A9) THEN
      IF (KAP1.EQ.0) THEN
      AP1GMN = ALIM(10)
      ELSE IF (KAP1.EQ.1) THEN
      AP1GMN = ALIM(11)
      END IF
      IF (KAP2.EQ.0) THEN
      AP2GMN = ALIM(10)
      ELSE IF (KAP2.EQ.1) THEN
      AP2GMN = ALIM(11)
      END IF
      ELSE
      IF (KAP1.EQ.0) THEN
      AP1GMN = 2.1
      ELSE IF (KAP1.EQ.1) THEN
      AP1GMN = 2.5
      END IF
      IF (KAP2.EQ.0) THEN
      AP2GMN = 2.1
      ELSE IF (KAP2.EQ.1) THEN
      AP2GMN = 2.5
      END IF
      END IF
      IF (NTAB(2602).NE.0) THEN
      IAD = NTAB(2602)
      IF (VNUM(IAD).EQ.0.) THEN
      NX = VNUM(IAD+1)
      NGAP1 = MIN(INT(VNUM(IAD+2)),9)
      IADY = IAD + NX + 3
      CALL TRANSR(VNUM(IADY),GAP1(1),NGAP1)
      GAP1(NGAP1+1) = A9
      GAP1(NGAP1+2) = 2.
      GAP1(NGAP1+3) = 1.
      END IF
      END IF
      IF (NTAB(2802).NE.0) THEN
      IAD = NTAB(2802)
      IF (VNUM(IAD).EQ.0.) THEN
      NX = VNUM(IAD+1)
      NGAP2 = MIN(INT(VNUM(IAD+2)),9)
      IADI = IAD + NX + 3
      CALL TRANSR(VNUM(IADI),GAP2(1),NGAP2)
      GAP2(NGAP2+1) = A9
      GAP2(NGAP2+2) = 2.
      GAP2(NGAP2+3) = 1.
      END IF
      END IF
      IF (ALIM(13).NE.0..AND.ALIM(13).NE.A9) THEN
      AL1GMN = ALIM(13)
      ELSE
      AL1GMN = 3.2
      ENDIF
      IF (NTAB(3002).NE.0) THEN
      IAD = NTAB(3002)
      IF (VNUM(IAD).EQ.0.) THEN
      NX = VNUM(IAD+1)
      NGLD1 = MIN(INT(VNUM(IAD+2)),9)
      IADY = IAD + NX + 3
      CALL TRANSR(VNUM(IADY),GLD1(1),NGLD1)
      GLD1(NGLD1+1) = A9
      GLD1(NGLD1+2) = 2.
      GLD1(NGLD1+3) = 1.
      END IF
      END IF
      IF (NTAB(3202).NE.0) THEN
      IAD = NTAB(3202)
      IF (VNUM(IAD).EQ.0.) THEN
      NX = VNUM(IAD+1)
      NGLD2 = MIN(INT(VNUM(IAD+2)),9)
      IADI = IAD + NX + 3
      CALL TRANSR(VNUM(IADI),GLD2(1),NGLD2)
      GLD2(NGLD2+1) = A9
      GLD2(NGLD2+2) = 2.
      GLD2(NGLD2+3) = 1.
      END IF
      END IF
      CALL TRANRI(AERO(1),ICFTO(1),2)
      CALL TRANRI(AERO(16),ICFA1(1),2)
      CALL TRANRI(AERO(21),ICFA2(1),2)
      CALL TRANRI(AERO(26),ICFL1(1),2)
      CALL TRANRI(AERO(31),ICFL2(1),2)
      IF (KPT27.EQ.1) ICFTO(2) = 100
      IF (KPA27.EQ.1) THEN
      ICFA1(2) = 100
      ICFA2(2) = 100
      END IF
      IF (KPL27.EQ.1) THEN
      ICFL1(2) = 100
      ICFL2(2) = 100
      END IF
      IF ((KPA27+KPL27).EQ.1) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** EFFECT NO  27  HAS TO BE THE SAME FOR APPROACH AND LANDING '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'EFFECT #27 HAS TO BE THE SAME FOR APPROACH AND LANDING'
      END IF
      END IF
      IF ((KPL27+KPL42+KPL44).GT.1) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' MULTIPLE FLAPS EFFECT SELECTED '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'MULTIPLE FLAPS EFFECTS SELECTED'
      END IF
      END IF
      IF (CUNF.EQ.'T') THEN
      WRITE (CFA1,FMT='(I2,''/'',I2)') ICFA1
      WRITE (CFA2,FMT='(I2,''/'',I2)') ICFA2
      WRITE (CFL1,FMT='(I2,''/'',I2)') ICFL1
      WRITE (CFL2,FMT='(I2,''/'',I2)') ICFL2
      ELSE
      IF (NAP1.NE.0) WRITE (CFA1,FMT='(1X,A4)') CFAP(NAP1)
      IF (NAP2.NE.0) WRITE (CFA2,FMT='(1X,A4)') CFAP(NAP2)
      IF (NLD1.NE.0) WRITE (CFL1,FMT='(1X,A4)') CFLD(NLD1)
      IF (NLD2.NE.0) WRITE (CFL2,FMT='(1X,A4)') CFLD(NLD2)
      END IF
      KPPM = 0
      IF (XMAS(1).LT.1.) THEN
      KPPM = 1
      DO 460 I = 2,9
      IF (XMAS(I).LE.XMAS(I-1)) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** BAD ARRANGEMENT IN  XMAS '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'BAD ARRANGEMENT IN XMAS'
      END IF
      END IF
  460 CONTINUE
      CALL TRANSR(XMAS(1),XPPM(1),12)
      END IF
      PMIN = ZLIM(1)
      PINI = ZLIM(2)
      PMAX = ZLIM(3)
      V2VSMI = ZLIM(4)
      V2VSMA = ZLIM(5)
      V1VRMI = ZLIM(6)
      V1VRI = ZLIM(7)
      V1VRMA = ZLIM(8)
      IF (NTAB(803).NE.0) THEN
      IAD = NTAB(803)
      IF (VNUM(IAD).EQ.0.) THEN
      NX = VNUM(IAD+1)
      NY = VNUM(IAD+2)
      V1VRMI = VNUM(IAD+NX+3)
      V1VRMA = VNUM(IAD+NX+NY+2)
      IKF = 0
      IF (V1VRMA.GT.1..OR.V1VRMA.LT..5) IKF = 1
      IF (V1VRMI.GT.1..OR.V1VRMI.LT..5) IKF = 1
      IF (V1VRMI.GT.V1VRMA) IKF = 1
      IF (IKF.EQ.1) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** BAD RANGE OF V1/VR IN NTAB(803) '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'BAD RANGE FOR V1/VR IN NTAB(803)'
      END IF
      END IF
      V1VRI = (V1VRMA+V1VRMI)/2
      END IF
      END IF
      ZMIN = ZLIM(9)
      ZMAX = ZLIM(10)
      DTMIN = ZLIM(11)
      DTMAX1 = ZLIM(12)
      DTMAX2 = ZLIM(13)
      CALL TRANSR(COEF(1),COEFP(1),40)
      COEF(8) = COEF(8)/1000.
      COEF(14) = COEF(14)/1000.
      COEF(22) = COEF(22)/1000.
      COEF(32) = COEF(32)/1000.
      COEF(34) = COEF(34)/1000.
      RETURN
  470 CONTINUE
      IF (KERR.NE.0) THEN
      CALL RIDERR(KERR,NT5,NT6,IMP)
      KF = 1
      RETURN
      END IF
  480 CONTINUE
      IF (K6.EQ.1) WRITE (NT6,FMT=10100)
      KF = 1
      RETURN
10000 FORMAT (5A4,5A4,5A4,7I1,I1,I1,I1,2A4,A2)
10010 FORMAT (1X,I2,3X,7I2,1X,I1,I1,2X,I1,I1,3X,5I2,1X,I1,A1,2X,I1,A1,
     +3X,5I2,A2,I1,I1,1X,I1,I1,I1,I1,I1,I1,I1,A4,A4)
10020 FORMAT (1X,I2,3X,7I2,3 (1X,I2),11X,F10.1,F10.2,F5.3,7X,A4,A4)
10030 FORMAT (A4)
10040 FORMAT (/,/,' ** THERE IS NO MODULE NAMED  ',5A4,5A4,
     +' IN THE MAIN FILE',/,30X,40 ('-'))
10041 FORMAT ('THERE IS NO MODULE NAMED ',5A4,5A4)
10050 FORMAT (/,/,' // YOU HAVE USED THE MODULE NAMED ',5A4,5A4,' //')
10060 FORMAT (/,/,' ** PROVIDED NUMBER OF RECORDS IN MODULE ',5A4,5A4,
     +' IS FALSE ',/,42X,40 ('-'))
10061 FORMAT ('NBR OF RECORDS IN MODULUS ',5A4,5A4,' IS FALSE')
10070 FORMAT (A1)
10080 FORMAT (/,/,/,' *** EFF.=',I2,
     +'  IS A BAD SELECTED EFFECT EITHER IN IZCODT OR IZCODA OR IZCODL'
     +)
10081 FORMAT ('EFFECT #',I2,' IS UNAVALIABLE IN IZCODT')
10082 FORMAT ('EFFECT #',I2,' IS UNAVALIABLE IN IZCODA')
10083 FORMAT ('EFFECT #',I2,' IS UNAVALIABLE IN IZCODL')
10090 FORMAT (/,/,' ** RWY STATUS :',A1,
     +' (FOR LANDING) OUT OF POSSIBLE RANGE :0,1,...,I,J')
10091 FORMAT ('RWY STATUS :',A1,' OUT OF POSSIBLE RANGE :0,1,...,I,J')
10100 FORMAT (/,/,' *** STOP 10  INPUT ERROR  SEE GENERAL OUTPUT ')
10110 FORMAT (/,/,' ** STOP12 - IZCODT(',I2,
     +') NOT AVAILABLE - SEE STATUS OF PERFO. DATA FILE')
10111 FORMAT ('IZCODT(',I2,
     +') NOT AVAILABLE - SEE STATUS OF PERFO. DATA FILE')
10120 FORMAT (/,/,' ** STOP12 - IZCODL(',I2,
     +') NOT AVAILABLE - SEE STATUS OF PERFO. DATA FILE')
10121 FORMAT ('IZCODL(',I2,
     +') NOT AVAILABLE - SEE STATUS OF PERFO. DATA FILE')
10130 FORMAT (/,/,' ** STOP12 - IZCODA(',I2,
     +') NOT AVAILABLE - SEE STATUS OF PERFO. DATA FILE')
10131 FORMAT ('IZCODA(',I2,
     +') NOT AVAILABLE - SEE STATUS OF PERFO. DATA FILE')
10140 FORMAT (/,/,' ** IZCODT(',I2,') NOT VALID SEE USER''S MANUAL ')
10141 FORMAT (' IZCODT(',I2,') NOT VALID. SEE USER''S MANUAL ')
10150 FORMAT (/,/,' ** IZCODA(',I2,') NOT VALID SEE USER''S MANUAL ')
10151 FORMAT ('IZCODA(',I2,') NOT VALID. SEE USER''S MANUAL ')
10160 FORMAT (/,/,' ** IZCODL(',I2,') NOT VALID SEE USER''S MANUAL ')
10161 FORMAT ('IZCODL(',I2,') NOT VALID .SEE USER''S MANUAL ')
10170 FORMAT (1X,/,1X,' *****    BAD VALUE OF CODE : KTAB2  ',/)
10171 FORMAT ('BAD VALUE FOR KTAB2')
10180 FORMAT (1X,/,1X,' *****    BAD VALUE OF CODE : KTAB1  ',/)
10181 FORMAT ('BAD VALUE FOR KTAB1')
10190 FORMAT (59X,I3)
10200 FORMAT (2(F8.3))
10201 FORMAT (4(F8.3))
10202 FORMAT (16X,2(F8.3))
10203 FORMAT (32X,3(I1,F6.4))
10204 FORMAT (2(F8.3),16X,3(I1,F6.4))
10205 FORMAT (4(F8.3),3(I1,F6.4))
10206 FORMAT (16X,2(F8.3),3(I1,F6.4))
10210 FORMAT (1X,/,1X,' *****    BAD VALUE OF CODE : KTAB1 VS KTAB2 ',/)
10211 FORMAT ('BAD VALUE FOR KTAB1 VERSUS KTAB2')
10220 FORMAT (1X,/,1X,' *****    BAD VALUE OF CODE : KTAB1 VS MODE ',/)
10221 FORMAT ('BAD VALUE FOR KTAB1 VERSUS MODE')
10230 FORMAT (1X,/,1X,' ** WARNING ** BRAKING SPEED OF CONF ',A5,I1,
     +' IS NOT DEFINED IN PERFO. DATA FILE',/)
10240 FORMAT (1X,/,1X,' ** WARNING ** REVERSE EFFECT IS NOT ALLOWED ',
     +' AT TAKE-OFF',/)
10241 FORMAT ('FOR JAPAN AIRLINES AIRCRAFT TYPE - NO REVERSE EFFECT',
     +' IS SET')
10250 FORMAT (1X,/,1X,' ** WARNING ** 50% FULL REVERSE EFFECT IS NOT',
     +' ALLOWED AT TAKE-OFF',/)
10251 FORMAT ('FOR JAPAN AIRLINES AIRCRAFT TYPE - NO REVERSE EFFECT',
     +' IS SET')
10260 FORMAT (1X,/,1X,' ** WARNING ** REVERSE EFFECT IS NOT ALLOWED ',
     +' AT LANDING',/)
10261 FORMAT ('FOR JAPAN AIRLINES AIRCRAFT TYPE - NO REVERSE EFFECT',
     +' IS SET')
10270 FORMAT (1X,/,1X,' ** WARNING ** 50% FULL REVERSE EFFECT IS NOT',
     +' ALLOWED AT LANDING',/)
10271 FORMAT ('FOR JAPAN AIRLINES AIRCRAFT TYPE - NO REVERSE EFFECT',
     +' IS SET')
10280 FORMAT (1X,/,1X,' ** WARNING ** 15-35FT SCREEN HEIGHT EFFECT IS',
     +' NOT ALLOWED AT TAKE-OFF',/)
10281 FORMAT ('FOR JAPAN AIRLINES AIRCRAFT TYPE - CONTAMINATED RUNWAY',
     +' - NO SCREEN HEIGHT EFFECT IS SET')
10282 FORMAT ('FOR JAPAN AIRLINES AIRCRAFT TYPE - WET NON GROOVED',
     +' RUNWAY - NO SCREEN HEIGHT EFFECT IS SET')
10283 FORMAT ('FOR JAPAN AIRLINES AIRCRAFT TYPE - WET GROOVED',
     +' RUNWAY - NO SCREEN HEIGHT EFFECT IS SET')
10290 FORMAT (1X,/,1X,' ** WARNING ** INPUT BRAKING MODE OPTION ',I1,
     +' (DELAYED BRAKING) IS NOT ALLOWED',/)
10291 FORMAT (1X,/,1X,'DELAYED BRAKING PROCEDURE IS NOT APPLICABLE ',/)
10292 FORMAT (1X,/,1X,'DEFAULT BRAKING MODE OPTION (0) IS USED')
10300 FORMAT (1X,/,1X,' *****    DELAYED BRAKING FORBIDDEN',
     +' FOR CONTAMINATED RUNWAY',/)
10301 FORMAT ('DELAYED BRAKING FORBIDDEN FOR CONTAMINATED RUNWAY')
      END
      SUBROUTINE READMO(
     &NTINP,
     &NTOUT,
     &IZDO1,
     &IZDO2,
     &KER,
     &IPOSG
     &
     &)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      REAL A1
      REAL A2
      REAL A79
      REAL A9
      REAL PMINF
      REAL PSTL
      REAL PSTL1
      REAL PSTL2
      REAL PSTRUC
      REAL PU
      REAL TU
      REAL UH
      REAL UL
      REAL UP
      REAL EPSI
      REAL C3
      REAL HU
      INTEGER COD
      INTEGER DRYCHK
      INTEGER DRYCHL
      INTEGER IATA
      INTEGER IDLL
      INTEGER IMP
      INTEGER ITERMA
      INTEGER K1
      INTEGER K2
      INTEGER KEMAX
      INTEGER KISU
      INTEGER KPPM
      INTEGER KS
      INTEGER KS4
      INTEGER KSB
      INTEGER KSP
      INTEGER KST
      INTEGER KSU
      INTEGER KTAB1
      INTEGER KTAB2
      INTEGER KTAB3
      INTEGER KTABL
      INTEGER KV1MN
      INTEGER L1610
      INTEGER LA42
      INTEGER MICRO
      INTEGER MODE
      INTEGER OUTMOD
      INTEGER NCONT
      INTEGER KTR
      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      REAL AK1
      REAL AK2
      REAL ASD
      REAL PP
      REAL TA
      REAL TISA
      REAL TOD
      REAL TOR
      REAL VC1
      REAL VENT
      REAL V2VS
      REAL WIDTH
      REAL ZP
      INTEGER IOBFTO
      INTEGER KF
      INTEGER NOBST
      INTEGER KOBS
      INTEGER KCGA
      INTEGER KCGL
      INTEGER KCGT
      REAL D(MAXOBS)
      REAL DGA(11)
      REAL DIST(10)
      REAL DP(MAXOBS)
      REAL H(MAXOBS)
      REAL HP(MAXOBS)
      REAL PEN1SI(24)
      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
      REAL TRAJ(32)
      REAL TRAJV(10)
      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      INTEGER NBTOLI
      INTEGER FILVER
      COMMON /FILESC/NBTOLI,FILVER
      LOGICAL LBOOST
      LOGICAL LBOOSL
      LOGICAL LCONF
      LOGICAL LRTO
      LOGICAL LDELBR
      LOGICAL LDELB2
      LOGICAL LDELBC
      LOGICAL LDELBN
      LOGICAL LDELBD
      COMMON /CONFIL/LCONF,LBOOST,LBOOSL,LRTO,LDELBR,LDELB2,LDELBC,
     +LDELBN,LDELBD
      INTEGER IPOSG,KER,NTINP,NTOUT
      CHARACTER*4 IZDO1(5),IZDO2(5)
      INTEGER I
      INTEGER IPOS
      INTEGER IPOSD
      INTEGER KERR
      INTEGER N
      INTEGER NDCOM
      INTEGER NDTAB
      INTEGER NPODR
      CHARACTER*4 IBID
      CHARACTER*4 IFIN
      CHARACTER*4 LAST
      CHARACTER*4 IZLU1(5)
      CHARACTER*4 IZLU2(5)
      CHARACTER*20 ITOB(50)
      EXTERNAL RIDERR
      DATA IFIN/'END '/
      IPOS = 1
      IF (FILVER.GE.1) THEN
      IPOSD = 2
      ELSE
      IPOSD = 1
      END IF
      IPOS = IPOSD
      N = 0
    1 CONTINUE
      N = N + 1
      READ (NTINP,FMT=10005,REC=IPOS,IOSTAT=KERR,ERR=70) ITOB(N),
     +NPODR
      IPOS = IPOS + NPODR
      READ (NTINP,FMT=10010,REC=IPOS,IOSTAT=KERR,ERR=70) IBID,LAST
      IPOS = IPOS + 1
      IF (LAST.NE.'LAST') GOTO 1
      IPOS = IPOSD
   10 CONTINUE
      READ (NTINP,FMT=10000,REC=IPOS,IOSTAT=KERR,ERR=70) IZLU1,IZLU2,
     +NDCOM,NDTAB,NPODR
   20 CONTINUE
      DO 30 I = 1,5
      IF (IZDO1(I).NE.IZLU1(I).OR.IZDO2(I).NE.IZLU2(I)) GO TO 40
   30 CONTINUE
      IPOSG = IPOS
      IF (IZDO2(1).EQ.'APP/') THEN
      LBOOSL = .FALSE.
      IF ((IZDO2(2)(3:3).EQ.'B').OR.(IZDO2(2)(3:3).EQ.'S')) THEN
      LBOOSL = .TRUE.
      ELSE
      DO 32 I=1,N
      IF ((IZDO2(1)//IZDO2(2)(1:2)//'B'.EQ.ITOB(I)(1:7)).OR.
     +(IZDO2(1)//IZDO2(2)(1:2)//'S'.EQ.ITOB(I)(1:7))) THEN
      LBOOSL = .TRUE.
      END IF
   32 CONTINUE
      END IF
      IF ((.NOT.LDELBR).AND.(.NOT.LDELBD)) THEN
      DO 33 I=1,N
      IF (IZDO2(1)//IZDO2(2)//IZDO2(3)(1:2)//'D'//IZDO2(3)(4:4)
     +//IZDO2(4)//IZDO2(5).EQ.ITOB(I)) THEN
      LDELBR = .TRUE.
      END IF
   33 CONTINUE
      END IF
      ELSE
      LBOOST = .FALSE.
      IF ((IZDO2(2)(3:3).EQ.'B').OR.(IZDO2(2)(3:3).EQ.'S')) THEN
      LBOOST = .TRUE.
      ELSE
      DO 35 I=1,N
      IF ((IZDO2(1)//IZDO2(2)(1:2)//'B'.EQ.ITOB(I)(1:7)).OR.
     +(IZDO2(1)//IZDO2(2)(1:2)//'S'.EQ.ITOB(I)(1:7))) THEN
      LBOOST = .TRUE.
      END IF
   35 CONTINUE
      END IF
      END IF
      IF (IZDO2(1).NE.'APP/') THEN
      LRTO = .FALSE.
      IF ((IZDO2(3)(2:2).EQ.'R').OR.(IZDO2(2)(3:3).EQ.'R')) THEN
      LRTO = .TRUE.
c-    ELSE
c-    DO 37 I=1,N
c-    IF (IZDO2(1)//IZDO2(2)//IZDO2(3)(1:1)//'R'.EQ.ITOB(I)(1:10))
c-   +THEN
c-    LRTO = .TRUE.
c-    END IF
c- 37 CONTINUE
      END IF
      END IF
      RETURN
   40 CONTINUE
      IPOS = IPOS + NPODR
      READ (NTINP,FMT=10010,REC=IPOS,IOSTAT=KERR,ERR=70) IBID,LAST
      IF (LAST.EQ.'LAST') GO TO 60
      IF (IBID.EQ.IFIN) THEN
      IPOS = IPOS + 1
      GO TO 10
      END IF
   60 CONTINUE
      KER = 1
      RETURN
   70 CONTINUE
      IF (KERR.NE.0) THEN
      CALL RIDERR(KERR,NTINP,NT6,IMP)
      KF = 1
      RETURN
      END IF
10000 FORMAT (5A4,5A4,20X,I2,4X,I4,4X,I6)
10005 FORMAT (20X,A20,20X,2X,4X,4X,4X,I6)
10010 FORMAT (2A4)
      END
