      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      INTEGER NPMAX
      REAL DIVER(20)
      REAL VNUM(20000)
      INTEGER NTAB(4200)
      COMMON /TABLE1/NTAB,NPMAX
      COMMON /TABLE2/VNUM,DIVER
      LOGICAL DRYLD1
      LOGICAL DRYLD2
      LOGICAL DRYTYP
      REAL BE30(96)
      REAL BE31(96)
      REAL BE32(96)
      REAL BINT(96)
      REAL BMAS(96)
      REAL BPIS(96)
      REAL BV2(96)
      REAL BVEN(96)
      REAL TZREF(21)
      REAL XPPM(12)
      REAL XVE(12)
      REAL XLE(12)
      REAL XLEL(12)
      REAL XMAL(12)
      REAL XMAS(12)
      REAL XBEL(12)
      COMMON /PISTE1/DRYTYP,DRYLD1,DRYLD2
      COMMON /PISTE2/XLE,XVE,XMAS,BINT,BPIS,BVEN,BV2,BMAS,BE30,BE31,
     +BE32,TZREF,XPPM,XMAL,XLEL,XBEL
      REAL VAL
      INTEGER KINF
      REAL XH(*),ZON(*)
      INTEGER ILG
      INTEGER IRG
      INTEGER KL
      INTEGER KLC
      INTEGER L
      REAL ZLS(12)
      EXTERNAL JNT,TRANSR
      ZLS(10) = A9
      ZLS(11) = 3.
      ZLS(12) = 1.
      DO 10 L = 1,96
      ZON(L) = 0.
   10 CONTINUE
      K1 = 1
      K2 = 9
      DO 20 ILG = 1,8
      KL = (ILG-1)*200 + 1
      IF (NTAB(KL).EQ.0) GO TO 20
      KLC = KL + KINF - 1
      IF (NTAB(KLC).EQ.0) GO TO 20
      VAL = TZREF(ILG)
      CALL JNT(KLC,VAL,XH(1),ZLS(1))
      IRG = (ILG-1)*12 + 1
      CALL TRANSR(ZLS(1),ZON(IRG),12)
   20 CONTINUE
      RETURN
      END
      SUBROUTINE REDUT
      INTEGER JASHFT
