      INTEGER NEFFL
      INTEGER NEFFT
      INTEGER NIGC
      INTEGER NLD1
      INTEGER NLD2
      INTEGER IBOOSL
      INTEGER IBOOST
      INTEGER IRTO
      INTEGER IALT
      INTEGER IZRTO
      INTEGER RWSHFT
      REAL TBAMU
      REAL LBAMU1
      REAL LBAMU2
      INTEGER IGC(30)
      INTEGER IZCODA(5)
      INTEGER IZCODL(5)
      INTEGER IZCODT(7)
      COMMON /INP1/NIGC,IZCODT,NAP1,KAP1,NAP2,KAP2,IZCODA,NLD1,KLD1,
     +NLD2,KLD2,IZCODL,NEFFT,NEFFA,NEFFL,IGC,IBOOSL,IBOOST,IRTO,
     +IALT,IZRTO,IBRACT,IBRAL1,IBRAL2,RWSHFT,DBRMOD
      COMMON /INP2/TBAMU,LBAMU1,LBAMU2
      REAL A1
      REAL A2
      REAL A79
      REAL A9
      REAL PMINF
      REAL PSTL
      REAL PSTL1
      REAL PSTL2
      REAL PSTRUC
      REAL PU
      REAL TU
      REAL UH
      REAL UL
      REAL UP
      REAL EPSI
      REAL C3
      REAL HU
      INTEGER COD
      INTEGER DRYCHK
      INTEGER DRYCHL
      INTEGER IATA
      INTEGER IDLL
      INTEGER IMP
      INTEGER ITERMA
      INTEGER K1
      INTEGER K2
      INTEGER KEMAX
