      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      INTEGER NPMAX
      REAL DIVER(20)
      REAL VNUM(20000)
      INTEGER NTAB(4200)
      COMMON /TABLE1/NTAB,NPMAX
      COMMON /TABLE2/VNUM,DIVER
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      REAL DEG
      INTEGER IC
      INTEGER ILG
      INTEGER IRG
      INTEGER KC
      INTEGER KL
      INTEGER KLC
      INTEGER L
      INTEGER NLP
      REAL X(12)
      REAL Y(12)
      REAL ZLS(12)
      EXTERNAL JNT,TRANSR
      NLP = 8
      KA = 0
      DO 10 L = 1,96
      BINT(L) = 0.
   10 CONTINUE
      DO 20 L = 1,7
      IF (IZCODT(L).NE.0) KA = 1
   20 CONTINUE
      IF (KA.NE.0) THEN
      K1 = 9
      K2 = 1
      X(10) = A9
      DO 40 ILG = 1,NLP
      KL = (ILG-1)*200 + 1
      IF (NTAB(KL).EQ.0) GO TO 40
      IF (ILG.LE.5) THEN
      CALL TRANSR(XLE(1),X(1),9)
      ELSE
      CALL TRANSR(XVE(1),X(1),9)
      END IF
      DEG = 1.
      DO 30 IC = 1,7
      KC = IZCODT(IC)
      IF (KC.EQ.0) GO TO 30
      KLC = KL + KC - 1
      IF (NTAB(KLC).EQ.0) GO TO 30
      CALL JNT(KLC,X,Y,ZLS)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***REDUT*** KLC ZLS '
      WRITE (NT6,FMT=*) KLC,ZLS
      END IF
      CALL TRANSR(ZLS(1),X(1),9)
      IF (DEG.LT.ZLS(11)) DEG = ZLS(11)
   30 CONTINUE
      X(11) = DEG
      X(12) = 1.
      IRG = (ILG-1)*12 + 1
      CALL TRANSR(X(1),BINT(IRG),12)
   40 CONTINUE
      END IF
      RETURN
      END
      SUBROUTINE REDUV(
     &KINF,
     &VAL,
     &ZON
     &)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      REAL A1
      REAL A2
      REAL A79
