      REAL UP
      REAL EPSI
      REAL C3
      REAL HU
      INTEGER COD
      INTEGER DRYCHK
      INTEGER DRYCHL
      INTEGER IATA
      INTEGER IDLL
      INTEGER IMP
      INTEGER ITERMA
      INTEGER K1
      INTEGER K2
      INTEGER KEMAX
      INTEGER KISU
      INTEGER KPPM
      INTEGER KS
      INTEGER KS4
      INTEGER KSB
      INTEGER KSP
      INTEGER KST
      INTEGER KSU
