      INTEGER L1610
      INTEGER LA42
      INTEGER MICRO
      INTEGER MODE
      INTEGER OUTMOD
      INTEGER NCONT
      INTEGER KTR
      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      INTEGER NPMAX
      REAL DIVER(20)
      REAL VNUM(20000)
      INTEGER NTAB(4200)
      COMMON /TABLE1/NTAB,NPMAX
      COMMON /TABLE2/VNUM,DIVER
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      REAL AK1
      REAL AK2
      REAL ASD
      REAL PP
      REAL TA
      REAL TISA
      REAL TOD
      REAL TOR
      REAL VC1
      REAL VENT
      REAL V2VS
      REAL WIDTH
      REAL ZP
      INTEGER IOBFTO
      INTEGER KF
      INTEGER NOBST
      INTEGER KOBS
      INTEGER KCGA
      INTEGER KCGL
      INTEGER KCGT
      REAL D(MAXOBS)
      REAL DGA(11)
      REAL DIST(10)
      REAL DP(MAXOBS)
      REAL H(MAXOBS)
      REAL HP(MAXOBS)
      REAL PEN1SI(24)
      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
      REAL TRAJ(32)
      REAL TRAJV(10)
      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      LOGICAL DRYLD1
      LOGICAL DRYLD2
      LOGICAL DRYTYP
      REAL BE30(96)
      REAL BE31(96)
      REAL BE32(96)
      REAL BINT(96)
      REAL BMAS(96)
      REAL BPIS(96)
      REAL BV2(96)
      REAL BVEN(96)
      REAL TZREF(21)
      REAL XPPM(12)
      REAL XVE(12)
      REAL XLE(12)
      REAL XLEL(12)
      REAL XMAL(12)
      REAL XMAS(12)
      REAL XBEL(12)
      COMMON /PISTE1/DRYTYP,DRYLD1,DRYLD2
      COMMON /PISTE2/XLE,XVE,XMAS,BINT,BPIS,BVEN,BV2,BMAS,BE30,BE31,
     +BE32,TZREF,XPPM,XMAL,XLEL,XBEL
      REAL VAL
      INTEGER KINF
      REAL ZON(*)
      INTEGER ILG
      INTEGER IRG
      INTEGER KL
      INTEGER KLC
      INTEGER KLCX
      INTEGER L
      REAL TMP(12)
      REAL ZLS(12)
      EXTERNAL JNT,TRANSR
      TMP(10) = A9
      TMP(11) = 1.
      TMP(12) = 1.
      ZLS(10) = A9
      ZLS(11) = 1.
      ZLS(12) = 1.
      DO 10 L = 1,96
      ZON(L) = 0.
   10 CONTINUE
      K1 = 9
      K2 = 1
      IF (VAL.EQ.0.) THEN
      RETURN
      ELSE
      DO 20 ILG = 1,8
      KL = (ILG-1)*200 + 1
      IF (NTAB(KL).EQ.0) GO TO 20
      KLC = KL + KINF - 1
      IF (NTAB(KLC).EQ.0) GO TO 20
      IF ((KINF.EQ.6).AND.(VAL.LT.-2.0)) THEN
      KLCX = KL + 40 - 1
      IF (NTAB(KLCX).EQ.0) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,FMT=10000) KLCX
      WRITE (NT6,FMT='(/,A,//)')
     +'           *** CURRENT COMPUTATION ABORTED'
      END IF
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10000) KLCX
      END IF
      KF = 1
      RETURN
      ELSE
      IF (ILG.LE.5) THEN
      CALL JNT(KLC,XLE(1),-2.0,TMP(1))
      ELSE
      CALL JNT(KLC,XVE(1),-2.0,TMP(1))
      END IF
      IF (ILG.LE.5) THEN
      CALL JNT(KLCX,TMP(1),VAL,ZLS(1))
      ELSE
      CALL JNT(KLCX,TMP(1),VAL,ZLS(1))
      END IF
      END IF
      ELSE
      IF (ILG.LE.5) THEN
      CALL JNT(KLC,XLE(1),VAL,ZLS(1))
      ELSE
      CALL JNT(KLC,XVE(1),VAL,ZLS(1))
      END IF
      END IF
      IRG = (ILG-1)*12 + 1
      CALL TRANSR(ZLS(1),ZON(IRG),12)
   20 CONTINUE
      RETURN
      END IF
10000 FORMAT ('*** RUNWAY SLOPE EXTENDED EFFECT #',I3,
     &' NOT AVAILABLE IN PERFORMANCE DATA FILE!')
      END
      SUBROUTINE RIDERR(
     &KERR,
     &NTIN,
     &NTOUT,
     &IMP
     &)
      INTEGER IMP,KERR,NTIN,NTOUT
      INTEGER IDIR
      INTEGER LERR
      INTEGER NR
      CHARACTER*10 DIREC
      CHARACTER*132 FILENM
      CHARACTER*132 LINE
      INQUIRE (UNIT=NTIN,NAME=FILENM)
      INQUIRE (NTIN,DIRECT=DIREC)
      IF (DIREC(1:3).NE.'YES') THEN
      IDIR = 0
      ELSE
      IDIR = 1
      END IF
      IF (IDIR.EQ.0) THEN
      BACKSPACE (NTIN)
      READ (NTIN,FMT='(A132)',IOSTAT=LERR,ERR=10) LINE
      ELSE
      INQUIRE (NTIN,NEXTREC=NR,IOSTAT=LERR,ERR=10)
      NR = NR - 1
      IF (NR.LE.0) NR = 1
      READ (NTIN,FMT='(A132)',REC=NR) LINE
      END IF
      IF (NTOUT.GT.0) THEN
      IF (IMP.EQ.0.OR.IMP.EQ.2) THEN
      WRITE (NTOUT,FMT=10000) KERR,FILENM
      IF (IDIR.EQ.0) THEN
      WRITE (NTOUT,FMT=10010)
      ELSE
      WRITE (NTOUT,FMT=10020) NR
      END IF
      WRITE (NTOUT,FMT=10030) LINE
      WRITE (NTOUT,FMT=10040)
      END IF
      END IF
      IF (IMP.EQ.1.OR.IMP.EQ.2) THEN
C      WRITE (*,FMT=10000) KERR,FILENM
      IF (IDIR.EQ.0) THEN
C      WRITE (*,FMT=10010)
      ELSE
C      WRITE (*,FMT=10020) NR
      END IF
C      WRITE (*,FMT=10030) LINE
C      WRITE (*,FMT=10040)
      END IF
      RETURN
   10 CONTINUE
      IF (LERR.NE.0) THEN
      RETURN
      END IF
10000 FORMAT (/,' READING FORTRAN ERROR #: ',I5,'  IN FILE : ',A132)
10010 FORMAT (' LAST LINE READ : ')
10020 FORMAT (' LAST LINE READ (LINE NUMBER : ',I7,' )')
10030 FORMAT (1X,A132)
10040 FORMAT (/,' PLEASE CHECK CONTAINS OF THIS LINE OR PREVIOUS ONES',
     +/)
      END
      SUBROUTINE SUPBL(
     &Z,
     &L
     &)
      INTEGER L
      CHARACTER*(*) Z
      INTEGER I
      INTEGER J
      CHARACTER A
      J = 0
      DO 10 I = 1,L
      A = Z(I:I)
      IF (A.NE.' ') THEN
      Z(I:I) = ' '
      J = J + 1
      Z(J:J) = A
      END IF
   10 CONTINUE
      RETURN
      END
