      REAL TTAI(MAXTTA)
      REAL TV2(MAXTTA,MAXVQ)
      REAL TVMAX(MAXTTA,MAXVQ)
      REAL TVMIN(MAXTTA,MAXVQ)
      REAL TVPKG(MAXTTA-1,MAXVQ)
      INTEGER IHSD1(MAXTTA-1,MAXVQ)
      INTEGER IHSD2(MAXTTA-1,MAXVQ)
      INTEGER ITMAX(MAXTTA,MAXVQ)
      INTEGER JJ1(MAXTTA,MAXVQ)
      INTEGER JJ2(MAXTTA,MAXVQ)
      INTEGER IT1(29)
      INTEGER IT2(29)
      INTEGER LJ1(29)
      INTEGER LJ2(29)
      INTEGER LV2(5)
      INTEGER LVMAX(5)
      INTEGER LVMIN(5)
      COMMON /RESLB1/LJ1,LJ2,LVMIN,LVMAX,LV2,IT1,IT2,JJ1,
     +JJ2,ITMAX,IHSD1,IHSD2,IHSDMI
      COMMON /RESLB2/PRON,TTAI,RPKG,RPKGI,RVMAX,RVMIN,RV2,RASS,
     +TAA,TPKG,TV2,TVMIN,TVMAX,TASS,TVPKG,ZPQNH,RVMCA,RVMCG
      CHARACTER*243 PATH_D
      CHARACTER*243 PATH_P
      CHARACTER*255 NT11CT
      CHARACTER*255 NT1CT
      CHARACTER*255 NT2CT
      CHARACTER*255 NT3CT
      CHARACTER*255 NT4CT
      CHARACTER*255 NT5CT
      CHARACTER*255 NT6CT
      CHARACTER*255 NT7CT
      CHARACTER*255 NT8CT
      CHARACTER*255 NT9CT
      CHARACTER*255 NT1DCT
      CHARACTER*255 NT2DCT
      CHARACTER*255 NT3DCT
      CHARACTER*255 NT4DCT
      CHARACTER*255 NT8DCT
      COMMON /FILES/NT1CT,NT2CT,NT3CT,NT4CT,NT5CT,NT6CT,NT7CT,NT8CT,
     +NT9CT,NT11CT,NT1DCT,NT2DCT,NT3DCT,NT4DCT,NT8DCT,PATH_D,
     +PATH_P
      REAL TCAS
      INTEGER NPROND
      REAL PVMC(7)
      INTEGER IMCA(7)
      INTEGER IPRON(5)
      COMMON /TMBTN1/NPROND,IPRON,IMCA
      COMMON /TMBTN2/TCAS,PVMC
      INTEGER KMODE
      INTEGER NRW
      REAL BTOD2(7)
      REAL RWYL(7)
      REAL RWYP(7)
      COMMON /BAL1/NRW,KMODE
      COMMON /BAL2/RWYL,RWYP,BTOD2
      LOGICAL CHECK1
      LOGICAL CHECK2
      LOGICAL RWNXTT
      LOGICAL RWNXTL
      LOGICAL NXTPLT(MAXTTA,MAXVQ)
      LOGICAL NXTPL1(MAXTAL,MAXVQ)
      LOGICAL NXTPL2(MAXTAL,MAXVQ)
      COMMON /CTESL/CHECK1,CHECK2,RWNXTT,RWNXTL,NXTPLT,NXTPL1,NXTPL2
      LOGICAL LBOOST
      LOGICAL LBOOSL
      LOGICAL LCONF
      LOGICAL LRTO
      LOGICAL LDELBR
      LOGICAL LDELB2
      LOGICAL LDELBC
      LOGICAL LDELBN
      LOGICAL LDELBD
      COMMON /CONFIL/LCONF,LBOOST,LBOOSL,LRTO,LDELBR,LDELB2,LDELBC,
     +LDELBN,LDELBD
      CHARACTER*10 CASENB
      CHARACTER*4 LTITW(16)
      COMMON /COMPC/LTITW,CASENB
      INTEGER*4 CBPROC
      INTEGER*4 ICODE
      CHARACTER*24 PROCID
      REAL TCAS1
      REAL TOD2
      REAL TOR2
      REAL VC2
      REAL VLOFM
      REAL VPNEU
      INTEGER I
      INTEGER ICONT
      INTEGER IOS
      INTEGER IPAS
      INTEGER J
      INTEGER KER
      INTEGER KPRT
      INTEGER KTEMP
      INTEGER KTOD
      INTEGER KTOR
      INTEGER KU
      INTEGER L
      INTEGER MA
      INTEGER MB
      INTEGER MC
      INTEGER PNTIND
      CHARACTER*2 STAPE
      CHARACTER*12 NT1F
      CHARACTER*12 NT2F
      CHARACTER*12 NT3F
      CHARACTER*12 NT4F
      CHARACTER*255 MSG
      CHARACTER*255 F_TAPE
      INTEGER GCAPST
      REAL FINTID
      EXTERNAL FINTID,GCAPST
      EXTERNAL BOUCL,ENGOUT,FICHB,FICHE,INIOUT,INITI,INITR,NXTAC,OPNFIL,
     +RDINP1,REDUT,REDUV,SCPCHK,SETMSG,THSD,WOUT1,WOUTL
      INTRINSIC AINT,SQRT
      AV = 'ATRA'
      MICRO = 1
      IATA = 1
      IDLL = 0
      KPRT = 0
      SDP = '1'
      IMP = 0
      INTB = 1
      ICONT = 0
      WRITE (ISU,FMT='(A2,1X,2A4)') ISSU,IDT1,IDT2
      LJALAC = .FALSE.
      IBRACT = 0
      TBAMU = 0.
      IBRAL1 = 0
      LBAMU1 = 0.
      IBRAL2 = 0
      LBAMU2 = 0.
      RWSHFT = 0
      LDELBR = .FALSE.
      LDELB2 = .FALSE.
      LDELBC = .FALSE.
      LDELBN = .FALSE.
      LDELBD = .FALSE.
      DBRMOD = 0
      DO 1 J = 1,2
      VDELBR(J) = 0
    1 CONTINUE
      RWNXTT = .FALSE.
      RWNXTL = .FALSE.
    5 CONTINUE
      CALL OPNFIL(IPAS,KPRT,KER,PROCID,CBPROC,ICODE)
      IF (ICODE.EQ.3.OR.ICODE.EQ.9) THEN
      RETURN
      END IF
      IF (KER.EQ.1) THEN
      GO TO 180
      ELSE IF (KER.EQ.2) THEN
      RETURN
      END IF
      IF ((IDLL.EQ.0).AND.(.NOT.IPAD)) THEN
      IPAS = 1
      ELSE
      IPAS = 0
      END IF
      MA = 0
      MB = 0
      MC = 0
      KF = 0
      NBERR = 0
      NPMAX = 20000
      TEMP(1) = 0.
      E(25) = 0.
      KEMAX = 5
      V1VRI = .94
      E(1) = .01
      E(2) = .01
      E(3) = .001
      E(4) = .01
      E(5) = .01
      E(7) = .01
      E(8) = .01
      E(9) = .001
      E(10) = .001
      E(11) = .5
      DXM(1) = .01
      DXM(2) = .01
      DXM(3) = .0005
      AK1 = 22.557696/1000000.
      AK2 = 5.255876
      NGRAD1 = 0
      NGRAD2 = 0
      A9 = 99999999.
      A79 = 9999999.
      CALL INITR(TTA,41,A79)
      MODE = 0
      LCW = 0
      NCW = 0
      DRYCHK = 0
      DRYCHL = 0
      CASENB = '          '
      DO 10 I = 1,MERR
      WRITE (ERRM(I),FMT='(80X)')
   10 CONTINUE
   20 CONTINUE
      IF (ICONT.LT.9) THEN
      WRITE(CASENB,FMT='(A5,I1)') 'CASE ',ICONT+1
      ELSEIF (ICONT.LT.99) THEN
      WRITE(CASENB,FMT='(A5,I2)') 'CASE ',ICONT+1
      ELSEIF (ICONT.LT.999) THEN
      WRITE(CASENB,FMT='(A5,I3)') 'CASE ',ICONT+1
      ELSEIF (ICONT.LT.9999) THEN
      WRITE(CASENB,FMT='(A5,I4)') 'CASE ',ICONT+1
      ELSEIF (ICONT.LT.99999) THEN
      WRITE(CASENB,FMT='(A5,I5)') 'CASE ',ICONT+1
      END IF
      IF (IATA.EQ.0) THEN
      IF ((MA.EQ.1).OR.(MA.EQ.2)) THEN
      IF ((DRYCHK.EQ.0).AND.(DRYCHL.EQ.0)) THEN
      IF ((LDELBR).AND.(.NOT.LDELB2)) THEN
      LDELB2 = .TRUE.
      REWIND(NT5)
      IF (ICONT.EQ.0) THEN
      READ(NT5,*)
      READ(NT5,*)
      ELSE
      IF (MA.EQ.2) THEN
      DO 25 I = 1,ICONT
      CALL NXTAC(NT5,KER)
   25 CONTINUE
      ELSEIF (MA.EQ.1) THEN
      DO 26 I = 1,ICONT
      CALL NXTAC(NT5,KER)
   26 CONTINUE
      END IF
      END IF
      ELSEIF (LDELBR.AND.LDELB2) THEN
      LDELBR = .FALSE.
      LDELB2 = .FALSE.
      END IF
      ELSE
      IF ((LDELBR).AND.(.NOT.LDELBC).AND.(.NOT.LDELB2)) THEN
      LDELBC = .TRUE.
      END IF
      END IF
      END IF
      END IF
      MA = 0
      CALL INITR(GENE,20,0.)
      KV1MN = 0
      AHSD = 0.
      STEEP1 = 0
      STEEP2 = 0
      DO 30 J = 1,20
      COEF(2*J) = 0.
      COEF(2*J-1) = 1.
   30 CONTINUE
      KTJ = 1
      IOS = 0
      IF (IATA.EQ.1) THEN
      CALL FICHE(MA,MB)
      IF ((KFI.EQ.1).OR. (KF.NE.0)) THEN
      CALL INIOUT
      RETURN
      END IF
      END IF
      IF (MICRO.EQ.1) THEN
      IMP = 2
      ELSE IF (MICRO.EQ.0) THEN
      IMP = 0
      END IF
      IF (IDLL.EQ.1) IMP = 0
      IF (K6.NE.1) IMP = -1
      CALL RDINP1(PROCID,CBPROC,ICODE)
      IF (ICODE.EQ.3.OR.ICODE.EQ.9) THEN
      RETURN
      END IF
      IF (IATA.EQ.1) THEN
      IF (PSTRUC.EQ.0.) THEN
      PSTRUC = XMAS(9)
      END IF
      CALL SCPCHK
      END IF
      IF (REGU(8).EQ.'PA42') THEN
      IF (NIGC.EQ.(1+RWSHFT).OR. (NIGC.GE.10.AND.NIGC.LE.15)) THEN
      LA42 = 0
      ELSE
      LA42 = 1
      END IF
      ELSE
      LA42 = 0
      END IF
      IF (KF.EQ.3) THEN
      CALL NXTAC(NT5,KER)
      KF = 0
      ICONT = ICONT + 1
      IF (KER.EQ.1) THEN
      GO TO 40
      ELSE
      GO TO 20
      END IF
      ELSE IF ((KF.NE.0).OR. (KFI.EQ.1)) THEN
      IF (IATA.EQ.1) THEN
      CALL INIOUT
      RETURN
      ELSE
      GO TO 180
      END IF
      END IF
      IF (IATA.EQ.1) THEN
      IF (RK2T.NE.A9) V2VS = RK2T
      IF (RKV1.NE.A9) FV1VR = RKV1
      END IF
      IF (IPAS.EQ.1.AND. (MODE.EQ.2)) THEN
      CLOSE (NT1,STATUS='DELETE')
      CLOSE (NT2,STATUS='DELETE')
      CLOSE (NT3,STATUS='DELETE')
      CLOSE (NT4,STATUS='DELETE')
      OPEN (NT1,FILE=NT1F,FORM='UNFORMATTED')
      OPEN (NT2,FILE=NT2F,FORM='UNFORMATTED')
      OPEN (NT3,FILE=NT3F,FORM='UNFORMATTED')
      OPEN (NT4,FILE=NT4F,FORM='UNFORMATTED')
      IPAS = 2
      END IF
      IF (MICRO.EQ.1) THEN
      IF ((IDLL.EQ.0).AND.(.NOT.IPAD)) THEN
      IF (IATA.EQ.0) WRITE (*,FMT=10000) IAC,ITO
      ELSE IF (IDLL.EQ.1) THEN
      WRITE (MSG,FMT=10010) IAC,ITO
      ICODE = 1
      CALL SETMSG(ICODE,MSG,PROCID,CBPROC)
      IF (ICODE.EQ.3.OR.ICODE.EQ.9) THEN
      RETURN
      END IF
      END IF
      END IF
      VPNEU = AERO(11)
      VC1 = 16./ (AERO(6)*AERO(5))
      IF (VC1.LE.0.) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' INVALID VALUE FOR STATEMENT : VC1 = SQRT(VC1)'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'INVALID VALUE FOR STATEMENT : VC1 = SQRT(VC1)'
      END IF
      GO TO 180
      END IF
      VC1 = SQRT(VC1)*FTOKV
      IF (AERO(3).NE.0.) THEN
      VC2 = 16./ (AERO(6)*AERO(3))
      IF (VC2.LE.0.) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' INVALID VALUE FOR STATEMENT : VC2 = SQRT(VC2)'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'INVALID VALUE FOR STATEMENT : VC2 = SQRT(VC2)'
      END IF
      GO TO 180
      END IF
      VC2 = SQRT(VC2)/.5144
      END IF
      KTOD = IGC(1)/10
      KTOR = IGC(2)/10
      PTOD2 = A9
      PTOR2 = A9
      IF (KTOD.EQ.1.AND.KTOR.EQ.501) KTJ = 0
      IF (KTJ.EQ.1.AND.KMO.EQ.1.AND.K6.EQ.1) WRITE (NT6,FMT=10020)
      IF (KTJ.EQ.1.AND.KMO.EQ.1) KTJ = 0
   40 CONTINUE
      IF (IATA.EQ.0) THEN
      MB = 0
      CALL FICHE(MA,MB)
      IF ((KF.EQ.1).OR.(KFT.NE.0)) THEN
      GO TO 40
      ELSE IF (KF.EQ.2) THEN
      GO TO 180
      END IF
      KTEMP = 0
      DO 60 I = 1,40
      DO 50 J = 1,5
      IHSD1(I,J) = A9
      IHSD2(I,J) = A9
      TVPKG(I,J) = A9
   50 CONTINUE
   60 CONTINUE
      CALL INITR(ZPQNH,5,A9)
      IF (TTA(2).NE.A79) THEN
      IF (TTA(1).GT.TTA(2)) KTEMP = 1
      END IF
      IF (MA.EQ.1) THEN
      IF ((DRYCHK.EQ.0).AND. (DRYCHL.EQ.0)) THEN
      GO TO 170
      ELSE
      IF (DRYCHK.NE.0) CALL WOUT1(INTB,PROCID,CBPROC,ICODE)
      IF (DRYCHL.NE.0) CALL WOUTL(INTB)
      IF ((DRYCHK.EQ.1).OR. (DRYCHL.EQ.1)) THEN
      IF (DRYCHK.EQ.1) DRYCHK = 2
      IF (DRYCHL.EQ.1) DRYCHL = 2
      INTB = INTB + 1
      WRITE(STAPE,'(I2)') NTB(INTB)
      PNTIND = GCAPST('.',NT1CT)
      F_TAPE=NT1CT(1:PNTIND)//STAPE
      OPEN (NTB(INTB),FORM='UNFORMATTED',
     +ACCESS='SEQUENTIAL',ERR=180,IOSTAT=IOS,
     +FILE=F_TAPE)
      WRITE(STAPE,'(I2)') NTBL(INTB)
      PNTIND = GCAPST('.',NT1CT)
      F_TAPE=NT1CT(1:PNTIND)//STAPE
      OPEN (NTBL(INTB),FORM='UNFORMATTED',
     +ACCESS='SEQUENTIAL',ERR=180,IOSTAT=IOS,
     +FILE=F_TAPE)
      REWIND (NT5)
      IF (MICRO.EQ.1) READ (NT5,FMT='(/)')
      DO 70 I = 1,ICONT
      CALL NXTAC(NT5,KER)
   70 CONTINUE
      CALL ENGOUT(2)
      GO TO 20
      ELSE IF ((DRYCHK.EQ.2).OR. (DRYCHL.EQ.2)) THEN
      DO 80 I = INTB,1,-1
      CLOSE (NTB(I),STATUS='DELETE')
      CLOSE (NTBL(I),STATUS='DELETE')
   80 CONTINUE
      INTB = 1
      IF (LDELBC) THEN
      LDELBC = .FALSE.
      END IF
      DRYCHK = 0
      DRYCHL = 0
      GO TO 170
      END IF
      END IF
      ELSE IF (MA.EQ.2) THEN
      IF ((DRYCHK.EQ.0).AND. (DRYCHL.EQ.0)) THEN
      IF ((LDELB2).OR.
     +((.NOT.LDELBR).AND.(.NOT.LDELBC)
     +.AND.(.NOT.LDELB2))) THEN
      ICONT = ICONT + 1
      END IF
      GO TO 20
      ELSE
      IF (DRYCHK.NE.0) CALL WOUT1(INTB,PROCID,CBPROC,ICODE)
      IF (DRYCHL.NE.0) CALL WOUTL(INTB)
      IF ((DRYCHK.EQ.1).OR. (DRYCHL.EQ.1)) THEN
      IF (DRYCHK.EQ.1) DRYCHK = 2
      IF (DRYCHL.EQ.1) DRYCHL = 2
      INTB = INTB + 1
      WRITE(STAPE,'(I2)') NTB(INTB)
      PNTIND = GCAPST('.',NT1CT)
      F_TAPE=NT1CT(1:PNTIND)//STAPE
      OPEN (NTB(INTB),FORM='UNFORMATTED',
     +ACCESS='SEQUENTIAL',ERR=180,IOSTAT=IOS,
     +FILE=F_TAPE)
      WRITE(STAPE,'(I2)') NTBL(INTB)
      PNTIND = GCAPST('.',NT1CT)
      F_TAPE=NT1CT(1:PNTIND)//STAPE
      OPEN (NTBL(INTB),FORM='UNFORMATTED',
     +ACCESS='SEQUENTIAL',ERR=180,IOSTAT=IOS,
     +FILE=F_TAPE)
      REWIND (NT5)
      IF (MICRO.EQ.1) READ (NT5,FMT='(/)')
      DO 90 I = 1,ICONT
      CALL NXTAC(NT5,KER)
   90 CONTINUE
      CALL ENGOUT(2)
      ELSE IF ((DRYCHK.EQ.2).OR. (DRYCHL.EQ.2)) THEN
      DO 100 I = INTB,1,-1
      CLOSE (NTB(I),STATUS='DELETE')
      CLOSE (NTBL(I),STATUS='DELETE')
  100 CONTINUE
      INTB = 1
      IF ((LDELB2).OR.
     +((.NOT.LDELBR).AND.(.NOT.LDELBC)
     +.AND.(.NOT.LDELB2))) THEN
      ICONT = ICONT + 1
      ELSE
      REWIND (NT5)
      IF (ICONT.EQ.0) THEN
      READ(NT5,*)
      READ(NT5,*)
      END IF
      DO 105 I = 1,ICONT
      CALL NXTAC(NT5,KER)
  105 CONTINUE
      END IF
      DRYCHK = 0
      DRYCHL = 0
      IF (LDELBC) THEN
      LDELBR = .FALSE.
      LDELBC = .FALSE.
      LDELB2 = .TRUE.
      END IF
      END IF
      GO TO 20
      END IF
      END IF
      ELSE
      IF (KF.EQ.1) THEN
      CALL INIOUT
      RETURN
      END IF
      END IF
      IF (LA42.EQ.1) TOD = TOR
      IF ((MICRO.EQ.1).AND. ((DRYCHK.NE.2).OR. (DRYCHL.NE.2))) THEN
      IF ((IDLL.EQ.0).AND.(.NOT.IPAD)) THEN
C      WRITE (*,FMT=10030) NPIST(1), (NPIST(I),I=2,7),QFU
      ELSE IF (IDLL.EQ.1) THEN
      WRITE (MSG,FMT=10030) NPIST(1), (NPIST(I),I=2,7),QFU
      ICODE = 1
      CALL SETMSG(ICODE,MSG,PROCID,CBPROC)
      IF (ICODE.EQ.3.OR.ICODE.EQ.9) THEN
      RETURN
      END IF
      END IF
      END IF
      CALL INITR(ZOUT,60,A9)
      DIVER(3) = 0.
      IF ((KSP.NE.0).AND. (QLD.NE.1.)) CALL ENGOUT(3)
      ITERMA = 15
      EPSI = .001
      IF (MB.EQ.2) GO TO 40
      KU = 0
      IF ((MODE.NE.0).AND.(MODE.NE.1)) THEN
      VQT(1) = QNHC
      NVQT = 1
      VQ0 = WIND
      CODCAL = 1
      END IF
      CALL INITR(TZREF,20,A9)
      CALL INITR(DIVER,20,0.)
      DO 110 J = 1,29
      IF (PRON(J).EQ.9999999.) GO TO 120
  110 CONTINUE
  120 CONTINUE
      NPROND = J - 1
      DO 130 J = 1,NTA
      TTAI(J) = TTA(NTA-J+1)
  130 CONTINUE
      TTA(NTA+1) = 99999999.
      IF (A1.EQ.1..OR.A1.EQ.2.) THEN
      KU = 1
      ELSE
      KU = 0
      END IF
      IF (IGC(3).NE.0.AND.IGC(4).NE.0) THEN
      E(25) = 1.
      ELSE
      E(25) = 0.
      END IF
      CALL REDUT
      CALL REDUV(30,-99.,BE30)
      CALL REDUV(31,-99.,BE31)
      CALL REDUV(32,-99.,BE32)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' BINT '
      WRITE (NT6,FMT=*) BINT
      WRITE (NT6,FMT='(A)') ' BE30 '
      WRITE (NT6,FMT=*) BE30
      WRITE (NT6,FMT='(A)') ' BE31 '
      WRITE (NT6,FMT=*) BE31
      WRITE (NT6,FMT='(A)') ' BE32 '
      WRITE (NT6,FMT=*) BE32
      END IF
      IF (E(25).EQ.1.) THEN
      TOD2 = TOD - ATOD
      TOR2 = TOR - ATOD
      TOD2 = (TOD2-COEF(16))/COEF(15)
      TOR2 = (TOR2-COEF(18))/COEF(17)
      TOD2 = FINTID(TOD2,BINT(25),XLE(1),12)
      TOR2 = FINTID(TOR2,BINT(37),XLE(1),12)
      IF (MODE.EQ.5) THEN
      DO 140 L = 1,NRW
      BTOD2(L) = (RWYL(L)-COEF(16))/COEF(15)
      BTOD2(L) = FINTID(BTOD2(L),BINT(25),XLE(1),12)
  140 CONTINUE
      END IF
      END IF
      VLOFM = VPNEU
      VLOFM = FINTID(VLOFM,BINT(73),XVE(1),12)
      CALL REDUV(6,PP,BPIS)
      IF (E(25).EQ.1.) THEN
      TOD2 = FINTID(TOD2,BPIS(25),XLE(1),12)
      TOR2 = FINTID(TOR2,BPIS(37),XLE(1),12)
      IF (MODE.EQ.5) THEN
      DO 150 L = 1,NRW
      BTOD2(L) = FINTID(BTOD2(L),BPIS(25),XLE(1),12)
  150 CONTINUE
      END IF
      END IF
      VLOFM = FINTID(VLOFM,BPIS(73),XVE(1),12)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' BPIS '
      WRITE (NT6,FMT=*) BPIS
      END IF
      K1 = 1
      CALL BOUCL(TCAS1,TOD2,TOR2,VC2,VLOFM,KTEMP,KU,MA,MB,MC,KER,
     &PROCID,CBPROC,ICODE)
      IF (ICODE.EQ.3.OR.ICODE.EQ.9) THEN
      RETURN
      END IF
      IF (KER.EQ.1) THEN
      GO TO 180
      ELSE IF (KER.EQ.2) THEN
      GO TO 40
      END IF
      MB = 0
      MC = 0
      IF ((MODE.NE.0).AND.(MODE.NE.1)) GO TO 40
      IF (AV.EQ.'A3BA') THEN
      IF (ITMAX(1,NVQT).EQ.1000) THEN
      NGRAD2 = 0
      ELSE
      IF (ITMAX(1,NVQT).LE.AINT(TCAS1)) THEN
      NGRAD2 = 0
      END IF
      END IF
      IF (TEMP(1).EQ.0..OR.TEMP(1).EQ.4.) THEN
      IF (A2.EQ.1..AND.NVQT.EQ.5.AND.DRYCHK.EQ.0) CALL FICHB
      END IF
      END IF
      IF (IATA.EQ.0) THEN
      IF ((KTR.EQ.2).AND. (AV.EQ.'A3BA').AND. (DRYCHK.EQ.0)) THEN
      IF (DIVER(1).EQ.A79.OR.DIVER(2).EQ.A79) CALL THSD
      END IF
      GO TO 40
      ELSE
      CALL INIOUT
      RETURN
      END IF
  170 CONTINUE
      IF (IATA.EQ.0) THEN
      IF ((LDELBR).AND.(.NOT.LDELB2)) THEN
      GO TO 20
      END IF
      END IF
      IF (IATA.EQ.0) THEN
      CLOSE (NT11)
      IF (MODE.EQ.2) THEN
      CLOSE (NT1,STATUS='DELETE')
      CLOSE (NT2,STATUS='DELETE')
      CLOSE (NT3,STATUS='DELETE')
      CLOSE (NT4,STATUS='DELETE')
      ELSE
      CLOSE (NT5)
      IF (MICRO.EQ.1) CLOSE (NT6)
      CALL CLOSFL(NT1)
      CALL CLOSFL(NT2)
      CALL CLOSFL(NT3)
      CALL CLOSFL(NT4)
      CLOSE (NT7)
      IF (AV.EQ.'A3BA') THEN
      CALL CLOSFL(NT8)
      CALL CLOSFL(NT9)
      END IF
      CALL CLOSFL(NT1D)
      CALL CLOSFL(NT2D)
      CALL CLOSFL(NT8D)
      END IF
      IF ((IDLL.EQ.0).AND.(.NOT.IPAD)) THEN
      STOP ' END OF  TLC  COMPUTATION '
      ELSE IF (IDLL.EQ.1) THEN
      MSG = ' END OF   T L C   COMPUTATION  '
      ICODE = 4
      CALL SETMSG(ICODE,MSG,PROCID,CBPROC)
      RETURN
      ELSE IF (IPAD) THEN
      RETURN
      END IF
      END IF
  180 CONTINUE
      IF (IOS.NE.0) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A,I4,A)') ' ERROR #',IOS,
     +' WHILE OPENING TEMPORARY FILE'
      END IF
      IF (K6.EQ.1) WRITE (NT6,FMT='(/,A)') ' INTERRUPTED COMPUTATION '
      CLOSE (NT11)
      CLOSE (NT5)
      IF (MICRO.EQ.1) CLOSE (NT6)
      CALL CLOSFL(NT1)
      CALL CLOSFL(NT2)
      CALL CLOSFL(NT3)
      CALL CLOSFL(NT4)
      CLOSE (NT7)
      IF (AV.EQ.'A3BA') THEN
      CLOSE (NT8)
      CLOSE (NT9)
      END IF
      IF ((IDLL.EQ.0).AND.(.NOT.IPAD)) THEN
      IF (MICRO.EQ.1) WRITE (*,FMT='(/,A)')
     +' INTERRUPTED COMPUTATION - SEE GENERAL OUTPUT : RESUGEN.OUT'
      STOP ' INTERRUPTED COMPUTATION  '
      ELSE IF (IDLL.EQ.1) THEN
      ICODE =3
      MSG = ' INTERRUPTED COMPUTATION SEE GENERAL INPUT FILE : '//
     +NT6CT
      CALL SETMSG(ICODE,MSG,PROCID,CBPROC)
      RETURN
      ELSE IF (IPAD) THEN
      RETURN
      END IF
10000 FORMAT ('  AIRCRAFT ---> ',5A4,'  CONFIG. ---> ',5A4,/)
10010 FORMAT ('  AIRCRAFT ---> ',5A4,'  CONFIG. ---> ',5A4)
10020 FORMAT (/,' ***  OBSTACLE MARGIN : 15FT')
10030 FORMAT (2X,A4,2X,6A4,2X,2A4)
      END
      SUBROUTINE TRANRI(
     &X,
     &J,
     &N
     &)
      INTEGER N
      REAL X(*)
      INTEGER J(*)
      INTEGER L
      INTRINSIC INT
      DO 10 L = 1,N
      J(L) = INT(X(L))
   10 CONTINUE
      RETURN
      END
      SUBROUTINE TRANSA(
     &KI,
     &KJ,
     &N
     &)
      INTEGER N
      CHARACTER*4 KI(*),KJ(*)
      INTEGER L
      DO 10 L = 1,N
      KJ(L) = KI(L)
   10 CONTINUE
      RETURN
      END
      SUBROUTINE TRANSI(
     &I,
     &J,
     &N
     &)
      INTEGER N
      INTEGER I(*),J(*)
      INTEGER L
      DO 10 L = 1,N
      J(L) = I(L)
   10 CONTINUE
      RETURN
      END
      SUBROUTINE TRANSR(
     &RI,
     &RJ,
     &N
     &)
      INTEGER N
      REAL RI(*),RJ(*)
      INTEGER L
      DO 10 L = 1,N
      RJ(L) = RI(L)
   10 CONTINUE
      RETURN
      END
      REAL FUNCTION ZPRES(
     &ZG,
     &DT
     &)
      REAL DT,ZG
      REAL CT,DZP,ZG0,ZG1,ZG2,ZP,ZP1,ZP2
      INTEGER ITER
      INTRINSIC ABS,ALOG
      REAL ZGEOM
      ZGEOM(ZP,DT) = ZP - DT/.0065*ALOG(1.-.0065*ZP/288.15)
      ITER = 0
      DZP = 10.
      ZG0 = ZG*.3048
      ZP1 = ZG0
   10 CONTINUE
      ZG1 = ZGEOM(ZP1,DT)
      IF (ABS(ZG0-ZG1).LE.0.1) GO TO 20
      ZP2 = ZP1 + DZP
      ZG2 = ZGEOM(ZP2,DT)
      CT = (ZG2-ZG1)/DZP
      ZP1 = ZP1 + (ZG0-ZG1)/CT
      ITER = ITER + 1
      IF (ITER.EQ.5) STOP ' *** PB IN ZPRES  '
      GO TO 10
   20 CONTINUE
      ZPRES = ZP1/.3048
      RETURN
      END
