      EXTERNAL ENGOUT,FICHE,INFLU,INITB1,INITI,INITR,JNT,PIST,REDUH,
     +REDUV,SV1MIN,TRAJE,TRANSR,WMAXI,ZFICB
      INTRINSIC ABS,AMAX1,AMIN1,FLOAT,MOD,SQRT
      DATA IVMC/'VMCA','VMCG'/
      KER = 0
      P = 150.
      P0 = 10332.3
      PFTO1 = A9
      PFTOM = A9
      CALL INITI(IMCA,7,0)
      KOD = 0
      IOBFTO = 0
      IF (MODE.EQ.5) NVQT = NRW
      DO 360 IJK = 1,NTA
      NLCT = IJK
      KOD1 = 0
      CALL INITI(IVMCA,7,0)
      CALL INITI(IVMCG,7,0)
      DO 350 I = 1,NVQT
      I1 = 0
      I2 = 0
      J1 = 0
      J2 = 0
      NCCT = I
      IF (MODE.EQ.5) THEN
      TOD = RWYL(I)
      TOR = TOD
      ASD = TOD
      END IF
      DO 10 IEF = 1,3
      NLFLAG(I,IEF) = .FALSE.
   10 CONTINUE
      CALL INITR(ZOUTE,20,0.)
      V1MBAL = A9
      V1VRMB = A9
      DO 340 IEF = 1,3
      IF (CODCAL.EQ.1) THEN
      VENT = VQ0
      IF (MODE.EQ.5) THEN
      QFE = QNHC
      ELSE
      QFE = VQT(I)
      END IF
      ELSE
      VENT = VQT(I)
      IF ((MODE.EQ.1).AND. (IEF.NE.1)) THEN
      QFE = VQ0 + DQNH(IEF-1)
      ELSE
      QFE = VQ0
      END IF
      END IF
      IF (PU.EQ.1) QFE = QFE*33.8638
      IF ((IATA.EQ.0).OR.(CODCAL.EQ.1.)) THEN
      IF (ABS(QFE-1013.25).GT..005) THEN
      PZM = QFE*10.19715
      ZP = ((1.- ((PZM/P0)** (1./AK2)))/AK1)/.3048
      ZP = ZG + ZP
      ELSE
      ZP = ZG
      END IF
      END IF
      IF ((VENT.GE.XTWD(1)).AND.(VENT.LE.XTWD(2))) THEN
      LXTWD = .TRUE.
      V2VSMI = XTWD(3)
      SSGMIN = XTWD(4)
      GAMXWP = XTWD(5)
      ELSE
      LXTWD = .FALSE.
      V2VSMI = ZLIM(4)
      SSGMIN = ZLIM(28)
      GAMXWP = 1.
      END IF
      TRA = TTA(IJK)
      IF (TU.EQ.1.) TRA = (TRA-32.)/1.8
      IF (LACONX) THEN
      TM1 = FINT(ZP,VIRTEM(1),VIRTEM(ITM1),1)
      TM2 = FINT(ZP,VIRTEM(1),VIRTEM(ITM2),1)
      DT1 = FINT(ZP,VIRTEM(1),VIRTEM(IDT),1)
      IF (TRA.LE.TM1) THEN
      DT = 0.0
      ELSE IF (TRA.GT.TM2) THEN
      DT = FINT(TRA,VIRTEM(ITM3),VIRTEM(IDTB),1)
      ELSE
      DT = (TRA-TM1)/(TM2-TM1)*DT1
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** TM1,TM2,DT1,DT,TRA,TRA+DT'
      WRITE (NT6,FMT=*) TM1,TM2,DT1,DT,TRA,TRA+DT
      END IF
      TRA = TRA + DT
      END IF
      TS = 288.15 - .0065*ZP*.3048 - 273.15
      TRISA = TRA - TS
      IF (TRISA.LT.-30) THEN
      TISA = -30
      TA = TISA + TS
      ELSE
      TA = TRA
      TISA = TRISA
      END IF
      IF (IEF.NE.1) THEN
      IF ((MODE.EQ.0).OR. (DQNH(IEF-1).EQ.0.).OR.
     +(CODCAL.EQ.1)) THEN
      DTOW(I,IEF-1)   = 0.
      DV1MIN(I,IEF-1) = 0.
      DV1MIN(I,IEF-1) = 0.
      DV1MOY(I,IEF-1) = 0.
      DVR(I,IEF-1)    = 0.
      DV2(I,IEF-1)    = 0.
      NLFLAG(I,IEF) = .TRUE.
      GO TO 340
      END IF
      END IF
      IF (IMCA(I).EQ.1) THEN
      CALL INITB1(V1MIN,V1MAX,VR,V2,J1,J2,I,IJK)
      IF ((KSP.NE.0).AND. (IEF.EQ.1)) CALL ENGOUT(5)
      GO TO 290
      END IF
      CALL INITR(ZOUT,60,A9)
      CALL INITR(ZOUTS,60,A9)
      ASDMBA = A9
      TODMBA = A9
      TORMBA = A9
      KMU = 0
      KMCA = 0
      KMCG = 0
      KMCG2 = 0
      KMCA1 = 0
      KMCAG = 0
      ITER = 0
      TCAS = FINT(ZP,DTCD(1),DTCD(14),1)
      IF ((IJK.EQ.1).AND. (IEF.EQ.1)) THEN
      ZPQNH(I) = ZP
      TISAM = DTCD(21)
      ZPFTOM = ZP + AERO(8)
      DZFTOM = ZPRES(ZPFTOM,TISAM) - ZPRES(ZP,TISAM)
      ZPFTOM = ZP + DZFTOM
      K1 = 1
      K2 = 1
      CALL JNT(2401,TISAM,ZPFTOM,Z(1))
      PFTOM = Z(1)
      IF (NTAB(2404).NE.0) CALL JNT(2404,PFTOM,FTOKV,Z(1))
      PFTOM = Z(1)*COEF(21) + COEF(22)
      CALL INFLU(2401,PFTOM,IZCODT(1),RS)
      PFTOM = RS
      PFTOMT(I) = PFTOM
      PFTO1 = PFTOM
      ELSE
      PFTO1 = PFTOMT(I)
      END IF
      KB = 0
      PSTRUK = PSTRUC
      LV2MA = .FALSE.
      IF (KOD1.EQ.0) THEN
      IF (TISA.LT.ZLIM(14)) THEN
      ICT = 1
      ELSE IF (TISA.GE.ZLIM(15)) THEN
      ICT = 3
      ELSE
      ICT = 2
      END IF
      K1 = 1
      K2 = 1
      IR0 = 0
      DO 20 L = 1,4001,200
      IR0 = IR0 + 1
      IF (NTAB(L).NE.0) THEN
      CALL JNT(L,TISA,ZP,Z(1))
      TZREF(IR0) = Z(1)
      END IF
   20 CONTINUE
      IF (ICT.EQ.2) THEN
      IF (NTAB(2210).NE.0.AND.NTAB(2211).NE.0) THEN
      CALL JNT(2210,TISA,ZP,Z(1))
      TZREF(1) = Z(1)
      ELSE
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** TOD 450 451 MISSING'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'TOD 450 451 MISSING'
      END IF
      KER = 1
      RETURN
      END IF
      IF (NTAB(2214).NE.0.AND.NTAB(2215).NE.0) THEN
      CALL JNT(2214,TISA,ZP,Z(1))
      TZREF(2) = Z(1)
      ELSE
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** TOR 2214 2215 MISSING'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'TOR 2214 2215 MISSING'
      END IF
      KER = 1
      RETURN
      END IF
      ELSE IF (ICT.EQ.3) THEN
      IF (NTAB(2212).NE.0.AND.NTAB(2212).NE.0) THEN
      CALL JNT(2212,TISA,ZP,Z(1))
      TZREF(1) = Z(1)
      ELSE
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** TOD 2212 2213 MISSING'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'TOD 2212 2213 MISSING'
      END IF
      KER = 1
      RETURN
      END IF
      IF (NTAB(2216).NE.0.AND.NTAB(2217).NE.0) THEN
      CALL JNT(2216,TISA,ZP,Z(1))
      TZREF(2) = Z(1)
      ELSE
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** TOR 2216 2217 MISSING'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'TOR 2216 2217 MISSING'
      END IF
      KER = 1
      RETURN
      END IF
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***BOUCL*** TZREF '
      WRITE (NT6,FMT=*) TZREF
      END IF
      PFTO = TZREF(13)
      ZPFTO = ZP + AERO(8)
      DZPFTO = ZPRES(ZPFTO,TISA) - ZPRES(ZP,TISA)
      ZPFTO = ZP + DZPFTO
      CALL JNT(2401,TISA,ZPFTO,Z(1))
      PFTO = Z(1)
      IF (NTAB(2404).NE.0) CALL JNT(2404,PFTO,FTOKV,Z(1))
      PFTO = Z(1)*COEF(21) + COEF(22)
      CALL INFLU(2401,PFTO,IZCODT(1),RS)
      PFTO = RS
      ZOUT(24) = PFTO*UP
      IF (AERO(10).EQ.0.) THEN
      IF (NTAB(2203).EQ.0) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** VMCA INFO. MISSING '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'VMCA INFO. MISSING '
      END IF
      KER = 1
      RETURN
      END IF
      CALL JNT(2203,TRISA,ZP,Z(1))
      VMCA = Z(1)
      ELSE
      VMCA = AERO(10)/1.05
      END IF
      VMCA = VMCA + DVMCA
      VMCA = VMCA*COEF(25) + COEF(26)
      VMCAR = VMCA*1.05
      VMCA2 = VMCA*1.10
      IF (CVIT(21).NE.0) THEN
      VMCAIA = FINTV(1.1*VMCA,CVIT(21))
      ELSE
      IF (NTAB(2205).EQ.0) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** V2 CAS-IAS MISSING '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'V2 CAS-IAS MISSING'
      END IF
      KER = 1
      RETURN
      END IF
      K2 = 1
      K1 = 1
      CALL JNT(2205,PMIN,1.1*VMCA,Z(1))
      VMCAIA = Z(1)
      END IF
      IF (IEF.EQ.1) THEN
      IVMCA(7) = AR(VMCAIA)
      END IF
      IF (AERO(9).EQ.0.) THEN
      IF (NTAB(2201).EQ.0) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** VMCG INFO. MISSING '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'VMCG INFO. MISSING '
      END IF
      KER = 1
      RETURN
      END IF
      CALL JNT(2201,TRISA,ZP,Z(1))
      VMCG = Z(1)
      ELSE
      VMCG = AERO(9)
      END IF
      VMCG = VMCG + DVMCG + DVMCPE
      VMCG = VMCG + VMC1(NIGC-RWSHFT)
      VMCG = VMCG*COEF(23) + COEF(24)
      VMCGIA = FINTV(VMCG,CVIT(1))
      IF (IEF.EQ.1) THEN
      IVMCG(7) = AR(VMCGIA)
      END IF
      IF (KPPM.EQ.1) CALL TRANSR(XPPM(1),XMAS(1),12)
      CALL REDUH(2,XXX,BMAS,XMAS)
      K2 = 9
      K1 = 1
      IF (ICT.EQ.2) THEN
      VAL = TZREF(1)
      CALL JNT(2211,VAL,XMAS(1),ZLS(1))
      CALL TRANSR(ZLS(1),BMAS(1),9)
      VAL = TZREF(2)
      CALL JNT(2215,VAL,XMAS(1),ZLS(1))
      CALL TRANSR(ZLS(1),BMAS(13),9)
      ELSE IF (ICT.EQ.3) THEN
      VAL = TZREF(1)
      CALL JNT(2213,VAL,XMAS(1),ZLS(1))
      CALL TRANSR(ZLS(1),BMAS(1),9)
      VAL = TZREF(2)
      CALL JNT(2217,VAL,XMAS(1),ZLS(1))
      CALL TRANSR(ZLS(1),BMAS(13),9)
      END IF
      K2 = 1
      IF ((MODE.EQ.0).AND. (CODCAL.EQ.0.)) KOD1 = 1
      IF (MODE.EQ.5) KOD1 = 1
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***BOUCL*** BMAS '
      WRITE (NT6,FMT=*) BMAS
      END IF
      END IF
      IF (KOD.NE.1) THEN
      CALL REDUV(5,VENT,BVEN)
      IF (E(25).EQ.1.) THEN
      TOD2V = FINTID(TOD2,BVEN(25),XLE(1),12)
      TOR2V = FINTID(TOR2,BVEN(37),XLE(1),12)
      IF (MODE.EQ.5) THEN
      DO 30 L = 1,NRW
      BTOD2(L) = FINTID(BTOD2(L),BVEN(25),XLE(1),12)
   30 CONTINUE
      END IF
      END IF
      VLOFV = FINTID(VLOFM,BVEN(73),XVE(1),12)
      IF (NOBST.NE.0.OR.KTR.NE.0) THEN
      CALL JNT(2005,X,VENT,Z(1))
      END IF
      K1 = 1
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***BOUCL*** BVEN '
      WRITE (NT6,FMT=*) BVEN
      END IF
      IF (CODCAL.EQ.1.) KOD = 1
      END IF
   40 CONTINUE
      IOD = 0
      IF (PSTRUK.GT.PFTO) THEN
      COD = 8
      PMINI = PFTO
      ELSE
      COD = 1
      PMINI = PSTRUK
      END IF
      CODINI = COD
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***BOUCL*** PSTRUC,PFTO,COD '
      WRITE (NT6,FMT=*) PSTRUC,PFTO,COD
      END IF
      IF (RWNXTT) THEN
      ZL = AMIN1(V2VSMA,V2SMAL) - AMAX1(V2VSMI,V2SMIL)
      A = AMAX1(V2VSMI,V2SMIL)
      B = AMIN1(V2VSMA,V2SMAL)
      ELSE
      ZL = V2VSMA - V2VSMI
      A = V2VSMI
      B = V2VSMA
      END IF
      F(1) = 1.
      F(2) = 1.
      DO 50 K = 3,25
      F(K) = F(K-1) + F(K-2)
      IF (F(K).GE.P) GO TO 60
   50 CONTINUE
      K = 15
   60 CONTINUE
      DELTA = ZL/F(K)
      X1 = A + DELTA*F(K-2)
      X2 = A + DELTA*F(K-1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' DELTA,X1,X2,K,F '
      WRITE (NT6,FMT=*) DELTA,X1,X2,K,F
      END IF
      IF (V2VS.NE.0.) X2 = V2VS
   70 CONTINUE
      V2SVS = X2
      CJ1 = 0
      CJ2 = 0
      CI1 = 0
      CI2 = 0
      L = 1
      ICOD = 0
   80 CONTINUE
      K1 = 9
      IF (KS.EQ.1) WRITE (NT6,FMT=10000) V2SVS
      IF (KF.EQ.1) THEN
      KER = 2
      RETURN
      END IF
      CALL REDUV(4,V2SVS,BV2)
      IF (E(25).EQ.1.) THEN
      TOD2S = FINTID(TOD2V,BV2(25),XLE(1),12)
      TOR2S = FINTID(TOR2V,BV2(37),XLE(1),12)
      IF (MODE.EQ.5) THEN
      TOD2S = FINTID(BTOD2(I),BV2(25),XLE(1),12)
      END IF
      END IF
      VLOFS = FINTID(VLOFV,BV2(73),XVE(1),12)
      K1 = 1
      K2 = 1
      CALL JNT(1804,TZREF(10),V2SVS,Z(1))
      IF (KPPM.EQ.1) THEN
      PPM = Z(1)
      DO 90 M = 1,9
      XMAS(M) = PPM*XPPM(M)
   90 CONTINUE
      END IF
      P2S = Z(1)*COEF(7) + COEF(8)
      CALL INFLU(1801,P2S,IZCODT(1),RS)
c     P2S = RS
      K2 = 9
c     CALL JNT(1802,P2S,PENT2S(1),ZLS(1))
      CALL JNT(1802,RS,PENT2S(1),ZLS(1))
      DO 100 J = 1,9
      PENT2S(J+10) = ZLS(J)
      PEN2SI(J) = ZLS(10-J)
  100 CONTINUE
      PENT2S(10) = A9
      PEN2SI(10) = A9
      IF ((SSGMIN.NE.2.4).OR.(GAMXWP.NE.1.).OR.
     &(COEF(9).NE.1.0).OR.(COEF(10).NE.0.)) THEN
      GAMA = (SSGMIN-COEF(10))/COEF(9)
      GAMA = GAMA/GAMXWP
      RS = FINT(GAMA,PENT2S(1),PENT2S(11),2)
      END IF
      P2S = RS
      ZOUT(23) = P2S*UP
      ICOD3 = 0
      P3S = A9
      IF (NTAB(2007).NE.0) THEN
      K2 = 1
      K1 = 1
      CALL JNT(2007,V2SVS,X,ZLS(1))
      G3S = ZLS(1)
      IF (G3S.GT.2.4) THEN
      P3S = FINT(G3S,PENT2S(1),PENT2S(11),2)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' G3S,P3S  '
      WRITE (NT6,FMT=*) G3S,P3S
      END IF
      END IF
      END IF
      IF (NOBST.NE.0.OR.KTR.NE.0) THEN
      K1 = 9
      K2 = 1
      CALL JNT(2003,X,Y,V2SVS)
      CALL JNT(2006,DIST(1),V2SVS,ZLS(1))
      DO 110 J = 1,10
      TRAJV(J) = ZLS(J)
  110 CONTINUE
      IPP = 1
      Y(1) = 3.1
      CALL JNT(2004,X,Y(1),ZLS(1))
      IPP = 0
      END IF
      K1 = 1
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** PENT2S,PEN2SI,BV2,TRAJV '
      WRITE (NT6,FMT=*) PENT2S,PEN2SI,BV2,TRAJV
      END IF
      PMINF = PMINI
      COD = CODINI
      IF (TZREF(9).NE.A9) THEN
      P1S = A9
      K1 = 1
      CALL JNT(1604,TZREF(9),V2SVS,Z(1))
      P1S = Z(1)*COEF(13) + COEF(14)
      CALL INFLU(1601,P1S,IZCODT(1),RS)
      P1S = RS
      ZOUT(22) = P1S*UP
      IF (P1S.LT.PMINF) THEN
      PMINF = P1S
      COD = 2
      END IF
      END IF
      IF (P2S.LT.PMINF) THEN
      PMINF = P2S
      COD = 2
      END IF
      IF (P3S.LT.PMINF) THEN
      PMINF = P3S
      COD = 2
      ICOD3 = 1
      END IF
      PVLOF = FINTID(VLOFS,BMAS(73),XMAS(1),12)
      IF (PVLOF.LT.PMINF) THEN
      PMINF = PVLOF
      COD = 5
      END IF
      IF (PP.GT.0.) THEN
      IF (NTAB(20).NE.0) THEN
      CALL JNT(20,PP,V2SVS,Z(1))
      R1 = Z(1)
      R2 = FINT(R1,PENT2S(1),PENT2S(11),2)
      IF (R2.LT.PMINF) THEN
      PMINF = R2
      COD = 7
      ICOD = 0
      END IF
      END IF
      END IF
      IF (NTAB(220).NE.0) THEN
      CALL JNT(220,V2SVS,ZP,Z(1))
      R1 = P2S*Z(1)
      IF (R1.LT.PMINF) THEN
      PMINF = R1
      COD = 7
      ICOD = 0
      END IF
      ELSE
      IF (NTAB(1820).NE.0) THEN
      CALL JNT(1820,V2SVS,ZP,Z(1))
      R1 = P2S*Z(1)
      IF (R1.LT.PMINF) THEN
      PMINF = R1
      COD = 7
      END IF
      END IF
      END IF
      IF (E(25).NE.0.) THEN
      PTOD2 = FINTID(TOD2S,BMAS(25),XMAS(1),12)
      PTOR2 = FINTID(TOR2S,BMAS(37),XMAS(1),12)
      IF (MODE.EQ.5) THEN
      PTOR2 = A9
      END IF
      PTODA = MIN(PTOD2,PTOR2)
      IF (PTODA.LT.PMINF) THEN
      PMINF = PTODA
      COD = 7
      ICOD = 1
      END IF
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** PMINF,COD,PVLOF,P1S,P2S,P3S,PTOD2,PTOR2'
      WRITE (NT6,FMT=*) PMINF,COD,PVLOF,P1S,P2S,P3S,PTOD2,PTOR2
      END IF
      IF ((KMU.EQ.1).OR. (KMCG2.EQ.1).OR. (KMCA.NE.0).OR.
     +(V2VS.NE.0)) THEN
      IOD = 3
      ELSE
      IOD = K
      END IF
      GO TO (120,130,150,170) L
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10010)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10020)
      END IF
  120 CONTINUE
      CALL WMAXI(X2,Y2,I2,J2,V2,IOD,KFP)
      IF (KF.EQ.1) THEN
      KER = 2
      RETURN
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** X2,Y2,I2,J2,V2,IOD,K '
      WRITE (NT6,FMT=*) X2,Y2,I2,J2,V2,IOD,K
      END IF
      IF ((KFP.EQ.1).OR.NXTPLT(IJK,I)) THEN
      CALL INITB1(V1MIN,V1MAX,VR,V2,J1,J2,I,IJK)
      IF ((KSP.NE.0).AND. (IEF.EQ.1)) CALL ENGOUT(6)
      GO TO 290
      END IF
      IF (KMCG2.EQ.1) THEN
      IF (ABS(Y2-PSTRUK).GT.DXM(2)) THEN
      IF (V2VS.NE.0.) THEN
      KMCG = 1
      GO TO 320
      ELSE
      KMCG2 = 0
      GO TO 40
      END IF
      END IF
      IF (KMCG.EQ.1) GO TO 320
      XM(1) = Y2
      XM(2) = X2
      XM(3) = V2
      GO TO 210
      END IF
      IF ((V2VS.NE.0.).OR. (KMU.EQ.1).OR. (KMCA.NE.0)) THEN
      GO TO 200
      ELSE
      V2SVS = X1
      L = 2
      GO TO 80
      END IF
  130 CONTINUE
      CALL WMAXI(X1,Y1,I1,J1,V1,IOD,KFP)
      IF (KF.EQ.1) THEN
      KER = 2
      RETURN
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** X1,Y1,I1,J1,V1,IOD,K '
      WRITE (NT6,FMT=*) X1,Y1,I1,J1,V1,IOD,K
      END IF
      IF ((KFP.EQ.1).OR.NXTPLT(IJK,I)) THEN
      CALL INITB1(V1MIN,V1MAX,VR,V2,J1,J2,I,IJK)
      IF ((KSP.NE.0).AND. (IEF.EQ.1)) CALL ENGOUT(6)
      GO TO 290
      END IF
      Y1 = -Y1
      Y2 = -Y2
      J1 = 0
      J2 = 0
  140 CONTINUE
      K = K - 1
      IF (Y1.GT.Y2) THEN
      A = X1
      X1 = X2
      Y1 = Y2
      V1 = V2
      X2 = A + DELTA*F(K-1)
      V2SVS = X2
      L = 4
      ELSE
      X2 = X1
      Y2 = Y1
      V2 = V1
      IF (K.LE.2) THEN
      X1 = A
      ELSE
      X1 = A + DELTA*F(K-2)
      END IF
      V2SVS = X1
      L = 3
      END IF
      GO TO 80
  150 CONTINUE
      CI2 = I2
      CJ2 = J2
      CALL WMAXI(X1,Y1,I1,J1,V1,IOD,KFP)
      IF (KF.EQ.1) THEN
      KER = 2
      RETURN
      END IF
      IF ((K.EQ.3).AND. (I1.NE.CI1).AND. (I1.NE.CI2)) CI1 = I1
      IF ((K.EQ.3).AND. (J1.NE.CJ1).AND. (J1.NE.CJ2)) CJ1 = J1
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** X1,Y1,I1,J1,V1,IOD,K '
      WRITE (NT6,FMT=*) X1,Y1,I1,J1,V1,IOD,K
      END IF
      IF ((KFP.EQ.1).OR.NXTPLT(IJK,I)) THEN
      CALL INITB1(V1MIN,V1MAX,VR,V2,J1,J2,I,IJK)
      IF ((KSP.NE.0).AND. (IEF.EQ.1)) CALL ENGOUT(6)
      GO TO 290
      END IF
      Y1 = -Y1
      GO TO 180
  170 CONTINUE
      CI1 = I1
      CJ1 = J1
      CALL WMAXI(X2,Y2,I2,J2,V2,IOD,KFP)
      IF (KF.EQ.1) THEN
      KER = 2
      RETURN
      END IF
      IF ((K.EQ.3).AND. (J2.NE.CJ2).AND. (J2.NE.CJ1)) CJ2 = J2
      IF ((K.EQ.3).AND. (I2.NE.CI2).AND. (I2.NE.CI1)) CI2 = I2
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** X2,Y2,I2,J2,V2,IOD,K '
      WRITE (NT6,FMT=*) X2,Y2,I2,J2,V2,IOD,K
      END IF
      IF ((KFP.EQ.1).OR.NXTPLT(IJK,I)) THEN
      CALL INITB1(V1MIN,V1MAX,VR,V2,J1,J2,I,IJK)
      IF ((KSP.NE.0).AND. (IEF.EQ.1)) CALL ENGOUT(6)
      GO TO 290
      END IF
      Y2 = -Y2
  180 CONTINUE
      IF (K.GT.3) GO TO 140
      IF (Y1.GT.Y2) THEN
      XOPT = X2
      YOPT = -Y2
      VOPT = V2
      ELSE
      XOPT = X1
      YOPT = -Y1
      VOPT = V1
      END IF
      CALL REDUV(4,XOPT,BV2)
      IF (KMCG.EQ.1) GO TO 250
      V2VSU = FINTV(YOPT,VMU(1))
      IF (V2VSU.GT. (XOPT+.0001)) KMU = 1
      IF (KMU.EQ.1) THEN
      X2 = V2VSU
      GO TO 70
      END IF
      XM(1) = YOPT
      XM(2) = XOPT
      XM(3) = VOPT
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***BOUCL*** XM '
      WRITE (NT6,FMT=*) XM
      END IF
      J1 = CJ1
      J2 = CJ2
      I1 = CI1
      I2 = CI2
      IF (J1.EQ.0) J1 = J2
      IF (J2.EQ.0) J2 = J1
      IF (IATA.EQ.1) THEN
      ISLC1I = J1
      ISLC2I = J2
      ISLC1A = J1
      ISLC2A = J2
      END IF
      IF (FV1VR.NE.0.) THEN
      IF ((J1.EQ.3).OR. (J1.EQ.9).OR. (J1.EQ.10)) THEN
      J1 = 3
      ELSE IF (J1.EQ.4) THEN
      J1 = 6
      ELSE IF (J1.EQ.11) THEN
      J1 = 4
      END IF
      IF ((IATA.EQ.1).AND.(J1.EQ.3)) THEN
      ISLC1I = -3
      ISLC1A = -3
      END IF
      IF ((J2.EQ.3).OR. (J2.EQ.9).OR. (J2.EQ.10)) THEN
      J2 = 3
      ELSE IF (J2.EQ.4) THEN
      J2 = 6
      ELSE IF (J2.EQ.11) THEN
      J2 = 4
      END IF
      IF ((IATA.EQ.1).AND.(J2.EQ.3)) THEN
      ISLC2I = -3
      ISLC2A = -3
      END IF
      ELSE
      IF ((J1.EQ.9).OR. (J1.EQ.10)) THEN
      J1 = 3
      ELSE IF (J1.EQ.4) THEN
      J1 = 6
      ELSE IF (J1.EQ.11) THEN
      J1 = 4
      END IF
      IF ((J2.EQ.9).OR. (J2.EQ.10)) THEN
      J2 = 3
      ELSE IF (J2.EQ.4) THEN
      J2 = 6
      ELSE IF (J2.EQ.11) THEN
      J2 = 4
      END IF
      IF (J1.EQ.3.AND.CI1.EQ.4) THEN
      J1 = 6
      IF (IATA.EQ.1) THEN
      ISLC1I = 4
      ISLC1A = 4
      END IF
      END IF
      IF (J2.EQ.3.AND.CI2.EQ.4) THEN
      J2 = 6
      IF (IATA.EQ.1) THEN
      ISLC2I = 4
      ISLC2A = 4
      END IF
      END IF
      IF ((J1.EQ.6.AND.J2.EQ.3).OR.(J2.EQ.6.AND.J1.EQ.3)) THEN
      J1 = 6
      J2 = 6
      IF (IATA.EQ.1) THEN
      ISLC1I = 4
      ISLC1A = 4
      ISLC2I = 4
      ISLC2A = 4
      END IF
      END IF
      IF ((IATA.EQ.1).AND.(J1.EQ.3)) THEN
      ISLC1I = -3
      ISLC1A = -3
      END IF
      IF ((IATA.EQ.1).AND.(J2.EQ.3)) THEN
      ISLC2I = -3
      ISLC2A = -3
      END IF
      END IF
      GO TO 210
  200 CONTINUE
      IF (KMCG.EQ.1) GO TO 250
      IF (KMU.EQ.0) THEN
      V2VSU = FINTV(Y2,VMU(1))
      IF (V2VSU.GT. (X2+.0001)) THEN
      KMU = 1
      X2 = V2VSU
      GO TO 70
      END IF
      END IF
      IF (IATA.EQ.1) THEN
      IF (V2VS.NE.0.) THEN
      IF (((J1.EQ.0).OR.(J1.EQ.J2)).AND.(I2.NE.0)) THEN
      ISLC1A = I2
      ELSE IF (J1.NE.0) THEN
      ISLC1A = J1
      ELSE
      ISLC1A = J2
      END IF
      ELSE IF (KMU.EQ.1) THEN
      ISLC1A = I2
      ELSE
      IF (J1.EQ.0) THEN
      ISLC1A = J2
      ELSE
      ISLC1A = J1
      END IF
      END IF
      ISLC2A = J2
      IF ((ISLC1A.EQ.ISLC2A).AND.(KMCA.NE.0)) THEN
      ISLC2A = 14
      END IF
      ISLC1I = ISLC1A
      ISLC2I = ISLC2A
      END IF
      XM(1) = Y2
      XM(2) = X2
      XM(3) = V2
      IF (FV1VR.NE.0.) THEN
      IF ((J2.EQ.3).OR. (J2.EQ.9).OR. (J2.EQ.10)) THEN
      J2 = 3
      ELSE IF (J2.EQ.4) THEN
      J2 = 6
      ELSE IF (J2.EQ.11) THEN
      J2 = 4
      END IF
      J1 = J2
      IF (IATA.EQ.1) THEN
      IF (V2VS.EQ.0.) THEN
      IF (J2.EQ.3) THEN
      ISLC1I = -3
      ISLC1A = -3
      ISLC2I = -3
      ISLC2A = -3
      END IF
      END IF
      END IF
      ELSE
      IF ((J2.EQ.9).OR. (J2.EQ.10)) J2 = 3
      IF ((J2.EQ.3).AND. (I2.EQ.4)) THEN
      J2 = 6
      ELSE IF (J2.EQ.4) THEN
      J2 = 6
      ELSE IF (J2.EQ.11) THEN
      J2 = 4
      END IF
      J1 = J2
      IF (J2.EQ.3.AND.I2.EQ.4) THEN
      J2 = 6
      IF ((IATA.EQ.1).AND.(V2VS.EQ.0)) THEN
      ISLC1I = 4
      ISLC1A = 4
      ISLC2I = 4
      ISLC2A = 4
      END IF
      END IF
      J1 = J2
      IF (IATA.EQ.1) THEN
      IF ((V2VS.EQ.0.).AND.(J2.NE.8)) THEN
      IF (J2.EQ.3) THEN
      ISLC1I = -3
      ISLC1A = -3
      ISLC2I = -3
      ISLC2A = -3
      END IF
      ELSE
      IF (XM(3).EQ.V1VRMI) THEN
      ISLC1I = 15
      ISLC1A = 15
      ELSE IF (XM(3).EQ.V1VRMA) THEN
      ISLC1I = 16
      ISLC1A = 16
      END IF
      END IF
      END IF
      END IF
  210 CONTINUE
      GAMA = FINT(XM(1),PEN2SI(1),PEN2SI(11),2)
      GAMA = GAMA*GAMXWP
      GAMA = GAMA*COEF(9) + COEF(10)
      ZASS = 10000.
      VOPT = XM(3)
      V1VR = VOPT
      CALL PIST(8,XM(1),XVE(1),RF)
      VR = RF
      IF (AERO(3).NE.0.) THEN
      IF (XM(1).LE.0.) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' INVALID VALUE FOR STATEMENT : V2 = SQRT(XM(1)...'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'INVALID VALUE FOR STATEMENT : V2 = SQRT(XM(1)...'
      END IF
      KER = 1
      RETURN
      END IF
      V2 = SQRT(XM(1)*1000.)*VC2*XM(2)
      ELSE
      K2 = 1
      K1 = 1
      CALL JNT(2207,XM(1),Y,Z(1))
      V2 = Z(1)
      CALL JNT(2208,V2,V2SVS,Z(1))
      V2 = Z(1)
      IF (KCGT.EQ.1) THEN
      CALL JNT(2209,V2,Y,Z(1))
      V2 = Z(1)
      END IF
      END IF
      VS = V2/V2SVS
      V2 = V2 + DV2CP
      IF (KMCG2.EQ.1) THEN
      V1MAX = VR*VOPT
      V1VR = VOPT
      IF (FV1VR.EQ.0.) THEN
      VOPTP = VOPT
      V1VR = 0.
      Z25 = ZOUT(25)
      Z26 = ZOUT(26)
      KV1MN = 1
      DO 220 L = 9,NCONT
      CALL SV1MIN(XM(1),V1SVR,L)
      VMCGVR = VMCG/VR
      V1VR = MAX(V1VR,V1SVR,VMCGVR)
      XM(3) = V1VR
  220 CONTINUE
      KV1MN = 0
      ZOUT(25) = Z25
      ZOUT(26) = Z26
      XM(3) = VOPT
      END IF
      V1MIN = VR*V1VR
      J1 = 1
      J2 = 1
      GO TO 320
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***BOUCL****  TA  **** VENT ***'
      WRITE (NT6,FMT=*) TA,VENT
      END IF
      KMCA2 = 0
      IF (KMCA.EQ.2) THEN
      GO TO 230
      ELSE IF (((KMCA.EQ.0).or.(KMCAG.EQ.1)).AND. (VR.GE.VMCAR)
     +.AND.(V2.GE.VMCA2)) THEN
      GO TO 260
      END IF
      KMCA = 1
      IF (V2VS.NE.0.) THEN
      IF (RK2T.EQ.A9) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +'  ****  VMCA OPTIMIZATION NOT POSSIBLE FOR FIX V2/VS OPTION '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'VMCA OPTIMIZATION NOT POSSIBLE FOR FIX V2/VS OPTION'
      END IF
      END IF
      IF (KB.EQ.1) THEN
      KMCA2 = 1
      GO TO 320
      ELSE
      GO TO 250
      END IF
      END IF
      F1 = VMCAR - VR
      IF (KMCA1.EQ.1) THEN
      IF (F1.LT.0.1) GO TO 260
      IF (ITER.GT.5) GO TO 240
      IF (EY1*F1.LT.0.) THEN
      EX2 = XM(2)
      EY2 = F1
      EX3 = (ABS(EY1)*EX2+ABS(EY2)*EX1)/ (ABS(EY1)+ABS(EY2))
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** EY1 EX1 EY2 EX2 EX3 '
      WRITE (NT6,FMT=*) EY1,EX1,EY2,EX2,EX3
      END IF
      END IF
      IF (EY2*F1.LT.0.) THEN
      EX1 = XM(2)
      EY1 = F1
      EX3 = (ABS(EY1)*EX2+ABS(EY2)*EX1)/ (ABS(EY1)+ABS(EY2))
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** EY1 EX1 EY2 EX2 EX3 '
      WRITE (NT6,FMT=*) EY1,EX1,EY2,EX2,EX3
      END IF
      END IF
      X2 = EX3
      ITER = ITER + 1
      GO TO 70
      END IF
      IF ((MOD(ITER,2)).EQ.0) THEN
      EY1 = F1
      EX1 = XM(2)
      ELSE IF ((MOD(ITER,2)).EQ.1) THEN
      EY2 = F1
      EX2 = XM(2)
      END IF
      F3 = VMCA2 - V2
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** ITER VMCAR VMCA2 VR V2 XM(3) F1 F3 '
      WRITE (NT6,FMT=*) ITER,VMCAR,VMCA2,VR,V2,XM(3),F1,F3
      END IF
      IF (F1.LT..1.AND. (ABS(F3).LT..1)) GO TO 260
      IF (F3.LT..1.AND. (ABS(F1).LT..1)) GO TO 260
      KMCA = 2
      IF (RWNXTT) THEN
      V2SCMA = AMIN1(V2VSMA,V2SMAL)
      ELSE
      V2SCMA = V2VSMA
      END IF
      IF (ITER.EQ.0) DV = (V2SCMA-XM(2))/2.
      IF (ITER.GT.0.OR.DV.EQ.0.) DV = DXM(2)
      XM(2) = XM(2) + DV
      IF (XM(2).GT.V2SCMA) THEN
      XM(2) = V2SCMA
      IF (LV2MA) GO TO 250
      LV2MA = .TRUE.
      END IF
      X2 = XM(2)
      GO TO 70
  230 CONTINUE
      F2 = VMCAR - VR
      F4 = VMCA2 - V2
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** ITER VMCAR VMCA2 VR V2 XM(3) F2 F4 '
      WRITE (NT6,FMT=*) ITER,VMCAR,VMCA2,VR,V2,XM(3),F2,F4
      END IF
      X2 = X2 - DV
      X3 = X2
      X2 = X2 - F1*DV/ (F2-F1)
      X3 = X3 - F3*DV/ (F4-F3)
      X2 = MAX(X2,X3)
      IF (X2.GT.V2SCMA) THEN
      X2 = V2SCMA
      IF (LV2MA) GO TO 250
      LV2MA = .TRUE.
      END IF
      IF (ITER.EQ.0.AND.X2.GT. (V2SCMA+DXM(2)/2.)) GO TO 250
      KMCA = 1
      ITER = ITER + 1
      IF (ITER.GT.5.AND.KMCA1.EQ.0) THEN
      KMCA1 = 1
      EX3 = (ABS(EY1)*EX2+ABS(EY2)*EX1)/ (ABS(EY1)+ABS(EY2))
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** EY1 EX1 EY2 EX2 EX3 '
      WRITE (NT6,FMT=*) EY1,EX1,EY2,EX2,EX3
      END IF
      X2 = EX3
      KMCA = 0
      kmcag = 0
      ITER = 1
      GO TO 70
      END IF
  240 CONTINUE
      IF (ITER.GT.5) THEN
      KF = 1
      KER = 2
      IF (K6.EQ.1) WRITE (NT6,FMT=10030)
      RETURN
      ELSE
      GO TO 70
      END IF
  250 CONTINUE
      IF (KB.EQ.1) THEN
      KMCA2 = 1
      GO TO 320
      ELSE
      IF (KTEMP.EQ.0) IMCA(I) = 1
      IF (KMCA.NE.0) IVCOM = IVMC(1)
      IF (KMCG.NE.0) IVCOM = IVMC(2)
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) IVCOM,TTA(IJK),VQT(I)
      CALL INITB1(V1MIN,V1MAX,VR,V2,J1,J2,I,IJK)
      IF ((KSP.NE.0).AND. (IEF.EQ.1)) CALL ENGOUT(5)
      GO TO 290
      END IF
  260 CONTINUE
      IF (RWNXTT) THEN
      IF (XM(1).LE.PMILBT) THEN
      WRITE (NT6,FMT=10060) XM(1)*UP,IP,PMILBT*UP,IP
      CALL INITB1(V1MIN,V1MAX,VR,V2,J1,J2,I,IJK)
      IF ((KSP.NE.0).AND. (IEF.EQ.1)) CALL ENGOUT(6)
      GO TO 290
      END IF
      END IF
      KMCA = 0
      kmcag = 0
      XLP(1) = XM(1)
      XLP(2) = XM(2)
      VRP = VR
      TVPKG(IJK,I) = XLP(1)
      IF (MODE.NE.5) THEN
      VQP = VQT(I)
      ELSE
      VQP = RWYP(I)
      END IF
      VOPTP = VOPT
      V1MAX = VR*VOPT
      IF ((J1.NE.3).AND. (J2.NE.3).AND. (J1.NE.4).AND.
     +(J2.NE.4).AND. (J1.NE.6).AND. (J2.NE.6).AND.
     +(FV1VR.EQ.0.)) THEN
      V1VR = 0.
      Z25 = ZOUT(25)
      Z26 = ZOUT(26)
      KV1MN = 1
      IF (IATA.EQ.1) THEN
      IF ((ISLC1A.EQ.1).OR.(ISLC1A.EQ.2).OR.(ISLC1A.EQ.5).OR.
     +(ISLC1A.EQ.7).OR.(ISLC1A.EQ.8).OR.
     +(ISLC1A.EQ.14)) THEN
      ISLC1I = ISLC1A
      ELSE IF ((ISLC2A.EQ.1).OR.(ISLC2A.EQ.2).OR.
     +(ISLC2A.EQ.7).OR.(ISLC2A.EQ.5).OR.(ISLC2A.EQ.8).OR.
     +(ISLC1A.EQ.14)) THEN
      ISLC1I = ISLC2A
      END IF
      END IF
      VMCGVR = VMCG/VR
      DO 270 L = 9,NCONT
      CALL SV1MIN(XM(1),V1SVR,L)
      V1VR = MAX(V1VR,V1SVR,VMCGVR)
      XM(3) = V1VR
      IF (IATA.EQ.1) THEN
      IF (ABS(V1VR-V1VRMI).LT.EPSI/100.) THEN
      ISLC2I = 15
      ELSE IF (ABS(V1VR-VMCGVR).LT.EPSI/100.) THEN
      ISLC2I = 13
      ELSE IF (ABS(V1VR-V1SVR).LT.EPSI/100.) THEN
      ISLC2I = L
      END IF
      END IF
  270 CONTINUE
      KV1MN = 0
      XM(3) = VOPT
      ZOUT(25) = Z25
      ZOUT(26) = Z26
      END IF
      V1MIN = VR*V1VR
      XM(1) = XM(1)*1000.
      V1MAXP = V1MAX
      V1MINP = V1MIN
      V1VRP = V1VR
      V2P = V2
      IF ((J1.EQ.1).AND. (J2.EQ.1).AND.
     +((PSTRUK*1000.-XM(1)).GT.5.)) THEN
      J1 = 3
      J2 = 3
      IF ((ISLC1I.EQ.1).AND.(ISLC2I.EQ.1)) THEN
      ISLC1I = -3
      ISLC2I = -3
      END IF
      IF ((ISLC1A.EQ.1).AND.(ISLC2A.EQ.1)) THEN
      ISLC1A = -3
      ISLC2A = -3
      END IF
      END IF
      IF (V1MIN-VMCG.LT..2) THEN
      IF (J1.EQ.J2) THEN
      J2 = 9
      END IF
      IF (ISLC1I.EQ.ISLC2I) THEN
      IF (ISLC1I.EQ.-3) THEN
      XDUM(1) = XLP(1)
      XDUM(3) = XLP(3)
      XDUM(3) = V1VRP
      CALL PIST(5,XDUM,XLE,RF)
      ASDC = RF*COEF(1)+COEF(2)+AASD
      CALL PIST(6,XDUM(1),XVE(1),RF)
      V1BE = RF*COEF(19) + COEF(20)
      IF (ABS(ASDC-ASD).LT.1.) THEN
      ISLC1I = 3
      ELSE IF (ABS(V1MIN-V1BE).LT.0.2) THEN
      ISLC1A = 4
      END IF
      END IF
      END IF
      END IF
      IF (V1MAX-VMCG.LT..2) THEN
      IF (ISLC1A.EQ.ISLC2A) THEN
      ISLC2A = 13
      END IF
      IF (ISLC1A.EQ.-3) THEN
      XDUM(1) = XLP(1)
      XDUM(3) = XLP(3)
      XDUM(3) = VOPTP
      CALL PIST(5,XDUM,XLE,RF)
      ASDC = RF*COEF(1)+COEF(2)+AASD
      CALL PIST(6,XDUM(1),XVE(1),RF)
      V1BE = RF*COEF(19) + COEF(20)
      IF (ABS(ASDC-ASD).LT.1.) THEN
      ISLC1A = 3
      ELSE IF (ABS(V1MAX-V1BE).LT.0.2) THEN
      ISLC1A = 4
      END IF
      END IF
      END IF
      IF (((V2-VMCA2).LT..2).OR. ((VR-VMCAR).LT..2)) THEN
      IF (J1.EQ.J2) THEN
      J2 = 9
      END IF
      IF (ISLC1A.EQ.ISLC2A) THEN
      ISLC2A = 14
      END IF
      END IF
      IF ((ABS(XM(1)-PSTRUC*1000.).LE.2.).AND. (J1.NE.1)) THEN
      J2 = 1
      IF (ISLC1I.NE.1) THEN
      ISLC1I = 1
      END IF
      IF (ISLC1A.NE.1) THEN
      ISLC1A = 1
      END IF
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***BOUCL*** V2 VR V1MAX V1VR V1MIN '
      WRITE (NT6,FMT=*) V2,VR,V1MAX,V1VR,V1MIN
      END IF
      IF (V1MIN.GT.V1MAX+.2) THEN
      V1MIN = 10000
      V1MAX = 10000
      END IF
      IF (KB.EQ.1) GO TO 320
      V1MIN = FINTV(V1MIN,CVIT(1))
      V1MAX = FINTV(V1MAX,CVIT(1))
      VR = FINTV(VR,CVIT(1))
      IF (CVIT(21).NE.0) THEN
      V2 = FINTV(V2,CVIT(21))
      ELSE
      IF (NTAB(2205).EQ.0) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** V2 CAS-IAS MISSING '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'V2 CAS-IAS MISSING'
      END IF
      KER = 1
      RETURN
      END IF
      K2 = 1
      K1 = 1
      PMT = XM(1)/1000.
      CALL JNT(2205,PMT,V2P,Z(1))
      V2 = Z(1)
      END IF
      VMCGIA = FINTV(VMCG,CVIT(1))
      IF (CVIT(21).NE.0) THEN
      VMCAIA = FINTV(1.1*VMCA,CVIT(21))
      ELSE
      IF (NTAB(2205).EQ.0) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' STOP  *** V2 CAS-IAS MISSING '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'V2 CAS-IAS MISSING'
      END IF
      KER = 1
      RETURN
      END IF
      K2 = 1
      K1 = 1
      PMT = XM(1)/1000.
      CALL JNT(2205,PMT,1.1*VMCA,Z(1))
      VMCAIA = Z(1)
      END IF
      IF (J1.EQ.2.AND.ICOD3.EQ.1) THEN
      J1 = 19
      IF (IATA.EQ.1) THEN
      IF (ISLC1I.EQ.2) THEN
      ISLC1I = 17
      END IF
      IF (ISLC1A.EQ.2) THEN
      ISLC1A = 17
      END IF
      END IF
      END IF
      IF (J1.EQ.7.AND.ICOD.EQ.0) THEN
      J1 = 3
      IF (IATA.EQ.1) THEN
      IF (ISLC1I.EQ.7) THEN
      ISLC1I = 18
      END IF
      IF (ISLC1A.EQ.7) THEN
      ISLC1A = 18
      END IF
      END IF
      END IF
      IF (J2.EQ.2.AND.ICOD3.EQ.1) THEN
      J2 = 19
      IF (IATA.EQ.1) THEN
      IF (ISLC2I.EQ.2) THEN
      ISLC1I = 17
      END IF
      IF (ISLC2A.EQ.2) THEN
      ISLC1A = 17
      END IF
      END IF
      END IF
      IF (J2.EQ.7.AND.ICOD.EQ.0) THEN
      J2 = 3
      IF (IATA.EQ.1) THEN
      IF (ISLC2I.EQ.7) THEN
      ISLC2I = 18
      END IF
      IF (ISLC2A.EQ.7) THEN
      ISLC2A = 18
      END IF
      END IF
      END IF
      IF (IEF.EQ.1) THEN
      ZASS = 10000.
      ASS(I) = ZASS
      IF (KU.EQ.1) THEN
      PKG(I) = XM(1)*2.20462
      ELSE
      PKG(I) = XM(1)
      END IF
      PVMC(I) = PKG(I)
      IV1MAX(I) = AR(V1MAX)
      IV1MIN(I) = AR(V1MIN)
      IVR(I) = AR(VR)
      IV2(I) = AR(V2)
      IVMCA(I) = AR(VMCAIA)
      IVMCG(I) = AR(VMCGIA)
      IVMCA(7) = MAX(IVMCA(7),IVMCA(I))
      IVMCG(7) = MAX(IVMCG(7),IVMCG(I))
      J1COD(I) = J1
      J2COD(I) = J2
      ELSE
      DTOW(I,IEF-1) = XM(1)*UP/1000. - PKG(I)
      DV1MIN(I,IEF-1) = AR(V1MIN) - IV1MIN(I)
      DV1MAX(I,IEF-1) = AR(V1MAX) - IV1MAX(I)
      DV1MOY(I,IEF-1) = (AR(V1MAX) + AR(V1MIN) -
     +IV1MAX(I) - IV1MIN(I))/2.
      IF (ABS(DV1MOY(I,IEF-1)).GE.100.0)
     +DV1MOY(I,IEF-1) = 10000.
      DVR(I,IEF-1) = AR(VR) - IVR(I)
      IF (ABS(DVR(I,IEF-1)).GE.100.0) DVR(I,IEF-1) = 10000.
      DV2(I,IEF-1) = AR(V2) - IV2(I)
      IF (ABS(DV2(I,IEF-1)).GE.100.0) DV2(I,IEF-1) = 10000.
      ZOUTE(IEF+2) = DTOW(I,IEF-1)
      ZOUTE(IEF+4) = DV1MIN(I,IEF-1)
      ZOUTE(IEF+6) = DV1MAX(I,IEF-1)
      ZOUTE(IEF+8) = DVR(I,IEF-1)
      ZOUTE(IEF+10) = DV2(I,IEF-1)
      ZOUTE(IEF+12) = DV1MOY(I,IEF-1)
      CALL PIST(5,XLP(1),XLE(1),RF)
      ZOUT(17) = (RF*COEF(1)+COEF(2)+AASD)/UL
      CALL PIST(1,XLP(1),XLE(1),RF)
      ZOUT(18) = (RF*COEF(3)+COEF(4)+ATOD)/UL
      CALL PIST(6,XLP(1),XVE(1),RF)
      ZOUT(21) = RF*COEF(19) + COEF(20)
      DQVMCA(IEF-1) = INT(AR(VMCAIA))-IVMCA(7)
      DQVMCG(IEF-1) = INT(AR(VMCGIA))-IVMCG(7)
      END IF
      ZOUT(1) = TTA(IJK)
      ZOUT(4) = FLOAT(J1)
      ZOUT(5) = FLOAT(J2)
      ZOUT(22) = P1S*UP
      ZOUT(23) = P2S*UP
      ZOUT(43) = VMCG
      ZOUT(50) = PVLOF*UP
      ZOUT(51) = VMCA
      IF (PTOD2.NE.A9) ZOUT(58) = PTOD2*UP
      IF (PTOR2.NE.A9) ZOUT(59) = PTOR2*UP
      ZOUT(24) = PFTO*UP
      IF (KTR.EQ.1.OR.KTR.EQ.2) CALL TRAJE(GAMA)
      IF ((KSP.NE.0).AND. (IEF.EQ.1)) CALL ENGOUT(1)
      IF (IEF.EQ.1) THEN
      IF (ABS(V1MAXP-V1MINP).GT.EPSI) THEN
      IV1MB(I) = AR(V1MBAL)
      ELSE
      IV1MB(I) = IV1MAX(I)
      END IF
      ELSE
      IF (KSP.NE.0) CALL ENGOUT(13)
      DV1MOY(I,IEF-1) = (AR(V1MBAL) - IV1MB(I))
      IF (ABS(DV1MOY(I,IEF-1)).GE.100.0) THEN
      DV1MOY(I,IEF-1) = 10000.
      END IF
      ZOUTE(IEF+12) = DV1MOY(I,IEF-1)
      END IF
      IF ((IJK.EQ.NTA).AND. (I.EQ.NVQT)) THEN
      DO 280 J = 1,NOBST
      IF (D(J).GT.ZOUT(40)) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT=10050)
     +'* WARNING : OBSTACLE #',J,
     +' LOCATED AFTER FINAL TAKEOFF POINT'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10050)
     +'WARNING : OBSTACLE #',J,
     +' LOCATED AFTER FINAL TAKEOFF POINT'
      END IF
      KFI = 2
      IOBFTO = 1
      END IF
  280 CONTINUE
      END IF
      IF (MODE.EQ.5) GO TO 340
      IF (KST.EQ.2.AND.ZLIM(17).NE.0.) THEN
      IF ((TRISA.GE.-30.2).AND.(ABS(PP).LE.2.).AND.
     +(VENT.GE.-10)) THEN
      IF (.NOT.(LEFT(9).OR.LEFT(17).OR.LEFT(18).OR.LEFT(26)
     +.OR.LEFT(27).OR.LEFT(34).OR.LEFT(36)).AND.
     +(DVMCPE.EQ.0).AND.(ICFTO(2).EQ.15)) THEN
      IF ((ABS(XM(1)-PSTRUC*1000.).LE.2.).AND.(J1.EQ.1).AND.
     +((J2.EQ.1).OR.(J2.EQ.9))) THEN
      NL = 0
      NLF = 0
      NLP = 0
      DASD = ASD - ZOUT(17)*UL
      DTOD = TOD - ZOUT(18)*UL
      DV1F = ZOUT(21) - V1MAXP
      IF (ZLIM(16).LT.100.) THEN
      IF (DV1F.GT.ZLIM(16)) NLF = 1
      ELSE
      NLF = 1
      END IF
      IF (DASD.GE.ZLIM(17).AND.DTOD.GE.ZLIM(17)) NLP = 1
      IF (NLP.EQ.1.AND.NLF.EQ.1) NL = 1
      IF (NL.EQ.1.AND.ABS(V1MAXP-VRP).LE..1) THEN
      NLFLAG(I,IEF) = .TRUE.
      ZOUTE(IEF) = 1.
      END IF
      END IF
      END IF
      END IF
      END IF
c     IF ((OUTMOD.NE.0).AND.(DRYCHK.NE.1)) THEN
c     CALL OUT1(NT1,IJK,I)
c     END IF
      GO TO 340
  290 CONTINUE
      TASS(IJK,I) = ZASS
      TPKG(IJK,I) = PKG(I)
      TVMAX(IJK,I) = VR
      TVMIN(IJK,I) = (V1MAX+V1MIN)/2.
      TV2(IJK,I) = V2
      JJ1(IJK,I) = J1
      JJ2(IJK,I) = J2
c     IF ((OUTMOD.NE.0).AND.(DRYCHK.NE.1)) THEN
c     CALL OUT1(NT1,IJK,I)
c     END IF
      IF (NTA.EQ.1) GO TO 340
      IF (IJK.NE.NTA) GO TO 340
      IF (A2.NE.1) GO TO 340
      IF (TEMP(1).EQ.1..OR.TEMP(1).EQ.2..OR.
     +TEMP(1).EQ.3.) GO TO 340
      IF (NVQT.NE.5) GO TO 340
      IF ((MODE.NE.0).AND. (MODE.NE.1)) GO TO 340
      CALL ZFICB(I,TCAS1,KJJ,KER)
      IF (KER.EQ.2) THEN
      RETURN
      ELSE IF (KER.EQ.3) THEN
      GO TO 340
      END IF
      IPRON(I) = KJJ
  300 CONTINUE
      KB = 1
      KMCG2 = 0
      PSTRUK = PRON(KJJ)/1000.
      IF (KU.EQ.1) PSTRUK = PSTRUK/2.20462
      CODINI = 1
      PMINI = PSTRUK
      PMINF = PSTRUK
      COD = 1
      IF (RWNXTT) THEN
      DV2F = (AMIN1(V2VSMA,V2SMAL)-AMAX1(V2VSMI,V2SMIL))/8.
      ELSE
      DV2F = (V2VSMA-V2VSMI)/8.
      END IF
      XM(1) = PSTRUK
      XM(3) = XM(3)
      IF (RWNXTT) THEN
      XV2 = AMAX1(V2VSMI,V2SMIL) - DV2F
      ELSE
      XV2 = V2VSMI - DV2F
      END IF
      DO 310 M1 = 1,9
      XV2 = XV2 + DV2F
      XM(2) = XV2
      CALL REDUV(4,XV2,BV2)
      CALL PIST(8,XM(1),XVE(1),RF)
      VR = RF
      IF (AERO(3).NE.0.) THEN
      IF (XM(1).LE.0.) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' INVALID VALUE FOR STATEMENT : V2 = SQRT(XM(1)...'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'INVALID VALUE FOR STATEMENT : V2 = SQRT(XM(1)...'
      END IF
      KER = 1
      RETURN
      END IF
      V2 = SQRT(XM(1)*1000.)*VC2*XM(2)
      ELSE
      K2 = 1
      K1 = 1
      CALL JNT(2207,XM(1),Y,Z(1))
      V2 = Z(1)
      CALL JNT(2208,V2,XV2,Z(1))
      V2 = Z(1)
      IF (KCGT.EQ.1) THEN
      CALL JNT(2209,V2,Y,Z(1))
      V2 = Z(1)
      END IF
      END IF
      V2 = V2 + DV2CP
      BVMC(M1) = XV2
      BVMC(M1+10) = VR
      BVMC(M1+20) = V2
  310 CONTINUE
      BVMC(10) = A9
      BVMC(20) = A9
      BVMC(30) = A9
      V2VSU = FINTV(PSTRUK,VMU(1))
      V2VSG = FINT(VMCG,BVMC(11),BVMC(1),2)
      V2VSR = FINT(VMCAR,BVMC(11),BVMC(1),2)
      V2VS2 = FINT(VMCA2,BVMC(21),BVMC(1),2)
      IF (RWNXTT) THEN
      AX2 = AMAX1(V2SMIL,V2VSMI,V2VSU,V2VSG,V2VSR,V2VS2)
      ELSE
      AX2 = AMAX1(V2VSMI,V2VSU,V2VSG,V2VSR,V2VS2)
      END IF
      IF (KS.EQ.3) THEN
      WRITE (NT6,FMT='(A)') ' *** VMC CONTROL ***  TA VENT '
      WRITE (NT6,FMT=*) TA,VENT
      WRITE (NT6,FMT='(A)')
     +' PSTRUK,AX2,V2VSU,V2VSG,V2VSR,V2VS2,BVMC '
      WRITE (NT6,FMT=*) PSTRUK,AX2,V2VSU,V2VSG,V2VSR,V2VS2,BVMC
      END IF
      IF (RWNXTT) THEN
      V2SGMI = AMAX1(V2VSMI,V2SMIL)
      V2SGMA = AMIN1(V2VSMA,V2SMAL)
      ELSE
      V2SGMI = V2VSMI
      V2SGMA = V2VSMA
      END IF
      IF (AX2.GT.V2SGMA) THEN
      KMCG = 1
      KMCG2 = 1
      GO TO 320
      ELSE IF ((AX2.GE.V2SGMI).AND. (AX2.LE.V2SGMA)) THEN
      KMCG2 = 1
      PMINI = PSTRUK
      IF (V2VS.NE.0.) THEN
      IF (V2VS.LT.AX2.AND.AX2.NE.V2VSU) THEN
      KMCG = 1
      KMCG2 = 1
      GO TO 320
      END IF
      X2 = V2VS
      ELSE
      X2 = AX2
      END IF
      GO TO 70
      END IF
  320 CONTINUE
      IF (KMCA2.EQ.1.OR.KMCG.EQ.1) THEN
      ITMAX(KJJ,I) = 1000
      JJ1(KJJ,I) = 1000
      JJ2(KJJ,I) = 1000
      TPKG(KJJ,I) = 1000.
      TVMAX(KJJ,I) = 1000.
      TVMIN(KJJ,I) = 1000.
      TASS(KJJ,I) = 1000.
      TV2(KJJ,I) = 1000.
      ELSE
      ITMAX(KJJ,I) = TTA(NTA)
      TPKG(KJJ,I) = 0.
      VMAX = FINTV(V1MAX,CVIT(1))
      VMIN = FINTV(V1MIN,CVIT(1))
      VRB = FINTV(VR,CVIT(1))
      V2B = FINTV(V2,CVIT(21))
      VM = (VMAX+VMIN)/2.
      TVMIN(KJJ,I) = AR(VM)
      TVMAX(KJJ,I) = AR(VRB)
      TV2(KJJ,I) = AR(V2B)
      TASS(KJJ,I) = ZASS
      IF (J1.EQ.7.AND.ICOD.EQ.0) J1 = 3
      JJ1(KJJ,I) = J1
      IF (J1.EQ.1) JJ1(KJJ,I) = 10
      IF (J2.EQ.7.AND.ICOD.EQ.0) J2 = 3
      JJ2(KJJ,I) = J2
      IF (J2.EQ.1) JJ2(KJJ,I) = 10
      END IF
      IF (KJJ.EQ.NPROND) GO TO 330
      KJJ = KJJ + 1
      IF (KMCG2.EQ.1.AND.KMCG.EQ.1) GO TO 320
      GO TO 300
  330 CONTINUE
      IF ((I.EQ.NVQT).AND. (IEF.EQ.1)) THEN
      CALL ENGOUT(10)
      CALL ENGOUT(11)
      END IF
c     IF ((OUTMOD.NE.0).AND.(DRYCHK.NE.1)) THEN
c     CALL OUT1(NT1,IJK,I)
c     END IF
  340 CONTINUE
      IF (DRYCHK.NE.0) THEN
      CALL ENGOUT(12)
      END IF
      IF ((IJK.EQ.NTA).AND. (I.EQ.NVQT).AND. (DRYCHK.NE.0)) THEN
      CALL ENGOUT(9)
      END IF
  350 CONTINUE
      MB = 1
      IF (IATA.EQ.0) CALL FICHE(MA,MB)
  360 CONTINUE
      RETURN
10000 FORMAT (/,/,20X,'V2SVS = ',F10.7,/)
10010 FORMAT (/,/,10X,'ILLEGAL GOTO IN MAIN')
10020 FORMAT ('ILLEGAL GOTO IN MAIN')
10030 FORMAT (/,/,' *** BAD CONVERGENCE FOR VMCA ')
10040 FORMAT (/,/,' ***',A4,' LIMITATION - TAKE OFF NOT ALLOWED FOR :',
     +/,10X,' TEMPERATURE = ',F6.2,10X,'WIND (OR QNH) = ',F10.3)
10050 FORMAT (A,I2,A)
10060 FORMAT (1X,/,1X,'WARNING *** MAXIMAL WEIGHT: ',F7.1,1X,A2,
     +' LOWER THAN AFM MIN WEIGHT: ',F7.1,1X,A2,
     +' AT TAKE-OFF')
      END
