      INTEGER NCONT
      INTEGER KTR
      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      LOGICAL DRYLD1
      LOGICAL DRYLD2
      LOGICAL DRYTYP
      REAL BE30(96)
      REAL BE31(96)
      REAL BE32(96)
      REAL BINT(96)
      REAL BMAS(96)
      REAL BPIS(96)
      REAL BV2(96)
      REAL BVEN(96)
      REAL TZREF(21)
      REAL XPPM(12)
      REAL XVE(12)
      REAL XLE(12)
      REAL XLEL(12)
      REAL XMAL(12)
      REAL XMAS(12)
      REAL XBEL(12)
      COMMON /PISTE1/DRYTYP,DRYLD1,DRYLD2
      COMMON /PISTE2/XLE,XVE,XMAS,BINT,BPIS,BVEN,BV2,BMAS,BE30,BE31,
     +BE32,TZREF,XPPM,XMAL,XLEL,XBEL
      REAL GAMXWP
      INTEGER IK1T
      INTEGER IK2T
      INTEGER IKVF
      INTEGER IKV1
      INTEGER IKV2
      REAL AERO(40)
      REAL COEF(40)
      REAL COEFP(40)
      REAL CVIT(80)
      REAL DTCA(21)
      REAL DTCD(21)
      REAL GAP(21)
      REAL GLD(21)
      REAL RAER(8)
      REAL RTFP(8)
      REAL RGLD(8)
      REAL TCGC(20)
      REAL TK1T(20)
      REAL TK2T(20)
      REAL TKV1(20)
      REAL TKVA(40)
      REAL TKVF(20)
      REAL TKVL(40)
      REAL TVQ(8)
      REAL VMU(20)
      REAL V2CP(20)
      REAL GLDA(21)
      REAL VMPE(30)
      REAL XTWD(40)
      COMMON /VAR1/IK1T,IK2T,IKVF,IKV1,IKV2
      COMMON /VAR2/COEF,DTCA,DTCD,AERO,CVIT,GAP,GLD,VMU,COEFP,TK2T,TKVF,
     +TKVA,TKVL,TVQ,TCGC,RGLD,RAER,RTFP,TKV1,TK1T,V2CP,VMPE,
     +XTWD,GAMXWP,GLDA
      REAL AASD
      REAL AHSD
      REAL ATOD
      REAL GENE(20)
      COMMON /TLIATA/GENE,AASD,ATOD,AHSD
      REAL AASDP
      REAL ASDMBA
      REAL ASDP
      REAL ATODP
      REAL P2PC
      REAL P2S
      REAL PMAXLP
      REAL PMAXP2
      REAL PTOD2
      REAL PTOR2
      REAL TODMBA
      REAL TODP
      REAL TORMBA
      REAL TORP
      REAL V1MAXP
      REAL V1MBAL
      REAL V1MINP
      REAL V1VRLP
      REAL V1VRMB
      REAL V1VRP
      REAL V1VRP2
      REAL V21
      REAL V2P
      REAL VOPTP
      REAL VQP
      REAL VRP
      REAL WIDTHP
      REAL ZGP
      INTEGER IPP
      REAL XLP(3)
      REAL ZOUL1(60)
      REAL ZOUL2(60)
      REAL ZOUT(60)
      REAL ZOUTE(20)
      REAL ZOUTS(60)
      COMMON /SPOUT1/IPP
      COMMON /SPOUT2/ZOUT,XLP,VQP,VRP,V1MAXP,V1MINP,V1VRP,V2P,VOPTP,
     +V1VRLP,PMAXLP,TORP,ASDP,TODP,P2S,V21,AASDP,ATODP,PTOR2,
     +PTOD2,P2PC,ZOUL1,ZOUL2,WIDTHP,ZGP,ZOUTE,PMAXP2,V1VRP2,ZOUTS
     +,V1VRMB,V1MBAL,ASDMBA,TODMBA,TORMBA
      INTEGER IXTRPL
      REAL PINI
      REAL PMAX
      REAL PMIN
      REAL V1VRI
      REAL V1VRMA
      REAL V1VRMI
      REAL V2VSMA
      REAL V2VSMI
      REAL ZMAX
      REAL ZMIN
      REAL SSGMIN
      REAL DTMAX1
      REAL DTMAX2
      REAL DTMIN
      REAL TMILBT
      REAL TMALBT
      REAL ZMILBT
      REAL ZMALBT
      REAL WMILBT
      REAL WMALBT
      REAL SMILBT
      REAL SMALBT
      REAL TMILL1
      REAL TMALL1
      REAL ZMILL1
      REAL ZMALL1
      REAL WMILL1
      REAL WMALL1
      REAL SMILL1
      REAL SMALL1
      REAL TMILL2
      REAL TMALL2
      REAL ZMILL2
      REAL ZMALL2
      REAL WMILL2
      REAL WMALL2
      REAL SMILL2
      REAL SMALL2
      REAL V2SMIL
      REAL V2SMAL
      REAL V1RMIL
      REAL V1RMAL
      REAL PMILBT
      REAL PMALBT
      REAL PMILL1
      REAL PMALL1
      REAL PMILL2
      REAL PMALL2
      REAL ALIM(20)
      REAL ZLIM(40)
      COMMON /LIMIT1/IXTRPL
      COMMON /LIMIT2/ZLIM,PMIN,PINI,PMAX,V2VSMI,V2VSMA,V1VRMI,V1VRI,
     +V1VRMA,ZMIN,ZMAX,DTMIN,DTMAX1,DTMAX2,ALIM,SSGMIN,
     +TMILBT,TMALBT,ZMILBT,ZMALBT,WMILBT,WMALBT,SMILBT,SMALBT,
     +TMILL1,TMALL1,ZMILL1,ZMALL1,WMILL1,WMALL1,SMILL1,SMALL1,
     +TMILL2,TMALL2,ZMILL2,ZMALL2,WMILL2,WMALL2,SMILL2,SMALL2,
     +V2SMIL,V2SMAL,V1RMIL,V1RMAL,PMILBT,PMALBT,PMILL1,PMALL1,
     +PMILL2,PMALL2
      REAL P9
      REAL KVMAX
      INTEGER IG
      REAL POBS(MAXOBS)
      COMMON /PBOB1/IG
      COMMON /PBOB2/KVMAX,POBS,P9
      INTEGER NPMAX
      REAL DIVER(20)
      REAL VNUM(20000)
      INTEGER NTAB(4200)
      COMMON /TABLE1/NTAB,NPMAX
      COMMON /TABLE2/VNUM,DIVER
      REAL KVMIN
      INTEGER IR
      REAL FOBS(MAXFOB)
      COMMON /SV1/IR
      COMMON /SV2/FOBS,KVMIN
      REAL F
      INTEGER N
      REAL XL(3)
      REAL CORDG
      REAL D3
      REAL D3CL
      REAL DEBD3
      REAL DFTO
      REAL DFTOCV
      REAL DG
      REAL DHPP
      REAL DHV
      REAL DOBS
      REAL DOBSV
      REAL GAMA
      REAL HOBS
      REAL HTRAJ
      REAL RF
      REAL TOD1M
      REAL TODC
      REAL TODTM
      REAL V1MAX
      REAL VFREIN
      REAL X
      INTEGER I
      INTEGER J
      INTEGER K
      INTEGER L
      INTEGER NOBSD
      INTEGER NOBSF
      REAL Z(12)
      REAL FINT,ZPRES
      EXTERNAL FINT,ZPRES
      EXTERNAL INFLU,JNT,PIST
      INTRINSIC ABS,SQRT
      IF (N.GT.10) GO TO 60
      GO TO (10,10,20,30,10,10,10,10,40,
     +50) N
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10000)
      RETURN
   10 CONTINUE
      F = XL(1) - PMINF
      IF (ABS(F).LE. (DXM(1)/10.)) THEN
      F = 0.
      XL(1) = PMINF
      END IF
      RETURN
   20 CONTINUE
      CALL PIST(5,XL(1),XLE(1),RF)
      F = RF*COEF(1) + COEF(2) + AASD - ASD
      RETURN
   30 CONTINUE
      CALL PIST(6,XL(1),XVE(1),RF)
      VFREIN = RF*COEF(19) + COEF(20)
      CALL PIST(8,XL(1),XVE(1),RF)
      V1MAX = RF*XL(3)
      F = V1MAX - VFREIN
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' ***CONT***  VFREIN,V1MAX '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) VFREIN,V1MAX
      RETURN
   40 CONTINUE
      CALL PIST(1,XL(1),XLE(1),RF)
      F = RF*COEF(3) + COEF(4) + ATOD - TOD
      RETURN
   50 CONTINUE
      CALL PIST(2,XL(1),XLE(1),RF)
      F = RF*COEF(5) + COEF(6) + ATOD - TOR
      RETURN
   60 CONTINUE
      CALL PIST(1,XL(1),XLE(1),RF)
      TOD1M = RF
      TOD1M = TOD1M*COEF(3) + COEF(4) + ATOD
      GAMA = FINT(XL(1),PEN2SI(1),PEN2SI(11),2)
      GAMA = GAMA*GAMXWP
      GAMA = GAMA*COEF(9) + COEF(10)
      CALL JNT(2004,X,GAMA,Z(1))
      ZOUT(25) = A9
      ZOUT(26) = A9
      TODTM = 0.
      TODC = TOD1M
      IF (SSGMIN.NE.2.4) THEN
      IF (KV1MN.EQ.0) THEN
      IF (E(25).EQ.1.) THEN
      CALL PIST(3,XL(1),XLE(1),RF)
      TODTM = RF
      TODTM = TODTM*COEF(15) + COEF(16) + ATOD
      IF (TODC.LT.TODTM) TODC = TODTM
      END IF
      END IF
      END IF
   70 CONTINUE
      DHPP = PP*TODC/30.48
      TRAJ(22) = TRAJ(23)*TRAJ(2)
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' ***CONT***  GAMA,TODC,TOD1M,TODTM,DHPP,TRAJ '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) GAMA,TODC,TOD1M,TODTM,DHPP,TRAJ
      NOBSD = 1
      NOBSF = NOBST
      IF (KVMAX.EQ.1) THEN
      NOBSD = IG
      NOBSF = NOBSD
      END IF
      DO 160 L = NOBSD,NOBSF
      DOBS = D(L) - TODC
      DOBSV = FINT(DOBS,DIST(1),TRAJV(1),1)
      DHV = (DOBS-DOBSV)*.008/.3048
      HTRAJ = FINT(DOBSV,TRAJ(1),TRAJ(12),1)
      IF (DOBSV.GE.TRAJ(9)) THEN
      D3 = TRAJ(10) - TRAJ(9)
      Z(1) = D3
      IF (NTAB(2001).NE.0) THEN
      K1 = 1
      K2 = 1
      CALL JNT(2001,D3,TISA,Z(1))
      D3 = Z(1)
      CALL JNT(2002,D3,ZP,Z(1))
      END IF
      D3CL = Z(1)
      DFTO = TRAJ(9) + D3CL
      DFTOCV = FINT(DFTO,DIST(1),TRAJV(1),1)
      DFTOCV = DFTO - (DFTOCV-DFTO)
      DEBD3 = FINT(TRAJ(9),DIST(1),TRAJV(1),1)
      DHV = (TRAJ(9)-DEBD3)*.008/.3048
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' ***CONT***  D3CL,DFTO,DFTOCV,DEBD3,DHV '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) D3CL,DFTO,DFTOCV,DEBD3,DHV
      END IF
      HOBS = H(L) + DHV - DHPP
      CORDG = FINT(DOBSV,TRAJ(2),TRAJ(23),1)
      IF (DOBSV.LT.TRAJ(2)) CORDG = TRAJ(22)/DOBSV
      IF (KTJ.EQ.1) HOBS = HOBS + 20.
      DG = (HOBS-HTRAJ)*CORDG
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' ***CONT***  DOBS,DOBSV,HTRAJ,HOBS,CORDG,DG '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) DOBS,DOBSV,HTRAJ,HOBS,CORDG,
     +DG
      IF (KVMIN.EQ.1) THEN
      K = (L-1)*5 + IR
      FOBS(K) = DG
      GO TO 160
      END IF
      IF (KVMAX.EQ.1) THEN
      F = DG
      RETURN
      END IF
      IF (L.EQ.1) GO TO 150
      IF (F*DG) 130,140,140
  130 CONTINUE
      IF (DG.GT.0.) GO TO 150
      GO TO 160
  140 CONTINUE
      IF (F.LT.DG) GO TO 150
      GO TO 160
  150 CONTINUE
      F = DG
      J = L
  160 CONTINUE
      IF (ABS(F).LE..01) ZOUT(25) = XL(1)*UP
      IF (ABS(F).LE..01) ZOUT(26) = J
      RETURN
10000 FORMAT (/,/,10X,'ILLEGAL GOTO IN CONT')
      END
