      REAL AASDP
      REAL ASDMBA
      REAL ASDP
      REAL ATODP
      REAL P2PC
      REAL P2S
      REAL PMAXLP
      REAL PMAXP2
      REAL PTOD2
      REAL PTOR2
      REAL TODMBA
      REAL TODP
      REAL TORMBA
      REAL TORP
      REAL V1MAXP
      REAL V1MBAL
      REAL V1MINP
      REAL V1VRLP
      REAL V1VRMB
      REAL V1VRP
      REAL V1VRP2
      REAL V21
      REAL V2P
      REAL VOPTP
      REAL VQP
      REAL VRP
      REAL WIDTHP
      REAL ZGP
      INTEGER IPP
      REAL XLP(3)
      REAL ZOUL1(60)
      REAL ZOUL2(60)
      REAL ZOUT(60)
      REAL ZOUTE(20)
      REAL ZOUTS(60)
      COMMON /SPOUT1/IPP
      COMMON /SPOUT2/ZOUT,XLP,VQP,VRP,V1MAXP,V1MINP,V1VRP,V2P,VOPTP,
     +V1VRLP,PMAXLP,TORP,ASDP,TODP,P2S,V21,AASDP,ATODP,PTOR2,
     +PTOD2,P2PC,ZOUL1,ZOUL2,WIDTHP,ZGP,ZOUTE,PMAXP2,V1VRP2,ZOUTS
     +,V1VRMB,V1MBAL,ASDMBA,TODMBA,TORMBA
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      REAL AK1
      REAL AK2
      REAL ASD
      REAL PP
      REAL TA
      REAL TISA
      REAL TOD
      REAL TOR
      REAL VC1
      REAL VENT
      REAL V2VS
      REAL WIDTH
      REAL ZP
      INTEGER IOBFTO
      INTEGER KF
      INTEGER NOBST
      INTEGER KOBS
      INTEGER KCGA
      INTEGER KCGL
      INTEGER KCGT
      REAL D(MAXOBS)
      REAL DGA(11)
      REAL DIST(10)
      REAL DP(MAXOBS)
      REAL H(MAXOBS)
      REAL HP(MAXOBS)
      REAL PEN1SI(24)
      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
      REAL TRAJ(32)
      REAL TRAJV(10)
      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      LOGICAL CHECK1
      LOGICAL CHECK2
      LOGICAL RWNXTT
      LOGICAL RWNXTL
      LOGICAL NXTPLT(MAXTTA,MAXVQ)
      LOGICAL NXTPL1(MAXTAL,MAXVQ)
      LOGICAL NXTPL2(MAXTAL,MAXVQ)
      COMMON /CTESL/CHECK1,CHECK2,RWNXTT,RWNXTL,NXTPLT,NXTPL1,NXTPL2
      REAL B
      INTEGER J
      REAL XN(3)
      REAL GOLDN
      REAL F1
      REAL F2
      REAL K6S
      REAL P1
      REAL P2
      REAL P11
      REAL P3PC
      REAL PI
      REAL V1RMAW
      INTEGER IR1
      INTEGER ITER
      INTEGER KE
      REAL XC(3)
      PARAMETER ( GOLDN = 1.618033989 )
      REAL FINT
      EXTERNAL FINT
      EXTERNAL CONT
      INTRINSIC ABS,AMIN1
      IF (RWNXTT) THEN
      V1RMAW = AMIN1(V1VRMA,V1RMAL)
      ELSE
      V1RMAW = V1VRMA
      END IF
      KVMAX = 0
      XN(3) = V1RMAW
      IF (J.EQ.11) THEN
      XN(1) = XN(1) - DXM(1)
      PI = AMIN1(P2PC,P9,PTOD2)
      END IF
      KE = 0
      ITER = 0
   10 CONTINUE
      IF (XN(1).LE.PMIN.OR.XN(1).GE.PMAX) KE = KE + 1
      IF (KE.GE.3) THEN
      IF (XN(1).LE.PMIN) P9 = PMIN
      IF (XN(1).GE.PMAX) P9 = PMAX
      RETURN
      END IF
      CALL CONT(J,XN(1),F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' *** PV1MAX *** ITER J XN3 F1 '
      WRITE (NT6,FMT=*) ITER,J,XN,F1
      END IF
      IF (ABS(E(J)*F1).LT. (EPSI/5.)) THEN
      IF (J.EQ.9) P9 = XN(1)
      RETURN
      END IF
      XN(1) = XN(1) + DXM(1)
      CALL CONT(J,XN(1),F2)
      XN(1) = XN(1) - DXM(1)
      XN(1) = XN(1) - F1*DXM(1)/ (F2-F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' *** PV1MAX *** ITER J XN3 F2 '
      WRITE (NT6,FMT=*) ITER,J,XN,F2
      END IF
      ITER = ITER + 1
      IF (J.EQ.11) THEN
      IF (XN(1).GT.P2PC.OR.XN(1).GT.P9) GO TO 30
      IF (XN(1).LT.PMIN) GO TO 30
      END IF
      IF (ITER.GE.ITERMA) THEN
      IF (J.EQ.11) THEN
      GO TO 30
      ELSE
      RETURN
      END IF
      END IF
      GO TO 10
   30 CONTINUE
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ********* PV1MAX / PB OBST*************** ITER J XN3 F1 F2'
      WRITE (NT6,FMT=*) ITER,J,XN,F1,F2
      END IF
      IG = 0
      P11 = A9
      DO 40 IG = 1,NOBST
      POBS(IG) = A9
   40 CONTINUE
      P3PC = FINT(3.0,PENT2S(1),PENT2S(11),2)
      K6S = K6
      K6 = 0
      XC(1) = PMIN
      XC(2) = XN(2)
      XC(3) = XN(3)
      CALL CONT(J,XC,F1)
      IF (F1.GT.0) THEN
      XN(1) = PMIN - DXM(1)
      RETURN
      END IF
      XC(1) = PMAX
   45 CONTINUE
      CALL CONT(J,XC,F1)
      IF (KF.EQ.1) THEN
      XC(1) = XC(1) - DXM(1)*5
      KF = 0
      GO TO 45
      END IF
      K6 = K6S
      KVMAX = 1
      P11 = MIN(XC(1),P9)
      DO 70 IG = 1,NOBST
      KE = 0
      ITER = 0
      XN(1) = P11
      P1 = PMIN
      P2 = XC(1)
   50 CONTINUE
      IF (XN(1).LE.PMIN.OR.XN(1).GE.PMAX) KE = KE + 1
      IF (KE.GE.3) GO TO 70
      CALL CONT(J,XN(1),F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' *** PV1MAX *** ITER J XN3 F1 NO OBS'
      WRITE (NT6,FMT=*) ITER,J,XN,F1,IG
      END IF
      IF (ITER.EQ.0) THEN
      IF (F1.LT.0.) GO TO 70
      ELSE IF ((F1.LT.0).AND.(XN(1).GT.P1)) THEN
      P1 = XN(1)
      ELSE IF ((F1.GT.0).AND.(XN(1).LT.P2)) THEN
      P2 = XN(1)
      END IF
      IF (ABS(E(J)*F1).LT. (EPSI/5.)) GO TO 60
      XN(1) = XN(1) - DXM(1)
      CALL CONT(J,XN(1),F2)
      XN(1) = XN(1) + DXM(1)
      XN(1) = XN(1) + F1*DXM(1)/ (F2-F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' *** PV1MAX *** ITER J XN3 F2 NO OBS'
      WRITE (NT6,FMT=*) ITER,J,XN,F2,IG
      END IF
      ITER = ITER + 1
      IF ((XN(1).LE.P1).OR.(XN(1).GE.P2)) THEN
      XN(1) = (GOLDN - 1.)*(P1 + (GOLDN-1.)*P2)
      END IF
      IF (ITER.GE.ITERMA) THEN
      if ((p2-p1).le.0.01) then
      xn(1) = p1
      go to 60
      else
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *****  BAD CONVERGENCE IN PV1MAX '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'BAD CONVERGENCE IN PV1MAX'
      END IF
      KVMAX = 0
      RETURN
      end if
      END IF
      GO TO 50
   60 CONTINUE
      POBS(IG) = XN(1)
      IF (XN(1).LT.P11) THEN
      P11 = XN(1)
      IR1 = IG
      ZOUT(25) = P11*UP
      ZOUT(26) = IR1
      END IF
   70 CONTINUE
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' *** PV1MAX *** P2PC,P9,IR1,P11,POBS  '
      WRITE (NT6,FMT=*) P2PC,P9,IR1,P11,POBS
      END IF
      XN(1) = P11
      KVMAX = 0
      IG = 0
      RETURN
      END
