      SUBROUTINE SV1MAX(
     +XM,
     +V1SMA,
     +L
     +)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      INTEGER IXTRPL
      REAL PINI
      REAL PMAX
      REAL PMIN
      REAL V1VRI
      REAL V1VRMA
      REAL V1VRMI
      REAL V2VSMA
      REAL V2VSMI
      REAL ZMAX
      REAL ZMIN
      REAL SSGMIN
      REAL DTMAX1
      REAL DTMAX2
      REAL DTMIN
      REAL TMILBT
      REAL TMALBT
      REAL ZMILBT
      REAL ZMALBT
      REAL WMILBT
      REAL WMALBT
      REAL SMILBT
      REAL SMALBT
      REAL TMILL1
      REAL TMALL1
      REAL ZMILL1
      REAL ZMALL1
      REAL WMILL1
      REAL WMALL1
      REAL SMILL1
      REAL SMALL1
      REAL TMILL2
      REAL TMALL2
      REAL ZMILL2
      REAL ZMALL2
      REAL WMILL2
      REAL WMALL2
