      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      LOGICAL CHECK1
      LOGICAL CHECK2
      LOGICAL RWNXTT
      LOGICAL RWNXTL
      LOGICAL NXTPLT(MAXTTA,MAXVQ)
      LOGICAL NXTPL1(MAXTAL,MAXVQ)
      LOGICAL NXTPL2(MAXTAL,MAXVQ)
      COMMON /CTESL/CHECK1,CHECK2,RWNXTT,RWNXTL,NXTPLT,NXTPL1,NXTPL2
      REAL V1SMA
      INTEGER L
      REAL XM(3)
      REAL F1
      REAL F2
      REAL V1RMIW
      INTEGER ITER
      INTEGER KE
      REAL XC(3)
      EXTERNAL CONT
      INTRINSIC ABS,AMAX1
      IF (RWNXTT) THEN
      V1RMIW = AMAX1(V1VRMI,V1RMIL)
      ELSE
      V1RMIW = V1VRMI
      END IF
      KE = 0
      ITER = 0
      XC(1) = XM(1)
      XC(2) = XM(2)
      XC(3) = XM(3)
   10 CONTINUE
      IF (XC(3).LE.V1RMIW) THEN
      XC(3) = V1RMIW
      KE = KE + 1
      END IF
      CALL CONT(L,XC(1),F1)
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** SV1MAX *** ITER L XC3 F1 '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) ITER,L,XC,F1
      IF (ABS(E(L)*F1).LT. (EPSI/5.)) GO TO 20
      XC(3) = XC(3) + DXM(3)
      CALL CONT(L,XC(1),F2)
      IF (F1.EQ.F2) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *****  BAD CONVERGENCE IN SV1MAX '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'BAD CONVERGENCE IN SV1MAX'
      END IF
      RETURN
      END IF
      XC(3) = XC(3) - DXM(3)
      XC(3) = XC(3) - F1*DXM(3)/ (F2-F1)
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** SV1MAX *** ITER L XC3 F2 '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) ITER,L,XC,F2
      ITER = ITER + 1
      IF (ITER.GE.ITERMA) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *****  BAD CONVERGENCE IN SV1MAX '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +' BAD CONVERGENCE IN SV1MAX'
      END IF
      RETURN
      END IF
      GO TO 10
   20 CONTINUE
      V1SMA = XC(3)
      IF (V1SMA.GT.1.) V1SMA = 1.
      RETURN
      END
      SUBROUTINE SV1MIN(
     &XM,
