      REAL SMALL2
      REAL V2SMIL
      REAL V2SMAL
      REAL V1RMIL
      REAL V1RMAL
      REAL PMILBT
      REAL PMALBT
      REAL PMILL1
      REAL PMALL1
      REAL PMILL2
      REAL PMALL2
      REAL ALIM(20)
      REAL ZLIM(40)
      COMMON /LIMIT1/IXTRPL
      COMMON /LIMIT2/ZLIM,PMIN,PINI,PMAX,V2VSMI,V2VSMA,V1VRMI,V1VRI,
     +V1VRMA,ZMIN,ZMAX,DTMIN,DTMAX1,DTMAX2,ALIM,SSGMIN,
     +TMILBT,TMALBT,ZMILBT,ZMALBT,WMILBT,WMALBT,SMILBT,SMALBT,
     +TMILL1,TMALL1,ZMILL1,ZMALL1,WMILL1,WMALL1,SMILL1,SMALL1,
     +TMILL2,TMALL2,ZMILL2,ZMALL2,WMILL2,WMALL2,SMILL2,SMALL2,
     +V2SMIL,V2SMAL,V1RMIL,V1RMAL,PMILBT,PMALBT,PMILL1,PMALL1,
     +PMILL2,PMALL2
      REAL A1
      REAL A2
      REAL A79
      REAL A9
      REAL PMINF
      REAL PSTL
      REAL PSTL1
      REAL PSTL2
      REAL PSTRUC
      REAL PU
      REAL TU
      REAL UH
      REAL UL
      REAL UP
      REAL EPSI
      REAL C3
      REAL HU
      INTEGER COD
      INTEGER DRYCHK
      INTEGER DRYCHL
      INTEGER IATA
      INTEGER IDLL
      INTEGER IMP
      INTEGER ITERMA
      INTEGER K1
      INTEGER K2
      INTEGER KEMAX
      INTEGER KISU
      INTEGER KPPM
      INTEGER KS
      INTEGER KS4
      INTEGER KSB
      INTEGER KSP
      INTEGER KST
      INTEGER KSU
      INTEGER KTAB1
      INTEGER KTAB2
      INTEGER KTAB3
      INTEGER KTABL
      INTEGER KV1MN
      INTEGER L1610
      INTEGER LA42
      INTEGER MICRO
      INTEGER MODE
      INTEGER OUTMOD
      INTEGER NCONT
      INTEGER KTR
      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      REAL AK1
      REAL AK2
      REAL ASD
      REAL PP
      REAL TA
      REAL TISA
      REAL TOD
      REAL TOR
      REAL VC1
      REAL VENT
      REAL V2VS
      REAL WIDTH
      REAL ZP
      INTEGER IOBFTO
      INTEGER KF
      INTEGER NOBST
      INTEGER KOBS
      INTEGER KCGA
      INTEGER KCGL
      INTEGER KCGT
      REAL D(MAXOBS)
      REAL DGA(11)
      REAL DIST(10)
      REAL DP(MAXOBS)
      REAL H(MAXOBS)
      REAL HP(MAXOBS)
      REAL PEN1SI(24)
      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
      REAL TRAJ(32)
      REAL TRAJV(10)
      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      REAL KVMIN
      INTEGER IR
      REAL FOBS(MAXFOB)
      COMMON /SV1/IR
      COMMON /SV2/FOBS,KVMIN
      REAL AASDP
      REAL ASDMBA
      REAL ASDP
      REAL ATODP
      REAL P2PC
      REAL P2S
      REAL PMAXLP
      REAL PMAXP2
      REAL PTOD2
      REAL PTOR2
      REAL TODMBA
      REAL TODP
      REAL TORMBA
      REAL TORP
      REAL V1MAXP
      REAL V1MBAL
      REAL V1MINP
      REAL V1VRLP
      REAL V1VRMB
      REAL V1VRP
      REAL V1VRP2
      REAL V21
      REAL V2P
      REAL VOPTP
      REAL VQP
      REAL VRP
      REAL WIDTHP
      REAL ZGP
      INTEGER IPP
      REAL XLP(3)
      REAL ZOUL1(60)
      REAL ZOUL2(60)
      REAL ZOUT(60)
      REAL ZOUTE(20)
      REAL ZOUTS(60)
      COMMON /SPOUT1/IPP
      COMMON /SPOUT2/ZOUT,XLP,VQP,VRP,V1MAXP,V1MINP,V1VRP,V2P,VOPTP,
     +V1VRLP,PMAXLP,TORP,ASDP,TODP,P2S,V21,AASDP,ATODP,PTOR2,
     +PTOD2,P2PC,ZOUL1,ZOUL2,WIDTHP,ZGP,ZOUTE,PMAXP2,V1VRP2,ZOUTS
     +,V1VRMB,V1MBAL,ASDMBA,TODMBA,TORMBA
      LOGICAL CHECK1
      LOGICAL CHECK2
      LOGICAL RWNXTT
      LOGICAL RWNXTL
      LOGICAL NXTPLT(MAXTTA,MAXVQ)
      LOGICAL NXTPL1(MAXTAL,MAXVQ)
      LOGICAL NXTPL2(MAXTAL,MAXVQ)
      COMMON /CTESL/CHECK1,CHECK2,RWNXTT,RWNXTL,NXTPLT,NXTPL1,NXTPL2
      REAL V1SVR
      INTEGER L
      REAL XM(3)
      REAL DV
      REAL DV0
      REAL F1
      REAL F2
      REAL V1V
      REAL V1VI
      REAL V1RMIW
      INTEGER I
      INTEGER ITER
      INTEGER J
      INTEGER J1
      INTEGER J2
      INTEGER K
      INTEGER KE
      REAL F(11)
      REAL XC(3)
      REAL FINT
      EXTERNAL FINT
      EXTERNAL CONT,TRANSR
      INTRINSIC ABS,AMAX1
      DATA F/5*0.,99999999.,5*0./
      IF (RWNXTT) THEN
      V1RMIW = AMAX1(V1VRMI,V1RMIL)
      ELSE
      V1RMIW = V1VRMI
      END IF
      KVMIN = 0
      KE = 0
      ITER = 0
      XC(1) = XM(1)
      XC(2) = XM(2)
      XC(3) = XM(3)
      DV = DXM(3)*10.
   10 CONTINUE
      IF (XC(3).LE.V1RMIW) THEN
      XC(3) = V1RMIW
      KE = KE + 1
      END IF
      IF (XC(3).GE.VOPTP) THEN
      XC(3) = VOPTP
      KE = KE + 1
      END IF
      IF (KE.GE.3.AND.L.NE.11) THEN
      V1SVR = XC(3)
      RETURN
      END IF
      CALL CONT(L,XC(1),F1)
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** SV1MIN *** ITER L XC3 F1 '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) ITER,L,XC,F1
      IF (ABS(E(L)*F1).LT. (EPSI/5.)) GO TO 50
      XC(3) = XC(3) + DV
      CALL CONT(L,XC(1),F2)
      IF (F1.EQ.F2) THEN
      V1SVR = VOPTP
      RETURN
      END IF
      XC(3) = XC(3) - DV
      XC(3) = XC(3) - F1*DV/ (F2-F1)
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** SV1MIN *** ITER L XC3 F2 '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) ITER,L,XC,F2
      ITER = ITER + 1
      IF (ITER.GE.ITERMA) THEN
      V1SVR = VOPTP
      RETURN
      END IF
      IF (L.EQ.11) THEN
      IF (XC(3).LT.XM(3).OR.ITER.GT.5) THEN
      V1V = XM(3)
      V1VI = XM(3)
      DV0 = (VOPTP-XM(3))/4.
      IF (DV0.LE..001) THEN
      V1SVR = VOPTP
      RETURN
      END IF
      KVMIN = 1
      DO 20 I = 1,5
      IR = I
      XC(3) = VOPTP - DV0* (I-1)
      CALL CONT(L,XC(1),F2)
      F(I+6) = XC(3)
   20 CONTINUE
      KVMIN = 0
      DO 40 I = 1,NOBST
      K = (I-1)*5 + 1
      CALL TRANSR(FOBS(K),F(1),5)
      IF (KS.EQ.1) WRITE (NT6,FMT='(A)')
     +' *** SV1MIN PB OBS ***   F  '
      IF (KS.EQ.1) WRITE (NT6,FMT=*) F
      J1 = 0
      J2 = 0
      DO 30 J = 1,5
      IF (F(J).GE.0.) J1 = 1
      IF (F(J).GE.F(J+1)) J2 = 1
   30 CONTINUE
      IF (J1.EQ.1) THEN
      IF (J2.EQ.0) THEN
      V1VI = FINT(0.,F(1),F(7),1)
      IF (V1VI.GT.V1V) V1V = V1VI
      ELSE
      V1SVR = VOPTP
      RETURN
      END IF
      END IF
   40 CONTINUE
      V1SVR = V1V
      IF (V1V.LT.XM(3)) V1SVR = XM(3)
      IF (V1V.GT.VOPTP) V1SVR = VOPTP
      RETURN
      END IF
      END IF
      GO TO 10
   50 CONTINUE
      V1SVR = XC(3)
      RETURN
      END
