      REAL RK2T
      REAL RKV1
      REAL RKVF
      REAL RKVLD1
      REAL RKVLD2
      REAL VMCA
      REAL VMCG
      REAL VS
      INTEGER KMCA
      INTEGER KMCAG
      INTEGER KMCG
      INTEGER KMU
      REAL VDELBR(2)
      REAL VMAP(20)
      REAL VMC1(20)
      REAL VMGP(20)
      COMMON /VIT1/KMCA,KMCG,KMU,KMCAG
      COMMON /VIT2/VMCA,VMCG,RK2T,RKVF,AKV1,AKV2,RKVLD1,RKVLD2,
     +FTOKV,AP1KV,AP2KV,VMC1,VMGP,VMAP,DVMCG,DVMCA,RKV1,
     +DV2CP,DVMCPE,VS,VDELBR
      INTEGER DBRMOD
      INTEGER IBRACT
      INTEGER IBRAL1
      INTEGER IBRAL2
      INTEGER KAP1
      INTEGER KAP2
      INTEGER KLD1
      INTEGER KLD2
      INTEGER NAP1
      INTEGER NAP2
      INTEGER NEFFA
      INTEGER NEFFL
      INTEGER NEFFT
      INTEGER NIGC
      INTEGER NLD1
      INTEGER NLD2
      INTEGER IBOOSL
      INTEGER IBOOST
      INTEGER IRTO
      INTEGER IALT
      INTEGER IZRTO
      INTEGER RWSHFT
      REAL TBAMU
      REAL LBAMU1
      REAL LBAMU2
      INTEGER IGC(30)
      INTEGER IZCODA(5)
      INTEGER IZCODL(5)
      INTEGER IZCODT(7)
      COMMON /INP1/NIGC,IZCODT,NAP1,KAP1,NAP2,KAP2,IZCODA,NLD1,KLD1,
     +NLD2,KLD2,IZCODL,NEFFT,NEFFA,NEFFL,IGC,IBOOSL,IBOOST,IRTO,
     +IALT,IZRTO,IBRACT,IBRAL1,IBRAL2,RWSHFT,DBRMOD
      COMMON /INP2/TBAMU,LBAMU1,LBAMU2
      REAL GAMAR
      REAL D3
      REAL DCV
      REAL DDIST
      REAL DHPP
      REAL DHSD0
      REAL DHSD4
      REAL DZPFTO
      REAL DZPH
      REAL DZPH4
      REAL GAMA
      REAL GFTO
      REAL H1
      REAL HGN1
      REAL HGN2
      REAL HGR1
      REAL HGR2
      REAL HM
      REAL HM1
      REAL HSD0
      REAL HSDN0
      REAL HSDN4
      REAL HSDR4
      REAL PFTOR
      REAL PHSD
      REAL RF
      REAL RS
      REAL S1
      REAL S2
      REAL S3
      REAL TOD1M
      REAL TODC
      REAL TODTM
      REAL X
      REAL ZFTO
      REAL ZGH
      REAL ZGH4
      REAL ZPFTO
      INTEGER I
      INTEGER KARDI
      REAL HN(10)
      REAL TRAJR(21)
      REAL Z(12)
      REAL FINT,ZPRES
      EXTERNAL FINT,ZPRES
      EXTERNAL INFLU,JNT,PIST
      KARDI = 0
      HM = 0.
      GAMA = GAMAR
      CALL JNT(2004,X,GAMA,Z(1))
      TRAJR(1) = 0.
      DO 10 I = 2,9
      TRAJR(I+11) = TRAJ(I+11) + TRAJ(I)*.008/.3048
   10 CONTINUE
      TRAJR(11) = A9
      TRAJR(12) = 0.
      TRAJR(21) = TRAJR(20)
      IF (NTAB(2001).NE.0) THEN
      D3 = TRAJ(10) - TRAJ(9)
      K1 = 1
      K2 = 1
      CALL JNT(2001,D3,TISA,Z(1))
      D3 = Z(1)
      CALL JNT(2002,D3,ZP,Z(1))
      D3 = Z(1)
      TRAJ(10) = TRAJ(9) + D3
      END IF
      DO 20 I = 2,10
      DCV = FINT(TRAJ(I),DIST(1),TRAJV(1),1)
      DDIST = TRAJ(I) - DCV
      TRAJR(I) = TRAJ(I) + DDIST
   20 CONTINUE
      HN(1) = 0.
      DO 30 I = 2,9
      HN(I) = TRAJR(11+I) - TRAJR(I)*.008/.3048
   30 CONTINUE
      HN(10) = A9
      S1 = TRAJR(2)
      HGR1 = TRAJR(13)
      HGN1 = HN(2)
      S2 = TRAJR(9)
      HGR2 = TRAJR(20)
      HGN2 = HN(9)
      S3 = TRAJR(10)
      IF (AHSD.NE.0.) THEN
      HSD0 = AHSD
      ELSE
      HSD0 = AERO(12)
      END IF
      PHSD = AERO(13)
      HSDR4 = 400.
      IF (HSD0.GT.HGR2) THEN
      KARDI = 1
      HSD0 = HGR2
      END IF
      IF (HSD0.LT.400.) HSD0 = 400.
      DHSD0 = FINT(HSD0,TRAJR(12),TRAJR(1),1)
      HSDN0 = HSD0 - DHSD0*.008/.3048
      DHSD4 = FINT(HSDR4,TRAJR(12),TRAJR(1),1)
      HSDN4 = HSDR4 - DHSD4*.008/.3048
      XLP(3) = VOPTP
      CALL PIST(1,XLP(1),XLE(1),RF)
      TOD1M = RF
      TOD1M = TOD1M*COEF(3) + COEF(4) + ATOD
      TODC = TOD1M
      TODTM = 0.
      IF (SSGMIN.NE.2.4) THEN
      IF (E(25).EQ.1.) THEN
      CALL PIST(3,XLP(1),XLE(1),RF)
      TODTM = RF
      TODTM = TODTM*COEF(15) + COEF(16) + ATOD
      IF (TODC.LT.TODTM) TODC = TODTM
      END IF
      END IF
      DHPP = (PP/100.)*(TODC/.3048)
      IF (NOBST.NE.0) THEN
      DO 40 I = 1,NOBST
      H1 = H(I) - DHPP
      IF (H1.GT.HM) HM = H1
   40 CONTINUE
      IF (KTJ.EQ.1) HM = HM + 20.
      HM1 = HM
      HM = HM + PHSD
      IF (HSDN0.LT.HM) THEN
      KARDI = 1
      HSDN0 = HM
      END IF
      IF (HSDN4.LT.HM) HSDN4 = HM
      IF (HSDN0.GT.HGN2) THEN
      KARDI = 1
      HSDN0 = HGN2
      END IF
      DHSD0 = FINT(HSDN0,HN(1),TRAJR(1),1)
      HSD0 = HSDN0 + DHSD0*.008/.3048
      DHSD4 = FINT(HSDN4,HN(1),TRAJR(1),1)
      HSDR4 = HSDN4 + DHSD4*.008/.3048
      END IF
      IF (KARDI.EQ.1) DIVER(3) = 1.
      ZOUT(27) = GAMA
      ZOUT(28) = S1/UL
      ZOUT(29) = HGN1/UH
      ZOUT(30) = HGR1/UH
      ZGH = DHPP + HGR1 + ZG + 35.
      DZPH = ZPRES(ZGH,TISA) - ZPRES(ZG,TISA)
      ZOUT(31) = DZPH/UH
      ZOUT(32) = DHSD0/UL
      ZOUT(33) = HSDN0/UH
      ZOUT(34) = HSD0/UH
      ZGH = DHPP + HSD0 + ZG + 35.
      DZPH = ZPRES(ZGH,TISA) - ZPRES(ZG,TISA)
      ZOUT(35) = DZPH/UH
      ZGH4 = DHPP + HSDR4 + ZG + 35.
      DZPH4 = ZPRES(ZGH4,TISA) - ZPRES(ZG,TISA)
      IF (TISA.LE.DTCD(21).AND.DIVER(5).LT.DZPH4) DIVER(5) = DZPH4
      IF (TISA.LE.DTCD(21).AND.DIVER(1).LT.(ZOUT(35)*UH))
     +DIVER(1) = ZOUT(35)*UH
      ZOUT(36) = S2/UL
      ZOUT(37) = HGN2/UH
      ZOUT(38) = HGR2/UH
      ZGH = DHPP + HGR2 + ZG + 35.
      DZPH = ZPRES(ZGH,TISA) - ZPRES(ZG,TISA)
      ZOUT(39) = DZPH/UH
      IF (DIVER(4).EQ.0.) DIVER(4) = DZPH
      IF (TISA.LE.DTCD(21).AND.DIVER(4).GT.ZOUT(39)*UH)
     +DIVER(4) = ZOUT(39)*UH
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' HSDM: ZGH-DZPH-ZG-HGR2 '
      WRITE (NT6,FMT=*) ZGH,DZPH,ZG,HGR2
      END IF
      ZOUT(40) = S3/UL
      IF (NOBST.NE.0) ZOUT(42) = ZOUT(34) - HM1/UH
      IF (AERO(12).LT.(ZOUT(39)*UH).AND.AERO(12).GT.DZPH4) THEN
      IHSD1(NLCT,NCCT) = AERO(12)
      ELSE
      IHSD1(NLCT,NCCT) = DZPH4
      END IF
      IHSDMI = IHSD1(NLCT,NCCT)
      IHSD2(NLCT,NCCT) = ZOUT(39)*UH
      IF (TISA.LE.DTCD(21)) THEN
      ZFTO = AERO(8)
      IF (ZFTO.LT.HSD0) ZFTO = HSD0
      ZGH = DHPP + ZFTO + ZG + 35.
      DZPFTO = ZPRES(ZGH,TISA) - ZPRES(ZG,TISA)
      ZPFTO = DZPFTO + ZP
      K1 = 1
      K2 = 1
      CALL JNT(2401,TISA,ZPFTO,Z(1))
      PFTOR = Z(1)
      IF (NTAB(2404).NE.0) CALL JNT(2404,PFTOR,FTOKV,Z(1))
      PFTOR = Z(1)*COEF(21) + COEF(22)
      CALL INFLU(2401,PFTOR,IZCODT(1),RS)
      PFTOR = RS
      K2 = 9
      CALL JNT(2402,PFTOR,PMFTO(11),Z(1))
      K2 = 1
      DO 60 I = 1,9
      PMFTO(I) = Z(I)
   60 CONTINUE
      GFTO = FINT(XLP(1),PMFTO(1),PMFTO(11),2)
      ZOUT(41) = GFTO
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***TRAJE*** GAMA DHSD0 HSD0 GFTO T RAJR HN '
      WRITE (NT6,FMT=*) GAMA,DHSD0,HSD0,GFTO,TRAJR,HN
      END IF
      RETURN
      END
