      INTEGER KOBS
      INTEGER KCGA
      INTEGER KCGL
      INTEGER KCGT
      REAL D(MAXOBS)
      REAL DGA(11)
      REAL DIST(10)
      REAL DP(MAXOBS)
      REAL H(MAXOBS)
      REAL HP(MAXOBS)
      REAL PEN1SI(24)
      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
