      REAL V1RMIL
      REAL V1RMAL
      REAL PMILBT
      REAL PMALBT
      REAL PMILL1
      REAL PMALL1
      REAL PMILL2
      REAL PMALL2
      REAL ALIM(20)
      REAL ZLIM(40)
      COMMON /LIMIT1/IXTRPL
      COMMON /LIMIT2/ZLIM,PMIN,PINI,PMAX,V2VSMI,V2VSMA,V1VRMI,V1VRI,
     +V1VRMA,ZMIN,ZMAX,DTMIN,DTMAX1,DTMAX2,ALIM,SSGMIN,
     +TMILBT,TMALBT,ZMILBT,ZMALBT,WMILBT,WMALBT,SMILBT,SMALBT,
     +TMILL1,TMALL1,ZMILL1,ZMALL1,WMILL1,WMALL1,SMILL1,SMALL1,
     +TMILL2,TMALL2,ZMILL2,ZMALL2,WMILL2,WMALL2,SMILL2,SMALL2,
     +V2SMIL,V2SMAL,V1RMIL,V1RMAL,PMILBT,PMALBT,PMILL1,PMALL1,
     +PMILL2,PMALL2
      REAL AASDP
      REAL ASDMBA
      REAL ASDP
      REAL ATODP
      REAL P2PC
      REAL P2S
      REAL PMAXLP
      REAL PMAXP2
      REAL PTOD2
      REAL PTOR2
      REAL TODMBA
      REAL TODP
      REAL TORMBA
      REAL TORP
      REAL V1MAXP
      REAL V1MBAL
      REAL V1MINP
      REAL V1VRLP
      REAL V1VRMB
      REAL V1VRP
      REAL V1VRP2
      REAL V21
      REAL V2P
      REAL VOPTP
      REAL VQP
      REAL VRP
      REAL WIDTHP
      REAL ZGP
      INTEGER IPP
      REAL XLP(3)
      REAL ZOUL1(60)
      REAL ZOUL2(60)
      REAL ZOUT(60)
      REAL ZOUTE(20)
      REAL ZOUTS(60)
      COMMON /SPOUT1/IPP
      COMMON /SPOUT2/ZOUT,XLP,VQP,VRP,V1MAXP,V1MINP,V1VRP,V2P,VOPTP,
     +V1VRLP,PMAXLP,TORP,ASDP,TODP,P2S,V21,AASDP,ATODP,PTOR2,
     +PTOD2,P2PC,ZOUL1,ZOUL2,WIDTHP,ZGP,ZOUTE,PMAXP2,V1VRP2,ZOUTS
     +,V1VRMB,V1MBAL,ASDMBA,TODMBA,TORMBA
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      REAL GAMXWP
      INTEGER IK1T
      INTEGER IK2T
      INTEGER IKVF
      INTEGER IKV1
      INTEGER IKV2
      REAL AERO(40)
      REAL COEF(40)
      REAL COEFP(40)
      REAL CVIT(80)
      REAL DTCA(21)
      REAL DTCD(21)
      REAL GAP(21)
      REAL GLD(21)
      REAL RAER(8)
      REAL RTFP(8)
      REAL RGLD(8)
      REAL TCGC(20)
      REAL TK1T(20)
      REAL TK2T(20)
      REAL TKV1(20)
      REAL TKVA(40)
      REAL TKVF(20)
      REAL TKVL(40)
      REAL TVQ(8)
      REAL VMU(20)
      REAL V2CP(20)
      REAL GLDA(21)
      REAL VMPE(30)
      REAL XTWD(40)
      COMMON /VAR1/IK1T,IK2T,IKVF,IKV1,IKV2
      COMMON /VAR2/COEF,DTCA,DTCD,AERO,CVIT,GAP,GLD,VMU,COEFP,TK2T,TKVF,
     +TKVA,TKVL,TVQ,TCGC,RGLD,RAER,RTFP,TKV1,TK1T,V2CP,VMPE,
     +XTWD,GAMXWP,GLDA
      REAL P9
      REAL KVMAX
      INTEGER IG
      REAL POBS(MAXOBS)
      COMMON /PBOB1/IG
      COMMON /PBOB2/KVMAX,POBS,P9
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      LOGICAL DRYLD1
      LOGICAL DRYLD2
      LOGICAL DRYTYP
      REAL BE30(96)
      REAL BE31(96)
      REAL BE32(96)
      REAL BINT(96)
      REAL BMAS(96)
      REAL BPIS(96)
      REAL BV2(96)
      REAL BVEN(96)
      REAL TZREF(21)
      REAL XPPM(12)
      REAL XVE(12)
      REAL XLE(12)
      REAL XLEL(12)
      REAL XMAL(12)
      REAL XMAS(12)
      REAL XBEL(12)
      COMMON /PISTE1/DRYTYP,DRYLD1,DRYLD2
      COMMON /PISTE2/XLE,XVE,XMAS,BINT,BPIS,BVEN,BV2,BMAS,BE30,BE31,
     +BE32,TZREF,XPPM,XMAL,XLEL,XBEL
      INTEGER I,IOD1
      REAL XN(3)
      REAL GOLDN
      REAL F1
      REAL F2
      REAL G2PC
      REAL GAM1
      REAL GAM2
      REAL IR1
      REAL K6S
      REAL P
      REAL P1
      REAL P11
      REAL P3PC
      REAL RDUM
      REAL PDMIN
      REAL PDMAX
      INTEGER ITER
      INTEGER J
      REAL XC(3)
      PARAMETER ( GOLDN = 1.618033989 )
      REAL FINT
      EXTERNAL FINT
      EXTERNAL CONT
      INTRINSIC ABS,AMIN1
      P = PMINF
      I = COD
      P3PC = FINT(3.0,PENT2S(1),PENT2S(11),2)
      DO 30 J = 1,11
      IF (J.EQ.4.AND.TZREF(6).EQ.A9) GO TO 30
      IF (J.EQ.11.AND.NOBST.EQ.0) GO TO 30
      IF (J.EQ.1.OR.J.EQ.2.OR.J.EQ.5.OR.J.EQ.6.OR.J.EQ.7.OR.
     +J.EQ.8) GO TO 30
      ITER = 0
      XN(1) = PINI
      IF (J.EQ.11) XN(1) = P
      IF (J.EQ.11.AND.IOD1.EQ.3.AND.XN(1).LT.AMIN1(PMAXLP,PTOD2))
     +THEN
      G2PC = (ZLIM(29)-COEF(10))/COEF(9)
      P2PC = FINT(G2PC,PENT2S(1),PENT2S(11),2)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ///VIFIX/IOD3 XN P2PC PMAXLP PTOD2'
      WRITE (NT6,FMT=*) XN,P2PC,PMAXLP,PTOD2
      END IF
      XN(1) = AMIN1(PMAXLP,PTOD2)
      IF (P2PC.LT.AMIN1(PMAXLP,PTOD2)) THEN
      XN(1) = P2PC
      END IF
      END IF
      P1 = XN(1)
   10 CONTINUE
      CALL CONT(J,XN(1),F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***V1FIX*** J F1 ITER XN '
      WRITE (NT6,FMT=*) J,F1,ITER,XN
      END IF
      IF (F1.LE.0..AND.J.EQ.11.AND.ITER.EQ.0) GO TO 20
      IF (ABS(E(J)*F1).LT. (EPSI/5.)) GO TO 20
      XN(1) = XN(1) + DXM(1)
      CALL CONT(J,XN(1),F2)
      XN(1) = XN(1) - DXM(1)
      XN(1) = XN(1) - F1*DXM(1)/ (F2-F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***V1FIX*** J F2 ITER XN '
      WRITE (NT6,FMT=*) J,F2,ITER,XN
      END IF
      IF (ITER.EQ.0.AND.J.EQ.11) THEN
      IF (XN(1).LT.PMIN.OR.XN(1).GT.P1) THEN
      ITER = ITER + 1
      GAM1 = FINT(P1,PEN2SI(1),PEN2SI(11),2)
      GAM1 = GAM1*GAMXWP
      GAM1 = GAM1*COEF(9) + COEF(10)
      GAM2 = GAM1 + F1
      RDUM = FINT(GAM2,PENT2S(1),PENT2S(11),2)
      IF ((RDUM.LT.PMIN).OR.(RDUM.GT.P1)) THEN
      XN(1) = P3PC
      ELSE
      XN(1) = RDUM
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***V1FIX*** GAM1 GAM2 XN '
      WRITE (NT6,FMT=*) GAM1,GAM2,XN
      END IF
      GO TO 10
      END IF
      END IF
      ITER = ITER + 1
      IF (J.EQ.11) THEN
      IF (XN(1).GT.P2PC.OR.XN(1).GT.P9) GO TO 40
      IF (XN(1).LT.PMIN) GO TO 40
      END IF
      IF (ITER.GT.ITERMA) THEN
      IF (J.EQ.11) THEN
      GO TO 40
      END IF
      KF = 1
      END IF
      IF (KF.EQ.1) THEN
      WRITE (NT6,FMT=10000) J
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10001) J
      END IF
      RETURN
      END IF
      GO TO 10
   20 CONTINUE
      IF ((J.EQ.3.OR.J.EQ.9.OR.J.EQ.10).AND.
     +PMAXLP.GT.XN(1)) THEN
      PMAXLP = XN(1)
      PMAXP2 = XN(1)
      V1VRP2 = XN(3)
      END IF
      IF (XN(1).GE.P) GO TO 30
      P = XN(1)
      I = J
   30 CONTINUE
      XN(1) = P
      RETURN
   40 CONTINUE
      IG = 0
      DO 50 IG = 1,20
      POBS(IG) = A9
   50 CONTINUE
      XC(1) = PMIN
      XC(2) = XN(2)
      XC(3) = XN(3)
      K6S = K6
      K6 = 0
      CALL CONT(J,XC,F1)
      IF (F1.GT.0) THEN
      XN(1) = PMIN - DXM(1)
      RETURN
      END IF
      XC(1) = PMAX
   55 CONTINUE
      CALL CONT(J,XC,F1)
      IF (KF.EQ.1) THEN
      XC(1) = XC(1) - DXM(1)*5
      KF = 0
      GO TO 55
      END IF
      K6 = K6S
      KVMAX = 1
      P11 = XC(1)
      DO 80 IG = 1,NOBST
      ITER = 0
      XN(1) = P11
      PDMIN = PMIN
      PDMAX = XC(1)
   60 CONTINUE
      CALL CONT(J,XN(1),F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' *** PV1MAX *** ITER J XN3 F1 NO OBS'
      WRITE (NT6,FMT=*) ITER,J,XN,F1,IG
      END IF
      IF (ABS(E(J)*F1).LT. (EPSI/5.)) THEN
      GO TO 70
      ELSE IF ((ITER.EQ.0).AND.(F1.LT.0.)) THEN
      GO TO 70
      ELSE
      ITER = ITER + 1
      END IF
      IF ((F1.LT.0).AND.(XN(1).GT.PDMIN)) THEN
      PDMIN = XN(1)
      ELSE IF ((F1.GT.0).AND.(XN(1).LT.PDMAX)) THEN
      PDMAX = XN(1)
      END IF
      XN(1) = XN(1) - DXM(1)
      CALL CONT(J,XN(1),F2)
      XN(1) = XN(1) + DXM(1)
      XN(1) = XN(1) + F1*DXM(1)/ (F2-F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' *** V1FIX *** ITER J XN3 F2 NO OBS'
      WRITE (NT6,FMT=*) ITER,J,XN,F2,IG
      END IF
      IF ((XN(1).LE.PDMIN).OR.(XN(1).GE.PDMAX)) THEN
      XN(1) = (GOLDN - 1.)*(PDMIN + (GOLDN-1.)*PDMAX)
      END IF
      IF (ITER.GE.ITERMA) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *****  BAD CONVERGENCE IN V1FIX '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +'BAD CONVERGENCE IN V1FIX'
      END IF
      KVMAX = 0
      RETURN
      END IF
      GO TO 60
   70 CONTINUE
      POBS(IG) = XN(1)
      IF (XN(1).LT.P11) THEN
      P11 = XN(1)
      IR1 = IG
      END IF
   80 CONTINUE
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' *** V1FIX *** P2PC,P9,IR1,P11,POBS  '
      WRITE (NT6,FMT=*) P2PC,P9,IR1,P11,POBS
      END IF
      IF (P11.LT.P) THEN
      XN(1) = P11
      I = 11
      ELSE
      XN(1) = P
      END IF
      ZOUT(25) = P11*UP
      ZOUT(26) = IR1
      KVMAX = 0
      IG = 0
      RETURN
10000 FORMAT (/,/,' *** INCORRECT CONVERGENCE IN V1FIX FOR CONT.:',I2)
10001 FORMAT ('INCORRECT CONVERGENCE IN V1FIX FOR CONT.:',I2)
      END
