      REAL TIWLC2(MAXTAL,MAXVQ)
      REAL TIWEB2(MAXTAL,MAXVQ)
      REAL TOWLD1(MAXTAL,MAXVQ)
      REAL TOWAC1(MAXTAL,MAXVQ)
      REAL TOWLC1(MAXTAL,MAXVQ)
      REAL TOWEB1(MAXTAL,MAXVQ)
      REAL TOWLD2(MAXTAL,MAXVQ)
      REAL TOWAC2(MAXTAL,MAXVQ)
      REAL TOWLC2(MAXTAL,MAXVQ)
      REAL TOWEB2(MAXTAL,MAXVQ)
      INTEGER CLJ1(MAXTAL,MAXVQ)
      INTEGER CLJ2(MAXTAL,MAXVQ)
      INTEGER DJ1(MAXTAL,MAXVQ)
      INTEGER DJ2(MAXTAL,MAXVQ)
      INTEGER LTITR(5)
      INTEGER LTITRL(5)
      COMMON /LDG1/LTITR,LTITRL,KODIF,CLJ1,CLJ2,DJ1,DJ2,NGAP1,NGAP2,
     +NGLD1,NGLD2,NTAL,LAT1,LAT2
      COMMON /LDG2/TLDA,BMASL,BVENL,BINFL,BPISL,BEAT,TLDP,QLD,FV1VR,
     +AP1G,AP2G,AP1K,AP2K,CLD1,CLD2,GAP1,GAP2,GLD1,GLD2,
     +AP1GMN,AP2GMN,AL1GMN,AL1G,SLATA,FLAPA,SLATL,FLAPL,
     +STAPMN,STAPMX,STEEP1,STEEP2,TALD1,TRLD1,TACG1,TLCG1,TIWLD1,
     +TIWAC1,TIWLC1,TALD2,TRLD2,TACG2,TLCG2,TIWLD2,TIWAC2,TIWLC2,
     +TOWLD1,TOWAC1,TOWLC1,TOWLD2,TOWAC2,TOWLC2,CLDW1,CLDW2,
     +EMASL,EVENL,EINFL,EPISL,EEAT,EB1L,EB2L,TLEB1,TLEB2,TIWEB1,
     +TIWEB2,TOWEB1,TOWEB2
      REAL P9
      REAL KVMAX
      INTEGER IG
      REAL POBS(MAXOBS)
      COMMON /PBOB1/IG
      COMMON /PBOB2/KVMAX,POBS,P9
      REAL AKV1
      REAL AKV2
      REAL AP1KV
      REAL AP2KV
      REAL DV2CP
      REAL DVMCA
      REAL DVMCPE
      REAL DVMCG
      REAL FTOKV
      REAL RK2T
      REAL RKV1
      REAL RKVF
      REAL RKVLD1
      REAL RKVLD2
      REAL VMCA
      REAL VMCG
      REAL VS
      INTEGER KMCA
      INTEGER KMCAG
      INTEGER KMCG
      INTEGER KMU
      REAL VDELBR(2)
      REAL VMAP(20)
      REAL VMC1(20)
      REAL VMGP(20)
      COMMON /VIT1/KMCA,KMCG,KMU,KMCAG
      COMMON /VIT2/VMCA,VMCG,RK2T,RKVF,AKV1,AKV2,RKVLD1,RKVLD2,
     +FTOKV,AP1KV,AP2KV,VMC1,VMGP,VMAP,DVMCG,DVMCA,RKV1,
     +DV2CP,DVMCPE,VS,VDELBR
      REAL AK1
      REAL AK2
      REAL ASD
      REAL PP
      REAL TA
      REAL TISA
      REAL TOD
      REAL TOR
      REAL VC1
      REAL VENT
      REAL V2VS
      REAL WIDTH
      REAL ZP
      INTEGER IOBFTO
      INTEGER KF
      INTEGER NOBST
      INTEGER KOBS
      INTEGER KCGA
      INTEGER KCGL
      INTEGER KCGT
      REAL D(MAXOBS)
      REAL DGA(11)
      REAL DIST(10)
      REAL DP(MAXOBS)
      REAL H(MAXOBS)
      REAL HP(MAXOBS)
      REAL PEN1SI(24)
      REAL PEN2SI(24)
      REAL PEN3SI(24)
      REAL PENT1S(24)
      REAL PENT2S(24)
      REAL PENT3S(24)
      REAL SOBS(11)
      REAL TRAJ(32)
      REAL TRAJV(10)
      COMMON /OBST1/NOBST,KF,KCGT,KCGA,KCGL,IOBFTO,KOBS
      COMMON /OBST2/DIST,TRAJV,TRAJ,PENT2S,PEN2SI,VC1,AK1,AK2,H,D,TISA,
     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      REAL GAMXWP
      INTEGER IK1T
      INTEGER IK2T
      INTEGER IKVF
      INTEGER IKV1
      INTEGER IKV2
      REAL AERO(40)
      REAL COEF(40)
      REAL COEFP(40)
      REAL CVIT(80)
      REAL DTCA(21)
      REAL DTCD(21)
      REAL GAP(21)
      REAL GLD(21)
      REAL RAER(8)
      REAL RTFP(8)
      REAL RGLD(8)
      REAL TCGC(20)
      REAL TK1T(20)
      REAL TK2T(20)
      REAL TKV1(20)
      REAL TKVA(40)
      REAL TKVF(20)
      REAL TKVL(40)
      REAL TVQ(8)
      REAL VMU(20)
      REAL V2CP(20)
      REAL GLDA(21)
      REAL VMPE(30)
      REAL XTWD(40)
      COMMON /VAR1/IK1T,IK2T,IKVF,IKV1,IKV2
      COMMON /VAR2/COEF,DTCA,DTCD,AERO,CVIT,GAP,GLD,VMU,COEFP,TK2T,TKVF,
     +TKVA,TKVL,TVQ,TCGC,RGLD,RAER,RTFP,TKV1,TK1T,V2CP,VMPE,
     +XTWD,GAMXWP,GLDA
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      LOGICAL CHECK1
      LOGICAL CHECK2
      LOGICAL RWNXTT
      LOGICAL RWNXTL
      LOGICAL NXTPLT(MAXTTA,MAXVQ)
      LOGICAL NXTPL1(MAXTAL,MAXVQ)
      LOGICAL NXTPL2(MAXTAL,MAXVQ)
      COMMON /CTESL/CHECK1,CHECK2,RWNXTT,RWNXTL,NXTPLT,NXTPL1,NXTPL2
      REAL V1VR,W,Y
      INTEGER I1,IOD,J1,KFP
      REAL A
      REAL B
      REAL B1
      REAL C
      REAL CPMAX
      REAL DD
      REAL DET
      REAL DV
      REAL ERROR
      REAL F
      REAL F1
      REAL F2
      REAL F3
      REAL F4
      REAL F5
      REAL F6
      REAL G2PC
      REAL PINIT
      REAL RF
      REAL V1
      REAL V1RMIW
      REAL V1RMAW
      REAL V1SMA
      REAL V1VRIT
      REAL V2
      REAL VSAUV
      REAL WSAUV
      INTEGER I
      INTEGER I2
      INTEGER IB
      INTEGER IK
      INTEGER IKE
      INTEGER IOD1
      INTEGER IOD2
      INTEGER IOD3
      INTEGER ISAUV
      INTEGER ITER
      INTEGER J
      INTEGER JSAUV
      INTEGER KP
      INTEGER MOD
      REAL BIDON(5)
      REAL XL(3)
      REAL XN(3)
      INTEGER KE(4)
      REAL FINT
      EXTERNAL FINT
      EXTERNAL CONT,PIST,PV1MAX,PV1MIN,PVMCG,SV1MAX,V1FIX
      INTRINSIC ABS,AMIN1,AMAX1
      KFP = 0
      IF (IOD.EQ.13) THEN
      IF (RWNXTT) THEN
      BIDON(1) = AMAX1(V2VSMI,V2SMIL)
      BIDON(2) = AMIN1(V2VSMA,V2SMAL)
      ELSE
      BIDON(1) = V2VSMI
      BIDON(2) = V2VSMA
      END IF
      BIDON(3) = A9
      BIDON(4) = XMAS(1)
      BIDON(5) = XMAS(1) + DXM(1)
      END IF
      CPMAX = PMAX
      IOD2 = 0
      V1VRLP = A9
      P2PC = A9
      P9 = A9
      PMAXLP = A9
      IF (FV1VR.NE.0.) THEN
      KMCG = 0
      XN(2) = Y
      XN(3) = FV1VR
      IOD1 = IOD
      CALL V1FIX(XN,I2,IOD1)
      CALL PIST(8,XN(1),XVE(1),RF)
      F1 = VMCG - (RF*XN(3))
      IF (ABS(F1).GE..05.AND.F1.GT.0.)KMCG = 1
      IF (KMCG.EQ.1) THEN
      IF (V2VS.EQ.0..AND.KMU.EQ.0) THEN
      XN(1) = FINT(XN(2),BIDON(1),BIDON(4),1)
      END IF
      END IF
      IF (NOBST.NE.0.AND.IOD.EQ.3.AND.ZOUT(25).EQ.A9) THEN
      G2PC = (ZLIM(29)-COEF(10))/COEF(9)
      P2PC = FINT(G2PC,PENT2S(1),PENT2S(11),2)
      ZOUT(54) = P2PC*UP
      IF (P2PC.GT.AMIN1(PMAXLP,PTOD2)) ZOUT(54) = A9
      ZOUT(55) = A9
      END IF
      W = XN(1)
      IF (W.LE.PMIN) THEN
      IF (IATA.EQ.1) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT=10020)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10021)
      END IF
      KF = 1
      ELSE
      KFP = 1
      END IF
      END IF
      V1VR = XN(3)
      J1 = I2
      RETURN
      END IF
      PINIT = PINI
      IF (RWNXTT) THEN
      V1RMIW = AMAX1(V1VRMI,V1RMIL)
      V1RMAW = AMIN1(V1VRMA,V1RMAL)
      V1VRIT = (V1RMIW+V1RMAW)/2.
      ELSE
      V1VRIT = V1VRI
      V1RMIW = V1VRMI
      V1RMAW = V1VRMA
      END IF
      XL(2) = Y
      VSAUV = -99999999.
      IK = 0
      I = 3
      KP = 0
   20 CONTINUE
      WSAUV = 200000.
      IF (I.GT.4) GO TO 240
      J = COD - 1
   30 CONTINUE
      J = J + 1
      IF (J.NE.COD.AND.J.LT.9) J = 9
      IF (J.GE.NCONT+1) GO TO 230
   40 CONTINUE
      ITER = 0
      MOD = 0
      IF (J.GE.11) THEN
      PINIT = XL(1) - 2*DXM(1)
      V1VRIT = XL(3)
      IF (KP.EQ.1) THEN
      CALL PV1MAX(XL,9,B)
      IF (XL(1).GT.WSAUV) XL(1) = WSAUV
      IF (IOD2.EQ.1) XL(1) = AMIN1(P2PC,P9,PTOD2)
      CALL PV1MAX(XL,J,B)
      GO TO 200
      END IF
      END IF
      XL(1) = PINIT
      XL(3) = V1VRIT
      DO 60 IKE = 1,4
      KE(IKE) = 0
   60 CONTINUE
   70 CONTINUE
      IF (XL(1).GE.CPMAX) THEN
      XL(1) = CPMAX - DXM(1)
      MOD = 1
      KE(1) = KE(1) + 1
      END IF
      IF (XL(1).LE.PMIN) THEN
      XL(1) = PMIN + DXM(1)
      MOD = 1
      KE(2) = KE(2) + 1
      END IF
      IF (XL(3).GE.V1RMAW) THEN
      XL(3) = V1RMAW - DXM(3)
      MOD = 1
      KE(3) = KE(3) + 1
      END IF
      IF (XL(3).LE.V1RMIW) THEN
      XL(3) = V1RMIW + DXM(3)
      MOD = 1
      KE(4) = KE(4) + 1
      IF (KE(4).EQ.3) CALL PV1MIN(XL,I,B)
      IF (KE(4).EQ.3) GO TO 200
      END IF
      IF (KE(1).GE.KEMAX) THEN
      XL(1) = CPMAX
      GO TO 200
      ELSE IF (KE(2).GE.KEMAX) THEN
      XL(1) = PMIN
      GO TO 200
      ELSE IF (KE(3).GE.KEMAX) THEN
      XL(3) = V1RMAW
      GO TO 200
      ELSE IF (KE(3).GE.KEMAX) THEN
      XL(3) = V1RMIW
      GO TO 200
      END IF
      IF (MOD.LT.1) THEN
      DO 130 IKE = 1,4
      KE(IKE) = 0
  130 CONTINUE
      END IF
      MOD = 0
      CALL CONT(I,XL(1),F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  I,F1,XL '
      WRITE (NT6,FMT=*) I,F1,XL
      END IF
      CALL CONT(J,XL(1),F2)
      IF (KF.EQ.1) RETURN
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  J,F2,XL '
      WRITE (NT6,FMT=*) J,F2,XL
      END IF
      ERROR = E(I)*E(I)*F1*F1 + E(J)*E(J)*F2*F2
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  ERROR  '
      WRITE (NT6,FMT=*) ERROR
      END IF
      IF ((ERROR-EPSI*EPSI/5.).GT.0.) THEN
      XL(1) = XL(1) + DXM(1)
      CALL CONT(I,XL(1),F3)
      CALL CONT(J,XL(1),F4)
      XL(1) = XL(1) - DXM(1)
      XL(3) = XL(3) + DXM(3)
      CALL CONT(I,XL(1),F5)
      CALL CONT(J,XL(1),F6)
      XL(3) = XL(3) - DXM(3)
      IF (KF.EQ.1) RETURN
      A = (F3-F1)/DXM(1)
      B = (F5-F1)/DXM(3)
      C = (F4-F2)/DXM(1)
      DD = (F6-F2)/DXM(3)
      DET = A*DD - B*C
      IF (DET.EQ.0.) GO TO 200
      XL(1) = XL(1) + (-DD*F1+B*F2)/DET
      XL(3) = XL(3) + (C*F1-A*F2)/DET
      ITER = ITER + 1
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  ITER,XL '
      WRITE (NT6,FMT=*) ITER,XL
      ENDIF
      IF (KE(3).EQ.3) THEN
      IF (J.EQ.11) THEN
      CALL PV1MAX(XL,9,B)
      IF (XL(1).GT.WSAUV) XL(1) = WSAUV
      END IF
      IF (IOD2.EQ.1) XL(1) = AMIN1(P2PC,P9,PTOD2)
      CALL PV1MAX(XL(1),J,B)
      IF (J.EQ.9.OR.J.EQ.10) KP = 1
      GO TO 200
      END IF
      IF (K6.EQ.1) THEN
      IF (ITER.GE.ITERMA.AND.IOD.LE.3.AND.ERROR.GE..001)
     +WRITE (NT6,FMT=10000) TA,VENT,XL(2),I,J,ERROR
      END IF
      IF (ITER.GE.ITERMA) GO TO 200
      GO TO 70
      ELSE IF (XL(1).EQ.CPMAX-DXM(1)) THEN
      XL(1) = CPMAX
      CALL CONT(I,XL(1),F1)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  I,F1,XL '
      WRITE (NT6,FMT=*) I,F1,XL
      END IF
      CALL CONT(J,XL(1),F2)
      IF (KF.EQ.1) RETURN
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  J,F2,XL '
      WRITE (NT6,FMT=*) J,F2,XL
      END IF
      ERROR = E(I)*E(I)*F1*F1 + E(J)*E(J)*F2*F2
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  ERROR  '
      WRITE (NT6,FMT=*) ERROR
      END IF
      IF ((ERROR-EPSI*EPSI/5.).GT.0.) THEN
      XL(1) = CPMAX-DXM(1)
      END IF
      END IF
  200 CONTINUE
      IF (IOD.EQ.3.AND.I.EQ.3) THEN
      IF (J.EQ.9.OR.J.EQ.10) THEN
      PMAXLP = XL(1)
      V1VRLP = XL(3)
      PMAXP2 = XL(1)
      V1VRP2 = XL(3)
      ELSE IF (J.EQ.11) THEN
      ZOUT(54) = ZOUT(25)
      ZOUT(55) = ZOUT(26)
      END IF
      END IF
      IF (XL(1).LT.WSAUV) THEN
      WSAUV = XL(1)
      VSAUV = XL(3)
      JSAUV = J
      IF (KE(4).EQ.3) JSAUV = I
      ISAUV = I
      END IF
      IF (J.EQ.9.OR. (J.EQ.10.AND.NOBST.NE.0)) GO TO 220
      GO TO 30
  220 CONTINUE
      J = J + 1
      XL(1) = WSAUV
      XL(3) = VSAUV
      IOD3 = 0
      IF (J.EQ.11.AND.I.EQ.3.AND.IOD.EQ.3.AND.
     +XL(1).LT.AMIN1(PMAXLP,PTOD2)) THEN
      IOD3 = 1
      G2PC = (ZLIM(29)-COEF(10))/COEF(9)
      P2PC = FINT(G2PC,PENT2S(1),PENT2S(11),2)
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ///WMAXI/IOD3 XL P2PC PMAXLP PTOD2'
      WRITE (NT6,FMT=*) XL,P2PC,PMAXLP,PTOD2
      END IF
      XL(1) = AMIN1(PMAXLP,PTOD2)
      XL(3) = V1VRLP
      IF (P2PC.LT.AMIN1(PMAXLP,PTOD2)) THEN
      XL(1) = P2PC
      CALL SV1MAX(XL(1),V1SMA,3)
      IF (V1SMA.GT.XL(3)) XL(3) = V1SMA
      IOD2 = 1
      END IF
      END IF
      CALL CONT(J,XL(1),F)
      IF (KF.EQ.1) RETURN
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  J,F,XL '
      WRITE (NT6,FMT=*) J,F,XL
      END IF
      IF (E(J)*F.GE.EPSI) THEN
      IF (IOD3.EQ.1.AND.XL(3).GE.1.) THEN
      IOD3 = 0
      IF (P9.GT.CPMAX) P9 = P2S
      CALL PV1MAX(XL(1),J,B)
      GO TO 200
      ELSE
      IF (J.EQ.11.AND.I.EQ.3.AND.XL(3).GE.1.) THEN
      IF (P9.GT.CPMAX) P9 = P2S
      CALL PV1MAX(XL(1),J,B)
      GO TO 200
      ENDIF
      GOTO 40
      END IF
      END IF
      IF (J.EQ.10.AND.NOBST.NE.0) GO TO 220
      IF (J.EQ.11.AND.I.EQ.3.AND.IOD.EQ.3) THEN
      ZOUT(54) = P2PC*UP
      IF (P2PC.GT.AMIN1(PMAXLP,PTOD2)) ZOUT(54) = A9
      ZOUT(55) = A9
      END IF
  230 CONTINUE
      I = 4
      KP = 0
      IF (IK.EQ.1) GO TO 240
      IK = 1
      XL(1) = WSAUV
      XL(3) = VSAUV
      CALL CONT(I,XL(1),F)
      IF (KF.EQ.1) RETURN
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)') ' ***WMAXI***  J,F,XL '
      WRITE (NT6,FMT=*) J,F,XL
      END IF
      IF (E(I)*F.GE.EPSI) GO TO 20
  240 CONTINUE
      J1 = JSAUV
      I1 = ISAUV
      IB = 0
      KMCG = 0
      XL(1) = WSAUV
      XL(3) = VSAUV
  250 CONTINUE
      IF (IB.NE.0) CALL PVMCG(XL(1),I1,B1)
      IF (XL(3).GT.V1RMAW) KMCG = 1
      IF (KMCG.EQ.1) THEN
      IF (V2VS.EQ.0..AND.KMU.EQ.0) THEN
      XL(1) = FINT(XL(2),BIDON(1),BIDON(4),1)
      XL(3) = 1.
      END IF
      GO TO 260
      END IF
      CALL PIST(8,XL(1),XVE(1),RF)
      V1 = XL(3)*RF
      F1 = VMCG - V1
      IF (IB.EQ.0.AND.F1.LE.0.) GO TO 260
      IF (IB.EQ.0.AND.F1.GT.0..AND.J1.EQ.11.AND.XL(3).GE.V1RMAW) THEN
      IF (V2VS.EQ.0.) THEN
      KMCG = 1
      XL(1) = FINT(XL(2),BIDON(1),BIDON(4),1)
      GO TO 260
      ELSE
      KMCG = 1
      GO TO 260
      END IF
      END IF
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***WMAXI*** ITER VMCG V1 VR  XL    ,F1 ,KMCG'
      WRITE (NT6,FMT=*) IB,VMCG,V1,RF,XL,F1,KMCG
      END IF
      IF (ABS(F1).LE.0.05) THEN
      J1 = I1
      IF ((IOD.EQ.3).AND.(I.EQ.3)) THEN
      IF ((J.EQ.9).OR.(J.EQ.10)) THEN
      PMAXP2 = XL(1)
      V1VRP2 = XL(3)
      END IF
      END IF
      if (kmca.ne.0) then
      kmcag = 1
      end if
      I = 3
      CALL CONT(I,XL(1),F)
      IF (KF.EQ.1) RETURN
      IF (E(I)*F.GT.EPSI) THEN
      IF (CPMAX.EQ.XL(1)) THEN
      KFP = 1
      RETURN
      ELSE
      CPMAX = XL(1)
      GO TO 20
      END IF
      END IF
      I = 4
      CALL CONT(I,XL(1),F)
      IF (KF.EQ.1) RETURN
      IF (E(I)*F.GT.EPSI) THEN
      IF (CPMAX.EQ.XL(1)) THEN
      KFP = 1
      RETURN
      ELSE
      CPMAX = XL(1)
      GO TO 20
      END IF
      END IF
      GO TO 260
      END IF
      IF (IB.EQ.0) DV = V1RMAW - XL(3)
      IF (IB.GT.0.OR.DV.EQ.0.) DV = DXM(3)*10.
      XL(3) = XL(3) + DV
      CALL PVMCG(XL(1),I1,B1)
      CALL PIST(8,XL(1),XVE(1),RF)
      V2 = XL(3)*RF
      F2 = VMCG - V2
      IF (KS.EQ.1) THEN
      WRITE (NT6,FMT='(A)')
     +' ***WMAXI***  ITER VMCG V1 VR  XL   ,F2 ,KMCG'
      WRITE (NT6,FMT=*) IB,VMCG,V2,RF,XL,F2,KMCG
      END IF
      IF (F2.EQ.F1) THEN
      XL(3) = XL(3) + DV
      CALL PVMCG(XL(1),I1,B1)
      CALL PIST(8,XL(1),XVE(1),RF)
      V2 = XL(3)*RF
      F2 = VMCG - V2
      IF (F2.EQ.F1) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *****  BAD CONVERGENCE FOR VMCG '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'BAD CONVERGENCE FOR VMCG'
      END IF
      RETURN
      ELSE
      XL(3) = XL(3) - 2*DV
      XL(3) = XL(3) - 2*F1*DV/ (F2-F1)
      END IF
      ELSE
      XL(3) = XL(3) - DV
      XL(3) = XL(3) - F1*DV/ (F2-F1)
      END IF
      IF (XL(3).LT.VSAUV) XL(3) = VSAUV
      IB = IB + 1
      IF (IB.GT.6) THEN
      KF = 1
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' *****  BAD CONVERGENCE FOR VMCG '
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)') 'BAD CONVERGENCE FOR VMCG'
      END IF
      RETURN
      END IF
      GO TO 250
  260 CONTINUE
      WSAUV = XL(1)
      VSAUV = XL(3)
      V1VR = VSAUV
      W = WSAUV
      IF (W.GT.PMINF) W = PMINF
      IF (W.LE.PMIN) THEN
      IF (IATA.EQ.1) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT=10020)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT=10021)
      END IF
      KF = 1
      ELSE
      KFP = 1
      END IF
      END IF
      RETURN
10000 FORMAT (' BAD CONVERGENCE FOR : TEMP=',F6.2,' WIND=',F7.2,/,
     +' V2/VS=',F8.6,' CONT=',I3,3X,I3,3X,' ERROR=',F14.9,/)
10010 FORMAT (/,/,' *****  BAD CONVERGENCE FOR VMCG')
10020 FORMAT (' *** COMPUTATION ERROR *** MTOW LOWER THAN PMIN  ')
10021 FORMAT ('MTOW LOWER THAN PMIN')
      END
      SUBROUTINE ZFICB(
     +I,
     +TCAS1,
     +KJJ,
     +KER
     +)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      REAL A1
      REAL A2
      REAL A79
      REAL A9
      REAL PMINF
      REAL PSTL
      REAL PSTL1
      REAL PSTL2
      REAL PSTRUC
      REAL PU
      REAL TU
      REAL UH
      REAL UL
      REAL UP
      REAL EPSI
      REAL C3
      REAL HU
      INTEGER COD
      INTEGER DRYCHK
      INTEGER DRYCHL
      INTEGER IATA
      INTEGER IDLL
      INTEGER IMP
      INTEGER ITERMA
      INTEGER K1
      INTEGER K2
      INTEGER KEMAX
      INTEGER KISU
      INTEGER KPPM
      INTEGER KS
      INTEGER KS4
      INTEGER KSB
      INTEGER KSP
      INTEGER KST
      INTEGER KSU
      INTEGER KTAB1
      INTEGER KTAB2
      INTEGER KTAB3
      INTEGER KTABL
      INTEGER KV1MN
      INTEGER L1610
      INTEGER LA42
      INTEGER MICRO
      INTEGER MODE
      INTEGER OUTMOD
      INTEGER NCONT
      INTEGER KTR
      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      REAL TCAS
      INTEGER NPROND
      REAL PVMC(7)
      INTEGER IMCA(7)
      INTEGER IPRON(5)
      COMMON /TMBTN1/NPROND,IPRON,IMCA
      COMMON /TMBTN2/TCAS,PVMC
      REAL CODCAL
      REAL VQ0
      REAL ZG
      INTEGER KA
      INTEGER KODCAL
      INTEGER NTA
      INTEGER NVQT
      INTEGER NVQL
      REAL ASS(7)
      REAL PKG(7)
      REAL TTA(MAXTTA)
      REAL VQT(7)
      REAL VQL(7)
      REAL V1MOY(7)
      INTEGER IV1MB(7)
      INTEGER IV1MAX(7)
      INTEGER IV1MIN(7)
      INTEGER IV2(7)
      INTEGER IVMCA(7)
      INTEGER IVMCG(7)
      INTEGER IVR(7)
      INTEGER J1COD(7)
      INTEGER J2COD(7)
      COMMON /RESLA1/IV1MIN,IV1MAX,J1COD,J2COD,IVR,IV2,
     +KA,KODCAL,NVQT,NVQL,NTA,IVMCA,IVMCG,IV1MB
      COMMON /RESLA2/PKG,ASS,ZG,VQ0,VQT,VQL,V1MOY,TTA,CODCAL
      INTEGER IHSDMI
      REAL PRON(29)
      REAL RASS(28)
      REAL RPKG(29)
      REAL RPKGI(29)
      REAL RVMAX(28)
      REAL RVMIN(28)
      REAL RV2(28)
      REAL TAA(17)
      REAL ZPQNH(5)
      REAL RVMCA(MAXTTA)
      REAL RVMCG(MAXTTA)
      REAL TASS(MAXTTA,MAXVQ)
      REAL TPKG(MAXTTA,MAXVQ)
      REAL TTAI(MAXTTA)
      REAL TV2(MAXTTA,MAXVQ)
      REAL TVMAX(MAXTTA,MAXVQ)
      REAL TVMIN(MAXTTA,MAXVQ)
      REAL TVPKG(MAXTTA-1,MAXVQ)
      INTEGER IHSD1(MAXTTA-1,MAXVQ)
      INTEGER IHSD2(MAXTTA-1,MAXVQ)
      INTEGER ITMAX(MAXTTA,MAXVQ)
      INTEGER JJ1(MAXTTA,MAXVQ)
      INTEGER JJ2(MAXTTA,MAXVQ)
      INTEGER IT1(29)
      INTEGER IT2(29)
      INTEGER LJ1(29)
      INTEGER LJ2(29)
      INTEGER LV2(5)
      INTEGER LVMAX(5)
      INTEGER LVMIN(5)
      COMMON /RESLB1/LJ1,LJ2,LVMIN,LVMAX,LV2,IT1,IT2,JJ1,
     +JJ2,ITMAX,IHSD1,IHSD2,IHSDMI
      COMMON /RESLB2/PRON,TTAI,RPKG,RPKGI,RVMAX,RVMIN,RV2,RASS,
     +TAA,TPKG,TV2,TVMIN,TVMAX,TASS,TVPKG,ZPQNH,RVMCA,RVMCG
      REAL FLAPTO
      REAL QNH
      REAL SLATTO
      INTEGER NGRAD1
      INTEGER NGRAD2
      INTEGER NCT1
      INTEGER NCT4
      REAL TEMP(MAXTTA)
      INTEGER ICFA1(2)
      INTEGER ICFA2(2)
      INTEGER ICFL1(2)
      INTEGER ICFL2(2)
      INTEGER ICFTO(2)
      COMMON /CONFI1/ICFTO,ICFA1,ICFA2,ICFL1,ICFL2,NCT1,
     +NCT4,NGRAD1,NGRAD2
      COMMON /CONFI2/TEMP,QNH,SLATTO,FLAPTO
      REAL TCAS1
      INTEGER I,KER,KJJ
      REAL GRAD1
      REAL GRAD2
      REAL PREEL
      REAL TF
      REAL V2B
      REAL VMAX
      REAL VMIN
      INTEGER KB1
      INTEGER KB2
      INTEGER KJ
      INTEGER KJ1
      INTEGER KJM
      INTEGER KL
      INTEGER KL1
      INTEGER KLP
      INTEGER LK
      INTEGER LK1
      REAL AR,FINT
      EXTERNAL AR,FINT
      INTRINSIC ABS,AINT,IFIX
      KER = 0
      KB1 = 0
      KB2 = 0
      KLP = 0
      IF (TU.EQ.0.) TCAS1 = TCAS + .2
      IF (TU.EQ.1.) TCAS1 = (TCAS+.2)*1.8 + 32.
      DO 10 KL = 1,NTA
      RPKG(KL) = TPKG(KL,I)
      IF ((TPKG(KL,I).EQ.A9).AND.(KL.NE.1)) RPKG(KL) = RPKG(KL-1) - 1.
      RVMAX(KL) = TVMAX(KL,I)
      RVMIN(KL) = TVMIN(KL,I)
      RV2(KL) = TV2(KL,I)
      RASS(KL) = TASS(KL,I)
      LJ1(KL) = JJ1(KL,I)
      LJ2(KL) = JJ2(KL,I)
   10 CONTINUE
      DO 20 KL = 1,NPROND
      KLP = KL
      IF (RPKG(1).GT.PRON(KL)) GO TO 30
   20 CONTINUE
   30 CONTINUE
      KLP = KLP - 1
      DO 40 KL1 = 2,NTA
      IF (RPKG(KL1-1).GT.RPKG(KL1)) GO TO 50
      RPKG(KL1) = RPKG(KL1-1) - 1.
   40 CONTINUE
   50 CONTINUE
      DO 60 KL = 1,NTA
      RPKGI(KL) = RPKG(NTA-KL+1)
   60 CONTINUE
      RPKG(NTA+1) = 99999999.
      RPKGI(NTA+1) = 99999999.
      IF (NTA.LT.9.OR.I.NE.1) GO TO 80
      IF (ABS(RPKG(3)-PSTRUC).LT..001) GO TO 70
      GRAD1 = (RPKG(3)-RPKG(4))/ABS(TTA(4)-TTA(3))
      NGRAD1 = 10*IFIX(GRAD1*.08)
   70 CONTINUE
      IF (ABS(RPKG(4)-PSTRUC).LT..001) GO TO 80
      GRAD2 = (RPKG(4)-RPKG(8))/ABS(TTA(8)-TTA(4))
      NGRAD2 = 100*IFIX(GRAD2*.008)
   80 CONTINUE
      DO 130 KJ = 1,NPROND
      IF (IMCA(I).EQ.0) GO TO 100
      IF (PRON(KJ).GE.PVMC(I)) GO TO 100
      KJM = KJ
      DO 90 KJ1 = KJM,NPROND
      ITMAX(KJ1,I) = 1000
      JJ1(KJ1,I) = 1000
      JJ2(KJ1,I) = 1000
      TPKG(KJ1,I) = 1000.
      TVMAX(KJ1,I) = 1000.
      TVMIN(KJ1,I) = 1000.
      TASS(KJ1,I) = 1000.
      TV2(KJ1,I) = 1000.
   90 CONTINUE
      KER = 3
      RETURN
  100 CONTINUE
      TF = FINT(PRON(KJ),RPKGI(1),TTAI(1),1)
      IF (KF.EQ.1) THEN
      KER = 2
      RETURN
      END IF
      KJJ = KJ
      IF (TF.LT.TTA(1)) THEN
      ITMAX(KJ,I) = 1000
      JJ1(KJ,I) = 1000
      JJ2(KJ,I) = 1000
      TPKG(KJ,I) = 1000.
      TVMAX(KJ,I) = 1000.
      TVMIN(KJ,I) = 1000.
      TASS(KJ,I) = 1000.
      TV2(KJ,I) = 1000.
      IF (KJ.EQ.KLP) THEN
      TPKG(KJ,I) = (RPKG(1)-PRON(KJ))*.001
      ITMAX(KJ,I) = TTA(1)
      TVMAX(KJ,I) = AR(RVMAX(1))
      TVMIN(KJ,I) = AR(RVMIN(1))
      TV2(KJ,I) = AR(RV2(1))
      TASS(KJ,I) = RASS(1)
      JJ1(KJ,I) = LJ1(1)
      JJ2(KJ,I) = LJ2(1)
      END IF
      ELSE
      IF (TF.GT.TTA(NTA)) KB1 = KB1 + 1
      IF (KB1.GE.2) RETURN
      IF (KB1.EQ.1) TF = TTA(NTA)
      IF (TF.LT.0.) TF = TF - 1.
      IF (AINT(TF).EQ.AINT(TCAS1)) KB2 = 2
      IF (TF.GT.TCAS1) KB2 = KB2 + 1
      IF (KB2.EQ.1.AND.KJ.EQ.1) KB2 = 2
      IF (KB2.EQ.1) TF = TCAS1
      TF = AINT(TF)
      ITMAX(KJ,I) = TF
      PREEL = FINT(TF,TTA(1),RPKG(1),1)
      TPKG(KJ,I) = (PREEL-PRON(KJ))*.001
      VMAX = FINT(TF,TTA(1),RVMAX(1),1)
      TVMAX(KJ,I) = AR(VMAX)
      VMIN = FINT(TF,TTA(1),RVMIN(1),1)
      TVMIN(KJ,I) = AR(VMIN)
      V2B = FINT(TF,TTA(1),RV2(1),1)
      TV2(KJ,I) = AR(V2B)
      TASS(KJ,I) = FINT(TF,TTA(1),RASS(1),1)
      DO 110 LK = 1,NTA
      IF (TF.LT.TTA(LK)) GO TO 120
      LK1 = LK
  110 CONTINUE
  120 CONTINUE
      JJ1(KJ,I) = LJ1(LK1)
      JJ2(KJ,I) = LJ2(LK1)
      END IF
  130 CONTINUE
      KER = 3
      RETURN
      END
      SUBROUTINE ERROR1(
     +ATAB,
     +VTAB,
     +K6,
     +NT6,
     +NBERR,
     +ERRM,
     +MERR
     +)
      REAL VTAB
      INTEGER K6,MERR,NBERR,NT6
      CHARACTER*10 ATAB
      CHARACTER*80 ERRM(*)
      IF (K6.EQ.1) WRITE (NT6,10000) ATAB,VTAB
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10000) ATAB,VTAB
      END IF
      RETURN
10000 FORMAT (1X,'INPUT ERROR: ',A10,F3.0,
     +' NOT APPLICABLE FOR THIS A/C ','MODEL')
      END
      SUBROUTINE ERROR2(
     +ATAB,
     +K6,
     +NT6,
     +NBERR,
     +ERRM,
     +MERR
     +)
      INTEGER K6,MERR,NBERR,NT6
      CHARACTER*9 ATAB
      CHARACTER*80 ERRM(*)
      IF (K6.EQ.1) WRITE (NT6,10000) ATAB
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10000) ATAB
      END IF
      RETURN
10000 FORMAT (1X,'INPUT ERROR: ',A9,' NOT DEFINED - SEE USER''S MANUAL')
      END
      SUBROUTINE ERROR3(
     +ATAB1,
     +ATAB2,
     +K6,
     +NT6,
     +NBERR,
     +ERRM,
     +MERR
     +)
      INTEGER K6,MERR,NBERR,NT6
      CHARACTER*9 ATAB1,ATAB2
      CHARACTER*80 ERRM(*)
      IF (K6.EQ.1) WRITE (NT6,10000) ATAB1,ATAB2
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10000) ATAB1,ATAB2
      END IF
      RETURN
10000 FORMAT (1X,'INPUT ERROR: ','CONFLICT BETWEEN ',A9,' AND ',A9)
      END
      SUBROUTINE ERROR4(
     +ATAB,
