      IF (K6.EQ.1) WRITE (NT6,10000) ATAB,VTAB
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10000) ATAB,VTAB
      END IF
      RETURN
10000 FORMAT (1X,'INPUT ERROR: ',A10,F3.0,
     +' NOT VALID-SEE USER''S MANUAL')
      END
      SUBROUTINE ERROR5(
     +K6,
     +NT6,
     +NBERR,
     +ERRM,
     +MERR
     +)
      INTEGER K6,MERR,NBERR,NT6
      CHARACTER*80 ERRM(*)
      IF (K6.EQ.1) WRITE (NT6,10000)
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10000)
      END IF
      RETURN
10000 FORMAT (1X,'INPUT ERROR: TOO MANY EFFECTS ARE USED (5 MAXIMUM)')
      END
