      CHARACTER*20 REVNBR
      CHARACTER*20 RWYNBR
      CHARACTER*255 ACMDBI
      CHARACTER*255 MISCLA
      CHARACTER*132 COMENT(20)
      COMMON /TINPA/ACTYPE,ENGTYP,RATING,BRAKES,CERTIF,REVNBR,DATE,
     +DBOPTI,ACMDBI,APTIDT,RWYNBR,COMENT,MISCLA,FDCFGI
      LOGICAL LBOOST
      LOGICAL LBOOSL
      LOGICAL LCONF
      LOGICAL LRTO
      LOGICAL LDELBR
      LOGICAL LDELB2
      LOGICAL LDELBC
      LOGICAL LDELBN
      LOGICAL LDELBD
      COMMON /CONFIL/LCONF,LBOOST,LBOOSL,LRTO,LDELBR,LDELB2,LDELBC,
     +LDELBN,LDELBD
      INTEGER MA,MB
      REAL A9P20
      REAL DLP
      real zpt
      real qfe
      real pzm
      real ts
      real p0
      INTEGER I
      INTEGER IERR1
      INTEGER IERR2
      INTEGER IERR3
      INTEGER IPAS
      INTEGER IZCO
      INTEGER J
      INTEGER K
      INTEGER KER
      CHARACTER*2 LA
      CHARACTER*2 LF
      CHARACTER*2 LPA
      CHARACTER*2 LPF
      CHARACTER*9 PROG
      CHARACTER*10 TEXT
      EXTERNAL ERROR1,ERROR2,ERROR3,ERROR4,ERROR5,GETMTO,ICONF,INITA,
     +INITI,IPOPT,ISPIA
      INTRINSIC INT
      SAVE IPAS
      DATA IPAS/0/
      DATA LA,LF,LPA,LPF/'FT','M ','LB','KG'/
      data p0/10332.3/
      A79 = 9999999.
      KFI = 0
      CALL INITI(IZCODT,7,0)
      TLDA = 0.
      QLD = 2.
      DGA(11) = 99999999.
      KF = 0
      NVQT = 1
      NTA = 1
      TEMP(1) = 0.
      KS4 = 0
      KST = 0
      NAP1 = 0
      KAP1 = 0
      NAP2 = 0
      KAP2 = 0
      NLD1 = 0
      KLD1 = 0
      NLD2 = 0
      KLD2 = 0
      KTAB1 = 0
      KISU = 0
      NCONT = 10
      AP1G = 0.
      AP2G = 0.
      AP1K = 0.
      AP2K = 0.
      CLD1 = 0.
      CLD2 = 0.
      PMAXP2 = A9
      V1VRP2 = A9
      IVW = ' KT '
      IQ = 'HPA '
      ERFLAG = ' '
      DO 5 I=1,10
      WRITE (ERRMSG(I),'(80X)')
    5 CONTINUE
      A9P20 = 9.0E20
      IERR1 = 0
      IERR2 = 0
      IERR3 = 0
      IZCO = 1
      IF (POPT(21).NE.A9P20) THEN
      NT6 = INT(POPT(21))
      ELSE
      IF (POPT(20).EQ.1.) THEN
      ERFLAG = 'B'
      ERRMSG(1) = ' INPUT ERROR - TRACE OUTPUT FILE NOT DEFINED'
      KFI = 1
      RETURN
      END IF
      END IF
      IF (POPT(20).EQ.1..OR.POPT(20).EQ.0.) THEN
      K6 = INT(POPT(20))
      ELSE IF (POPT(20).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('POPT(20) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('POPT(20)= ',POPT(20),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (IPAS.EQ.0) THEN
      IF (K6.EQ.1) THEN
      IF (LW(NT6)) THEN
      WRITE (NT6,'(A1)') SDP
      ELSE
      LW(NT6) = .TRUE.
      END IF
      WRITE (NT6,FMT=10070) PROG,SCISSU,IDT1,IDT2,SDP
      END IF
      IPAS = 1
      END IF
      IF (UNIT(1).EQ.0.) THEN
      TU = 0.
      IT = 'DC'
      ELSE IF (UNIT(1).EQ.1.) THEN
      TU = 1.
      IT = 'DF'
c     ELSE IF ((UNIT(1).EQ.2.).OR. (UNIT(1).EQ.3.)) THEN
cC *  When 2. or 3. => Not applicable for this aircraft model
c     IERR2 = 1
c     CALL ERROR1('UNIT(1)=  ',UNIT(1),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (UNIT(1).EQ.2.) THEN
      TU = 0.
      IT = 'DC'
      ELSE IF (UNIT(1).EQ.3.) THEN
      TU = 1.
      IT = 'DF'
      ELSE IF (UNIT(1).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('UNIT(1)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('UNIT(1)=  ',UNIT(1),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (UNIT(2).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'UNIT(2)=  ',UNIT(2)
      END IF
      IF (UNIT(3).EQ.0.) THEN
      IF (UNIT(8).EQ.0.) A1 = 0.
      IF (UNIT(8).EQ.1.) A1 = 2.
      ELSE IF (UNIT(3).EQ.1.) THEN
      IF (UNIT(8).EQ.0.) A1 = 3.
      IF (UNIT(8).EQ.1.) A1 = 1.
      ELSE IF (UNIT(3).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('UNIT(3)=  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('UNIT(3)=  ',UNIT(3),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF ((UNIT(8).EQ.0.).OR. (UNIT(8).EQ.1.)) THEN
      CONTINUE
      ELSE IF (UNIT(8).EQ.2.) THEN
      IERR2 = 1
      CALL ERROR1('UNIT(8)=  ',UNIT(8),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (UNIT(8).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('UNIT(8)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('UNIT(8)=  ',UNIT(8),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (A1.EQ.0.) THEN
      IL = LF
      IP = LPF
      UP = 1000.
      UL = 1
      ELSE IF (A1.EQ.1.) THEN
      IL = LA
      IP = LPA
      UP = 2204.62
      UL = .3048
      ELSE IF (A1.EQ.2.) THEN
      IL = LF
      IP = LPA
      UP = 2204.62
      UL = 1.
      ELSE IF (A1.EQ.3.) THEN
      IL = LA
      IP = LPF
      UP = 1000.
      UL = .3048
      END IF
      IF (UNIT(4).EQ.0.) THEN
      IH = LF
      UH = 1./.3048
      ELSE IF (UNIT(4).EQ.1.) THEN
      IH = LA
      UH = 1.
      ELSE IF (UNIT(4).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('UNIT(4)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('UNIT(4)=  ',UNIT(4),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (UNIT(5).EQ.0.) THEN
      IERR2 = 1
      CALL ERROR1('UNIT(5)=  ',UNIT(5),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (UNIT(5).EQ.1.) THEN
      CONTINUE
      ELSE IF (UNIT(5).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('UNIT(5)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('UNIT(5)=  ',UNIT(5),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF ((UNIT(6).EQ.0.).OR. (UNIT(6).EQ.1.)) THEN
      PU = UNIT(6)
      ELSE IF (UNIT(6).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('UNIT(6)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('UNIT(6)=  ',UNIT(6),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (UNIT(7).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'UNIT(7)=  ',UNIT(7)
      END IF
      IF ((UNIT(9).EQ.0.).OR. (UNIT(9).EQ.1.).OR.
     +(UNIT(9).EQ.3.)) THEN
      IERR2 = 1
      CALL ERROR1('UNIT(9)=  ',UNIT(9),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (UNIT(9).EQ.2.) THEN
      CONTINUE
      ELSE IF (UNIT(9).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('UNIT(9)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('UNIT(9)=  ',UNIT(9),K6,NT6,NBERR,ERRM,MERR)
      END IF
      CALL IPOPT(IERR1,IERR2,IERR3,IZCO)
      CALL ICONF(IERR1,IERR2,IERR3,IZCO)
      CALL MELSRT(IZCODT,7)
      IF (RWYD(1).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('RWYD(1)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      ZG = RWYD(1)*UH
      IF (ZG.GT.8500.) THEN
      IALT = 2
      ELSE
      IALT = 1
      END IF
      END IF
      IF (XMET(4).EQ.0.) THEN
      IF (XMET(2).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('XMET(2) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      VQT(1) = XMET(2)
      VQT(2) = A79
      A2 = 3.
      CODCAL = 0.
      VQ0 = 1013.25
      IF (XMET(5).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('XMET(5) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      ZP = XMET(5)*UH
      END IF
      IWQ = IVW
      END IF
      ZG = ZP
      IF (ZG.GT.8500.) THEN
      IALT = 2
      ELSE
      IALT = 1
      END IF
      ELSE IF (XMET(4).EQ.1.) THEN
      IF (XMET(5).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('XMET(5) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      VQT(1) = XMET(5)
      VQT(2) = A79
      A2 = 4.
      CODCAL = 1.
      IF (XMET(2).EQ.A9P20) THEN
      IERR1 =1
      CALL ERROR2('XMET(2) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      VQ0 = XMET(2)
      END IF
      IWQ = IQ
      END IF
      ELSE IF (XMET(4).EQ.2.) THEN
      IERR2 = 1
      CALL ERROR1('XMET(4)=  ',XMET(4),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (XMET(1).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('XMET(1)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('XMET(4)=  ',XMET(4),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (XMET(1).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('XMET(1) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IF (UNIT(1).LE.1) THEN
      TTA(1) = XMET(1)
      TTA(2) = A79
      ELSE
      IF (XMET(4).EQ.0.) THEN
	     ZPT = XMET(5)*UH
      ELSE IF (UNIT(1).LE.3) THEN
      IF (PU.EQ.0.) THEN
      QFE = XMET(5)
      ELSE
      QFE = XMET(5)*33.8638
      END IF
      IF (ABS(QFE-1013.25).GT..005) THEN
      PZM = QFE*10.19715
      ZPT = ((1.- ((PZM/P0)** (1./AK2)))/AK1)/.3048
      ZPT = ZG + ZPT
      ELSE
      ZPT = ZG
      END IF
      END IF
      TS = 15. - .0065*ZPT*.3048
      IF (TU.EQ.1.) THEN
      TS = TS*1.8 + 32.
      END IF
      TTA(1) = TS + XMET(1)
      TTA(2) = A79
      END IF
      END IF
      IF (XMET(3).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'XMET(3)=  ',XMET(3)
      END IF
      IF (XMET(6).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'XMET(6)=  ',XMET(6)
      END IF
      IF (XMET(7).EQ.0.) THEN
      CONTINUE
      ELSE IF (XMET(7).EQ.1.) THEN
      IERR2 = 1
      CALL ERROR1('XMET(7)=  ',XMET(7),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (XMET(8).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'XMET(8)=  ',XMET(8)
      END IF
      IF (XMET(9).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'XMET(9)=  ',XMET(9)
      END IF
      IF (RWYD(2).EQ.0.) THEN
      TOR = RWYD(3)
      ASD = RWYD(4)
      TOD = RWYD(5)
      ELSE IF (RWYD(2).EQ.1.) THEN
      TOR = RWYD(3)
      TOD = RWYD(3) + RWYD(5)
      ASD = RWYD(3) + RWYD(4)
      ELSE IF (RWYD(2).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('RWYD(2)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('RWYD(2)=  ',RWYD(2),K6,NT6,NBERR,ERRM,MERR)
      END IF
      TORP = TOR
      ASDP = ASD
      TODP = TOD
      IF (RWYD(6).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('RWYD(6)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      PP = RWYD(6)
      END IF
      IF (RWYD(7).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'RWYD(7)=  ',RWYD(7)
      END IF
      IF (RWYD(8).EQ.0.) THEN
      CONTINUE
      ELSE IF (RWYD(8).EQ.1.) THEN
      IF (POPT(14).EQ.0.) THEN
      IF (AV.EQ.'ATRA') THEN
      NIGC = 15
      ELSE
      IERR2 = 1
      CALL ERROR1('RWYD(8)=  ',RWYD(8),K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE
      IERR1 = 1
      CALL ERROR3('RWYD(8)  ','POPT(14)  ',K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (RWYD(8).EQ.2.) THEN
      IERR2 = 1
      CALL ERROR1('RWYD(8)= ',RWYD(8),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (RWYD(8).EQ.3.) THEN
      IF (POPT(14).EQ.0.) THEN
      IF (AV.EQ.'ATRA') THEN
      NIGC = 10
      ELSE
      IERR2 = 1
      CALL ERROR1('RWYD(8)=  ',RWYD(8),K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE
      IERR1 = 1
      CALL ERROR3('RWYD(8)  ','POPT(14)  ',K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (RWYD(8).EQ.4.) THEN
      IF (POPT(14).EQ.0.) THEN
      IF (AV.EQ.'ATRA') THEN
      NIGC = 11
      ELSE
      IERR2 = 1
      CALL ERROR1('RWYD(8)=  ',RWYD(8),K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE
      IERR1 = 1
      CALL ERROR3('RWYD(8)  ','POPT(14)  ',K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (RWYD(8).EQ.5.) THEN
      IF (POPT(14).EQ.0.) THEN
      IF (AV.EQ.'ATRA') THEN
      NIGC = 12
      ELSE
      IERR2 = 1
      CALL ERROR1('RWYD(8)=  ',RWYD(8),K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE
      IERR1 = 1
      CALL ERROR3('RWYD(8)  ','POPT(14)  ',K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (RWYD(8).EQ.6.) THEN
      IF (POPT(14).EQ.0.) THEN
      IF (AV.EQ.'ATRA') THEN
      NIGC = 13
      ELSE
      IERR2 = 1
      CALL ERROR1('RWYD(8)=  ',RWYD(8),K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE
      IERR1 = 1
      CALL ERROR3('RWYD(8)  ','POPT(14)  ',K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (RWYD(8).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('RWYD(8)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('RWYD(8)=  ',RWYD(8),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (RWYD(9).NE.A9P20) THEN
      IF (RWYD(9).LE.1.AND.RWYD(9).GT.0.) THEN
      ASD = (ASD-AASD)*RWYD(9) + AASD
      ELSE
      IERR1 = 1
      CALL ERROR4('RWYD(9)=  ',RWYD(9),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (RWYD(10).NE.A9P20) THEN
      ASD = ASD + RWYD(10)
      ELSE
      CONTINUE
      END IF
      IF (AV.EQ.'ATRA') THEN
      IF (RWYD(11).NE.A9P20) THEN
      WIDTH = RWYD(11)
      ELSE
      WIDTH = 0.
      END IF
      WIDTHP = WIDTH
      END IF
      IF ((OBSD(1).GT.20.).OR. (OBSD(1).LT.0.)) THEN
      IERR1 = 1
      CALL ERROR4('OBSD(1)=  ',OBSD(1),K6,NT6,NBERR,ERRM,MERR)
      ELSE
      NOBST = INT(OBSD(1))
      END IF
      IF ((OBSD(2).EQ.0.).OR. (OBSD(2).EQ.1.)) THEN
      KOBS = INT(OBSD(2))
      ELSE IF (OBSD(2).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('OBSD(2)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('OBSD(2)=  ',OBSD(2),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (NOBST.NE.0) THEN
      NCONT = 11
      DO 10 J = 1,NOBST
      IF (OBSD(J*3).EQ.A9P20) THEN
      IERR1 = 1
      WRITE (TEXT,'(A5,I2,A2)') 'OBSD(',J*3,') '
      CALL ERROR2(TEXT,K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (OBSD(J*3+1).EQ.A9P20) THEN
      IERR1 = 1
      WRITE (TEXT,'(A5,I2,A2)') 'OBSD(',J*3+1,') '
      CALL ERROR2(TEXT,K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (KOBS.EQ.0) THEN
      D(J) = OBSD(J*3)
      H(J) = OBSD(J*3+1)*UH
      ELSE
      D(J) = OBSD(J*3)
      H(J) = OBSD(J*3+1)*UH
      D(J) = D(J) + TOR
      IF (A1.EQ.0..OR.A1.EQ.2.) THEN
      H(J) = H(J) + (TOR*PP)/30.48
      ELSE IF (A1.EQ.1..OR.A1.EQ.3.) THEN
      H(J) = H(J) + (TOR*PP)/100.
      END IF
      END IF
      IF (OBSD(J*3+2).NE.A9P20) THEN
      IERR3 = 1
      WRITE (TEXT,'(A5,I2,A2)') 'OBSD(',J*3+2,') '
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) TEXT,OBSD(J*3+2)
      END IF
      IF (D(J).LT.TOD) THEN
      IERR1 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) J
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10040) J
      END IF
      END IF
      D(J) = D(J)*UL
   10 CONTINUE
      END IF
      TOD = TOD*UL
      TOR = TOR*UL
      ASD = ASD*UL
      AASD = AASD*UL
      ATOD = ATOD*UL
      WIDTH = WIDTH*UL
      IF (NOBST.NE.0) THEN
      DO 20 J = 1,NOBST
      DLP = D(J) - TOD
      IF (DLP.LT.3.) TOD = D(J) - 3.
   20 CONTINUE
      END IF
      IF (FPTD(1).EQ.0.) THEN
      CONTINUE
      ELSE IF ((FPTD(1).EQ.1.).OR. (FPTD(1).EQ.2.)) THEN
      IERR2 = 1
      CALL ERROR1('FPTD(1)=  ',FPTD(1),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (FPTD(1).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('FPTD(1)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('FPTD(1)=  ',FPTD(1),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (FPTD(2).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(2)=  ',FPTD(2)
      END IF
      IF (FPTD(3).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(3)=  ',FPTD(3)
      END IF
      IF (FPTD(4).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(4)=  ',FPTD(4)
      END IF
      IF (FPTD(5).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(5)=  ',FPTD(5)
      END IF
      IF (FPTD(6).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(6)=  ',FPTD(6)
      END IF
      IF (FPTD(7).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(7)=  ',FPTD(7)
      END IF
      IF (FPTD(8).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(8)=  ',FPTD(8)
      END IF
      IF (FPTD(9).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(9)=  ',FPTD(9)
      END IF
      IF (FPTD(10).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(10)=  ',FPTD(10)
      END IF
      IF (FPTD(11).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(11)=  ',FPTD(11)
      END IF
      IF (FPTD(12).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(12)=  ',FPTD(12)
      END IF
      IF (FPTD(13).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(13)=  ',FPTD(13)
      END IF
      IF (FPTD(14).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(14)=  ',FPTD(14)
      END IF
      IF (FPTD(15).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(15)=  ',FPTD(15)
      END IF
      IF (FPTD(16).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10050) 'FPTD(16)=  ',FPTD(16)
      END IF
      CALL ISPIA(IERR1,IERR2,IERR3)
      CCERT = CERTIF(1:4)
      NPIST(1) = NBLAN
      K = 1
      DO 30 I = 2,6
      NPIST(I) = APTIDT(K:K+3)
      K = K + 4
   30 CONTINUE
      NPIST(7) = NBLAN
      K = 1
      DO 40 I = 1,2
      QFU(I) = RWYNBR(K:K+3)
      K = K + 4
   40 CONTINUE
      IF (LCONF) THEN
      IF (FDCFGI.EQ.'          ') THEN
      IERR1 = 1
      CALL ERROR2('FDCFGI',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      ACFTO = FDCFGI
      END IF
      ELSE
      IF (FDCFGI.NE.'          ') THEN
      IERR1 = 1
      CALL ERROR3('FDCFGI   ','CONF(1)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      CONTINUE
      END IF
      END IF
      IF (IERR3.EQ.1.AND.KFI.NE.6) THEN
      ERFLAG = 'F'
      KFI = 2
      END IF
      IF (IERR1.EQ.1.OR.IERR2.EQ.1) THEN
      ERFLAG = 'B'
      IF (K6.EQ.1) WRITE (NT6,FMT=10060) APTIDT,RWYNBR,ACMDBI
      KFI = 1
      END IF
      CALL GETMTO(NT11,KER)
      IF (KER.EQ.0) THEN
      CONTINUE
      ELSE IF (KER.EQ.1) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,'(A)')
     +'THERE IS NO MODULUS IN A/C DATA FILE ASSOCIATED WITH THE PROVIDED
     + CONFIGURATION'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),'(A)')
     +'THERE IS NO MODULUS IN A/C DATA FILE ASSOCIATED WITH THE PROVIDED
     + CONFIGURATION'
      END IF
      END IF
      KF = 1
      ELSE IF (KER.EQ.2) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,'(A)') 'PERFORMANCE DATA FILE CORRUPTED'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),'(A)') 'PERFORMANCE DATA FILE CORRUPTED'
      END IF
      END IF
      KF = 1
      ELSE IF (KER.EQ.3) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,'(A)')
     +'INPUT CONFIGURATION ARGUMENT FDCFGI NOT VALID'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),'(A)')
     +'INPUT CONFIGURATION ARGUMENT FDCFGI NOT VALID'
      END IF
      END IF
      KFI = 1
      END IF
      RETURN
10000 FORMAT (1X,'INPUT ERROR: ',A9,F3.0,' NOT VALID-SEE ',
     +'USER''S MANUAL')
10010 FORMAT (1X,'INPUT ERROR: ','CONFICT BETWEEN ',A9,' AND ',A9)
10020 FORMAT (1X,'INPUT ERROR: TOO MANY EFFECTS ARE USED (7 MAXIMUM)')
10030 FORMAT (1X,'INPUT ERROR: ',A9,F3.0,
     +' NOT APPLICABLE FOR THIS A/C ','MODEL')
10040 FORMAT (1X,
     +'INPUT ERROR: BAD OBSTACLE LOCATION FOR OBSTACLE NUMBER ',I2)
10050 FORMAT (1X,'*** WARNING *** ',A9,F12.5,' NOT USED FOR THIS A/C ',
     +'MODEL')
10060 FORMAT (1X,'*** THE LATTER MESSAGES ARE RELATED TO : ',/,1X,
     +'  - AIRPORT : ',A20,3X,'RUNWAY : ',A12,/,1X,
     +'  - AICRAFT : ',A60,/,/)
10070 FORMAT (20 (/),16X,47 ('*'),/,14X,47 ('*'),' *',/,14X,'*',45X,
     +'* *',/,14X,
     +'*   L O W  S P E E D  P E R F O R M A N C E   * *',/,14X,
     +'*',45X,'* *',/,14X,'*',19X,A9,17X,'* *',/,14X,'*',45X,
     +'* *',/,14X,
     +'*            TAKE OFF COMPUTATION             * *',/,14X,
     +'*         PROGRAM  ISSUE : ',A2,1X,A4,A4,8X,'* *',/,14X,
     +'*',45X,'* *',/,14X,47 ('*'),/,A1)
      END
      SUBROUTINE GETMTO(
     +NTINP,
     +KER
     +)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      INTEGER NBTOLI
      INTEGER FILVER
      COMMON /FILESC/NBTOLI,FILVER
      INTEGER DBRMOD
      INTEGER IBRACT
      INTEGER IBRAL1
      INTEGER IBRAL2
      INTEGER KAP1
      INTEGER KAP2
      INTEGER KLD1
      INTEGER KLD2
      INTEGER NAP1
      INTEGER NAP2
      INTEGER NEFFA
      INTEGER NEFFL
      INTEGER NEFFT
      INTEGER NIGC
      INTEGER NLD1
      INTEGER NLD2
      INTEGER IBOOSL
      INTEGER IBOOST
      INTEGER IRTO
      INTEGER IALT
      INTEGER IZRTO
      INTEGER RWSHFT
      REAL TBAMU
      REAL LBAMU1
      REAL LBAMU2
      INTEGER IGC(30)
      INTEGER IZCODA(5)
      INTEGER IZCODL(5)
      INTEGER IZCODT(7)
      COMMON /INP1/NIGC,IZCODT,NAP1,KAP1,NAP2,KAP2,IZCODA,NLD1,KLD1,
     +NLD2,KLD2,IZCODL,NEFFT,NEFFA,NEFFL,IGC,IBOOSL,IBOOST,IRTO,
     +IALT,IZRTO,IBRACT,IBRAL1,IBRAL2,RWSHFT,DBRMOD
      COMMON /INP2/TBAMU,LBAMU1,LBAMU2
      REAL CODCAL
      REAL VQ0
      REAL ZG
      INTEGER KA
      INTEGER KODCAL
      INTEGER NTA
      INTEGER NVQT
      INTEGER NVQL
      REAL ASS(7)
      REAL PKG(7)
      REAL TTA(MAXTTA)
      REAL VQT(7)
      REAL VQL(7)
      REAL V1MOY(7)
      INTEGER IV1MB(7)
      INTEGER IV1MAX(7)
      INTEGER IV1MIN(7)
      INTEGER IV2(7)
      INTEGER IVMCA(7)
      INTEGER IVMCG(7)
      INTEGER IVR(7)
      INTEGER J1COD(7)
      INTEGER J2COD(7)
      COMMON /RESLA1/IV1MIN,IV1MAX,J1COD,J2COD,IVR,IV2,
     +KA,KODCAL,NVQT,NVQL,NTA,IVMCA,IVMCG,IV1MB
      COMMON /RESLA2/PKG,ASS,ZG,VQ0,VQT,VQL,V1MOY,TTA,CODCAL
      CHARACTER SDP
      CHARACTER*4 CCERT
      CHARACTER*4 IETA
      CHARACTER*4 IH
      CHARACTER*4 IL
      CHARACTER*4 IP
      CHARACTER*4 IQ
      CHARACTER*4 IT
      CHARACTER*4 IV
      CHARACTER*4 IVW
      CHARACTER*4 IWQ
      CHARACTER*4 NBLAN
      CHARACTER*5 CGPL
      CHARACTER*5 CGPT
      CHARACTER*11 ISU
      CHARACTER*16 ZWID
      CHARACTER*21 ZWID2
      CHARACTER*4 BASL(10)
      CHARACTER*4 BAST(10)
      CHARACTER*4 CAR1(3)
      CHARACTER*4 CAR2(5)
      CHARACTER*4 CAR3(2)
      CHARACTER*4 CAR4(5)
      CHARACTER*4 CAR5(40)
      CHARACTER*4 CAR6(20)
      CHARACTER*4 CAR7(20)
      CHARACTER*4 CTIF(112)
      CHARACTER*4 IAC(5)
      CHARACTER*4 IAP(5)
      CHARACTER*4 ICTA(6)
      CHARACTER*4 ITO(5)
      CHARACTER*4 KOCA(40)
      CHARACTER*4 KOM1(12)
      CHARACTER*4 KOM11(20)
      CHARACTER*4 KOM12(20)
      CHARACTER*4 KOM13(12)
      CHARACTER*4 KOM14(12)
      CHARACTER*4 KOM15(12)
      CHARACTER*4 KOM16(12)
      CHARACTER*4 KOM2(12)
      CHARACTER*4 KOM3(216)
      CHARACTER*4 KOM4(80)
      CHARACTER*4 KOM4L(80)
      CHARACTER*4 KOM7(4)
      CHARACTER*4 KOM8(4)
      CHARACTER*4 KOMA(216)
      CHARACTER*4 KOML(216)
      CHARACTER*4 KOMP(32)
      CHARACTER*4 LTIT(2)
      CHARACTER*4 KOM5(4)
      CHARACTER*4 KOM6(4)
      CHARACTER*4 NDATE(3)
      CHARACTER*4 NPIST(7)
      CHARACTER*4 QFU(2)
      CHARACTER*4 REGU(14)
      COMMON /KOM/KOM1,KOM2,KOM3,KOM4,KOM5,KOM6,KOM7,KOMA,KOML,KOMP,
     +NBLAN,LTIT,NPIST,QFU,IL,IH,IP,IV,IT,IQ,IVW,IWQ,IETA,KOM8,
     +KOM11,KOM12,KOM13,KOM14,BAST,BASL,IAC,ITO,IAP,NDATE,ICTA,
     +SDP,CGPT,CGPL,ISU,KOM15,KOM16,CCERT,CTIF,REGU,KOCA,ZWID,
     +ZWID2,CAR1,CAR2,CAR3,CAR4,CAR5,CAR6,CAR7,KOM4L
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      LOGICAL LBOOST
      LOGICAL LBOOSL
      LOGICAL LCONF
      LOGICAL LRTO
      LOGICAL LDELBR
      LOGICAL LDELB2
      LOGICAL LDELBC
      LOGICAL LDELBN
      LOGICAL LDELBD
      COMMON /CONFIL/LCONF,LBOOST,LBOOSL,LRTO,LDELBR,LDELB2,LDELBC,
     +LDELBN,LDELBD
      CHARACTER CUNF
      CHARACTER*4 AV
      CHARACTER*5 CFA1
      CHARACTER*5 CFA2
      CHARACTER*5 CFL1
      CHARACTER*5 CFL2
      CHARACTER*5 CFTO
      CHARACTER*16 TEXAP1
      CHARACTER*16 TEXAP2
      CHARACTER*20 ACFAP
      CHARACTER*20 ACFLD
      CHARACTER*20 ACFTO
      CHARACTER*4 CFAP(3)
      CHARACTER*4 CFLD(3)
      COMMON /CONFIG/CUNF,CFTO,CFA1,CFA2,CFL1,CFL2,CFAP,CFLD,AV,TEXAP1,
     +TEXAP2,ACFTO,ACFAP,ACFLD
      REAL FLAPTO
      REAL QNH
      REAL SLATTO
      INTEGER NGRAD1
      INTEGER NGRAD2
      INTEGER NCT1
      INTEGER NCT4
      REAL TEMP(MAXTTA)
      INTEGER ICFA1(2)
      INTEGER ICFA2(2)
      INTEGER ICFL1(2)
      INTEGER ICFL2(2)
      INTEGER ICFTO(2)
      COMMON /CONFI1/ICFTO,ICFA1,ICFA2,ICFL1,ICFL2,NCT1,
     +NCT4,NGRAD1,NGRAD2
      COMMON /CONFI2/TEMP,QNH,SLATTO,FLAPTO
      INTEGER KER,NTINP
      CHARACTER*20 TIZLU(20)
      CHARACTER*20 LIZLU(20)
      INTEGER TFLAG(20,6)
      INTEGER LFLAG(20,6)
      LOGICAL FRTO(3,2)
      INTEGER P_POS
      INTEGER P_BOOS
      INTEGER P_RTO
      INTEGER P_ALTI
      INTEGER P_SLAT
      INTEGER P_FLAP
      INTEGER ISLAT
      INTEGER IFLAP
      INTEGER I
      INTEGER J
      INTEGER L
      INTEGER K
      INTEGER IPOS
      INTEGER NDCOM
      INTEGER NDTAB
      INTEGER NPODR
      INTEGER NTM
      INTEGER NLM
      INTEGER IALTI
      CHARACTER ABOOST
      CHARACTER ARTO
      CHARACTER ADUM
      CHARACTER*4 IBID
      CHARACTER*4 LAST
      CHARACTER*20 IZLU1
      CHARACTER*20 IZLU2
      CHARACTER*20 SFCFG
      LOGICAL FBOOST
      LOGICAL FBOOSL
      LOGICAL FFCFG
      LOGICAL FFBOOS
      LOGICAL FFALTI
      PARAMETER (P_POS=1,P_BOOS=2,P_RTO=3,P_ALTI=4,P_SLAT=5,P_FLAP=6)
      CHARACTER*20 UPPER
      EXTERNAL UPPER
      KER = 0
      FBOOST = .FALSE.
      FBOOSL = .FALSE.
      DO 2 I=1,2
      DO 1 J=1,2
      FRTO(I,J) = .FALSE.
    1 CONTINUE
    2 CONTINUE
      IF (FILVER.EQ.0) THEN
      IPOS = 1
      ELSE
      IPOS = 2
      END IF
      IF (IBOOST.EQ.2) THEN
      ABOOST = 'B'
      ELSE IF (IBOOST.EQ.3) THEN
      ABOOST = 'S'
      ELSE
      ABOOST = '-'
      END IF
      IF (IRTO.EQ.1) THEN
      ARTO = 'R'
      ELSE
      ARTO = '-'
      END IF
      IF (ZG.GT.8500.) THEN
      IALTI = 2
      ELSE
      IALTI = 1
      END IF
      IAC(1) = '    '
      K = 1
      L = 1
    5 CONTINUE
      READ (NTINP,FMT=10000,REC=IPOS) IZLU1,IZLU2,NDCOM,NDTAB,NPODR
      IF (IZLU2(1:3).EQ.'APP') THEN
      LIZLU(L) = IZLU2
      LFLAG(L,P_POS) = IPOS
      IF (IZLU2(7:7).EQ.'B') THEN
      LFLAG(L,P_BOOS) = 2
      FBOOSL = .TRUE.
      ELSE IF (IZLU2(7:7).EQ.'S') THEN
      LFLAG(L,P_BOOS) = 3
      FBOOSL = .TRUE.
      ELSE
      LFLAG(L,P_BOOS) = 1
      END IF
      READ (IZLU2(16:16),'(A1)') ADUM
      IF ((ADUM.GE.'0').AND.(ADUM.LE.'9')) THEN
      READ (ADUM,'(I1)') LFLAG(L,P_ALTI)
      ELSE
      READ (IZLU2(20:20),'(A1)') ADUM
      IF (ADUM.EQ.' ') THEN
      LFLAG(L,P_ALTI) = 1
      ELSE
      READ (IZLU2(20:20),'(I1)') LFLAG(L,P_ALTI)
      END IF
      END IF
      L = L + 1
      ELSE
      TIZLU(K) = IZLU2
      TFLAG(K,P_POS) = IPOS
      IF (IZLU2(1:1).EQ.'T') THEN
      READ (IZLU2(2:6),'(I2,1X,I2)',ERR=1040) TFLAG(K,P_SLAT),
     +TFLAG(K,P_FLAP)
      END IF
      IF (IZLU2(7:7).EQ.'B') THEN
      TFLAG(K,P_BOOS) = 2
      FBOOST = .TRUE.
      ELSE IF (IZLU2(7:7).EQ.'S') THEN
      TFLAG(K,P_BOOS) = 3
      FBOOST = .TRUE.
      ELSE
      TFLAG(K,P_BOOS) = 1
      END IF
      READ (IZLU2(16:16),'(A1)') ADUM
      IF ((ADUM.GE.'0').AND.(ADUM.LE.'9')) THEN
      READ (ADUM,'(I1)') TFLAG(K,P_ALTI)
      ELSE
      READ (IZLU2(20:20),'(A1)') ADUM
      IF (ADUM.EQ.' ') THEN
      TFLAG(K,P_ALTI) = 1
      ELSE
      READ (IZLU2(20:20),'(I1)') TFLAG(K,P_ALTI)
      END IF
      END IF
      IF (IZLU2(10:10).EQ.'R') THEN
      TFLAG(K,P_RTO) = 1
      FRTO(TFLAG(K,P_BOOS),TFLAG(K,P_ALTI)) = .TRUE.
      ELSE
      TFLAG(K,P_RTO) = 0
      END IF
      K = K + 1
      END IF
      IF (IAC(1).EQ.'    ') THEN
      READ (IZLU1,'(5A4)') (IAC(I),I=1,5)
      END IF
      IPOS = IPOS + NPODR
      READ (NTINP,FMT=10010,REC=IPOS) IBID,LAST
      IF (LAST.EQ.'LAST') GO TO 15
      IF (IBID.EQ.'END ') THEN
      IPOS = IPOS + 1
      GO TO 5
      ELSE
      GO TO 1040
      END IF
   15 CONTINUE
      NTM = K - 1
      NLM = L - 1
      IF (FBOOSL) THEN
      IF (.NOT.FBOOST) THEN
      IBOOSL = 1
      ELSE
      IBOOSL = IBOOST
      END IF
      ELSE
      IBOOSL = 0
      END IF
      IF (FBOOST) THEN
      IF (IBOOST.EQ.0) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,'(A)')
     +'CONF(56)= 0 NOT VALID FOR THIS AIRCRAFT FILE'
      END IF
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR+1
      ERRM(NBERR) = 'CONF(56)= 0 NOT VALID FOR THIS AIRCRAFT FILE'
      END IF
      GO TO 1030
      END IF
      ELSE
      IF (IBOOST.NE.0) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,'(A)')
     +'CONF(56)= 0 MANDATORY FOR THIS AIRCRAFT FILE'
      END IF
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR+1
      ERRM(NBERR) = 'CONF(56)= 0 MANDATORY FOR THIS AIRCRAFT FILE'
      END IF
      GO TO 1030
      END IF
      END IF
      IF (LCONF.AND.(ACFTO(1:1).NE.'C')) THEN
      SFCFG = UPPER(ACFTO,20)
      IF ((SFCFG(1:1).EQ.'S').AND.(SFCFG(4:4).EQ.'F')) THEN
      READ (SFCFG,'(1X,I2,1X,I2)',ERR=1030) ISLAT,IFLAP
      SLATTO = REAL(ISLAT)
      FLAPTO = REAL(IFLAP)
      ELSE IF ((SFCFG(1:1).EQ.'F').AND.(SFCFG(4:4).EQ.'S')) THEN
      READ (SFCFG,'(1X,I2,1X,I2)',ERR=1030) IFLAP,ISLAT
      SLATTO = REAL(ISLAT)
      FLAPTO = REAL(IFLAP)
      ELSE
      GOTO 1030
      END IF
      ELSE
      ISLAT = SLATTO
      IFLAP = FLAPTO
      END IF
      READ (LIZLU(1),'(5A4)') (IAP(I),I=1,5)
      DO 35 L=1,NLM
      IF (((LFLAG(L,P_BOOS).EQ.IBOOST).OR.(.NOT.FBOOSL)).AND.
     +(LFLAG(L,P_ALTI).EQ.IALTI))
     +THEN
      READ (LIZLU(L),'(5A4)') (IAP(I),I=1,5)
      GO TO 45
      END IF
   35 CONTINUE
   45 CONTINUE
      DO 55 K=1,NTM
      IF ((TFLAG(K,P_SLAT).EQ.ISLAT).AND.
     +(TFLAG(K,P_FLAP).EQ.IFLAP).AND.
     +((TFLAG(K,P_BOOS).EQ.IBOOST).OR.(.NOT.FBOOST)).AND.
     +((TFLAG(K,P_RTO).EQ.IRTO).OR.
     +(.NOT.FRTO(TFLAG(K,P_BOOS),TFLAG(K,P_ALTI)))).AND.
     +(TFLAG(K,P_ALTI).EQ.IALTI)) THEN
      READ (TIZLU(K),'(5A4)') (ITO(I),I=1,5)
      IF ((IRTO.NE.0).AND.FRTO(TFLAG(K,P_BOOS),TFLAG(K,P_ALTI)))
     +THEN
      IZCODT(IZRTO) = 0
      END IF
      GO TO 65
      END IF
   55 CONTINUE
      FFCFG = .TRUE.
      FFBOOS = .TRUE.
      FFALTI = .TRUE.
      DO 56 K=1,NTM
      IF ((TFLAG(K,P_SLAT).EQ.ISLAT).AND.
     +(TFLAG(K,P_FLAP).EQ.IFLAP)) THEN
      FFCFG = .FALSE.
      END IF
      IF (TFLAG(K,P_ALTI).EQ.IALTI) THEN
      FFALTI = .FALSE.
      END IF
   56 CONTINUE
      IF (FFCFG) THEN
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      ERRM(NBERR) =
     +'T/O CONFIGURATION NOT AVAILABLE IN PERFOMANCE DATA FILE'
      END IF
      END IF
      IF (FFALTI) THEN
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      ERRM(NBERR) =
     +'AIRPORT ALTITUDE NOT AVAILABLE IN PERFORMANCE DATA FILE'
      END IF
      END IF
      IF ((.NOT.FFCFG).AND.(.NOT.FFALTI)) THEN
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      ERRM(NBERR) =
     +'CHECK T/O CONFIGURATION, BOOST, RTO AND ALTITUDE RANGE'
      END IF
      END IF
      GO TO 1050
   65 CONTINUE
      RETURN
 1030 CONTINUE
      KER = 3
      RETURN
 1040 CONTINUE
      KER = 2
      RETURN
 1050 CONTINUE
      KER = 1
      RETURN
10000 FORMAT (A20,A20,20X,I2,4X,I4,4X,I6)
10010 FORMAT (2A4)
      END
      SUBROUTINE ICONF(
     +IERR1,
     +IERR2,
     +IERR3,
     +IZCO
     +)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      REAL CONF(200)
      REAL FPTD(200)
      REAL OBSD(200)
      REAL POPT(200)
      REAL RWYD(200)
      REAL SPIA(200)
      REAL SPIB(200)
      REAL SPIC(200)
      REAL UNIT(200)
      REAL XMET(200)
      COMMON /TINPN/POPT,CONF,XMET,RWYD,OBSD,FPTD,UNIT,SPIA,SPIB,SPIC
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
      INTEGER NT9
      INTEGER NTB(10)
      INTEGER NTBL(10)
      COMMON /TAPE/NT1,NT2,NT3,NT4,NT5,NT6,NT7,NT8,NT9,NT10,NT11,K6,NTB,
     +INTB,NTBL,NT1D,NT2D,NT3D,NT4D,NT8D
      INTEGER KFI
      INTEGER KFL
      INTEGER KFT
      INTEGER NBERR
      COMMON /ERRN/NBERR,KFI,KFL,KFT
      CHARACTER*80 ERRM(MERR)
      COMMON /ERRA/ERRM
      LOGICAL LBOOST
      LOGICAL LBOOSL
      LOGICAL LCONF
      LOGICAL LRTO
      LOGICAL LDELBR
      LOGICAL LDELB2
      LOGICAL LDELBC
      LOGICAL LDELBN
      LOGICAL LDELBD
      COMMON /CONFIL/LCONF,LBOOST,LBOOSL,LRTO,LDELBR,LDELB2,LDELBC,
     +LDELBN,LDELBD
      REAL FLAPTO
      REAL QNH
      REAL SLATTO
      INTEGER NGRAD1
      INTEGER NGRAD2
      INTEGER NCT1
      INTEGER NCT4
      REAL TEMP(MAXTTA)
      INTEGER ICFA1(2)
      INTEGER ICFA2(2)
      INTEGER ICFL1(2)
      INTEGER ICFL2(2)
      INTEGER ICFTO(2)
      COMMON /CONFI1/ICFTO,ICFA1,ICFA2,ICFL1,ICFL2,NCT1,
     +NCT4,NGRAD1,NGRAD2
      COMMON /CONFI2/TEMP,QNH,SLATTO,FLAPTO
      INTEGER DBRMOD
      INTEGER IBRACT
      INTEGER IBRAL1
      INTEGER IBRAL2
      INTEGER KAP1
      INTEGER KAP2
      INTEGER KLD1
      INTEGER KLD2
      INTEGER NAP1
      INTEGER NAP2
      INTEGER NEFFA
      INTEGER NEFFL
      INTEGER NEFFT
      INTEGER NIGC
      INTEGER NLD1
      INTEGER NLD2
      INTEGER IBOOSL
      INTEGER IBOOST
      INTEGER IRTO
      INTEGER IALT
      INTEGER IZRTO
      INTEGER RWSHFT
      REAL TBAMU
      REAL LBAMU1
      REAL LBAMU2
      INTEGER IGC(30)
      INTEGER IZCODA(5)
      INTEGER IZCODL(5)
      INTEGER IZCODT(7)
      COMMON /INP1/NIGC,IZCODT,NAP1,KAP1,NAP2,KAP2,IZCODA,NLD1,KLD1,
     +NLD2,KLD2,IZCODL,NEFFT,NEFFA,NEFFL,IGC,IBOOSL,IBOOST,IRTO,
     +IALT,IZRTO,IBRACT,IBRAL1,IBRAL2,RWSHFT,DBRMOD
      COMMON /INP2/TBAMU,LBAMU1,LBAMU2
      INTEGER IERR1,IERR2,IERR3,IZCO
      REAL A9P20
      EXTERNAL ERROR1,ERROR2,ERROR3,ERROR4,ERROR5
      A9P20 = 9.E20
      IF ((CONF(1).EQ.0.).OR. (CONF(1).EQ.2.).OR.
     +(CONF(1).EQ.3.)) THEN
      IERR2 = 1
      CALL ERROR1('CONF(1)=  ',CONF(1),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(1).EQ.1.) THEN
      LCONF = .FALSE.
      IF (CONF(2).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(2)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      SLATTO = CONF(2)
      END IF
      IF (CONF(3).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(3)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      FLAPTO = CONF(3)
      END IF
      ELSE IF (CONF(1).EQ.4.) THEN
      LCONF = .TRUE.
      IF (CONF(2).EQ.A9P20) THEN
      CONTINUE
      ELSE
      IERR1 = 1
      CALL ERROR3('CONF(2)  ','CONF(1)  ',K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(3).EQ.A9P20) THEN
      CONTINUE
      ELSE
      IERR1 = 1
      CALL ERROR3('CONF(3)  ','CONF(1)  ',K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(1).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(1)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(1)=  ',CONF(1),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF ((CONF(4).EQ.0.).OR. (CONF(4).EQ.3.).OR.
     +(CONF(4).EQ.4.)) THEN
      IERR2 = 1
      CALL ERROR1('CONF(4)=  ',CONF(4),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(4).EQ.1.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 7
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(4).EQ.2.) THEN
      CONTINUE
      ELSE IF (CONF(4).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(4)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(4)=  ',CONF(4),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(5).EQ.0.) THEN
      CONTINUE
      ELSE IF ((CONF(5).EQ.1.).OR. (CONF(5).EQ.2.).OR.
     +(CONF(5).EQ.3.).OR. (CONF(5).EQ.4.).OR.
     +(CONF(5).EQ.5.)) THEN
      IERR2 = 1
      CALL ERROR1('CONF(5)=  ',CONF(5),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(5).EQ.6) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 8
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(5).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(5)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(5)=  ',CONF(5),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(6).EQ.0.) THEN
      CONTINUE
      ELSE IF (CONF(6).EQ.2.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 36
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF ((CONF(6).EQ.1.).OR.(CONF(6).EQ.3.).OR.
     +(CONF(6).EQ.4.)) THEN
      IERR2 = 1
      CALL ERROR1('CONF(6)= ',CONF(6),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(6).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(6)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(6)=  ',CONF(6),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(7).EQ.0.) THEN
      CONTINUE
      ELSE IF (CONF(7).EQ.1.) THEN
      IERR2 = 1
      CALL ERROR1('CONF(7)=  ',CONF(7),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(7).EQ.2.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 13
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(7).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(7)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(7)=  ',CONF(7),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(8).EQ.0) THEN
      IF (POPT(14).EQ.0.) THEN
      CONTINUE
      ELSE
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 16
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      ELSE IF (CONF(8).EQ.1.) THEN
      CONTINUE
      ELSE IF ((CONF(8).EQ.2.).OR. (CONF(8).EQ.3.)) THEN
      IERR2 = 1
      CALL ERROR1('CONF(8)=  ',CONF(8),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(8).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(8)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(8)=  ',CONF(8),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(9).EQ.0.) THEN
      CONTINUE
      ELSE IF (CONF(9).EQ.1.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 35
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF ((CONF(9).EQ.2.).OR. (CONF(9).EQ.3.).OR.
     +(CONF(9).EQ.4.).OR. (CONF(9).EQ.5.).OR.
     +(CONF(9).EQ.6.).OR. (CONF(9).EQ.7.)) THEN
      IERR2 = 1
      CALL ERROR1('CONF(9)=  ',CONF(9),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(9).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(9)  ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(9)=  ',CONF(9),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(10).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(10)= ',CONF(10)
      END IF
      IF (CONF(11).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(11)= ',CONF(11)
      END IF
      IF (CONF(12).EQ.0.) THEN
      CONTINUE
      ELSE IF (CONF(12).EQ.1) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 9
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.2) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 11
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.3) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 12
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.4) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 17
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.5) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 18
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.6) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 24
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.7) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 25
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.8) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 26
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.9.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 33
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(12).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(12) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(12)= ',CONF(12),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(13).NE.A9P20) THEN
      IERR3 = 1
      CALL ERROR1('CONF(13)= ',CONF(13),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(14).EQ.0.) THEN
      CONTINUE
      ELSE IF (CONF(14).EQ.1.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 14
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(14).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(14) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(14)= ',CONF(14),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(15).EQ.0.) THEN
      CONTINUE
      ELSEIF (CONF(15).EQ.1.) THEN
      IERR2 = 1
      CALL ERROR1('CONF(15)= ',CONF(15),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(15).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(15) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(15)= ',CONF(15),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(16).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(16)=',CONF(16)
      END IF
      IF (CONF(17).EQ.0.) THEN
      CONTINUE
      ELSE IF (CONF(17).EQ.1.) THEN
      IERR2 = 1
      CALL ERROR1('CONF(17)= ',CONF(17),K6,NT6,NBERR,ERRM,MERR)
      ELSE IF (CONF(17).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(17) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(17)= ',CONF(17),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(18).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(18)= ',CONF(18)
      END IF
      IF (CONF(19).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(19)= ',CONF(19)
      END IF
      IF ((CONF(20).EQ.0.)) THEN
      CONTINUE
      ELSE IF ((CONF(20).EQ.1.).OR. (CONF(20).EQ.3.)) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 34
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(20).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(20) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(20)= ',CONF(20),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(21).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(21)= ',CONF(21)
      END IF
      IF (CONF(22).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(22)= ',CONF(22)
      END IF
      IF (CONF(23).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(23)= ',CONF(23)
      END IF
      IF (CONF(24).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(24)= ',CONF(24)
      END IF
      IF (CONF(25).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(25)= ',CONF(25)
      END IF
      IF (CONF(26).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(26)= ',CONF(26)
      END IF
      IF (CONF(27).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(27)= ',CONF(27)
      END IF
      IF (CONF(28).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(28)= ',CONF(28)
      END IF
      IF (CONF(29).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(29)= ',CONF(29)
      END IF
      IF (CONF(29).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(29)= ',CONF(29)
      END IF
      IF (CONF(29).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(29)= ',CONF(29)
      END IF
      IF (CONF(32).EQ.0.) THEN
      CONTINUE
      ELSE IF (CONF(32).EQ.1.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 27
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(32).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(32) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(32)= ',CONF(32),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(33).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(33)= ',CONF(33)
      END IF
      IF (CONF(34).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(34)= ',CONF(34)
      END IF
      IF (CONF(35).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(35)= ',CONF(35)
      END IF
      IF (CONF(36).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(36)= ',CONF(36)
      END IF
      IF (CONF(37).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(37)= ',CONF(37)
      END IF
      IF (CONF(38).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'CONF(38)= ',CONF(38)
      END IF
      IF (CONF(54).EQ.0.) THEN
      CONTINUE
      ELSE IF (CONF(54).EQ.1.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 28
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(54).EQ.2.) THEN
      IF (IZCO.LE.7) THEN
      IZCODT(IZCO) = 29
      IZCO = IZCO + 1
      ELSE
