      CALL ERROR4('CONF(54)= ',CONF(54),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(55).EQ.0.) THEN
      IRTO = 0
      IZRTO = 0
      ELSE IF (CONF(55).EQ.1.) THEN
      IRTO = 1
      IF (IZCO.LE.7) THEN
      IZRTO = IZCO
      IZCODT(IZCO) = 37
      IZCO = IZCO + 1
      ELSE
      IERR1 = 1
      CALL ERROR5(K6,NT6,NBERR,ERRM,MERR)
      END IF
      ELSE IF (CONF(55).EQ.A9P20) THEN
