      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(55)= ',CONF(55),K6,NT6,NBERR,ERRM,MERR)
      END IF
      IF (CONF(56).EQ.0.) THEN
      IBOOST = 0
      ELSE IF (CONF(56).EQ.1.) THEN
      IBOOST = 1
      ELSE IF (CONF(56).EQ.2.) THEN
      IBOOST = 2
      ELSE IF (CONF(56).EQ.3.) THEN
      IBOOST = 3
      ELSE IF (CONF(56).EQ.A9P20) THEN
      IERR1 = 1
      CALL ERROR2('CONF(56) ',K6,NT6,NBERR,ERRM,MERR)
      ELSE
      IERR1 = 1
      CALL ERROR4('CONF(56)= ',CONF(56),K6,NT6,NBERR,ERRM,MERR)
      END IF
      RETURN
10000 FORMAT (1X,'INPUT ERROR: ',A9,F3.0,' NOT VALID-SEE ',
     +'USER''S MANUAL')
10010 FORMAT (1X,'INPUT ERROR: ','CONFLICT BETWEEN ',A9,' AND ',A9)
10020 FORMAT (1X,'INPUT ERROR: TOO MANY EFFECTS ARE USED (7 MAXIMUM)')
10030 FORMAT (1X,'INPUT ERROR: ',A9,F3.0,
     +' NOT APPLICABLE FOR THIS A/C ','MODEL')
10040 FORMAT (1X,'*** WARNING *** ',A9,F12.5,' NOT USED FOR THIS A/C ',
     +'MODEL')
      END
      SUBROUTINE INIOUT
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
