     +TA,ZP,PP,TOR,ASD,TOD,VENT,DGA,V2VS,
     +PENT3S,PEN3SI,PENT1S,PEN1SI,WIDTH,DP,HP,SOBS
      CHARACTER*20 ERFLAG
      CHARACTER*20 MMDATE
      CHARACTER*20 MMIDNT
      CHARACTER*255 ACMDBO
      CHARACTER*80 ERRMSG(20)
      CHARACTER*80 OUTMIS(20)
      COMMON /TOUTA/ERFLAG,ERRMSG,MMIDNT,MMDATE,ACMDBO,OUTMIS
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
