      CHARACTER*20 APTIDT
      CHARACTER*20 BRAKES
      CHARACTER*20 CERTIF
      CHARACTER*20 DATE
      CHARACTER*20 DBOPTI
      CHARACTER*20 ENGTYP
      CHARACTER*20 FDCFGI
      CHARACTER*20 RATING
      CHARACTER*20 REVNBR
      CHARACTER*20 RWYNBR
      CHARACTER*255 ACMDBI
      CHARACTER*255 MISCLA
      CHARACTER*132 COMENT(20)
      COMMON /TINPA/ACTYPE,ENGTYP,RATING,BRAKES,CERTIF,REVNBR,DATE,
     +DBOPTI,ACMDBI,APTIDT,RWYNBR,COMENT,MISCLA,FDCFGI
      REAL CONF(200)
