      REAL OBSD(200)
      REAL POPT(200)
      REAL RWYD(200)
      REAL SPIA(200)
      REAL SPIB(200)
      REAL SPIC(200)
      REAL UNIT(200)
      REAL XMET(200)
      COMMON /TINPN/POPT,CONF,XMET,RWYD,OBSD,FPTD,UNIT,SPIA,SPIB,SPIC
      CHARACTER CUNF
      CHARACTER*4 AV
      CHARACTER*5 CFA1
      CHARACTER*5 CFA2
      CHARACTER*5 CFL1
      CHARACTER*5 CFL2
      CHARACTER*5 CFTO
      CHARACTER*16 TEXAP1
      CHARACTER*16 TEXAP2
      CHARACTER*20 ACFAP
      CHARACTER*20 ACFLD
      CHARACTER*20 ACFTO
      CHARACTER*4 CFAP(3)
      CHARACTER*4 CFLD(3)
      COMMON /CONFIG/CUNF,CFTO,CFA1,CFA2,CFL1,CFL2,CFAP,CFLD,AV,TEXAP1,
     +TEXAP2,ACFTO,ACFAP,ACFLD
      CHARACTER*2 SCISSU
      COMMON /SCPVER/SCISSU
      CHARACTER*4 IDT1
      CHARACTER*4 IDT2
      CHARACTER*4 ISSU
      COMMON /VERSIO/ISSU,IDT1,IDT2
      REAL AASDP
      REAL ASDMBA
      REAL ASDP
      REAL ATODP
      REAL P2PC
      REAL P2S
      REAL PMAXLP
      REAL PMAXP2
      REAL PTOD2
