      REAL V1VRP2
      REAL V21
      REAL V2P
      REAL VOPTP
      REAL VQP
      REAL VRP
      REAL WIDTHP
      REAL ZGP
      INTEGER IPP
      REAL XLP(3)
      REAL ZOUL1(60)
      REAL ZOUL2(60)
      REAL ZOUT(60)
      REAL ZOUTE(20)
      REAL ZOUTS(60)
      COMMON /SPOUT1/IPP
      COMMON /SPOUT2/ZOUT,XLP,VQP,VRP,V1MAXP,V1MINP,V1VRP,V2P,VOPTP,
     +V1VRLP,PMAXLP,TORP,ASDP,TODP,P2S,V21,AASDP,ATODP,PTOR2,
     +PTOD2,P2PC,ZOUL1,ZOUL2,WIDTHP,ZGP,ZOUTE,PMAXP2,V1VRP2,ZOUTS
     +,V1VRMB,V1MBAL,ASDMBA,TODMBA,TORMBA
      REAL A1
      REAL A2
      REAL A79
      REAL A9
      REAL PMINF
      REAL PSTL
      REAL PSTL1
      REAL PSTL2
      REAL PSTRUC
      REAL PU
      REAL TU
      REAL UH
      REAL UL
      REAL UP
      REAL EPSI
      REAL C3
      REAL HU
      INTEGER COD
      INTEGER DRYCHK
      INTEGER DRYCHL
      INTEGER IATA
      INTEGER IDLL
      INTEGER IMP
      INTEGER ITERMA
      INTEGER K1
      INTEGER K2
      INTEGER KEMAX
      INTEGER KISU
      INTEGER KPPM
      INTEGER KS
      INTEGER KS4
      INTEGER KSB
      INTEGER KSP
      INTEGER KST
      INTEGER KSU
      INTEGER KTAB1
      INTEGER KTAB2
      INTEGER KTAB3
      INTEGER KTABL
      INTEGER KV1MN
      INTEGER L1610
      INTEGER LA42
      INTEGER MICRO
      INTEGER MODE
      INTEGER OUTMOD
      INTEGER NCONT
      INTEGER KTR
      INTEGER KTJ
      INTEGER KMO
      INTEGER KTPA
      INTEGER NLCT
      INTEGER NCCT
      INTEGER NTPU
      LOGICAL LJALAC
      REAL DXM(3)
      REAL E(25)
      REAL PMFTO(19)
      COMMON /CTES1/LJALAC
      COMMON /CTES2/ITERMA,COD,K1,KS,K2,NCONT,KEMAX,KSP,KST,KTR,KS4,KTJ,
     +KSB,KPPM,MODE,KMO,KTPA,KTAB3,KTAB2,KTAB1,
     +KISU,MICRO,L1610,KV1MN,IATA,LA42,NLCT,NCCT,NTPU,IMP,IDLL,
     +DRYCHK,DRYCHL,KTABL,OUTMOD,KSU
      COMMON /CTES3/EPSI,PMINF,E,DXM,PSTRUC,C3,A1,A2,A9,UH,UL,UP,PMFTO,
     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      INTEGER ISLC1A
      INTEGER ISLC2A
      INTEGER ISLC1I
      INTEGER ISLC2I
      COMMON /XSCAP/ISLC1A,ISLC2A,ISLC1I,ISLC2I
      REAL GAMXWP
      INTEGER IK1T
      INTEGER IK2T
      INTEGER IKVF
      INTEGER IKV1
      INTEGER IKV2
      REAL AERO(40)
      REAL COEF(40)
      REAL COEFP(40)
      REAL CVIT(80)
      REAL DTCA(21)
      REAL DTCD(21)
      REAL GAP(21)
      REAL GLD(21)
      REAL RAER(8)
      REAL RTFP(8)
      REAL RGLD(8)
      REAL TCGC(20)
      REAL TK1T(20)
      REAL TK2T(20)
      REAL TKV1(20)
      REAL TKVA(40)
      REAL TKVF(20)
      REAL TKVL(40)
      REAL TVQ(8)
      REAL VMU(20)
      REAL V2CP(20)
      REAL GLDA(21)
      REAL VMPE(30)
      REAL XTWD(40)
      COMMON /VAR1/IK1T,IK2T,IKVF,IKV1,IKV2
      COMMON /VAR2/COEF,DTCA,DTCD,AERO,CVIT,GAP,GLD,VMU,COEFP,TK2T,TKVF,
     +TKVA,TKVL,TVQ,TCGC,RGLD,RAER,RTFP,TKV1,TK1T,V2CP,VMPE,
     +XTWD,GAMXWP,GLDA
      REAL A9P20
      INTEGER I
      A9P20 = 9.E20
      DO 10 I = 1,60
      CLIMIT(I) = A9P20
   10 CONTINUE
      DO 20 I = 1,40
      RWYSEG(I) = A9P20
   20 CONTINUE
      DO 30 I = 1,14
      FIRSEG(I) = A9P20
   30 CONTINUE
      DO 40 I = 1,20
      SECSEG(I) = A9P20
   40 CONTINUE
      DO 50 I = 1,20
      ACCSEG(I) = A9P20
   50 CONTINUE
      DO 60 I = 1,21
      FINSEG(I) = A9P20
   60 CONTINUE
      DO 70 I = 1,16
      OBSLIM(I) = A9P20
   70 CONTINUE
      DO 80 I = 1,18
      TRNDAT(I) = A9P20
   80 CONTINUE
      DO 90 I = 1,100
      SPOUTA(I) = A9P20
   90 CONTINUE
      IF (KMCA.NE.0) THEN
      KFI = 3
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      ERRM(NBERR) = 'VMCA LIMITATION - TAKE OFF NOT ALLOWED'
      END IF
      END IF
      IF (KMCG.NE.0) THEN
      KFI = 3
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      ERRM(NBERR) = 'VMCG LIMITATION - TAKE OFF NOT ALLOWED'
      END IF
      END IF
      IF ((V2VS.NE.0.).AND. (KMU.EQ.1)) THEN
      KFI = 4
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      ERRM(NBERR) =
     +'VMU LIMITATION - FIXED V2/VS HAS BEEN INCREASED'
      END IF
      END IF
      IF ((KF.EQ.0).AND.(KFI.EQ.0)) THEN
      ERFLAG = 'A'
      ELSE IF ((KF.EQ.0).AND.(KFI.EQ.1)) THEN
      ERFLAG = 'B'
      ELSE IF ((KF.EQ.0).AND.(KFI.EQ.2)) THEN
      ERFLAG = 'F'
      ELSE IF ((KF.EQ.0).AND.(KFI.EQ.3)) THEN
      ERFLAG = 'E'
      ELSE IF ((KF.EQ.0).AND.(KFI.EQ.4)) THEN
      ERFLAG = 'D'
      ELSE IF ((KF.EQ.0).AND.(KFI.EQ.5)) THEN
      ERFLAG = 'G'
      ELSE IF (KF.EQ.1) THEN
      ERFLAG = 'C'
      END IF
      IF (ERFLAG.EQ.'F') THEN
      IF (K6.EQ.1) WRITE (NT6,FMT=10000) APTIDT,RWYNBR,ACMDBI
      END IF
      DO 100 I=1,10
      ERRMSG(I) = ERRM(I)
  100 CONTINUE
      IF (AV.EQ.'A3BA') THEN
      MMIDNT = '        ATAM        '
      ELSE IF (AV.EQ.'ATRA') THEN
      MMIDNT = '        TTAM        '
      ELSE IF (AV.EQ.'A3BB') THEN
      MMIDNT = '        ATAMB       '
      ELSE
      CONTINUE
      END IF
      IF (AV.EQ.'A3BA') THEN
      MMDATE = '    G1/J   APR.99   '
      ELSE IF (AV.EQ.'ATRA') THEN
      MMDATE = '   '//SCISSU//'/'//ISSU//IDT1//IDT2//'  '
      ELSE IF (AV.EQ.'A3BB') THEN
      MMDATE = '     A/E   AUG.92   '
      ELSE
      CONTINUE
      END IF
