      SUBROUTINE ISPIA(
     +IERR1,
     +IERR2,
     +IERR3
     +)
      INTEGER JASHFT
      INTEGER MERR
      INTEGER MAXTTA
      INTEGER MAXTAL
      INTEGER MAXVQ
      INTEGER MAXOBS
      INTEGER MAXFOB
      INTEGER MXTAV1
      INTEGER MXTAV2
      INTEGER MXTALV
      PARAMETER (MERR = 20,MAXOBS=25,MAXFOB=MAXOBS*5,JASHFT=50)
      PARAMETER (MAXTTA=41,MAXTAL=29,MAXVQ=5)
      PARAMETER (MXTAV1=(MAXTTA-1)*MAXVQ)
      PARAMETER (MXTAV2=MAXTTA*MAXVQ)
      PARAMETER (MXTALV=MAXTAL*MAXVQ)
      REAL CONF(200)
      REAL FPTD(200)
      REAL OBSD(200)
      REAL POPT(200)
      REAL RWYD(200)
      REAL SPIA(200)
      REAL SPIB(200)
      REAL SPIC(200)
      REAL UNIT(200)
      REAL XMET(200)
      COMMON /TINPN/POPT,CONF,XMET,RWYD,OBSD,FPTD,UNIT,SPIA,SPIB,SPIC
      REAL GAMXWP
      INTEGER IK1T
      INTEGER IK2T
