      REAL V2CP(20)
      REAL GLDA(21)
      REAL VMPE(30)
      REAL XTWD(40)
      COMMON /VAR1/IK1T,IK2T,IKVF,IKV1,IKV2
      COMMON /VAR2/COEF,DTCA,DTCD,AERO,CVIT,GAP,GLD,VMU,COEFP,TK2T,TKVF,
     +TKVA,TKVL,TVQ,TCGC,RGLD,RAER,RTFP,TKV1,TK1T,V2CP,VMPE,
     +XTWD,GAMXWP,GLDA
      INTEGER INTB
      INTEGER K6
      INTEGER NT1
      INTEGER NT10
      INTEGER NT11
      INTEGER NT1D
      INTEGER NT2
      INTEGER NT2D
      INTEGER NT3
      INTEGER NT3D
      INTEGER NT4
      INTEGER NT4D
      INTEGER NT5
      INTEGER NT6
      INTEGER NT7
      INTEGER NT8
      INTEGER NT8D
