     +HU,TU,PU,PSTL,A79,PSTL1,PSTL2
      INTEGER IERR1,IERR2,IERR3
      REAL A9P20
      EXTERNAL ERROR4
      A9P20 = 9.E20
      IF (SPIA(1).NE.A9P20) THEN
      COEF(1) = SPIA(1)
      IF (SPIA(1).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(1)=  ',SPIA(1),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(2).NE.A9P20) THEN
      COEF(2) = SPIA(2)*UL
      END IF
      IF (SPIA(3).NE.A9P20) THEN
      COEF(3) = SPIA(3)
      IF (SPIA(3).EQ.0.) THEN
      IERR1 = 1
