      CALL ERROR4('SPIA(5)=  ',SPIA(5),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(6).NE.A9P20) THEN
      COEF(6) = SPIA(6)*UL
      END IF
      IF (SPIA(7).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'SPIA(7)=  ',SPIA(7)
      END IF
      IF (SPIA(8).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'SPIA(8)=  ',SPIA(8)
      END IF
      IF (SPIA(9).NE.A9P20) THEN
      COEF(15) = SPIA(9)
      IF (SPIA(9).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(9)=  ',SPIA(9),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(10).NE.A9P20) THEN
      COEF(16) = SPIA(10)*UL
      END IF
      IF (SPIA(11).NE.A9P20) THEN
      COEF(17) = SPIA(11)
      IF (SPIA(11).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(11)= ',SPIA(11),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(12).NE.A9P20) THEN
