      END IF
      IF (SPIA(13).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'SPIA(13)= ',SPIA(13)
      END IF
      IF (SPIA(14).NE.A9P20) THEN
