      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'SPIA(14)= ',SPIA(14)
      END IF
      IF (SPIA(15).NE.A9P20) THEN
      COEF(13) = SPIA(15)
      IF (SPIA(15).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(15)= ',SPIA(15),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(16).NE.A9P20) THEN
      COEF(14) = SPIA(16)*1000./UP
      END IF
      IF (SPIA(17).NE.A9P20) THEN
      COEF(7) = SPIA(17)
      IF (SPIA(17).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(17)= ',SPIA(17),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(18).NE.A9P20) THEN
      COEF(8) = SPIA(18)*1000./UP
      END IF
      IF (SPIA(19).NE.A9P20) THEN
      COEF(21) = SPIA(19)
      IF (SPIA(19).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(19)= ',SPIA(19),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(20).NE.A9P20) THEN
      COEF(22) = SPIA(20)*1000./UP
      END IF
      IF (SPIA(21).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'SPIA(21)= ',SPIA(21)
      END IF
      IF (SPIA(22).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'SPIA(22)= ',SPIA(22)
      END IF
      IF (SPIA(23).NE.A9P20) THEN
      COEF(9) = SPIA(23)
      IF (SPIA(23).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(23)= ',SPIA(23),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(24).NE.A9P20) THEN
      COEF(10) = SPIA(24)
      END IF
      IF (SPIA(25).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'SPIA(25)= ',SPIA(25)
      END IF
      IF (SPIA(26).NE.A9P20) THEN
      IERR3 = 1
      IF (K6.EQ.1) WRITE (NT6,FMT=10040) 'SPIA(26)= ',SPIA(26)
      END IF
      IF (SPIA(27).NE.A9P20) THEN
      COEF(19) = SPIA(27)
      IF (SPIA(27).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(27)= ',SPIA(27),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(28).NE.A9P20) THEN
      COEF(20) = SPIA(28)
      END IF
      IF (SPIA(29).NE.A9P20) THEN
      COEF(23) = SPIA(29)
      IF (SPIA(29).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(29)= ',SPIA(29),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(30).NE.A9P20) THEN
