      END IF
      IF (SPIA(31).NE.A9P20) THEN
      COEF(25) = SPIA(31)
      IF (SPIA(31).EQ.0.) THEN
      IERR1 = 1
      CALL ERROR4('SPIA(31)= ',SPIA(31),K6,NT6,NBERR,ERRM,MERR)
      END IF
      END IF
      IF (SPIA(32).NE.A9P20) THEN
      COEF(26) = SPIA(32)
      END IF
      RETURN
10000 FORMAT (1X,'INPUT ERROR: ',A9,F3.0,' NOT VALID-SEE ',
     +'USER''S MANUAL')
10010 FORMAT (1X,'INPUT ERROR: ','CONFLICT BETWEEN ',A9,' AND ',A9)
10020 FORMAT (1X,'INPUT ERROR: TOO MANY EFFECTS ARE USED (7 MAXIMUM)')
10030 FORMAT (1X,'INPUT ERROR: ',A9,F3.0,
     +' NOT APPLICABLE FOR THIS A/C ','MODEL')
