      SUBROUTINE MELSRT(
     +IZCOD,
     +NBCO
     +)
      INTEGER IZCOD(*),NBCO
      INTEGER NBMEL
      INTEGER I
      INTEGER J
      INTEGER K
      INTEGER IDUM
      INTEGER NBIZCO
      INTEGER ORDLST(40)
      INTEGER TMP(7)
      INTEGER ITMP(7)
      PARAMETER (NBMEL=40)
      DATA ORDLST/10,16,14, 7, 8, 9,13,17,22,23,
     +24,25,26,27,33,34,35,36,28,29,
     +11,12,37,38,16*0/
      K = 1
      DO 10 I=1,NBCO
      TMP(I) = -IZCOD(I)
      ITMP(I) = 0
   10 CONTINUE
      DO 30 I=1,NBCO-1
      DO 20 J=I+1,NBCO
      IF (TMP(J).LT.TMP(I)) THEN
      IDUM = TMP(I)
      TMP(I) = TMP(J)
      TMP(J) = IDUM
      END IF
   20 CONTINUE
      TMP(I) = -TMP(I)
   30 CONTINUE
      TMP(NBCO) = -TMP(NBCO)
      DO 40 I=1,NBCO
      IF (TMP(I).EQ.0) THEN
      NBIZCO = I - 1
      GO TO 50
      END IF
   40 CONTINUE
      NBIZCO = NBCO
   50 CONTINUE
      IF (NBIZCO.EQ.0) RETURN
      K = 1
      DO 70 I=1,NBMEL
      DO 60 J = 1,NBIZCO
      IF (TMP(J).EQ.ORDLST(I)) THEN
      IZCOD(K) = TMP(J)
      ITMP(J) = 1
      K = K + 1
      IF (K.GT.NBCO) THEN
      GO TO 100
      END IF
      END IF
   60 CONTINUE
   70 CONTINUE
      DO 80 I=1,NBIZCO
      IF (ITMP(I).EQ.0) THEN
      IZCOD(K) = TMP(I)
      ITMP(I) = 1
      K = K + 1
      END IF
   80 CONTINUE
      DO 90 I = NBIZCO+1,NBCO
      IZCOD(I) = 0
   90 CONTINUE
  100 CONTINUE
      RETURN
      END
