      INTEGER LTITR(5)
      INTEGER LTITRL(5)
      COMMON /LDG1/LTITR,LTITRL,KODIF,CLJ1,CLJ2,DJ1,DJ2,NGAP1,NGAP2,
     +NGLD1,NGLD2,NTAL,LAT1,LAT2
      COMMON /LDG2/TLDA,BMASL,BVENL,BINFL,BPISL,BEAT,TLDP,QLD,FV1VR,
     +AP1G,AP2G,AP1K,AP2K,CLD1,CLD2,GAP1,GAP2,GLD1,GLD2,
     +AP1GMN,AP2GMN,AL1GMN,AL1G,SLATA,FLAPA,SLATL,FLAPL,
     +STAPMN,STAPMX,STEEP1,STEEP2,TALD1,TRLD1,TACG1,TLCG1,TIWLD1,
     +TIWAC1,TIWLC1,TALD2,TRLD2,TACG2,TLCG2,TIWLD2,TIWAC2,TIWLC2,
     +TOWLD1,TOWAC1,TOWLC1,TOWLD2,TOWAC2,TOWLC2,CLDW1,CLDW2,
     +EMASL,EVENL,EINFL,EPISL,EEAT,EB1L,EB2L,TLEB1,TLEB2,TIWEB1,
     +TIWEB2,TOWEB1,TOWEB2
      REAL AKV1
      REAL AKV2
      REAL AP1KV
      REAL AP2KV
      REAL DV2CP
      REAL DVMCA
      REAL DVMCPE
      REAL DVMCG
      REAL FTOKV
      REAL RK2T
      REAL RKV1
      REAL RKVF
      REAL RKVLD1
      REAL RKVLD2
      REAL VMCA
      REAL VMCG
      REAL VS
      INTEGER KMCA
      INTEGER KMCAG
      INTEGER KMCG
      INTEGER KMU
      REAL VDELBR(2)
      REAL VMAP(20)
      REAL VMC1(20)
      REAL VMGP(20)
      COMMON /VIT1/KMCA,KMCG,KMU,KMCAG
      COMMON /VIT2/VMCA,VMCG,RK2T,RKVF,AKV1,AKV2,RKVLD1,RKVLD2,
     +FTOKV,AP1KV,AP2KV,VMC1,VMGP,VMAP,DVMCG,DVMCA,RKV1,
     +DV2CP,DVMCPE,VS,VDELBR
      REAL AASDP
      REAL ASDMBA
      REAL ASDP
      REAL ATODP
      REAL P2PC
      REAL P2S
      REAL PMAXLP
      REAL PMAXP2
      REAL PTOD2
      REAL PTOR2
      REAL TODMBA
      REAL TODP
      REAL TORMBA
      REAL TORP
      REAL V1MAXP
      REAL V1MBAL
      REAL V1MINP
      REAL V1VRLP
      REAL V1VRMB
      REAL V1VRP
      REAL V1VRP2
      REAL V21
      REAL V2P
      REAL VOPTP
      REAL VQP
      REAL VRP
      REAL WIDTHP
      REAL ZGP
      INTEGER IPP
      REAL XLP(3)
      REAL ZOUL1(60)
      REAL ZOUL2(60)
      REAL ZOUT(60)
      REAL ZOUTE(20)
      REAL ZOUTS(60)
      COMMON /SPOUT1/IPP
      COMMON /SPOUT2/ZOUT,XLP,VQP,VRP,V1MAXP,V1MINP,V1VRP,V2P,VOPTP,
     +V1VRLP,PMAXLP,TORP,ASDP,TODP,P2S,V21,AASDP,ATODP,PTOR2,
     +PTOD2,P2PC,ZOUL1,ZOUL2,WIDTHP,ZGP,ZOUTE,PMAXP2,V1VRP2,ZOUTS
     +,V1VRMB,V1MBAL,ASDMBA,TODMBA,TORMBA
      INTEGER IXTRPL
      REAL PINI
      REAL PMAX
      REAL PMIN
      REAL V1VRI
      REAL V1VRMA
      REAL V1VRMI
      REAL V2VSMA
      REAL V2VSMI
      REAL ZMAX
      REAL ZMIN
      REAL SSGMIN
      REAL DTMAX1
      REAL DTMAX2
      REAL DTMIN
      REAL TMILBT
      REAL TMALBT
      REAL ZMILBT
      REAL ZMALBT
      REAL WMILBT
      REAL WMALBT
      REAL SMILBT
      REAL SMALBT
      REAL TMILL1
      REAL TMALL1
      REAL ZMILL1
      REAL ZMALL1
      REAL WMILL1
      REAL WMALL1
      REAL SMILL1
      REAL SMALL1
      REAL TMILL2
      REAL TMALL2
      REAL ZMILL2
      REAL ZMALL2
      REAL WMILL2
      REAL WMALL2
      REAL SMILL2
      REAL SMALL2
      REAL V2SMIL
      REAL V2SMAL
      REAL V1RMIL
      REAL V1RMAL
      REAL PMILBT
      REAL PMALBT
      REAL PMILL1
      REAL PMALL1
      REAL PMILL2
      REAL PMALL2
      REAL ALIM(20)
      REAL ZLIM(40)
      COMMON /LIMIT1/IXTRPL
      COMMON /LIMIT2/ZLIM,PMIN,PINI,PMAX,V2VSMI,V2VSMA,V1VRMI,V1VRI,
     +V1VRMA,ZMIN,ZMAX,DTMIN,DTMAX1,DTMAX2,ALIM,SSGMIN,
     +TMILBT,TMALBT,ZMILBT,ZMALBT,WMILBT,WMALBT,SMILBT,SMALBT,
     +TMILL1,TMALL1,ZMILL1,ZMALL1,WMILL1,WMALL1,SMILL1,SMALL1,
     +TMILL2,TMALL2,ZMILL2,ZMALL2,WMILL2,WMALL2,SMILL2,SMALL2,
     +V2SMIL,V2SMAL,V1RMIL,V1RMAL,PMILBT,PMALBT,PMILL1,PMALL1,
     +PMILL2,PMALL2
      REAL K1MIN
      REAL K1MAX
      REAL K2MIN
      REAL K2MAX
      REAL P0
      REAL PPMIN
      REAL PPMAX
      REAL PZM
      REAL QFE
      REAL TMAX
      REAL TS
      REAL ZPMIN
      REAL ZPMAX
      REAL ZPT
      REAL WDMIN
      REAL WDMAX
      REAL WDTEST
      REAL FINTV
      EXTERNAL FINTV
      DATA P0/10332.3/
      IF (XMET(4).EQ.0.) THEN
      ZPT = XMET(5)
      ELSE
      IF (PU.EQ.0.) THEN
      QFE = VQT(1)
      ELSE
      QFE = VQT(1)*33.8638
      END IF
      IF (ABS(QFE-1013.25).GT..005) THEN
      PZM = QFE*10.19715
      ZPT = ((1.- ((PZM/P0)** (1./AK2)))/AK1)/.3048
      ZPT = ZG + ZPT
      ELSE
      ZPT = ZG
      END IF
      END IF
      TS = 15. - .0065*ZPT*.3048
      TMAX = TS + DTCD(20) + .2
      IF (TU.EQ.1.) THEN
      TMAX = TMAX*1.8 + 32.
      END IF
      IF (TTA(1).GT.TMAX) THEN
      IF (K6.EQ.1) WRITE (NT6,10000) 'INPUT TEMPERATURE XMET(1)=',
     +TTA(1),' ',IT,' EXCEED MAX TEMPERATURE FOR AIRPORT : ',TMAX,
     +' ',IT
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10000) 'INPUT TEMPERATURE XMET(1)=',
     +TTA(1),' ',IT,' EXCEED MAX TEMPERATURE FOR AIRPORT : ',TMAX,
     +' ',IT
      END IF
      KFI = 1
      END IF
      ZPMIN = ZLIM(9)
      ZPMAX = ZLIM(10)
      IF ((ZPT.LT.ZPMIN).OR.(ZPT.GT.ZPMAX)) THEN
      IF (K6.EQ.1) WRITE (NT6,10010) 'AIRPORT PRESSURE ALTITUDE ',
     +ZPT/UH,IH,' OUT OF AFM RANGE : [',ZPMIN/UH,',',ZPMAX/UH,
     +'] (',IH,')'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10010) 'AIRPORT PRESSURE ALTITUDE ',ZPT/UH,
     +IH,' OUT OF AFM RANGE : [',ZPMIN/UH,',',ZPMAX/UH,'] (',IH,
     +')'
      END IF
      KFI = 1
      END IF
      PPMIN = ZLIM(22)
      PPMAX = ZLIM(23)
      IF ((PP.LT.PPMIN).OR.(PP.GT.PPMAX)) THEN
      IF (K6.EQ.1) WRITE (NT6,10020) 'RUNWAY SLOPE RWYD(6)=',PP,
     +' % OUT OF AFM RANGE : [',PPMIN,',',PPMAX,'] (%)'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10020) 'RUNWAY SLOPE RWYD(6)=',PP,
     +' % OUT OF AFM RANGE : [',PPMIN,',',PPMAX,'] (%)'
      END IF
      KFI = 1
      END IF
      WDMIN = ZLIM(20)
      WDMAX = ZLIM(21)
      IF (CODCAL .EQ. 0) THEN
      WDTEST = VQT(1)
      ELSE IF (CODCAL .EQ. 1) THEN
      WDTEST = VQ0
      END IF
      IF ( (WDTEST .LT. WDMIN) .OR. (WDTEST .GT. WDMAX) ) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,10050) 'WIND',WDTEST,
     +' (KT) OUT OF AFM RANGE : [',WDMIN,',',WDMAX,'] (KT)'
      END IF
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10050) 'WIND',WDTEST,
     +' (KT) OUT OF AFM RANGE : [',WDMIN,',',WDMAX,'] (KT)'
      END IF
      KFI = 1
      END IF
      K1MIN = ZLIM(6)
      K1MAX = ZLIM(8)
      IF ((FV1VR.NE.0.).AND.((FV1VR.LT.K1MIN).OR.(FV1VR.GT.K1MAX))) THEN
      IF (K6.EQ.1) WRITE (NT6,10030) 'INPUT V1/VR POPT(6)=',FV1VR,
     +' OUT OF AFM RANGE : [',K1MIN,',',K1MAX,']'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10030) 'INPUT V1/VR POPT(6)=',FV1VR,
     +' OUT OF AFM RANGE : [',K1MIN,',',K1MAX,']'
      END IF
      IF (FV1VR.LT.K1MIN) THEN
      FV1VR = K1MIN
      ELSE IF (FV1VR.GT.K1MAX) THEN
      FV1VR = K1MAX
      END IF
      IF (K6.EQ.1) WRITE (NT6,10040) 'NEW V1/VR VALUE SET TO ',FV1VR
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10040) 'NEW V1/VR VALUE SET TO ',FV1VR
      END IF
      KFI = 4
      END IF
      K2MIN = ZLIM(4)
      K2MAX = ZLIM(5)
      IF ((V2VS.NE.0.).AND.((V2VS.LT.K2MIN).OR.(V2VS.GT.K2MAX))) THEN
      IF (K6.EQ.1) WRITE (NT6,10030) 'INPUT V2/VS POPT(8)=',V2VS,
     +' OUT OF AFM RANGE : [',K2MIN,',',K2MAX,']'
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10030) 'INPUT V2/VS POPT(8)=',V2VS,
     +' OUT OF AFM RANGE : [',K2MIN,',',K2MAX,']'
      END IF
      IF (V2VS.LT.K2MIN) THEN
      V2VS = K2MIN
      ELSE IF (V2VS.GT.K2MAX) THEN
      V2VS = K2MAX
      END IF
      IF (K6.EQ.1) WRITE (NT6,10040) 'NEW V2/VS VALUE SET TO ',V2VS
      IF (NBERR.LT.MERR) THEN
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),10040) 'NEW V2/VS VALUE SET TO ',V2VS
      END IF
      KFI = 4
      END IF
      DVMCPE = 0
      IF (VMPE(1).LT.A9) THEN
      IF (WIDTH.EQ.0.) THEN
      IF (K6.EQ.1) WRITE (NT6,FMT='(A)')
     +' WARNING  *** RUNWAY WIDTH MISSING. LARGE WIDTH ASSUMED'
      IF (NBERR.LT.MERR) THEN
      KFI = 5
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A)')
     +' WARNING  *** RUNWAY WIDTH MISSING. LARGE WIDTH ASSUMED'
      END IF
      ELSE IF (WIDTH.LT.VMPE(4)) THEN
      IF (K6.EQ.1) THEN
      WRITE (NT6,FMT='(A,F5.1,A,A2,A,F5.1,A,A2,A)')
     +' WARNING  *** INPUT RUNWAY WIDTH : ',WIDTHP,' (',IL,
     +') LOWER THAN AFM MINIMUM WIDTH : ',VMPE(4)/UL,' (',IL,')'
      WRITE (NT6,FMT='(A)') ' CALCULATION NOT ALLOWED'
      END IF
      IF (NBERR.LT.MERR) THEN
      KFI = 1
      NBERR = NBERR + 1
      WRITE (ERRM(NBERR),FMT='(A21,F5.1,A2,A2,A32,F5.1,A2,A2,A1)')
     +'INPUT RUNWAY WIDTH : ',WIDTHP,' (',IL,
     +') LOWER THAN AFM MINIMUM WIDTH : ',VMPE(4)/UL,' (',IL,')'
      END IF
      ELSE
      DVMCPE = FINTV(WIDTH,VMPE(1))
      END IF
      END IF
      RETURN
10000 FORMAT (A,F5.1,A1,A2,A,F5.1,A1,A2)
10010 FORMAT (A,F6.0,1X,A2,A,F6.0,A1,F6.0,A3,A2,A1)
10020 FORMAT (A,F5.2,A,F5.2,A1,F5.2,A)
10030 FORMAT (A,F5.3,A,F5.3,A1,F5.3,A1)
10040 FORMAT (A,F5.3)
10050 FORMAT (A,F10.2,A,F10.2,A1,F10.2,A)
      END
      SUBROUTINE THSD
      INTEGER I
      I = 1
      RETURN
      END
      CHARACTER*(*) FUNCTION UPPER(
     +LINE,
     +N
     +)
      INTEGER LSIZE
      INTEGER*2 I
      INTEGER*2 J
      CHARACTER*6 FMT
      PARAMETER (LSIZE=256)
      INTEGER N
      CHARACTER*(LSIZE) LINE
      INTRINSIC CHAR,ICHAR,INT,MIN
      WRITE (FMT,'(A1,I3,A2)') '(',N,'X)'
      WRITE (UPPER,FMT=FMT)
      J = 0
      DO 10 I=1,MIN(LSIZE,N)
      IF ((LINE(I:I).GE.'a').AND.(LINE(I:I).LE.'z')) THEN
      J = J + 1
      UPPER(J:J) = CHAR(ICHAR(LINE(I:I))-32)
      ELSE IF (LINE(I:I).EQ.' ') THEN
      CONTINUE
      ELSE
      J = J + 1
      UPPER(J:J) = LINE(I:I)
      END IF
   10 CONTINUE
      RETURN
      END
